\section{Comparison with Spatially Varying Exposure}
\change{Appendix Fig.~\ref{fig:fre_analysis_1d} illustrates a 1D signal sampled at 25$\%$ density using both regular and random grids, and compares the corresponding reconstruction results.
This example highlights the aliasing artifacts caused by regular sampling and demonstrates how random sampling, when combined with a simple non-negative least squares (NNLS) reconstruction, better preserves high-frequency content—supporting the effectiveness of incoherent sampling strategies in our system design.}
\begin{figure}
\includegraphics{figures/frequency_analysis_1d.pdf}
    \caption{\change{ 1D signal sampling and reconstruction comparison between regular and random grids.
    (a) The original high-frequency signal.
    (b) The signal sampled 25$\%$ uniformly on a regular grid, leading to aliasing.
    (c) The same signal sampled 25$\%$ using a random grid, which disrupts aliasing patterns.
    (d) Reconstruction results using non-negative least squares (NNLS). The regular grid produces strong aliasing and poor recovery (red), while the random sampling better preserves high-frequency content and results in a more accurate reconstruction (blue), demonstrating the advantage of incoherent sampling in the context of compressive sensing.}}
    \label{fig:fre_analysis_1d}
\end{figure}
