	\label{fig:sierpinski_graphs}
\end{figure}

Now, we consider \( G_\ell \), the Sierpiński graph at level \( \ell \), where we decompose the nodes into junction nodes and interior nodes, as explained above. We are interested in finding the optimal portfolio weights (\ref{eq:Optimal_w}). We decompose the weight vector \( \mathbf{w} \) into two components:  
\begin{equation}
\mathbf{w} =
\begin{pmatrix}
\mathbf{w}_{\text{jun}} \\
\mathbf{w}_{\text{in}}
\end{pmatrix},
\quad \mathbf{1}^t_{\text{jun}} \mathbf{w}_{\text{jun}} + \mathbf{1}^t_{\text{in}} \mathbf{w}_{\text{in}} = 1.
\end{equation}
where \( \mathbf{w}_{\text{jun}} \) represents the weights assigned to junction nodes, and \( \mathbf{w}_{\text{in}} \) represents the weights assigned to interior nodes. Similarly, \( \mathbf{1}_{\text{jun}} \) and \( \mathbf{1}_{\text{in}} \) are vectors of ones corresponding to the junction and interior nodes, respectively. The following result states that to compute the optimal weight vector \( \mathbf{w} \), all we need is the weights on the junction nodes, \( \mathbf{w}_{\text{jun}} \).

\begin{proposition}
\label{prop:Schur}
Let \( \mathbf{y} \) be a vector defined on all nodes, and decompose it as  
$\mathbf{y}^t = \big(\mathbf{y}_{\text{jun}}^t, \ \mathbf{y}_{\text{in}}^t \big)$. Define the following functions:
\begin{enumerate}
\item For a vector \( \mathbf{v} \) defined on the junction nodes, define  
$
   h(\mathbf{v}, \mathbf{y}) = \mathbf{X}^{-1} \mathbf{y}_{\text{in}} - \mathbf{X}^{-1} \mathbf{J} \mathbf{v}.
$
\item Define  
$
   g(\mathbf{y}) = \mathbf{y}_{\text{jun}} - \mathbf{J}^t \mathbf{X}^{-1} \mathbf{y}_{\text{in}}.
$
\end{enumerate}
Then, a vector \( \mathbf{w} \) satisfies the equation \( \mathbf{w} = \mathbf{\Sigma}^{-1} \mathbf{y} \) \text{if and only if} it can be written in the form
\begin{equation}
\label{eq:transJunToInt}
\mathbf{w} =
\begin{pmatrix}
\mathbf{w}_{\text{jun}} \\
h(\mathbf{w}_{\text{jun}}, \mathbf{y})
\end{pmatrix}.
\end{equation}
Furthermore, \( \mathbf{w}_{\text{jun}} \) satisfies the equation  
$\mathbf{w}_{\text{jun}} = \mathbf{S}(\Sigma)^{-1} g(\mathbf{y})$,
where \( \mathbf{S}(\Sigma) \) is the Schur complement of \( \mathbf{X} \) in \( \mathbf{\Sigma} \), given by $\mathbf{S}(\Sigma) = \mathbf{T} - \mathbf{J}^t \mathbf{X}^{-1} \mathbf{J}$.
\end{proposition}
\begin{proof}
We start with the assumption $\mathbf{w} = \mathbf{\Sigma}^{-1} \mathbf{y}$, which is equivalent to $\mathbf{\Sigma} \mathbf{w} =  \mathbf{y}$. Using the block structure of the covariance matrix \( \mathbf{\Sigma} \), we write:
\[
\begin{pmatrix}
\mathbf{T} & \mathbf{J}^t \\
\mathbf{J} & \mathbf{X}
\end{pmatrix}
\begin{pmatrix}
\mathbf{w}_{\text{jun}} \\
\mathbf{w}_{\text{in}}
\end{pmatrix}
=
\begin{pmatrix}
\mathbf{y}_{\text{jun}} \\
\mathbf{y}_{\text{in}}
\end{pmatrix}
\]
Expanding this system gives two equations. From the second equation $\mathbf{J} \mathbf{w}_{\text{jun}} + \mathbf{X} \mathbf{w}_{\text{in}} = \mathbf{y}_{\text{in}}$, we solve for \( \mathbf{w}_{\text{in}} \):
\[
\mathbf{w}_{\text{in}} = \mathbf{X}^{-1} \mathbf{y}_{\text{in}} - \mathbf{X}^{-1} \mathbf{J} \mathbf{w}_{\text{jun}} = h(\mathbf{w}_{\text{jun}},\mathbf{y}) 
\]
Now, substituting \( \mathbf{w}_{\text{in}} \) into the first equation 
$
\mathbf{T} \mathbf{w}_{\text{jun}} + \mathbf{J}^t (\mathbf{X}^{-1} \mathbf{y}_{\text{in}} - \mathbf{X}^{-1} \mathbf{J} \mathbf{w}_{\text{jun}}) = \mathbf{y}_{\text{jun}},
$
and rearranging, we obtain
\begin{equation*}
(\mathbf{T} - \mathbf{J}^t \mathbf{X}^{-1} \mathbf{J}) \mathbf{w}_{\text{jun}} = \mathbf{y}_{\text{jun}} - \mathbf{J}^t \mathbf{X}^{-1} \mathbf{y}_{\text{in}}.
\end{equation*}
By the definition of \( \mathbf{S}(\Sigma) \) and \( g(\mathbf{y}) \), we obtain
$
\mathbf{S}(\Sigma) \mathbf{w}_{\text{jun}} = g(\mathbf{y}).
$
Solving for \( \mathbf{w}_{\text{jun}} \) gives  
$
\mathbf{w}_{\text{jun}} = \mathbf{S}(\Sigma)^{-1} g(\mathbf{y}).
$
\end{proof}
We will determine the optimal weights (\ref{eq:Optimal_w}) by considering the case where \( \mathbf{w} = \mathbf{\Sigma}^{-1} \mathbf{1} \), corresponding to \( \mathbf{y} = \mathbf{1} \) in Proposition \ref{prop:Schur}. This proposition shows that once the weights on the junction nodes are determined, the weights for the interior nodes can be computed directly using the function \(  \mathbf{w}_{\text{in}} = h(\mathbf{w}_{\text{jun}},\mathbf{1}) \). This marks the first step in a \textit{divide-and-conquer} approach, where the optimization problem is systematically reduced to a smaller set of assets, specifically the junction nodes. To fully establish this framework, we now analyze how the inner product \( \langle \mathbf{w}, \mathbf{w} \rangle_{\Sigma} = \mathbf{w}^t \Sigma \mathbf{w} \) decomposes under this hierarchical structure.


\begin{proposition}
\label{prop:DecompOfVariance}
Let the function \( h(\mathbf{v}, \mathbf{y}) \) and the Schur complement \( \mathbf{S}(\Sigma) \) of \( \mathbf{X} \) in \( \mathbf{\Sigma} \) be defined as in Proposition \ref{prop:Schur}. Let \( \mathbf{w} \) and \( \mathbf{y} \) be vectors defined on all nodes. Then, the portfolio variance can be decomposed as   
\begin{align*}
\langle \mathbf{w}, \mathbf{w} \rangle_{\Sigma} =
& \ \langle \mathbf{w}_{\text{jun}}, \mathbf{w}_{\text{jun}} \rangle_{\mathbf{S}(\Sigma)} 
+ \mathbf{y}_{\text{in}}^t \mathbf{X}^{-1} \mathbf{y}_{\text{in}} \\
& + \langle \mathbf{w}_{\text{in}} - h(\mathbf{w}_{\text{jun}},\mathbf{y}), 
\mathbf{w}_{\text{in}} - h(\mathbf{w}_{\text{jun}},\mathbf{y})  \rangle_{\mathbf{X}}  + 2 \mathbf{y}_{\text{in}}^t \big( \mathbf{w}_{\text{in}} - h(\mathbf{w}_{\text{jun}},\mathbf{y}) \big).
\end{align*}
where we used the inner product notation for the variance introduced in (\ref{eq:innerProductNot}).
\end{proposition}

\begin{proof}
We begin by computing the inner product on the left-hand side:
\begin{equation}
\label{eq:comInnerProd}
\langle \mathbf{w}, \mathbf{w} \rangle_{\mathbf{\Sigma}}  = 
\mathbf{w}_{\text{jun}}^t \mathbf{T} \mathbf{w}_{\text{jun}} + 2 \mathbf{w}_{\text{jun}}^t \mathbf{J}^t \mathbf{w}_{\text{in}} + \mathbf{w}_{\text{in}}^t \mathbf{X} \mathbf{w}_{\text{in}}.
\end{equation}
Next, we compute the third term on the right-hand side:
\begin{equation*}
\mathbf{w}_{\text{in}}^t \mathbf{X} \mathbf{w}_{\text{in}}
+ 2 \mathbf{w}_{\text{jun}}^t \mathbf{J}^t \mathbf{w}_{\text{in}}
- 2 \mathbf{w}_{\text{in}}^t \mathbf{y}_{\text{in}}
+ \mathbf{y}_{\text{in}}^t \mathbf{X}^{-1} \mathbf{y}_{\text{in}}
- 2 \mathbf{w}_{\text{jun}}^t \mathbf{J}^t \mathbf{X}^{-1} \mathbf{y}_{\text{in}}
+ \mathbf{w}_{\text{jun}}^t \mathbf{J}^t \mathbf{X}^{-1} \mathbf{J} \mathbf{w}_{\text{jun}}.
\end{equation*}
We now compute the first term on the right-hand side:
\begin{equation*}
\mathbf{w}_{\text{jun}}^t \mathbf{T} \mathbf{w}_{\text{jun}} - \mathbf{w}_{\text{jun}}^t \mathbf{J}^t \mathbf{X}^{-1} \mathbf{J} \mathbf{w}_{\text{jun}}.
\end{equation*}
Combining these two expressions and simplifying their sum using (\ref{eq:comInnerProd}) gives the following:
\begin{equation*}
\langle \mathbf{w}, \mathbf{w} \rangle_{\mathbf{\Sigma}} 
+ \mathbf{y}_{\text{in}}^t \mathbf{X}^{-1} \mathbf{y}_{\text{in}}
- 2 \mathbf{y}_{\text{in}}^t \mathbf{w}_{\text{in}}
- 2 \mathbf{y}_{\text{in}}^t \mathbf{X}^{-1} \mathbf{J} \mathbf{w}_{\text{jun}}.
\end{equation*}
Rearranging the terms, we obtain:
\begin{equation*}
\langle \mathbf{w}, \mathbf{w} \rangle_{\mathbf{\Sigma}} 
- \mathbf{y}_{\text{in}}^t \mathbf{X}^{-1} \mathbf{y}_{\text{in}}
- 2 \mathbf{y}_{\text{in}}^t \mathbf{w}_{\text{in}}
- 2 \mathbf{y}_{\text{in}}^t \big( \mathbf{X}^{-1} \mathbf{J} \mathbf{w}_{\text{jun}} - \mathbf{X}^{-1} \mathbf{y}_{\text{in}} \big).
\end{equation*}
Finally, since $h(\mathbf{w}_{\text{jun}},\mathbf{y}) = \mathbf{X}^{-1} \mathbf{y}_{\text{in}} - \mathbf{X}^{-1} \mathbf{J} \mathbf{w}_{\text{jun}}$, the first and third terms on the right-hand side simplify to:
\begin{equation}
\langle \mathbf{w}, \mathbf{w} \rangle_{\mathbf{\Sigma}} 
- \mathbf{y}_{\text{in}}^t \mathbf{X}^{-1} \mathbf{y}_{\text{in}}
- 2 \mathbf{y}_{\text{in}}^t \big( \mathbf{w}_{\text{in}}
- h(\mathbf{w}_{\text{jun}},\mathbf{y}) \big).
\end{equation}
\end{proof}
The decomposition of \( \mathbf{w}^t \mathbf{\Sigma} \mathbf{w} \) in Proposition \ref{prop:DecompOfVariance} provides insight into how risk is distributed across junction and interior assets. When combined with Proposition \ref{prop:Schur}, this result justifies why solving for the junction node weights first is sufficient for optimization. Instead of working with the full covariance matrix, we can transform it into a smaller, reduced covariance structure using the Schur complement, which makes the problem more computationally efficient while preserving the key relationships between assets. The following theorem formalizes this observation.

\begin{theorem}
\label{thm:mainResult}
Let \( \mathbf{w} \) be defined as \( \mathbf{w} = \mathbf{\Sigma}^{-1} \mathbf{1} \). We decompose \( \mathbf{w} \) into junction and interior node weights
$
\mathbf{w} =
\begin{pmatrix}
\mathbf{w}_{\text{jun}},
\mathbf{w}_{\text{in}}
\end{pmatrix}^t
$
and compute the following:
\begin{enumerate}
    \item Compute the junction node weights by solving the following equation:
    \begin{align*}
    \mathbf{w}_{\text{jun}} = \mathbf{S}(\Sigma)^{-1}g(\mathbf{1}), \quad \quad g(\mathbf{1})= \mathbf{1}_{\text{jun}} - \mathbf{J}^t \mathbf{X}^{-1} \mathbf{1}_{\text{in}},
    \end{align*}
    where \( \mathbf{S}(\Sigma) = \mathbf{T} - \mathbf{J}^t \mathbf{X}^{-1} \mathbf{J} \) is the Schur complement.

    \item Once \( \mathbf{w}_{\text{jun}} \) is obtained, the interior node weights follow from:
    \[
    \mathbf{w}_{\text{in}} = h(\mathbf{w}_{\text{jun}}, \mathbf{1}), \quad \quad h(\mathbf{w}_{\text{jun}}, \mathbf{1}) = \mathbf{X}^{-1} \mathbf{1}_{\text{in}} - \mathbf{X}^{-1} \mathbf{J} \mathbf{w}_{\text{jun}}
    \]

    \item The vector \( \mathbf{w} \) minimizes \( \langle \mathbf{w}, \mathbf{w} \rangle_{\Sigma} \) if and only if the junction node weights \( \mathbf{w}_{\text{jun}} \) minimize \( \langle \mathbf{w}_{\text{jun}}, \mathbf{w}_{\text{jun}} \rangle_{\mathbf{S}(\Sigma)} \). Specifically, they differ by a positive constant term independent of \( \mathbf{w} \), given by:

\begin{equation}
\label{eq:variaceTwoLevels}
\langle \mathbf{w}, \mathbf{w} \rangle_{\Sigma} =
\langle \mathbf{w}_{\text{jun}}, \mathbf{w}_{\text{jun}} \rangle_{\mathbf{S}(\Sigma)}
+ \mathbf{1}_{\text{in}}^t \mathbf{X}^{-1} \mathbf{1}_{\text{in}}.
\end{equation}
\item Finally, we determine the minimum variance portfolio \( \mathbf{w}^* \), as defined in Equation (\ref{eq:Optimal_w}):
\[
\mathbf{w}^* =
\begin{pmatrix}
\mathbf{w}^{*}_{\text{jun}} \\[5pt]
\mathbf{w}^{*}_{\text{in}}
\end{pmatrix}
=
\frac{1}{\mathbf{1}_{\text{jun}}^t \mathbf{w}_{\text{jun}} + \mathbf{1}_{\text{in}}^t \mathbf{w}_{\text{in}}}
\begin{pmatrix}
\mathbf{w}_{\text{jun}} \\[5pt]
\mathbf{w}_{\text{in}}
\end{pmatrix}.
\]

Dividing Equation (\ref{eq:variaceTwoLevels}) by the normalization constant, the portfolio variance decomposes as:
\[
\langle \mathbf{w}^{*}, \mathbf{w}^{*} \rangle_{\Sigma} =
\langle \mathbf{w}^{*}_{\text{jun}}, \mathbf{w}^{*}_{\text{jun}} \rangle_{\mathbf{S}} 
+ \frac{\mathbf{1}_{\text{in}}^t \mathbf{X}^{-1} \mathbf{1}_{\text{in}}}{(\mathbf{1}_{\text{jun}}^t \mathbf{w}_{\text{jun}} + \mathbf{1}_{\text{in}}^t \mathbf{w}_{\text{in}})^2}.
\]
\end{enumerate}
\end{theorem}

\begin{proof}
The proof follows directly from the application of Propositions \ref{prop:Schur} and \ref{prop:DecompOfVariance}, where the vector \( \mathbf{y} \) in both cases is given by \( \mathbf{y} = \mathbf{1} \). The identity (\ref{eq:variaceTwoLevels}) follows from Proposition \ref{prop:DecompOfVariance}, where the last two terms vanish due to the condition \( \mathbf{w}_{\text{in}} = h(\mathbf{w}_{\text{jun}}, \mathbf{1}) \).
\end{proof}
One key advantage of dividing assets into junction assets and interior assets is that it significantly improves the efficiency of computing the inverse of the covariance matrix. As outlined in Theorem \ref{thm:mainResult}, Steps 1, 2, and 3, instead of inverting the full covariance matrix \( \mathbf{\Sigma} \), we only need to compute the inverses of the submatrices \( \mathbf{X} \) and \( \mathbf{S}(\Sigma) \). Notably, the inverse of \( \mathbf{X} \) is particularly straightforward due to its block diagonal structure:

\[
\mathbf{X}^{-1} =
  \setlength{\arraycolsep}{0pt}
  \setlength{\delimitershortfall}{0pt}
  \begin{pmatrix}
    \,\fbox{$B^{-1}_1$} & 0 & 0 & \cdots & 0\,  \\
    \,0 & \fbox{$B^{-1}_2$} & 0 & \cdots & 0\,  \\
    \,0 & 0 & \ddots & \ddots & \vdots\,  \\
    \,\vdots & \vdots & \ddots & \ddots & 0\,  \\
    \,0 & 0 & \cdots & 0 & \fbox{$B^{-1}_m$}\,  
  \end{pmatrix}
\]
\\
where each block corresponds to a matrix of size \( 3 \times 3 \), namely the covariance matrix of assets within a single cluster (within a copy of $G_1$), as seen in (\ref{eq:SigmaLevel2}). The number of blocks matches the number of clusters. This block-wise inversion significantly reduces computational complexity compared to directly inverting \( \mathbf{\Sigma} \). However, the situation with \( \mathbf{S}(\Sigma) \) is more intricate, as \( \mathbf{S}(\Sigma) \) is obtained via the Schur complement, capturing the interactions between junction and interior nodes. To better understand the role and behavior of \( \mathbf{S}(\Sigma) \), we now examine a concrete example.



\begin{example}[Continuation of Example \ref{ex:Level2Example1}]
\label{ex:Level2Example2}
From this point forward, we emphasize the level at which we are working, as this distinction will soon become important. Applying Theorem \ref{thm:mainResult}, we explicitly compute the optimal weight vector \( \mathbf{w}^*_2 \) (where the subscript denotes level 2 of the Sierpinski graph) and compare it with the previously derived results in (\ref{eq:optimalWeightsConcrete}). The first step is to compute the Schur complement of (\ref{eq:SigmaLevel2}):

\begin{equation}
\label{eq:SchurComp}
\renewcommand{\arraystretch}{1.5} % Increases row spacing
\mathbf{S}(\Sigma_2) =
\begin{pmatrix}
\begin{array}{ccc|ccc}
\frac{1051}{181} & 0 & 0 & \frac{288}{181} & -\frac{57}{362} & 0\\
0 & \frac{2438}{209} & 0 & -\frac{195}{418} & 0 & \frac{117}{418}\\
0 & 0 & \frac{4289}{733} & 0 & \frac{110}{733} & \frac{60}{733}\\
\hline
\frac{288}{181} & -\frac{195}{418} & 0 & \frac{518273}{151316} & \frac{38}{181} & -\frac{107}{836}\\
-\frac{57}{362} & 0 & \frac{110}{733} & \frac{38}{181} & \frac{3010675}{265346} & -\frac{74}{733}\\
0 & \frac{117}{418} & \frac{60}{733} & -\frac{107}{836} & -\frac{74}{733} & \frac{4124565}{612788}
\end{array}
\end{pmatrix}
\renewcommand{\arraystretch}{1} % Reset spacing for other matrices
\end{equation}
\\
By inverting this matrix, we obtain the junction weights \( \mathbf{w}_{2,\text{jun}} \) as specified in step one of the theorem:
\begin{equation}
\label{eq:w_jun2}
\mathbf{w}_{2,\text{jun}} \approx 
\left( 0.1, \  0.087, \  0.241, \  0.393, \  0.078, \  0.16 \right)^t
\end{equation}
Once the junction weights are established, the interior node weights follow from step two of the theorem:
\begin{equation}
\label{eq:w_in2}
\mathbf{w}_{2,\text{in}} \approx 
\left( -0.101, \  0.195, \  0.208, \  0.26, \  0.283, \  0.218, \  0.074, \  0.186, \  0.1 \right)^t
\end{equation}
With these components in place, we ensure normalization by computing:
\begin{equation*}
\mathbf{1}_{\text{jun}}^t \mathbf{w}_{2,\text{jun}}  + \mathbf{1}_{\text{in}}^t \mathbf{w}_{2,\text{in}} \approx  2.481
\end{equation*}
This leads to the final optimal weight vector \( \mathbf{w}^*_2 \), which matches the previously derived result in (\ref{eq:optimalWeightsConcrete}). The next step is to decompose the portfolio variance using Theorem \ref{thm:mainResult}. Specifically, the variance contribution from the junction weights at level 2 is:
\begin{equation}
\langle \mathbf{w}^{*}_{2,\text{jun}}, \mathbf{w}^{*}_{2,\text{jun}} \rangle_{\mathbf{S}(\Sigma_2)} \approx  0.221
\end{equation} 
The total portfolio variance is then computed as
$\langle \mathbf{w}^{*}_2, \mathbf{w}^{*}_2 \rangle_{\Sigma} \approx 0.403$, which also coincides with the previous result in (\ref{eq:optimalWeightsConcrete}).
\end{example}
