	\begin{definition}
		Define a matrix $\Omega^{\sigma}_{\epsilon}\in \mathbb{R}^{(n+1)\times(n+1)}$, called $\epsilon-$repelling matrix, as follows:
		\[ \Omega^{\sigma}_{\epsilon}(i,j):=(\vec{e_i}-\vec{e_j})^TL_{\epsilon}^{\dagger}(\vec{e_i}-\vec{e_j}) \] 
		We call $\Om(i,j)$ the $\epsilon-$repelling cost between $i$ and $j$.

	\end{definition}
	 Denote by $L_{\epsilon}^{\dagger}$ the pseudoinverse of $\Le$ and from the above theorem we know $L_{\epsilon}^{\dagger}=SS^T$ where $S$ is the vertex matrix of some $n-$simplex. 
	 \begin{proposition}
	 	$\sqrt{\Omega^{\sigma}_{\epsilon}(i,j)}$ is a distance on signed graph $\Gamma$.
	 \end{proposition}
	 \begin{proof}
	 	Assume $L_{\epsilon}^{\dagger}=SS^T$ where $S=\left[v_1,\cdots,v_{n+1}\right]^T$ is the vertex matrix of some $n-$simplex,
	 	\[ \Omega^{\sigma}_{\epsilon}(i,j)=\left(v_i-v_j\right)^T\left(v_i-v_j\right)=||v_i-v_j ||^2\ge 0\]
	 	\[ \sqrt{\Omega^{\sigma}_{\epsilon}(i,j)}=||v_i-v_j || \]
	 	Therefore, for $\forall i,j,k\in V$, 
	 	\[ \sqrt{\Omega^{\sigma}_{\epsilon}(i,j)}=||v_i-v_j ||\le||v_i-v_k ||+||v_k-v_j ||=\sqrt{\Omega^{\sigma}_{\epsilon}(i,k)}+\sqrt{\Omega^{\sigma}_{\epsilon}(j,k)} \]
	 \end{proof}

	 \begin{remark}
	 	From \cite[Property 1]{devriendt2022effective}, we know the off-diagonal entries of pseudoinverse of canonical Gram matrix reflect whether the dihedral angles of simplex are obtuse, right or acute. Because the off-diagonal entries of $\Le$ are both positive and negative, the simplex of $\epsilon-$repelling Laplacian is not a hyperacute simplex and the angles of its triangular face may be obtuse, which results in $\Omega^{\sigma}_{\epsilon}(\cdot,\cdot) $ not being a distance.
	 \end{remark}

	 \begin{lemma}
	 The signed resistance matrix $\Omega^{\sigma}_{\epsilon}$ is invertible.
	 \end{lemma}

	 \begin{proof}
	 	Denote by $\zeta$ the vector consisting of the diagonal entries of $L_{\epsilon}^{\dagger}$. From definition, we have 
	 	\[ \Omega^{\sigma}_{\epsilon}=\zeta\vec{1}^T+\vec{1}\zeta^T-2L_{\epsilon}^{\dagger} \]
	 	$L_{\epsilon}^{\dagger}$ is positive semidefinite whose null space is spanned by all ones vector since it's the pesudoinverse of $\Le$. Then for any $\vec{x}\perp \vec{1}$:
	 	\[ \vec{x}^T\Omega^{\sigma}\vec{x}=-2\vec{x}^TL_{\epsilon}^{\dagger}\vec{x}<0 \]
	 	For $\vec{x}=c\vec{1}$ where $c$ is a constant:  
	 	\[ \vec{x}^T\Omega^{\sigma}_{\epsilon}\vec{x}=c^2\vec{1}^T\Omega^{\sigma}\vec{1}>0 \]
	 	Therefore, for any $\vec{x}\neq \vec{0}$, $\vec{x}^T\Omega^{\sigma}_{\epsilon}\vec{x}\neq0 $, implying that $\Omega^{\sigma}_{\epsilon}$ is invertible.
	 \end{proof}

	 From \cite[Equation (14)]{devriendt2022effective} and \cite[Thm2.1.1]{fiedler2011matrices}, we obtain a matrix identity on positive-connected signed graph in the following theorem.

	 \begin{theorem}\label{eq2}
	 	\[ 
	 	-\frac{1}{2}\begin{pmatrix}
	 		0&\vec{1}^T\\
	 		\vec{1}&\Omega^{\sigma}_{\epsilon}
	 	\end{pmatrix}
	 	=\begin{pmatrix}
	 		4R^2&-2\vec{r}^T\\
	 		-2\vec{r}^T& \Le
	 	\end{pmatrix}^{-1}	 	
	 	 \]
	 	 where $R$ is the radius of the circumscribed hypersphere of the simplex of $\Le$ and $\vec{r}$ is barycentric coordinate of the circumcenter of the simplex of $\Le$.
	 \end{theorem}

	  Next we compare the original resistance $\Omega(i,j)$ on the underlying graph $G$ with the signed resistance $\Omega^{\sigma}_{\epsilon}(i,j)$ on $\Gamma$. Recall the definition of resistance distance $\Omega(i,j)$ on general graphs 
	  \[ \Omega(i,j):=(\vec{e_i}-\vec{e_j})^TL^{\dagger}(\vec{e_i}-\vec{e_j}) \]
	  where $L=L_{+}+L_{-}$ is the Laplacian on the underlying graph $G$. First we give a proposition about the expression of the pesudoinverse of any symmetric matrix in terms of the null space.

	  \begin{proposition}\label{pro1}
	  	Suppose $A$ is a symmetric and singular matrix and $\{\vec{z_1},\cdots,\vec{z_m}\}$ are the orthonormal basis of the null space of $A$, then the matrix 
	  	\[ A_0:=A+\sum_{j=1}^{m}\vec{z_j}\vec{z_j}^T \]
	  	 is invertible and the inverse is 
	  	 \[ A_0^{-1}=A^{\dagger}+\sum_{j=1}^{m}\vec{z_j}\vec{z_j}^T \]
	  \end{proposition}

	 \begin{proof}
	 	\begin{align*}
	 		&\left(A+\sum_{j=1}^{m}\vec{z_j}\vec{z_j}^T\right)\left(A^{\dagger}+\sum_{j=1}^{m}\vec{z_j}\vec{z_j}^T\right)\\
	 		=&AA^{\dagger}+\sum_{j=1}^{m}A\vec{z_j}\vec{z_j}^T+\sum_{j=1}^{m}\vec{z_j}\vec{z_j}^TA+\sum_{i=1}^{m}\sum_{j=1}^{m}\vec{z_i}\vec{z_i}^T\vec{z_j}\vec{z_j}^T\\
	 		=&AA^{\dagger}+\sum_{j=1}^{m}\vec{z_j}\vec{z_j}^T\\
	 		=&I
	 	\end{align*}
	 	Similarly we have 
	 	\[ \left(A^{\dagger}+\sum_{j=1}^{m}\vec{z_j}\vec{z_j}^T\right)\left(A+\sum_{j=1}^{m}\vec{z_j}\vec{z_j}^T\right)=I \]
	 	Therefore, we finish the proof.
	 \end{proof}

	 The next theorem shows $\epsilon-$repelling cost on signed graph is non-decreasing with respect to $\epsilon$  in case where $\epsilon<\epsilon_0$ may be negative. Note $\Le$ becomes the Laplacian on underlying graph $G$ when $\epsilon=-1$, hence we can compare the magnitudes of $\Omega_{\epsilon}^{\sigma}(i,j) $ and $\Omega(i,j) $.


	 \begin{proof}[Proof of Theorem \ref{main3}]
	 	Since both the orthonormal bases of null spaces $N(L_{+}-\epsilon_1L_{-})$ and $N(L_{+}-\epsilon_2L_{-})$ are $\{\frac{1}{\sqrt{n+1}}\vec{1}\}$, using Proposition (\ref{pro1}), we have
	 	\begin{align*}
	 		(L_{+}-\epsilon_1L_{-})^{\dagger}&=\left(L_{+}-\epsilon_1L_{-}+\frac{1}{n+1}\vec{1}\vec{1}^T\right)^{-1}-\frac{1}{n+1}\vec{1}\vec{1}^T\\
	 		(L_{+}-\epsilon_2L_{-})^{\dagger}&=\left(L_{+}-\epsilon_2L_{-}+\frac{1}{n+1}\vec{1}\vec{1}^T\right)^{-1}-\frac{1}{n+1}\vec{1}\vec{1}^T
	 	\end{align*}
	 	 Then
	 	 \begin{align*}
	 	 	&(L_{+}-\epsilon_2L_{-})^{\dagger}-(L_{+}-\epsilon_1L_{-})^{\dagger}\\
	 	 	=&\left(L_{+}-\epsilon_2L_{-}+\frac{1}{n+1}\vec{1}\vec{1}^T\right)^{-1}-\left(L_{+}-\epsilon_1L_{-}+\frac{1}{n+1}\vec{1}\vec{1}^T\right)^{-1}
	 	 \end{align*}
	 	 For convenience, we denote $L_{+}-\epsilon_2L_{-}+\frac{1}{n+1}\vec{1}\vec{1}^T$ by $B$ and $L_{+}-\epsilon_1L_{-}+\frac{1}{n+1}\vec{1}\vec{1}^T $ by $A$. Therefore,
	 	 \begin{align*} 
	 	 	B^{-1}=\left(I-\left(\epsilon_2-\epsilon_1\right)A^{-1}L_{-}\right)^{-1}A^{-1}
	 	 \end{align*}
	 	% Because $A\vec{1}=\vec{1}$ and $A\vec{y_i}=\lambda_i(L)\vec{y_i}$ where $\{y_i\}_{i=2}^{n+1}$ are the eigenvectors of the nonzero and nondecreasing eigenvalues $\{\lambda_i(L)\}_{i=2}^{n+1}$ of $L$, the minimal eigenvalue of $A$ is $\min\{1,\lambda_{2}(L)\}$.
	 	Let $\delta_{\epsilon_1}:=\frac{1}{2||A^{-1}||_2||L_{-}||_2}$ and if $0\le \epsilon_2-\epsilon_1\le\delta$:
	 	 \begin{align*}
	 	 	||(\epsilon_2-\epsilon_1)A^{-1}L_{-}||_2\le \frac{1}{2}<1
	 	 \end{align*}
	 	 So 
	 	 \begin{align*}
	 	 	\left(I-\left(\epsilon_2-\epsilon_1\right)A^{-1}L_{-}\right)^{-1}&=I+\sum_{i=1}^{\infty}\left[\left(\epsilon_2-\epsilon_1\right)A^{-1}L_{-}\right]^i\\
	 	 	B^{-1}-A^{-1}&=\sum_{i=1}^{\infty}\left[\left(\epsilon_2-\epsilon_1\right)A^{-1}L_{-}\right]^iA^{-1}
	 	 \end{align*}
	 	 In fact, for any $i\ge 1$, $\left(A^{-1}L_{-}\right)^iA^{-1}$ is positive semidefinite. When $i=2k$ is even, $\vec{x}^T\left(A^{-1}L_{-}\right)^iA^{-1}\vec{x}=\left(\left(L_{-}A^{-1}\right)^k\vec{x}\right)^TA^{-1}\left(\left(L_{-}A^{-1}\right)^k\vec{x}\right)\ge 0$. When $i=2k+1$ is odd, $\vec{x}^T\left(A^{-1}L_{-}\right)^iA^{-1}\vec{x}=\left(\left(A^{-1}L_{-}\right)^kA^{-1}\vec{x}\right)^TL_{-}\left(\left(A^{-1}L_{-}\right)^kA^{-1}\vec{x}\right)\ge 0$. Therefore,
	 	 \begin{align*}
	 	 	\Omega_{\epsilon_2}^{\sigma}(i,j)-\Omega_{\epsilon_1}^{\sigma}(i,j)&=\left(\vec{e_i}-\vec{e_j}\right)^T\left((L_{+}-\epsilon_2L_{-})^{\dagger}-(L_{+}-\epsilon_1L_{-})^{\dagger}\right)\left(\vec{e_i}-\vec{e_j}\right)\\
	 	 	&=\left(\vec{e_i}-\vec{e_j}\right)^T\left(B^{-1}-A^{-1}\right)\left(\vec{e_i}-\vec{e_j}\right)\ge 0
	 	 \end{align*} 	
	 	 Note $\delta_{\epsilon_1}$ is non-increasing with respect to $\epsilon_1$ since the second smallest eigenvalue of $A$ is non-increasing and always positive with respect to $\epsilon_1<\epsilon_0$ and $\delta_{\epsilon_0}>0$.
	 	 So $\Omega_{\epsilon}^{\sigma}(i,j)$ is non-decreasing on every closed interval whose length is no more than $\delta_{\epsilon_0}$ in $(-\infty,\epsilon_0)$. By transitivity we know $\Omega_{\epsilon}^{\sigma}(i,j)$ is non-decreasing in $(-\infty,\epsilon_0)$.
	 \end{proof}

	 \section{Node and edge $\epsilon-$repelling curvature}
	  %If all triangular faces of a simplex with obtuse dihedral angles are acute, we say the simplex has "triangular acute" property. In the previous section, we have constructed the signed graph's simplex $\mathcal{S}_{\epsilon}$  with respect to $\epsilon-$repelling Laplacian. In this section, we pay attention to the signed graph whose simplex has "triangular acute" property. 


	  %	\begin{definition}
