	 \begin{proposition}
	 	Suppose $B$ is an arbitrary symmetric matrix, then 
	 	\[ \sum_{i,j\in V}\vec{e_i}^T(\Le)B(\Le)\vec{e_j}\Omega_{\epsilon}^{\sigma}(i,j)=-2\text{tr}\left((\Le)B\right) \]
	 \end{proposition}
	 \begin{proof}
	 	Note that
	 	\[ \Omega_{\epsilon}^{\sigma}(i,j)=\vec{e_i}^T(\Le)^{\dagger}\vec{e_i}+\vec{e_j}^T(\Le)^{\dagger}\vec{e_j}-2\vec{e_i}^T(\Le)^{\dagger}\vec{e_j} \]
	 	and since $(\Le)\vec{1}=0$
	 	\begin{align*}
	 		&\sum_{i,j\in V}\vec{e_i}^T(\Le)B(\Le)\vec{e_j}\vec{e_i}^T(\Le)^{\dagger}\vec{e_i}\\
	 		=&\sum_{i\in V}\vec{e_i}^T(\Le)B(\Le)\vec{1}\vec{e_i}^T(\Le)^{\dagger}\vec{e_i}=0\\
	 		&\sum_{i,j\in V}\vec{e_i}^T(\Le)B(\Le)\vec{e_j}\vec{e_j}^T(\Le)^{\dagger}\vec{e_j}\\
	 		=&\sum_{j\in V}\vec{1}^T(\Le)B(\Le)\vec{1}\vec{e_i}^T(\Le)^{\dagger}\vec{e_i}=0
	 	\end{align*}
	 	Then we have
	 	\begin{align*}
	 		&\sum_{i,j\in V}\vec{e_i}^T(\Le)B(\Le)\vec{e_j}\Omega_{\epsilon}^{\sigma}(i,j)\\
	 		=&-2\sum_{i,j\in V}\vec{e_j}^T(\Le)B(\Le)\vec{e_i}\vec{e_i}^T(\Le)^{\dagger}\vec{e_j}\\
	 		=&-2\text{tr}\left((\Le)B(\Le)(\Le)^{\dagger}\right)\\
	 		=&-2\text{tr}\left((\Le)(\Le)^{\dagger}(\Le)B\right)\\
	 		=&-2\text{tr}\left((\Le)B\right)		
	 	\end{align*} 	
	 \end{proof}

	Take $B$ as $(\Le)^{\dagger}$ into the above proposition, we get the following lemma.
	 \begin{lemma}\label{lemma2}
	 	\[ \sum_{i,j\in V}\left(w^{+}_{ij}-\epsilon w^{-}_{ij}\right)\Omega_{\epsilon}^{\sigma}(i,j)=2\left(|V(G)|-1\right) \]
	 \end{lemma}

	 Inspired by the method of defining node discrete curvature which was proposed by S.Steinerberger\cite{Steinerberger2017} through a distance matrix's equilibrium solution, though $\Omega_{\epsilon}^{\sigma}$ may not be distance matrix. We define the Steinerberger's curvature on positive connected signed graph with respect to $\epsilon-$repelling matrix as node $\epsilon-$repelling curvature. 

	  \begin{definition}
	  	Suppose $\Gamma=(G,\sigma,w)$ is a positive connected signed graph with $n$ vertices and $\epsilon_0$ is its consensus index. For any fixed $0<\epsilon<\epsilon_0$, we call the unique solution $\tau_{\epsilon}:V(G)\rightarrow \mathbb{R}^n$ of the following equation as node signed curvature:
	  	\[ \Omega_{\epsilon}^{\sigma}\tau_{\epsilon}=n\vec{1} \]
	  \end{definition}

	  The next proposition give an explicit expression of $\tau_{\epsilon}$ in terms of the edge weight and $\epsilon-$repelling
	  cost. 
	  \begin{proposition}\label{pro3}
	  	\[ \tau_{\epsilon}(i)=\phi_{\epsilon}\left(1-\frac{1}{2}\sum_{j\sim i}(w^{+}_{ij}-\epsilon w^{-}_{ij})\Omega_{\epsilon}^{\sigma}(i,j)\right) \]
	  	where $\phi_{\epsilon}=n\vec{1}^T(\Omega_{\epsilon}^{\sigma})^{-1}\vec{1}$
	  \end{proposition}

	 \begin{proof}
	 	From the matrix identity in Thm \ref{eq2}, we know
	 	\begin{align}
	 		\Omega_{\epsilon}^{\sigma}\vec{r}&=2R^2\vec{1} \label{equ3}\\
	 		-2\vec{r}\vec{1}^T+(\Le)\Omega_{\epsilon}^{\sigma}&=-2I \label{equ4} \\
	 		\vec{r}^T\vec{1}&=1
	 	\end{align}
	 	Equation (\ref{equ3}) implies 
	 	\[ \tau_{\epsilon}=\frac{n}{2R^2}\vec{r} \]
	 	and Equation (\ref{equ4}) implies
	 	\[ \vec{r}(i)=1-\frac{1}{2}\sum_{j\sim i}(w^{+}_{ij}-\epsilon w^{-}_{ij})\Omega_{\epsilon}^{\sigma}(i,j) \]
	 	By left multiplying the inverse of $\Omega_{\epsilon}^{\sigma} $ in two sides of Equation (\ref{equ3}) and then left multiplying $\vec{1}^T$, we have
	 	\[ 2R^2=\frac{1}{\vec{1}^T(\Omega_{\epsilon}^{\sigma})^{-1}\vec{1}} \]
	 	To sum up, we have
	 	\begin{align*}
	 		\tau_{\epsilon}(i)=\frac{n}{2R^2}\vec{r}(i)
	 		=n\vec{1}^T(\Omega_{\epsilon}^{\sigma})^{-1}\vec{1}\left(1-\frac{1}{2}\sum_{j\sim i}(w^{+}_{ij}-\epsilon w^{-}_{ij})\Omega_{\epsilon}^{\sigma}(i,j)\right)
	 	\end{align*}
	 \end{proof}

	 Combining Lemma \ref{lemma2} and Proposition \ref{pro3}, we have the following corollary.
	 \begin{corollary}\label{coro3}
	 \[ \sum_{i\in V}\tau_{\epsilon}(i)=\phi_{\epsilon} \]	
	 \end{corollary}

	 An automorphism $f$ on a signed graph $(G,\sigma,w)$ is an automorphism on its underlying graph $G$ and satisfies $\sigma_{f(x)f(y)}=\sigma_{xy}$ for any edge $(x,y)\in E(G)$. A signed graph $(G,\sigma,w)$ is called vertex transitive if any vertex $x,y$, there exists an automorphism $f$ such that $f(x)=y$.

	 \begin{proposition}
	 	If Suppose $(G,\sigma,w)$ is a positive-connected and vertex transitive signed graph, the node $\epsilon-$repelling curvature is constant.
	 \end{proposition}

	 \begin{proof}
	 	For any $i,j \in V$, let $f$ be the automorphism such that $f(i)=j$ and $P$ is the permutation matrix of $f$. Then we have 
	 	\begin{align*}
	 		P^T(\Le)P&=\Le\\
	 		\left(P^T(\Le)P\right)^{\dagger}&=(\Le)^{\dagger}\\
	 		P^T(\Le)^{\dagger}P&=(\Le)^{\dagger}
	 	\end{align*}
	 	Therefore, the diagonal entries of $(\Le)^{\dagger} $ are same. Indeed,
	 	\begin{align*}
	 		(\Le)^{\dagger}_{ii}&=\vec{e_i}^T(\Le)^{\dagger}\vec{e_i}\\
	 		&=\vec{e_i}^TP^T(\Le)^{\dagger}P\vec{e_i}\\
	 		&=\vec{e_j}^T(\Le)^{\dagger}\vec{e_j}\\
	 		&=(\Le)^{\dagger}_{jj}
	 	\end{align*}
	 Hence $P\zeta=\zeta$ where $\zeta$ be the vector consisting of the diagonal entries of $(\Le)^{\dagger}$.
	 As a result,
	 	\begin{align*}
	 		P^T\Omega_{\epsilon}^{\sigma}P=P^T\left(\vec{1}\zeta^T+\zeta\vec{1}^T-2(\Le)^{\dagger}\right)P&=\vec{1}\zeta^T+\zeta\vec{1}^T-2(\Le)^{\dagger}=\Omega_{\epsilon}^{\sigma}\\
	 		P^T\left(\Omega_{\epsilon}^{\sigma}\right)^{-1}P&=\left(\Omega_{\epsilon}^{\sigma}\right)^{-1}\\
	 		P\tau_{\epsilon}=nP\left(\Omega_{\epsilon}^{\sigma}\right)^{-1}P^TP\vec{1}&=n\left(\Omega_{\epsilon}^{\sigma}\right)^{-1}\vec{1}=\tau_{\epsilon}
	 	\end{align*}
	 	Thus, we know $\tau_{\epsilon}(i)=\tau_{\epsilon}(j)$ for any $i,j\in V$ and $\tau_{\epsilon}$ is constant.
	 \end{proof}

	\begin{definition}
		We denote by $W_{\epsilon}(G^{\sigma})$ the sum of $\epsilon-$repelling cost of all pairs of vertices on positive connected signed graph $(G,\sigma,w)$:
		\[ W_{\epsilon}(G^{\sigma})=\sum_{i<j}\Omega_{\epsilon}^{\sigma}(i,j) \]
		called as $\epsilon-$repelling graph resistance.
	\end{definition}

	 \begin{lemma}
	 	\[ W_{\epsilon}(G^{\sigma})=|V(G)|\sum_{k=2}^{|V(G)|}\frac{1}{\lambda_k^{(\epsilon)}}\]
	 	where $\left\{\lambda_k^{(\epsilon)}\right\}$ are the nonzero and non-decreasing eigenvalues of $\Le$.
	 \end{lemma}
	 \begin{proof}
	 	\begin{align*}
	 		W_{\epsilon}(G^{\sigma})&=\frac{1}{2}\sum_{i,j}\left(\vec{e_i}-\vec{e_j}\right)^T(\Le)^{\dagger}\left(\vec{e_i}-\vec{e_j}\right)\\
	 		&=|V(G)|\sum_{i\in V}\vec{e_i}^T(\Le)^{\dagger}\vec{e_i}- \vec{1}^T(\Le)^{\dagger}\vec{1}\\
	 		&=|V(G)|\text{tr}\left((\Le)^{\dagger}\right)
	 	\end{align*}
	 \end{proof}

	 \begin{corollary}\label{coro2}
	 	\[ \frac{|V(G)|}{\lambda_2^{(\epsilon)}}<W_{\epsilon}(G^{\sigma})\le \frac{|V(G)|\left(|V(G)|-1\right)}{\lambda_2^{(\epsilon)}} \]
	 \end{corollary}

	  Then we prove Theorem \ref{main4}  which shows a lower bound for $ \lambda_2^{(\epsilon)}$ on signed graphs with positive node signed curvature.

	 \begin{proof}[Proof of Theorem \ref{main4}]
	 	\begin{align*}
	 		W_{\epsilon}(G^{\sigma})&=\frac{1}{2}\sum_{i,j}\Omega_{\epsilon}^{\sigma}(i,j)\\
	 		&\le \frac{1}{2}\sum_{i,j}\Omega_{\epsilon}^{\sigma}(i,j)\frac{\tau(j)}{K_{\epsilon}}\\
	 		&=\frac{|V(G)|^2}{2K_{\epsilon}}
	 	\end{align*}
	 	Combine the left inequality of corollary \ref{coro2} with the above inequality, we finish the proof.
	 \end{proof}

	 \begin{proposition}
	 Suppose $\tau_{\epsilon}$ on positive connected signed graph $\Gamma$ is non-negative. Let $X_{\epsilon}, N_{\epsilon}$ be the maximal and minimal $\epsilon-$repelling cost among all pairs of signed resistance respectively, then
	 \[ X_{\epsilon}\le \frac{2|V(G)|}{\phi_{\epsilon}}, N_{\epsilon}\le \frac{|V(G)|}{\phi_{\epsilon}} \]
	 \end{proposition}

	 \begin{proof}
	 	Assume $X_{\epsilon}=\Omega_{\epsilon}^{\sigma}(i,j)$ and $ X_{\epsilon}\le \Omega_{\epsilon}^{\sigma}(i,k)+\Omega_{\epsilon}^{\sigma}(k,j)$ for any $k\in V$. Suppose 
	 	$\mu=\frac{1}{2}\left(1_{\left\{x=i\right\}}+1_{\left\{x=j\right\}}\right)$ is a probability measure assigning equal and nonzero mass to the two points $i,j$ and zero elsewhere and $h$ is the row index such that $\Omega_{\epsilon}^{\sigma}(i,k)+\Omega_{\epsilon}^{\sigma}(k,j)$ is minimal, using the Minimax theorem in \cite[Thm 4]{Steinerberger2017} and corollary \ref{coro3}, we know
	 	\[ \frac{1}{2}X_{\epsilon}\le \frac{1}{2}\left(\Omega_{\epsilon}^{\sigma}(i,h)+\Omega_{\epsilon}^{\sigma}(h,j)\right)\le \frac{|V(G)|}{\phi_{\epsilon}} \]
	 	Therefore, we finish the proof for the upper bound of $X_{\epsilon}$. Suppose $N_{\epsilon}=\Omega_{\epsilon}^{\sigma}(k,l)$, let $\gamma=1_{\left\{x=l\right\}}$ be the probability measure only supported at vertex $l$. Similarly we have the upper bound for $N_{\epsilon}$.	 	
	 \end{proof}

	 \begin{definition}
	 	Define $\vartheta_{\epsilon}$ as the edge $\epsilon-$repelling curvature on $(G,\sigma,w)$ as follows:
	 	\[ \vartheta_{\epsilon}(i,j):=\frac{2(\tau_{\epsilon}(i)+\tau_{\epsilon}(j))}{\Omega_{\epsilon}^{\sigma}}+(1+\epsilon)\Lambda_{\epsilon}(i,j)\]
	 	where \[\Lambda_{\epsilon}(i,j)=d_i^{-}\left(1-\frac{\sum_{k\in V}\Om(j,k)p^{-}_{ik}}{\Om(i,j)}\right)+d_j^{-}\left(1-\frac{\sum_{k\in V}\Om(i,k)p^{-}_{jk}}{\Om(i,j)}\right) \]
	 	and $p^{-}_{ik}=\frac{w_{ik}^{-}}{d_i^{-}}, p^{-}_{jk}=\frac{w_{jk}^{-}}{d_j^{-}}$ are the probability of random walk on negative edges adjacent to $i,j$.
	 \end{definition}

	 \begin{remark}
	 	 For a pair of adjacent vertices $i\sim j$, the term $\sum_{k\in V}\Om(j,k)p^{-}_{ik} $ can be regarded as signed resistance between $j$ and the "effective negative neighbor" of $i$ and the ratio difference $1-\frac{\sum_{k\in V}\Om(j,k)p^{-}_{ik}}{\Om(i,j)}$ measures how the negative edges influence the $\epsilon-$signed resistance.
	 \end{remark}

	 \begin{lemma}\label{lem4}
	 	Assume $N_t, M_t$ are random nodes distributed according to probability distribution $\rho_{t,i}:=\exp^{-Qt}\vec{e_i}$ and $\rho_{t,j}:=\exp^{-Qt}\vec{e_j}$ where $Q=L_{+}+L_{-}$ is the original Laplacian, then
	 	\[ \lim\limits_{t\rightarrow 0}\frac{1}{t}\left(1-\frac{\mathbb{E}(\Om(N_t,M_t))}{\Om(i,j)}\right)=\vartheta_{\epsilon}(i,j) \]
	 \end{lemma}
	 \begin{proof}
	 	From Equation (\ref{equ4}), we have 
	 	\[ \Om(\Le)+(\Le)\Om=2\left(\vec{1}\tau_{\epsilon}^T+\tau_{\epsilon}\vec{1}^T-2I\right) \]
	 	Since $Q=\Le+(1+\epsilon)L_{-}$, we can compute
	 	\begin{align*}
	 		\Om Q+Q\Om=2\left(\vec{1}\tau_{\epsilon}^T+\tau_{\epsilon}\vec{1}^T-2I\right)+(1+\epsilon)(\Om L_{-}+L_{-}\Om)
	 	\end{align*}
	 	Next we write $\mathbb{E}(\Om(N_t,M_t)) $ as follows:
	 	\begin{align*}
	 		\mathbb{E}(\Om(N_t,M_t))&=\sum_{k,l\in V}\vec{e_i}^T\exp^{-Qt}\vec{e_k}\Om(k,l)\vec{e_l}^T\exp^{-Qt}\vec{e_j}\\
	 		&=\vec{e_i}^T\exp^{-Qt}\Om\exp^{-Qt}\vec{e_j}\\
	 		&=\vec{e_i}^T(I-tQ+O(t^2))\Om(I-tQ+O(t^2))\vec{e_j}\\
	 		%&=\vec{e_i}^T\left(\Om-2t\left(\vec{1}\tau^T+\tau\vec{1}^T-2I\right)-t(1+\epsilon)(\Om L_{-}+L_{-}\Om)\right)\vec{e_j}\\
	 		&=\Om(i,j)-2t\left(\tau_{\epsilon}(i)+\tau_{\epsilon}(j)\right)-t\left(1+\epsilon\right)\Om(i,j)(d_i^{-}+d_{j}^{-})\\
	 		&+t\left(1+\epsilon\right)\left(\sum_{k\in V}\Om(i,k)w_{kj}^{-}+\sum_{l\in V}\Om(j,l)w_{li}^{-}\right)+O(t^2)
	 	\end{align*}
	 	Therefore,
	 	\begin{align*}
	 		&\lim\limits_{t\rightarrow 0}\frac{1}{t}\left(1-\frac{\mathbb{E}(\Om(N_t,M_t))}{\Om(i,j)}\right)\\
	 		=&\frac{2(\tau_{\epsilon}(i)+\tau_{\epsilon}(j))}{\Omega_{\epsilon}^{\sigma}}+(1+\epsilon)(d_i^{-}+d_{j}^{-})-\left(1+\epsilon\right)\left(\sum_{k\in V}\frac{\Om(i,k)}{\Om(i,j)}w_{kj}^{-}+\sum_{l\in V}\frac{\Om(j,l)}{\Om(i,j)}w_{li}^{-}\right)\\
	 		=&\vartheta_{\epsilon}(i,j)
	 	\end{align*}
	 \end{proof}

	Let $\kappa^{(LLY)}$ be the Lin-Lu-Yau Ricci curvature\cite{lin2011ricci} with respect to $\epsilon-$repelling cost $\Om(i,j)$ on $G$. That is,
	  \[ \kappa^{(LLY)}(i,j)=\lim\limits_{\alpha\rightarrow 0}\frac{1}{\alpha}\left(1-\frac{W\left(m_i^{\alpha},m_j^{\alpha}\right)}{\Om(i,j)}\right) \] 
	 where $m_i^{\alpha}, m_j^{\alpha}$ are the probability distributions of lazy random walk on $G$, defined as follows:
	 \begin{align*}
	 	m_i^{\alpha}(l)=
	 	\begin{cases}
	 		&1-\alpha d_i \quad \text{if}\quad l=i\\
	 		&\alpha w_{il}\quad \text{if}\quad l\sim i\\
	 		&0\quad \text{otherwise}
	 	\end{cases}
	 	\quad
	 	m_j^{\alpha}(l)=
	 	\begin{cases}
	 		&1-\alpha d_j \quad \text{if}\quad l=j\\
	 		&\alpha w_{jl} \quad \text{if}\quad l\sim j\\
	 		&0\quad \text{otherwise}
	 	\end{cases}
	 \end{align*}
	 You can find $m_i^{\alpha}=(I-\alpha Q)\vec{e_i}, m_j^{\alpha}=(I-\alpha Q)\vec{e_j}$. The optimal transport cost $$W(m_i^{\alpha},m_j^{\alpha})=\inf\limits_{\Pi}\sum_{k,l\in V}\Pi(k,l)\Om(k,l)$$ is the minimal with respect to the transport plans $\Pi$ satisfying $$ \sum_{k\in V}\Pi(k,l)=m_j^{\alpha}(l), \sum_{l\in V}\Pi(k,l)=m_i^{\alpha}(k)$$
	  Then using the above lemma, we can compare $\kappa^{(LLY)}(i,j)$ with $\vartheta_{\epsilon}(i,j)$.


	 \begin{proof}[Proof of Theorem \ref{thmv}]
	 	Obviously, $A(k,l):=m_i^{\alpha}(k)m_j^{\alpha}(l) $ is a transport plan satisfying 
	 	$$ \sum_{k\in V}A(k,l)=m_j^{\alpha}(l)\quad \sum_{l\in V}A(k,l)=m_i^{\alpha}(k)$$ Thus, we have
	 	\[ W(m_i^{\alpha},m_j^{\alpha})\le \sum_{k,l\in V}A(k,l)\Om(k,l)=\vec{e_i}^T(I-Qt)\Om(I-Qt)\vec{e_j} \]
	 	Recall \[ \mathbb{E}(\Om(N_t,M_t))=\vec{e_i}^T(I-tQ)\Om(I-tQ)\vec{e_j}+O(t^2) \]
	 	Then we know 
	 	\[ \lim\limits_{t\rightarrow 0}\frac{1}{t}\left(1-\frac{\mathbb{E}(\Om(N_t,M_t))}{\Om(i,j)}\right)\le \lim\limits_{t\rightarrow 0}\frac{1}{t}\left(1-\frac{W(m_i^{\alpha},m_j^{\alpha})}{\Om(i,j)}\right)=\kappa^{(LLY)}(i,j) \]
	 	By Lemma \ref{lem4}, we have
	 	\[  \vartheta_{\epsilon}(i,j)\le \kappa^{(LLY)}(i,j) \]
	 \end{proof}

	 The Lin-Lu-Yau curvature $\kappa^{(LLY)}$ is based on the lazy random walk whose probability transition matrix is $P_t:=I-tQ$. The next lemma is concerned with the mixing rate of the lazy random walk.
	 \begin{lemma}\label{mix}
	 	Assume $G$ is finite with $|V|=n$ and $Q=D-A$ is its Laplacian. Let $d_{\text{max}}$ be the maximal degree of $G$. Then for any $0<t<\frac{1}{2d_{\text{max}}}$ and $n\in \mathbb{N}$, 
	 	\[ ||P_t^nf-\bar{f}||_2\le \rho^n||f||_2 \: ,\forall f:V\rightarrow \mathbb{R}\]
	 	where $\bar{f}=\frac{\sum_{x\in V}f(x)}{n}$, $\rho=1-t\mu_2$ is called the mixing rate of lazy random walk and $\mu_2$ is the minimal nonzero eigenvalue of $Q$.
	 \end{lemma}

	 \begin{proof}
	 	It's known that the maximal eigenvalue of $Q$ is no more than $2d_{\text{max}}$. So the eigenvalues of $P_t$ is positive if $0<t<\frac{1}{2d_{\text{max}}}$. Assume $\alpha_1\le \alpha_2\le\cdots\le \alpha_n=1$ are the eigenvalues of $P_t$ and $\{f_k\}_{k=1}^n$ are the orthonormal eigenfunctions satisfying $P_tf_k=\alpha_kf_k$. Note $f_n$ is constant and $f_n\equiv \frac{1}{\sqrt{n}}$. For any $f:V\rightarrow \mathbb{R}$, we write it as:
	 	\[ f=\sum_{k=1}^{n}(f,f_k)f_k \]
	 	Thus,
	 	\begin{align*}
	 		P_tf=\sum_{k=1}^{n}\alpha_k(f,f_k)f_k
	 	\end{align*}
	 	Then
	 	\begin{align*}
	 		P_t^nf&=\sum_{k=1}^{n}\alpha_k^n(f,f_k)f_k\\
	 		&=\frac{\sum_{x\in V}f(x)}{n}+\sum_{k=1}^{n-1}\alpha_k^n(f,f_k)f_k\\
	 		&=\bar{f}+\sum_{k=1}^{n-1}\alpha_k^n(f,f_k)f_k
	 	\end{align*}
	 	Therefore,
	 	\begin{align*}
	 	||P_t^nf-\bar{f}||_2^2&=||\sum_{k=1}^{n-1}\alpha_k^n(f,f_k)f_k||_2^2\\
	 	&=\sum_{k=1}^{n-1}\alpha_k^{2n}(f,f_k)^2\\
	 	&\le \alpha_{n-1}^{2n}||f||_2^2
	 	\end{align*}
	 	equivalent to
	 	\[ ||P_t^nf-\bar{f}||_2\le \alpha_{n-1}^n||f||_2=(1-t\mu_2)^n||f||_2 \]
	 \end{proof}

	 \begin{proof}[Proof of Theorem \ref{main5}]
	 	As a result of Theorem \ref{thmv}, we have
	 	\[ \kappa^{(LLY)}(i,j)\ge \vartheta_{\epsilon}(i,j)\ge k_{\epsilon} \]
	 	Since $G$ is finite, for any $\delta>0$, there exists $t_0>0$ satisfying:
	 	 \[ \frac{1}{t}\left(1-\frac{W(m_i^{t},m_j^{t})}{\Om(i,j)}\right)\ge (1-\delta)k_{\epsilon}, \quad \forall t\in (0,t_0) \]
	 	equivalent to
	 	\[ W(m_i^{t},m_j^{t})\le \left(1-\left(1-\delta\right)k_{\epsilon}t\right)\Om(i,j), \quad \forall t\in (0,t_0) \]
	 	From Kantorovich duality in \cite{villani2008optimal}, we know
	 	\[ W(m_i^{t},m_j^{t})=\sup\limits_{\Phi_{\epsilon}}\left\{ \sum_{x\in V} \phi(x)m_i^{t}(x)+\sum_{y\in V} \psi(y)m_j^{t}(y)\right\} \] 
	 	where the set $\Phi_{\epsilon}$ consists of all the pairs $(\phi,\psi)$ satisfying
	 	\[ \phi(x)+\psi(y)\le \Om(x,y), \quad \forall x,y \in V \]
	 	For any $k>0$ and assume $\phi:V\rightarrow \mathbb{R}$ satisfies $|\phi(x)-\phi(y)|\le k\Om(x,y), \quad \forall x,y \in V$, since $(\frac{\phi}{k},-\frac{\phi}{k}), (-\frac{\phi}{k},\frac{\phi}{k})\in \Phi_{\epsilon}$, 
	 	\begin{align*}
	 		W(m_i^{t},m_j^{t})&\ge \frac{1}{k}|\sum_{x\in V}\phi(x)\left(m_i^{t}(x)-m_j^{t}(x)\right)|\\
	 		&=|\left(I-tQ\right)\phi(i)-\left(I-tQ\right)\phi(j)|
	 	\end{align*}
	 Thus,
	 \[ |\left(I-tQ\right)\phi(i)-\left(I-tQ\right)\phi(j)|\le k\left(1-\left(1-\delta\right)k_{\epsilon}t\right)\Om(i,j) \]
	 Then for any $n\ge 1$,
	 \begin{align*}
	 	|\left(I-tQ\right)^n\phi(i)-\left(I-tQ\right)^n\phi(j)|&\le k\left(1-\left(1-\delta\right)k_{\epsilon}t\right)^n\Om(i,j)\\
	 	\sqrt[n]{|\left(I-tQ\right)^n\phi(i)-\left(I-tQ\right)^n\phi(j)|}&\le \sqrt[n]{k\Om(i,j)}\left(1-\left(1-\delta\right)k_{\epsilon}t\right)
	 \end{align*}
	 Let $n\rightarrow \infty$, we have
	 \[ \limsup_{n\rightarrow \infty}\sqrt[n]{|\left(I-tQ\right)^n\phi(i)-\left(I-tQ\right)^n\phi(j)|}\le 1-\left(1-\delta\right)k_{\epsilon}t \]
	 On the other hand, consider the mixing rate of $I-tQ$ and use Lemma \ref{mix}, for any $\phi:V\rightarrow \mathbb{R}$ we have :
	\begin{align*}
		|\left(I-tQ\right)^n\phi(i)-\left(I-tQ\right)^n\phi(j)|&\le |\left(I-tQ\right)^n\phi(i)-\bar{\phi}|+|\left(I-tQ\right)^n\phi(j)-\bar{\phi}|\\
		&\le ||\left(I-tQ\right)^n\phi-\bar{\phi}||\\
		&\le (1-t\mu_2)^n||\phi||_2
	\end{align*}
	Then
	\[ \limsup_{n\rightarrow \infty}\sqrt[n]{|\left(I-tQ\right)^n\phi(i)-\left(I-tQ\right)^n\phi(j)|}\le 1-t\mu_2\]
	Since $1-t\mu_2$ is the mixing rate, we have
	\[ 1-t\mu_2\le 1-\left(1-\delta\right)k_{\epsilon}t \]
	equivalent to
	\[ \mu_2\ge \left(1-\delta\right)k_{\epsilon} \]
 Let $\delta\rightarrow 0$, we have
 \[ \mu_2\ge k_{\epsilon} \]
	 \end{proof}
	 \section{Some examples}
	 \subsection{positive connected signed cycle}
	 Consider positive connected signed cycle $(C_n,\sigma_n)$ with simple weight, there exist only two cases. The first is trivial, that is $\sigma_n\equiv 1$ which means no negative edges. Since $L_{-}$ is zero, $\Om(\cdot,\cdot)$ is equal to resistance distance on the underlying graph $C_n$ for any $\epsilon$.  The other is that $(C_n,\sigma_n)$ consists of the positive subgraph $P_n$ and the negative subgraph $P_2$ where $P_n$ is path graph with $n$ vertices. 

	 We assume $\sigma_n$ takes $-1$ at the edge $(1,n)$ and $1$ at other edges and compute the consensus index $\epsilon_0$ as well as the signed node curvature and edge curvature for several values of $\epsilon $ smaller than $\epsilon_0$ when $n=3, 4$.

	 \paragraph*{\textbf{The consensus index of $(C_3,\sigma_3)$ is $\epsilon_0=0.5$}:} $\tau_{\epsilon}(1)=\tau_{\epsilon}(3)$ since vertices $1$ and $3$ can be transitive to each other. We can get  $\Lambda_{\epsilon}(1,2)=\Lambda_{\epsilon}(2,3)=0$ and $\Lambda_{\epsilon}(1,3)=2$ easily. 
