	 \subsection{positive connected signed complete graph}
	The positive subgraph of a positive connected signed complete graph $(K_n,\sigma_n)$ must contain some spanning tree and the number of the complete graph's spanning trees is $n^{n-2}$. So you can image the number of non-isomorphic $(K_n,\sigma_n)$ is also large when $n$ is large. Here, we enumerate several non-isomorphic signed graph structures of $K_4$ and also compute the node and edge curvatures on them.

	\paragraph*{\textbf{The case of one negative edge:}} Let $\sigma_4$ take $-1$ at $(1,4)$ and $1$ at other edges. The consensus index $\epsilon_0$ is $0.9999$. Take $\epsilon$ as $0.5$. Then we compute $\tau_{\epsilon}(1)=\tau_{\epsilon}(4)=2.4242, \tau_{\epsilon}(2)=\tau_{\epsilon}(3)=-0.4848$. Since $\Lambda_{\epsilon}(\cdot,\cdot) $ takes nonzero values only at $(1,4)$ and $\Lambda_{\epsilon}(1,4)=2$, we compute $\vartheta_{\epsilon}(1,2)=\vartheta_{\epsilon}(3,4)=\vartheta_{\epsilon}(4,2)=\vartheta_{\epsilon}(3,1)=4.4329, \vartheta_{\epsilon}(2,3)=-3.8784, \vartheta_{\epsilon}(1,4)=7.8484$.


	\paragraph*{\textbf{The case of two negative edges:}} 
	\begin{itemize}
		\item Let $\sigma_4$ take $-1$ at $(1,3), (2,4)$ and $1$ at other edges. The consensus index $\epsilon_0$ is $1$. Take $\epsilon$ as $0.5$. We compute $\tau_{\epsilon}(1)=\tau_{\epsilon}(2)=\tau_{\epsilon}(3)=\tau_{\epsilon}(4)=0.8889$. Since $\Lambda_{\epsilon}(1,3)=\Lambda_{\epsilon}(2,4)=2$ and $\Lambda_{\epsilon}$ is zero on other edges, we compute $\vartheta_{\epsilon}(1,2)=\vartheta_{\epsilon}(2,3)=\vartheta_{\epsilon}(3,4)=\vartheta_{\epsilon}(1,4)=2.8445;\vartheta_{\epsilon}(1,3)=\vartheta_{\epsilon}(2,4)=4.7778$.

		\item Let $\sigma_4$ take $-1$ at $(1,3), (1,4)$ and $1$ at other edges. The consensus index $\epsilon_0$ is $0.333$. Take $\epsilon$ as $0.1$. We compute $\tau_{\epsilon}(1)=1.7436, \tau_{\epsilon}(2)=-1.1454, \tau_{\epsilon}(3)=\tau_{\epsilon}(4)=1.1819$. Since $\Lambda_{\epsilon}(1,3)=\Lambda_{\epsilon}(1,4)=2.7021, \Lambda_{\epsilon}(2,3)=\Lambda_{\epsilon}(2,4)=-0.7286, \Lambda_{\epsilon}(1,2)=0.843, \Lambda_{\epsilon}(3,4)=-4.7139$ , we compute $\vartheta_{\epsilon}(1,3)=\vartheta_{\epsilon}(1,4)=5.4994,    \vartheta_{\epsilon}(2,3)=\vartheta_{\epsilon}(2,4)=-0.7033, \vartheta_{\epsilon}(1,2)=1.8578, \vartheta_{\epsilon}(3,4)=1.6693$.
	\end{itemize}

	\paragraph*{\textbf{The case of three negative edges:}}  
	\begin{itemize}
		\item Let $\sigma_4$ take $1$ at $(1,3), (1,4), (2,3)$ and $-1$ at other edges. The consensus index $\epsilon_0$ is $0.1715$. Take $\epsilon$ as $0.1$. Since $\Lambda_{\epsilon}(1,2)=\Lambda_{\epsilon}(3,4)=-6.1347, \Lambda_{\epsilon}(1,4)=\Lambda_{\epsilon}(2,3)=2.6556, \Lambda_{\epsilon}(1,3)=3.9994, \Lambda_{\epsilon}(2,4)=0.3492$, we can compute:
		\begin{align*}
			\tau_{\epsilon}(1)=\tau_{\epsilon}(3)=0.8344, &\tau_{\epsilon}(2)=\tau_{\epsilon}(4)=-0.3457\\
			\vartheta_{\epsilon}(1,2)=\vartheta_{\epsilon}(3,4)=-6.0546,& \vartheta_{\epsilon}(1,4)=\vartheta_{\epsilon}(2,3)=3.16\\ \vartheta_{\epsilon}(1,3)=4.8712, & \vartheta_{\epsilon}(2,4)=-0.4258
		\end{align*}
		\item Let $\sigma_4$ take $-1$ at $(1,2), (1,3), (1,4)$ and $1$ at other edges. The consensus index $\epsilon_0$ is $0.3333$. Take $\epsilon$ as $0.1$. Since $\Lambda_{\epsilon}(1,2)=\Lambda_{\epsilon}(1,3)=\Lambda_{\epsilon}(1,4)=0, \Lambda_{\epsilon}(2,3)=\Lambda_{\epsilon}(2,4)=\Lambda_{\epsilon}(3,4)=2$, we can compute:
		\begin{align*}
			\tau_{\epsilon}(1)=-1.4979, &\tau_{\epsilon}(2)=\tau_{\epsilon}(3)=\tau_{\epsilon}(4)=1.037\\
			\vartheta_{\epsilon}(1,2)=&\vartheta_{\epsilon}(1,3)=\vartheta_{\epsilon}(1,4)=-0.717\\ \vartheta_{\epsilon}(2,3)=&\vartheta_{\epsilon}(2,4)=\vartheta_{\epsilon}(3,4)=3.6518
		\end{align*}

	\end{itemize}
