\begin{prop} Let $X=\{x_i\}$ be a finite $T_0$-space. Then $x_i\prec x_j$ if and only if $r_i+c_j^\intercal =(p_1,\cdots,p_n)$ where $p_{i}=p_j=0$ and $p_{k}\neq 0$ for every $k\neq i,j$.
\end{prop}
\begin{proof}
Suppose $x_i\prec x_j$. Then $x_{i,j}=0$ and $p_j=x_{i,j}+x_{j,j}=x_{i,i}+x_{i,j}=p_i=0$. If $x_{i,k}+x_{k,j}=0$ for some $k\neq i,j$, then $x_i<x_k$ and $x_k<x_j$, which contradicts $x_i\prec x_j$.

If $r_i+c_j^\intercal=(p_1,\cdots,p_n)$ where $p_{i}=p_j=0$ and $p_{k}\neq 0$ for every $i\neq j$, then $x_{i,j}+x_{j,j}=x_{i,i}+x_{i,j}=0$ and $x_{i,k}+x_{k,j}\neq 0$ for every $k\neq i,j$. Hence, $x_i<x_j$ and there is no $k\neq i,j$ such that $x_i\leq x_k\leq x_j$.
\end{proof}


\begin{prop} Let $X=\{x_i\}$ be a finite topological space and $X_M^2=({m}_{i,j})$. Then $m_{i,j}=|\hat{F}_{x_j}\cap \hat{U}_{x_i}|+|\hat{U}_{x_i}\cap X\setminus C_{x_j}|+|\hat{F}_{x_j}\cap X\setminus C_{x_i}|+|X\setminus C_{x_i}\cup C_{x_j}|$ and $n-m_{i,j}=|F_{x_i}\cup U_{x_j}|$.
\end{prop}
\begin{proof}
We prove the first property, the second property may be deduced from the first one. Define $K_{i,j}=\{1\leq k\leq n|x_{i,k}=x_{k,j}=1   \}$, so $m_{i,j}=|K_{i,j}|$. Let us consider $k\in K_{i,j}$. Since $x_{i,k}=1$ we get $x_i>x_k$ or $x_i\notin C_{x_k}$. Similarly, $x_{k,j}=1$ implies that $x_k>x_j$ or $x_k\notin C_{x_j}$. Hence, 
$$|K_{i,j}|= |\hat{F}_{x_j}\cap \hat{U}_{x_i}|+|\hat{U}_{x_i}\cap X\setminus C_{x_j}|+|\hat{F}_{x_j}\cap X\setminus C_{x_i}|+|X\setminus C_{x_i}\cup C_{x_j}|.$$
\end{proof}
We can argue analogously to achieve a similar result using the transpose.
\begin{prop} Let $X=\{x_i\}$ be a finite $T_0$-space. 
\begin{itemize}
\item  If  $X_MX_M^\intercal=(m_{i,j})$. Then
$m_{i,j}=|\hat{U}_{x_i}\cap \hat{U}_{x_j}|+|\hat{U}_{x_i}\cap X\setminus C_{x_j}|+ |\hat{U}_{x_j}\cap X\setminus C_{x_i}|+|X\setminus C_{x_i}\cup C_{x_j}|$
and $n-m_{i,j}=|F_{x_i}\cup F_{x_j}|. $
\item If $X_M^\intercal X_M=(m_{i,j})$, then 
$m_{i,j}=|\hat{F}_{x_i}\cap \hat{F}_{x_j}|+|\hat{F}_{x_i}\cap X\setminus C_{x_j}|+ |\hat{F}_{x_j}\cap X\setminus C_{x_i}|+|X\setminus C_{x_i}\cup C_{x_j}|$
and $n-m_{i,j}=|U_{x_i}\cup U_{x_j}|. $
\end{itemize}
\end{prop}

Every matrix of $\mathcal{M}'$ can also be interpreted as the adjacency matrix of a digraph without loops, which we denote by $G_X$. Furthermore, we can derive a version of Theorem \ref{thm:matrices_grafos} for digraphs.  Let $\mathcal{G}$ be the set of all digraphs $G=(V,E)$ up to isomorphism such that:
\begin{enumerate}
\item There are no loops.
\item If $\{x,y\}\notin E$, then $\{y,x\}\in E$ for every $x,y\in V$.
\item If $\{x,y\},\{y,z \}\notin E$, then $\{x,z\}\notin E$  for every $x,y,z\in V$. 
\end{enumerate}

\begin{thm} The set of homeomorphism classes of finite topological spaces are in one-to-one correspondence with $\mathcal{G}$.
\end{thm}
