\section{Invariants}\label{sec:invariantes}
In this section, we examine the relationships between invariants of matrices and homotopy.
\subsection{Determinant}
Given a finite $T_0$-space $X$ and $X_M$, we characterize the beat points of $X$ in terms of the rows or columns of $X_M$.
\begin{thm}\label{thm_beat_points} Let $X=\{ x_i\}$ be a finite $T_0$-space. Then $x_i$ is an up (down) beat point if and only if there exists a row $r_j$ (column $c_j$) in $X_M$ such that $r_i-r_j=-e_i$ ($c_i-c_j=-e_i$) for some $1\leq j \leq n$. 
\end{thm}
\begin{proof}
Let us suppose that $x_i$ is an up beat point, so $\hat{F}_{x_i}$ has a minimum that we denote by $x_j$. We study cases: (i) If $x_{j,k}=0$ with $k\neq i$, then $x_j\in U_{x_k}$ so $x_i\in U_{x_k}$ and $x_{i,k}=0$ (ii) If $x_{j,k}=1$ with $k\neq i$ and  $x_{i,k}=0$, then $x_j\notin U_{x_k}$ and $x_i\in U_{x_k}$. This means that $x_i< x_k,x_j$ and $x_j\nleq x_k$, but the definition of up beat point implies that $x_i<x_j<x_k$, which entails the contradiction. Therefore, $x_{j,k}=1$ with $k\neq i$ implies $x_{i,k}=1$ (iii) By hypothesis $x_{ii}=0$ and $x_{j,i}=1$ since  $x_i\in U_{x_i}$ and $x_j\notin U_{x_i}$. Thus, $r_i-r_j=-e_i$. 

%Suppose now that $x_i$ is a down beat point, which means that $\hat{U}_{x_i}$ has a maximum that we denote by $x_j$. We study cases: (i) If $x_{ki}=0$ with $k\neq j$, then $x_k\in U_{x_i}$. Clearly $x_k< x_i<x_j$, so $x_{kj}=0$ (ii) If  $x_{ki}=1$ with $k\neq j$ and $x_{kj}=0$, then $x_k\notin U_{x_i}$ and $x_k\in U_{x_j}$. However, $x_k< x_j< x_i$ and we get a contradiction with $x_k\in U_{x_i}$ (iii) By hypothesis $x_{ij}=1$ and $x_{ii}=0$. Thus, $c_i-c_j=-e_i$.

Consider that there are two rows $r_i$ and $r_j$ satisfying $r_i-r_j=-e_i$. Therefore, $r_i$ and $r_j$ are not equal in the $i$-th coordinate, i.e., $x_{i,k}=x_{j,k}$ for every $k\neq i$ and $x_{j,i}=1$. On the other hand, $x_i<x_j$ because $x_{j,j}=0$ and $x_{i,j}-x_{j,j}=0$. We argue by contradiction, suppose there exists $x_k$ with $x_i<x_k<x_j$. Then $x_{j,k}=1$ and $x_{i,k}=0$, which gives the contradiction. This gives that $\hat{F}_{x_i}$ has a minimum given by $x_j$.

%Similarly, consider two columns $c_i$ and $c_j$ satisfying $c_i-c_j=-e_i$. Hence, $x_{ki}=x_{kj}$ for every $k\neq i$, $x_{ij}=1$ ($-1=x_{ii}-x_{ij}$) and $x_{ji}=0$ ($0=x_{ji}-x_{jj}$). Subsequently, $x_j<x_i$. If there exists $x_k$ with $x_j<x_k<x_i$, then $x_{kj}=1$ and $x_{ki}=0$, which entails a contradiction with $c_i-c_j=-e_i$. Thus, $\hat{U}_{x_i}$ has a maximum given by $x_j$. 
The other case of the result follows immediately from these arguments, Remark \ref{rem:up_son_down_opuesto} and Proposition \ref{prop:orden_opuesto_matriz}.
\end{proof}
As an immediate consequence of this result, we obtain:
\begin{cor} Let $X$ be a finite $T_0$-space. If  $c_i-c_j\neq -e_i$ and $r_i-r_j\neq -e_i$ for every $1\leq i,j\leq n$, then $X$ is not contractible .
% Then $X_M$ is not contractible if $|C(X)_i-C(X)_j|\neq 2\neq |R(X)_i-R(X)_j|$ for every $1\leq i,j\leq n$.
\end{cor}


\begin{rem} Suppose that $X=\{x_i\}$ is a finite  $T_0$-space. If $X$ has a minimum or maximum, then $\det (X_M)=0$. 
\end{rem}

\begin{cor}\label{cor:quitarbeatpoint_homotopy} Let $X$ be a finite $T_0$-space and $x_i\in X$ a beat point. Then $\det (X)=-\det (X\setminus x_i)$.
\end{cor}
\begin{proof}
Suppose that $x_j$ is the minimum (maximum) of $\hat{F}_{x_i}$ ($\hat{U}_{x_i}$). By Theorem \ref{thm_beat_points}, subtracting the $j$-row (column) from the $i$-row (column) and using the Laplace expansion along the $i$-row (column) one gets $\det (X)=-\det (X\setminus x_i)$. 
\end{proof}


\begin{cor}\label{cor:contractible_implies_determinant_zero} Let $X$ and $Y$ be finite $T_0$-spaces.
\begin{enumerate}
\item If $X$ and $Y$ are minimal finite spaces and $X$ is homotopy equivalent to $Y$, then $\det(X)=\det(Y)$.
\item If $X$ is homotopy equivalent to $Y$, then $|\det (X)|=|\det (Y)|$.
\item If $X$ is contractible, then $\det(X)=0$.
\end{enumerate}
\end{cor}


