\subsection{Product of posets with lexicographic order}
Let $X$ and $Y$ be finite $T_0$-spaces. Then the lexicographic order of $X\times Y$ is given by $(x,y)\leq (x',y')$ if and only if $x\leq x'$, or $x=x'$ and $y\leq y'$. We denote to this poset by $X\times_L Y$.
\begin{thm}[Lexicographic order] Let $X$ and $Y$ be finite $T_0$-spaces such that $|X|=n$ and $|Y|=m$. Then $(X\times_L Y)_M$ is $X_M\otimes Y_M$, where $\otimes$ denotes the Kronecker product using the rule: $x_{ij}Y_M=0_{m\times m}$ if $x_{ij}=0$ and $i\neq j$, $x_{ii}Y_M=Y_M$ and $x_{ij}Y_M=1_{m\times m}$ if $x_{ij}=1$.
\end{thm}
\begin{proof}
We can proceed as we did in the proof of Proposition \ref{prop:product}. We use the same notation for the elements of $X\times_L Y$. The block $A_{i,j}=\{z_{kl}\}$ (of dimension $m \times m$) of $(X\times Y)_M$ with $(i-1)m< k\leq im$ and $(j-1)m< l\leq jm$ for some $i,j=1,...,n$ represents the relations between the points $(x_i,y_s)$ and $(x_j,y_d)$ where $s,d=1,...,m$. Then $A_{i,j}=0_{m\times m}$ if $x_{ij}=0$ and $i\neq j$,  $A_{i,j}=Y_M$ if $i=j$, and $A_{i,j}=1_{m\times m}$ if $x_{ij}=1$. 
\end{proof}
\begin{cor} Let $X$ be a totally ordered set. Then for any finite $T_0$-space $Y$, $\det(X\times_L Y)=\det(Y)^{|X|}$.
\end{cor}

\begin{cor}\label{cor:esfera_con_otro_lex} Let $S^n$ be the minimal finite model of the $n$-dimensional sphere. Suppose $Y$ is a finite $T_0$-space with $m$ points satisfying $\det(Y)\neq 0$. Then $\det(X\times_L Y)=[\det(Y_M)^2(1-1_{1\times m}Y_M^{-1}1_{m\times 1})]^{n+1}$.
\end{cor}
\begin{proof}
$S^n\times_L Y$ is a block diagonal matrix whose block diagonals are of the form $$A=\begin{pmatrix}
Y_M  & 1_{m\times m}\\
1_{m\times m}  & Y_M
\end{pmatrix}. $$
Therefore, $\det(A)=\det(Y_M+1_{m \times m})\det(Y_M-1_{m\times m})=\det(Y_M)^2(1-1_{1\times m}Y_M^{-1}1_{m\times 1})$ and we get the result.

\end{proof}
\begin{cor} Let $S^n$ and $S^m$ be finite models of spheres. Then $\det(S^n\times_L S^m)$ is equal to $1$ if $m$ is odd and equal to $(-3)^{n+1}$ if $m$ is even
\end{cor}
\begin{proof}
Repeating similar arguments than the ones used in the proof of Corollary \ref{cor:esfera_con_otro_lex} we may deduce that $\det(S^n\times_L S^m)=\det(S^m_M-1)^{n+1}\det(S^m_M+1)^{n+1}=\det(S^m_M+1)^{n+1}$, which is equal to $1$ if $m$ is odd and equal to $(-3)^{n+1}$ if $m$ is even.
\end{proof}

\subsection{Mapping cylinder}
Let $f:X\rightarrow Y$ be a continuous map between finite $T_0$-spaces. The mapping cylinder $B(f)$ is defined as $X\sqcup Y$ keeping the given ordering within $X$ and $Y$ and for $x\in X$, $y\in Y$ setting $x\leq y$ in $B(f)$ if $f(x)\leq y$ in $Y$. Notice that $Y$ is a strong deformation retract of $B(f)$ (see \cite[Lemma 2.8.2]{barmak2011algebraic})
\begin{thm}[Mapping cylinder]\label{prop:MAPPING} Let $X$ and $Y$ be finite $T_0$-spaces such that $|X|=n$ and $|Y|=m$. Suppose $f:X\rightarrow Y$ is a continuous map. Then $B(f)_M$ is 
$$\begin{pmatrix}
X_M & A\\
 1_{m\times n}   & Y_M
\end{pmatrix}, $$
where $A$ is a matrix of dimension $n\times m$ satisfying that its $i$-th row is the $j$-th row of $Y_M$ if $f(x_i)=y_j$. 
\end{thm}
\begin{proof}
Set $B(f)=\{z_i\}_{i=1,...,n+m}$ where $z_i=x_i\in X$ if $1\leq i\leq n$ and $z_i=y_{i-n}\in Y$ if $n<i\leq n+m$. By construction it is clear that we only need to justify the matrix $A$. Suppose that $z_i\leq z_k$ where $i\leq n$ and $n<k\leq n+m$. This means that $f(z_i)=z_j\leq z_k$ for some $n<j\leq n+m$, which gives that $r_{ik}=\{z_{ik}|n+1\leq k\leq n+m\}$ is equal to the $j$-th row of $Y_M$.
\end{proof}


\begin{cor} Let $f:X\rightarrow Y$ be a continuous map between finite $T_0$-spaces. Then $\det (B(f))=\pm  \det (Y)$.
\end{cor}
\begin{proof}
We know the matrix of $B(f)$ by Proposition \ref{prop:MAPPING}. For each $1\leq i\leq n$, we subtract the $j$-th row from the $i$-th row where $f(x_i)=y_j$. The resulting matrix is 
$$\begin{pmatrix}
X_M-1_{n\times n} & 0_{n\times m}\\
1_{m\times n} & Y_M
\end{pmatrix}.
$$
Clearly, $X_M-1_{n\times n}$ is the incidence matrix of $X$ multiplied by $-1$. Rearranging this matrix, if necessary, we get that the first block is a triangular matrix. Thus $\det(B(f))=\pm 1 \det(Y)$.
\end{proof}


\subsection{Wedge}
Let $X$ and $Y$ be finite $T_0$-spaces with base points $x_0\in X$, $y_0\in Y$. The wedge $X\bigvee Y$ is the quotient $X\sqcup Y/\{x_0,y_0 \}$.

\begin{thm}[Wedge] Let $X$ and $Y$ be finite $T_0$-spaces such that $|X|=n$ and $|Y|=m$. Consider $x_i\in X$ and $y_j\in Y$. Then $X\vee Y_M$  is 
$$\begin{pmatrix}
X_M & c_i \otimes r_j\setminus{ y_{j,j}}\\
c_j\setminus y_{j,j}\otimes r_i &Y_M\setminus \{c_j,r_j\}
\end{pmatrix}, $$
where we use the same rule of the Kronecker product used in Proposition \ref{prop:product}.
\end{thm}
\begin{proof}
We are identifying the point $x_i$ with $y_j$. Then $x_s\leq y_k$ if and only if $x_s\leq x_i$ and $y_j\leq y_k$, or, equivalently, $x_{s,i}=0$ and $y_{j,k}=0$. From this, we deduce  $c_i \otimes r_j\setminus{ y_{j,j}}$. Moreover, we get that $y_k\leq x_s$ if an only if $y_k\leq y_j$ and $x_i\leq x_s$, or, equivalently, $y_{k,j}=0$ and $x_{i,s}=0$. Again, we may deduce $c_j\setminus y_{j,j}\otimes r_i$.
\end{proof}




