    \centering
    \includegraphics[width=0.47\linewidth]{Figs/plt_N3.png}
    \hspace{0.5cm}
    \includegraphics[width=0.47\linewidth]{Figs/plt_N10.png}
    % \captionsetup{justification=raggedright, singlelinecheck=false}
    \caption{Two different snapshots of the occupation number distribution for the Majorana fermion $\psi_1$, namely when the number of dilaton oscillation $N_{\rm osc}=3$ (left) and at the time of freeze-out, when $N_{\rm osc}=N_{\rm FO}=10$ (right). We have taken $m_{\psi_1}=5 \, \rm GeV$, $m_\varphi=0.5 \, \rm GeV$, $b=-2$, $\xi_0=0.8$, and $r=300$.}
