\section{General formulae for asymmetry generated}
\label{appendix:general}

We begin with the Lagrangian density in Eq.~\eqref{Eq:VDS}, namely
\begin{align}
\nonumber
\mathcal{L}_{\rm DS} \supset & \ \frac{i}{2}\bar \psi_i \partial_\mu \gamma^\mu \psi_i + i\bar \chi_\alpha \partial_\mu \gamma^\mu \chi_\alpha + \frac{1}{2} (\partial \eta)^2 - m_{\chi_\alpha} \bar \chi_\alpha \chi_\alpha  - \frac{1}{2} m_\eta^2 \eta^2   -  \mu_{\alpha \beta} \bar \chi_\alpha \chi_\beta \eta  -\frac{1}{2} m_{\psi_i} \bar \psi_i^c \psi_i \\ & - y_{i \alpha}\bar{\psi}_i \chi_\alpha \eta + {\rm h.c.}   \ ,
\end{align}
where $i, \alpha = 1,2$ are the $\psi$, $\chi$ generational indices, respectively. 

The asymmetric number density of  $\chi_{\alpha}$ i.e. $\delta n_{\chi_{\alpha}}=n_{\chi_{\alpha}}-n_{\Bar{\chi}_{\alpha}}$ is produced due to the difference between the decay rates $\Gamma_{\alpha}(\psi_1 \rightarrow \chi_{\alpha} \eta)$ and $\Bar{\Gamma}_{\alpha}(\psi_1 \rightarrow \Bar{\chi}_{\alpha} \eta)$
\begin{align}
\delta n_{\chi_{\alpha}}=n_{\psi_1}\cdot \frac{\Gamma_{\alpha}-\bar{\Gamma}_{\alpha}}{\Gamma_{\rm tot}} \ ,
\end{align}
where $\Gamma_{\rm tot}$ is the total decay width of $\psi_1$. The channels corresponding to the decay processes at tree and one-loop level are the following:

\begin{center}
    \noindent\includegraphics[width=0.7\textwidth]{Figs/decay_feynman.png}
\end{center}
Note that the four diagrams involving $\chi_\beta$ rather than $\bar\chi_\beta$ inside the loop do not contribute to the total asymmetry, but contribute to asymmetry in the individual generation of $\chi_\alpha$. The asymmetry arises from the interference between the tree level and the one-loop level. We use $\delta n_{\chi_{\alpha}}^{(y)}$ and $\delta n_{\chi_{\alpha}}^{(\mu)}$ to represent the asymmetry generated due to $y\bar{\psi}\chi \eta$ and $\mu \bar{\chi} \chi \eta$ couplings, respectively. We obtain

\begin{align}
    & \delta n_{\chi_{\alpha}}^{(y)}\approx n_{\psi_1}\cdot 4 \sum_j \Im(L_{\psi_j}) \frac{\Re(\sum_{\beta}y_{1\beta}y_{j\beta}^*)}{\sum_{\gamma}|y_{1\gamma}|^2} \Im(y_{1\alpha}y_{j\alpha}^*) \ , \\[1ex]
    & \delta n_{\chi_{\alpha}}^{(\mu)} \approx n_{\psi_1}\cdot 2 \sum_j \Im(L_{\chi_j}) \frac{\Im(y_{1\alpha}\mu_{j\alpha}^* \cdot \sum_{\beta}y^*_{1\beta}\mu_{j\beta})}{\sum_{\gamma}|y_{1\gamma}|^2} \ , \\[1ex]
    &     \delta n_{\chi_\alpha} =   \delta n_{\chi_{\alpha}}^{(y)}+ \delta n_{\chi_{\alpha}}^{(\mu)} \ ,
\end{align}
where $L_{\psi_j}=L(m_{\psi_1},m_{\psi_j}), L_{\chi_j}=L(m_{\psi_1},m_{\chi_j})$ are the corresponding loop functions (see for \textit{e.g.,} Ref.~\cite{Pilaftsis:1998pd}).

After $\chi_2$ decays due to the neutron portal coupling $\frac{1}{\Lambda_n^2} \chi_2 u_{R} d_{R} d_{R}$, it transfers the asymmetry to the visible baryons. Therefore, the final asymmetry for the DM, denoted as $\delta n_{\rm ADM}$, is stored in $\chi_1$, while the visible asymmetry is represented as $\delta n_{\rm BAU}$. They are given by
\begin{align}
    & \delta n_{\rm ADM} = \delta n_{\chi_1}+\delta n_{\chi_2}\cdot \frac{\Gamma_{\chi_2 \rightarrow \chi_1+\eta}}{\Gamma_{\chi_2}} \ , \label{Eq:ADM}\\[1ex]
    & \delta n_{\rm BAU} =\delta n_{\chi_2}\cdot \frac{\Gamma_{\chi_2 \rightarrow udd}}{\Gamma_{\chi_2}} \ ,
    \label{Eq:BAU}
\end{align}
where $\Gamma_{\chi_2}=\Gamma_{\chi_2 \rightarrow \chi_1+\eta}+\Gamma_{\chi_2 \rightarrow udd}$, and 
\begin{align}
    \nonumber
     \Gamma_{\chi_2 \rightarrow \chi_1+\eta} \approx & \, \frac{\mu_{12}^2}{8 \pi}\frac{(m_{\chi_1}+m_{\chi_2})^2-m_{\eta}^2}{m_{\chi_2}^3} \\ \nonumber & \times [(m_{\chi_2}^2-m_{\chi_1}^2-m_{\eta}^2)^2-4m_{\chi_1}^2m_{\eta}^2]^{\frac{1}{2}} \ , \\[1ex]
     \Gamma_{\chi_2 \rightarrow udd} \approx & \, \frac{1}{\Lambda_n^4}\frac{m_{\chi_2}^5}{192 \pi^3} \ .
\end{align}
Here, we assume $m_{\chi_2}\gg m_u,m_d$.




For simplicity, let us assume $|y_{ij}|=|y|, |\mu_{11}|=|\mu_{22}|$ and all phases are random. Then one obtains
\begin{align}
   & \delta n_{\chi_{\alpha}}^{(y)} \approx n_{\psi_1}\cdot 4   \Im(L_{\psi_2}) \cdot |y|^2 \ ,  \\[1ex]
    &\delta n_{\chi_{\alpha}}^{(\mu)} \approx n_{\psi_1}\cdot  (\Im(L_{\chi_1})+\Im(L_{\chi_2}))\cdot |\mu_{11}|\cdot |\mu_{12}| \ .
\end{align}
The loop functions can be estimated as (see $e.g.$ Ref.~\cite{Pilaftsis:1998pd})
\begin{align}
    % \nonumber
    \Im \left(L(M_1,M_2) \right) & =\frac{1}{8\pi}\cdot \bigg [\frac{\Delta M^2 M_1 M_2}{(\Delta M^2)^2+M_1^2 M_2^2\cdot (\frac{|y|^2}{8\pi})^2} +f \left(\frac{M_2^2}{M_1^2}\right)\bigg] \ ,
    \label{Eq:loopInt}
\end{align}
where $\Delta M^2=M_1^2-M_2^2$ and $f(x)=\sqrt{x}(1-(1+x) \ln(1+\frac{1}{x}))$. Here, the first term comes from the self-energy diagram, while the second term is due to the vertex diagram. In our model, we typically have $m_{\psi_2}> m_{\psi_1}> m_{\chi_2}> m_{\chi_1}$. For simplicity, we assume $\frac{m_{\psi_2}}{m_{\psi_1}}\sim \frac{m_{\psi_1}}{m_{\chi_{1,2}}}> 1$.
Finally, the total asymmetry in each generation can be expressed as: 
\begin{align}
    & \delta n_{\chi_{1}} \simeq n_{\psi_1}\cdot \frac{m_{\psi_1}}{m_{\psi_2}} (|y|^2+|\mu_{11}||\mu_{12}|) \ , \\[1ex]
    & \delta n_{\chi_{2}} \simeq n_{\psi_1}\cdot \frac{m_{\psi_1}}{m_{\psi_2}} (|y|^2-|\mu_{11}||\mu_{12}|) \ \label{Eq:asymmetry} .
\end{align}
 Together with Eqs.~\eqref{Eq:ADM}-\eqref{Eq:asymmetry}, we then find
\begin{align}
    % \nonumber
    \frac{\delta n_{\rm BAU}}{s(T_{\rm RH})} & \approx   
    \frac{(|y|^2-|\mu_{11}||\mu_{12}|) n_{\psi_1}}{4 \pi}  \left[ 1+12 \pi^2 \mu_{12}^2\cdot \left({\Lambda_n}/{m_{\chi_2}}\right)^4 \right]^{-1} \ ,
    \label{Eq:BAUAs}
\end{align}
which implies for $m_{\chi_2} \simeq $ GeV and $\Lambda_n \simeq 100$ TeV, the visible baryon asymmetry would be highly suppressed unless $\mu_{12} \lesssim m_{\chi_2}^2/(2 \sqrt3 \pi \Lambda_n^2)$. For $m_{\chi_2} = 3$ GeV, $\Lambda_n = 100$ TeV, this corresponds to $\mu_{12} \lesssim 10^{-10}$. One can arrange such a small $\mu_{12}$ via the wavefunction overlap in an extra dimension, as illustrated in appendix~\ref{appendix:5d}. Consequently, the contribution of $\mu$ terms are negligible for the resultant asymmetry in Eq.~\eqref{Eq:BAUAs}, and the final expression of visible asymmetry produced by heavy $\psi_1$ decay is
\begin{align}
    \delta n_{\chi_\alpha}\simeq n_{\psi_1}\frac{|y|^2}{4\pi}\cdot \frac{m_{\psi_1}}{m_{\psi_2}}\cdot \theta_{\rm CP} \ ,
\end{align}
where $\theta_{\rm CP}$ is the ${\cal O}(1)$ CP violating phase in the $y$-matrix.




\section{A possible 5D setup}
\label{appendix:5d}

\begin{figure}[!t]
    \centering
    \includegraphics[width=0.4\linewidth]{Figs/extra_dimension.png}
    \captionsetup{justification=raggedright, singlelinecheck=false}
    \caption{A possible embedding of the dark sector in a 5D warped geometry, where the SM lives on the UV brane.}
    \label{fig:extradimension}
\end{figure}


 Let us illustrate how $\mu_{12} \lesssim 10^{-10}$ can be achieved in a holographic embedding with a warped extra dimension bounded by two 3-branes, where the SM is taken to live on the UV brane, as shown in Fig.~\ref{fig:extradimension}. The relevant $\mu_{12}$ term in 5D is described as
\begin{align}
    S\supset \int d^5x \, k \sqrt{|g|} \ \tilde{\mu}_{12} \bar{\chi}_2(x,\theta)\chi_1(x,\theta)\eta(x,\theta)  \ ,
\end{align}
where $\tilde{\mu}_{12}$ is the corresponding 5D coupling. Let us take the zero-mode of $\eta$ to have a flat profile, while the zero-modes of $\chi_{1,2}$ are peaked towards the IR and UV branes, respectively. Their 5D profiles are given by 
\begin{align}
    & f_{\chi_i}(\theta)\simeq \sqrt{\frac{(1/2-c_i)}{e^{(1-2c_i)\pi k T_0}-1}}e^{(2-c_i)kT_0 |\theta|} \ ,  \\[1ex]
    & f_{\eta}(\theta) = \frac{1}{\sqrt{2\pi k T_0}} \ ,
\end{align}
where $c_{1,2}$ are the 5D bulk mass parameters for $\chi_{1,2}$. By choosing $c_1<\frac{1}{2}<c_2$, we get a IR localized $\chi_1$, and a UV localized $\chi_2$. After integrating over the extra dimension, we obtain the 4D effective $\mu_{12}$ as
\begin{align}
    % \nonumber
    \mu_{12} & \simeq \frac{\tilde{\mu}_{12}}{c_1+c_2} \cdot  \sqrt{\frac{{(2c_2-1)(1-2 c_1)}}{(1-e^{-(2c_2-1) \pi k T_0}) (e^{(1-2c_1) \pi k T_0}-1)}}  \cdot \frac{\left(1-e^{-(c_1+c_2) \pi k T_0 } \right)}{\sqrt{2 \pi k T_0}} \ .
\end{align}
The redshift factor $z_{\rm IR}$ from the UV mass scale $M_{\rm UV}$ to the IR mass scale $M_{\rm IR}$ is defined as ${M_{\rm IR}}= {M_{\rm UV}} \, e^{-\pi k T_0}= {M_{\rm UV}} \, z_{\rm IR}$. If $M_{\rm UV} = 10$ TeV,\footnote{See \textit{e.g.}, Ref.~\cite{Girmohanta:2025uue} for a consistent low-cutoff theory, and Refs.~\cite{Lee:2021wau,Girmohanta:2023sjv} for a three 3-brane setup and its associated cosmology, within which the present model can be embedded.} and $M_{\rm IR} = 1$ GeV, $z_{\rm IR} = 10^{-4}$. Taking $\tilde{\mu}_{12} \simeq {\cal O}(1)$, we can achieve $\mu_{12} \lesssim 10^{-10}$ for $c_1 \lesssim -2.1$, $c_2 \gtrsim 2.5$. The parameter space can be enlarged further if one assumes $\tilde{\mu}_{12} \ll 1$. As a result of being localized towards the IR brane, the DM candidate $\chi_1$ is stable against decay to lighter SM visible particles, while it is also the lightest DS fermion and does not decay to DS particles. This explains the stability of the DM.






