\section{Dijkgraaf's integrable condition and Contact term algebra}\label{Dijkcondandcontact}

In this section, we will restate Dijkgraaf's integrable condition in terms of the language of vertex algebra, and derive the contact term relations based on this condition. In Subsection \ref{cva}, we will recall necessary facts on conformal vertex algebra, for more details, please refer to \cite{Frenkel2001voa}, \cite{1996Modular}. In Subsection \ref{Dic}, we will give the definition of the integrable condition (see Definition \ref{intcdt}) which we call Dijkgraaf's condition, then examples and basic properties. In Subsection \ref{BCcontact}, we will define two important operations $B$, $C$ (see Definition \ref{defBC}) and derive the contact term relations (see Theorem \ref{contrel}).

\subsection{Conformal vertex algebra}\label{cva}

Let $(V, |0\rangle, T, Y(\cdot,z),\omega)$ be a $\mathbb{Z}_{\geq0}$-graded conformal vertex algebra of central charge $c$, that is,
\begin{enumerate}
  \item (state space) a graded vector space $V=\oplus_{n=0}^{\infty} V_n$ indexed by degree;
  \item (vacuum) a vector $|0\rangle\in V_0$;
  \item (translation operator) a degree 1 linear operator $T:V\rightarrow V$;
  \item (state-field correspondence) a linear operation (vertex operators)
  \begin{align*}
  Y(\cdot,z): &V\longrightarrow \End(V)[[z,z^{-1}]]\\
              &a\longmapsto Y(a,z)=\sum_{n\in\Z}a_{(n)}z^{-n-1};  \quad(a_{(n)}\in\End(V))
  \end{align*}
  \item (conformal vector) $\omega\in V_2$, $c\in\C$
\end{enumerate}
satisfying the following axioms:
\begin{itemize}
  \item (vacuum axiom) $Y(|0\rangle,z)=\Id_{V}$. Furthermore, for any $a\in V$, we have
         $$Y(a,z)|0\rangle\in V[[z]],\quad \lim_{z\rightarrow0}Y(a,z)|0\rangle=a;$$
  \item (translation axiom) $T|0\rangle=0$. For any $a\in V$, $Y(Ta,z)=\frac{d}{dz}Y(a,z)$;
  \item (locality axiom) All fields $Y(a,z)$, $a\in V$, are mutually local, i.e. for any $a,b\in V$, there exists $N\in\Z_+$, such that
  $$(z-w)^N[Y(a,z),Y(b,w)]=0;$$
  \item (energy-momentum tensor) $T(z):=Y(\omega,z)=\sum_{n\in\Z}L_nz^{-n-2}$, satisfies
  \begin{itemize}
  \item $L_{-1}=T$, $L_0 a=na$, for $a\in V_n$;
  \item $\{L_n\}_{n\in\Z}$ span the Virasoro algebra with central charge $c$.
\end{itemize}
\end{itemize}

There are some basic consequences that we will use later.

\begin{prop}\label{immediateconseq} Let $V$ be a $\Z_{\geq0}$-graded vertex algebra.
\begin{enumerate}
  \item For $a\in V_m$, $a_{(n)}\in\End(V)$ has degree $m-n-1$, i.e.
  $$a_{(n)}V_k\subset V_{k+m-n-1};$$
  \item $(Ta)_{(n)}=-na_{(n-1)}$, in particular, $(Ta)_{(0)}=0$;\\
$T(a_{(n)}b)+na_{(n-1)}b=a_{(n)}Tb$, in particular, $T(a_{(0)}b)=a_{(0)}Tb$.
\end{enumerate}
\end{prop}


Let $a,b\in V$. Their operator product expansion (OPE) can be expanded as
$$Y(a,z)Y(b,w)=\sum_{n\in\Z}\frac{Y(a_{(n)}b,w)}{(z-w)^{n+1}},$$
where $a_{(n)}b$ can be also viewed as defining an infinite tower of binary operations. 
\begin{prop}\label{nthprod}
Let $V$ be a $\Z_{\geq0}$-graded vertex algebra.
\begin{enumerate}
  \item For homogeneous elements $a,b\in V$,
  $$a_{(n)}b=\sum_{k=0}^{\infty}(-1)^{k+n+1}\frac{1}{k!}T^k(b_{(n+k)}a);$$
  \item (Borcherds Formula) For $a,b\in V$, every $l,m,n\in \mathbb{Z}$ :
$$\sum_{j\geq0}\binom{l}{j}\left[(-1)^ja_{(m+l-j)}b_{(n+j)}-(-1)^{j+l}b_{(n+l-j)}a_{(m+j)}\right]=\sum_{k\geq0}\binom{m}{k}\left(a_{(k+l)}\cdot b\right)_{(m+n-k)}.$$
\end{enumerate}
\end{prop}

For convenience, we list some simple cases of the Borcherds Formula.
\begin{cor}\label{Borcherdsspec} (1) For $l=n=0,m=1$,
$$a_{(1)}b_{(0)}-b_{(0)}a_{(1)}=\left(a_{(0)}b\right)_{(1)}+\left(a_{(1)}b\right)_{(0)}.$$
(2) For $l=0,m=n=1$,
$$a_{(1)}b_{(1)}-b_{(1)}a_{(1)}=\left(a_{(0)}b\right)_{(2)}+\left(a_{(1)}b\right)_{(1)}.$$
(3) For $m=n=0, l=2$,
$$a_{(2)}b_{(0)}-b_{(2)}a_{(0)}-2a_{(1)}b_{(1)}+2b_{(1)}a_{(1)}+a_{(0)}b_{(2)}-b_{(0)}a_{(2)}=\left(a_{(2)}b\right)_{(0)}.$$
In particular, $\left(a_{(2)}b\right)_{(0)}$ is skew-symmetric with respect to $a$ and $b$.
\end{cor}

\begin{prop}\label{kerT} Let $V$ be a $\Z_{\geq0}$-graded conformal vertex algebra. Then
$$\ker T\subset V_0.$$
\end{prop}

\begin{proof} It follows from the standard $sl_2$ relations of $\{L_{-1},L_0,L_1\}$ and degree condition. \qedhere
\end{proof}




\subsection{Dijkgraaf's integrable condition}\label{Dic}

Following Dijkgraaf's work \cite{Dijk1996master}, we introduce the following integrable condition\footnote{It is slightly different from Dijkgraaf's original statement, where he requires that the residue of OPE $A(z)B(w)$ belongs to $\ker(T)$, see \cite{Dijk1996master} (2.8). We find it more natural to work with $\im(T)$ as in Definition \ref{intcdt}.}.

\begin{defn}\label{intcdt} Let $(V, |0\rangle, Y(\cdot,z),\omega)$ be a $\mathbb{Z}_{\geq0}$-graded conformal vertex algebra. We say a subvertex algebra $\mathcal{A}\subset V$ satisfies the Dijkgraaf's condition, if
\begin{itemize}
\item $\mathcal{A}\cap V_1=0$,
\item For any $a,b\in\mathcal{A}$,
   $$a_{(0)}b\in T\mathcal{A},$$
   or equivalently,
   $$\Res_{z=w}Y(a,z)Y(b,w) \text{ is a total derivative.}$$
\end{itemize}
\end{defn}

In the derivation of Dijkgraaf's master equation, we will furthermore require that $\mathcal{A}$ has a countable number of elements $\{v_i\}_{i\in\mathbb{N}}$, such that
\begin{itemize}
  \item $\{v_i\}_{i\in\mathbb{N}}\subset \mathcal{A}_{>0}:=\mathcal{A}\cap \oplus_{n>0}V_n$ ,
  \item there exist constants $\{c^k_{ij}\}$ in $\mathbb{C}$, such that $$v_{j\ (0)}v_i-T\sum_{k\in\mathbb{N}}c^k_{ij}v_k\in T^2\mathcal{A}.$$
\end{itemize}

Immediately, we have
\begin{lem}\label{dijkcor} Let the subvertex algebra $\mathcal{A}\subset V$ satisfy the Dijkgraaf's condition. Then
\begin{enumerate}
  \item for $a,b\in\mathcal{A}$, we have
        $$[a_{(0)},b_{(0)}]=0.$$
  \item $T(\mathcal{A}_0)=0$.
\end{enumerate}
\end{lem}

\begin{rmk} Regarding $\mathcal{A}$ as a space encoding integrable deformations. One can always choose $\omega\in\mathcal{A}$, then $T(z)=Y(\omega,z)$ gives the energy-momentum tensor deformation. Therefore, the other elements $a\in\mathcal{A}_{>2}$ give the higher order (integrable) deformations.
\end{rmk}


We will give several examples of $\mathcal{A}$ in Subsection \ref{Dijkeg}. Before the examples, let us give one more important lemma associated to $\mathcal{A}$ for our future definition.

\begin{lem}\label{T-Inverse}
  There exists a well-defined linear operator
  $$
  T^{-1}: \mathcal{A}_{(0)}\mathcal{A}\rightarrow \mathcal{A}_{>0}
  $$
  which fits into the commutative diagram. 
  $$
  % https://tikzcd.yichuanshen.de/#N4Igdg9gJgpgziAXAbVABwnAlgFyxMJZABgBpiBdUkANwEMAbAVxiRGJAF9T1Nd9CKAIzkqtRizYAdKQFs6OABYBjRsACCnAPoduvbHgJEATKOr1mrRCBnylqhhs5ceIDAYFEAzGfGW2ACoAFLYKKmqaAJQu+vxGKD5CYhaS1qH2EdrAQcSRnOnhjppcYjBQAObwRKAAZgBOELJIZCA4EEhCeiD1jR3UbUjGXT1NiKat7Yg+fqkgATHdDaMALP2T0wx0AEYwDAAKfIaCIHVY5Yo4IOYSViBYCyNIqxOD1-7WAQB6wAC0nSWcIA
\begin{tikzcd}
0 \arrow[r] & \mathcal{A}_0 \arrow[r] & \mathcal{A} \arrow[r, "T"] & T(\mathcal{A})                                                    \\
            &                         &                            & \mathcal{A}_{(0)}\mathcal{A} \arrow[hookrightarrow,u, "i"'] \arrow[lu, "T^{-1}"]
\end{tikzcd}
  $$
%  if $c\in\mathcal{A}_{>0}$ such that $Tc=a$, then $c=T^{-1}a$.
  In particular, we have  $T(T^{-1}a)=a, a\in\mathcal{A}_{(0)}\mathcal{A}$ and  
  $$-n(T^{-1}a)_{(n-1)}=a_{(n)},\quad \text{for } n\geq1.$$
\end{lem}

\begin{proof} For $a,b\in\mathcal{A}$, assume $a_{(0)}b\neq0$. Then $\exists~c\in\mathcal{A}$ such that $a_{(0)}b=Tc$. Define
$$T^{-1}(a_{(0)}b)=\operatorname{Pr}(c),$$
here $\operatorname{Pr}:V\rightarrow \oplus_{n>0}V_n$ is the natural projection. By Lemma \ref{dijkcor} (2), we have $T(c-\operatorname{Pr}(c))=0$. Then
$$T(\operatorname{Pr}(c))=T(c)=a_{(0)}b.$$
Now we show $T^{-1}$ is well-defined, that is, it does not depend on the choice of $c$. Suppose that there exists another element $c'\in\mathcal{A}$, such that
$$T(c')=T(c)=a_{(0)}b,$$
then
$$T(\operatorname{Pr}(c')-\operatorname{Pr}(c))=0.$$
By Proposition \ref{kerT}, $\ker(T)\subset V_0$, then $\operatorname{Pr}(c')=\operatorname{Pr}(c)$. The remaining part follows from Proposition \ref{immediateconseq}.
\end{proof}


\subsubsection{Examples}\label{Dijkeg}
\begin{eg}[Vertex operator algebra from Novikov algebra]
This example is studied in \cite{BaiLiPei}.
We first recall the definition of a Novikov algebra (see \cite{BaiLiPei} and references therein). A Novikov algebra is a non-associative algebra $A$ with the product satisfying %(left-symmetric, right-commutative)
  \begin{align*}
    (ab)c-a(bc) & =(ba)c-b(ac) \\
    (ab)c &= (ac)b
  \end{align*}
  for $a,b,c\in \mathcal{A}$.  We also assume that $A$ is equipped with a symmetric bilinear form $\langle\cdot,\cdot\rangle$, satisfying
  \begin{equation}\label{bilinearform}
  \langle ab,c\rangle=\langle a,bc\rangle=\langle ba,c\rangle, ~\forall ~a,b,c \in A.
  \end{equation}

  Set
  $$
\widehat{A}=A\otimes \mathbb{C}[t,t^{-1}]\oplus\C\mathbf{c},  ~~\widehat{A}_+=A\otimes \mathbb{C}[t]\oplus \mathbb{C}\mathbf{c},  ~~   \widehat{A}_-=A\otimes t^{-1}\mathbb{C}[t^{-1}].
  $$
  Let $l\in \mathbb{C}$ and denote by $\mathbb{C}_l$ the one-dimensional $\widehat{A}_+$ -module with $\mathbf{c}$ acting as scalar $l$ and with $A\otimes \mathbb{C}[t]$ acting trivially. There exists a vertex algebra structure on the induced module
  $$
  V_{A}=U(\widehat{A})\otimes_{U(\widehat{A}_+)}\mathbb{C}_l,
  $$
  such that $(V_{A})_2=A$ and for any $a,b\in A$
  $$
  Y(a,z)Y(b,w)\sim \frac{\partial_wY(ba,w)}{z-w}+\frac{Y(ab,w)+Y(ba,w)}{(z-w)^2}+\frac{1}{12}\frac{\langle a,b\rangle\mathbf{c}}{(z-w)^3}.
  $$
  Then we can choose $\mathcal{A}\subset V_{A}$ to be the subvertex algebra generated by $|0\rangle$ and $A$ with
  \[a_{(0)}b=T(ba),\quad a_{(1)}b=ab+ba,\quad a_{(3)}b=\frac{1}{2}l\langle a,b\rangle|0\rangle,\quad a_{(2)}b=a_{(k\geq4)}b=0,\]
  for any $a,b\in A$. Let $\{v_i\}$ be a basis of $A$, then the coefficients $c^k_{ij}$ in Definition \ref{intcdt} are the structure constants of the Novikov algebra $A$.
\end{eg}

\begin{rmk}
A unital Novikov algebra $A$ with a symmetric bilinear form satisfying \eqref{bilinearform} amounts to a Frobenius algebra, i.e., a unital commutative and associative algebra with a non-degenerate symmetric and associative form. For a Frobenius algebra
$A$, a similar construction implies that the associated vertex algebra $L(A)$ \cite{Lam} is isomorphic to the corresponding Virasoro algebra, and $\big(L(A)_2,~a\cdot b:=a_{(1)}b\big)\cong A$ as an algebra. Thus, the structure constants $c_{ij}^k$ in the Frobenius algebra coincide with those in our definition. Such structure constants have important applications in the Poisson brackets of hydrodynamic type \cite{BN85}.  
\end{rmk}



\begin{eg}[$W_{\infty}$ algebra]\label{Walg} In terms of the free boson $\phi(z)$ with OPE 
$$\phi(z)\phi(w)\sim\log(z-w),$$
the fields of $W_{1+\infty}$ vertex operator algebra are given through
$$:e^{\phi(z)-\phi(w)}:=1+\sum_{k\geq1}\frac{(z-w)^k}{k!}W^{(k)}(w).$$

That is, for $k\geq1$,
\begin{equation}\label{Wk}
W^{(k)}(z)=\sum_{\sum_{i\geq1}ik_i=k}\frac{k!}{\prod k_i!}:\prod_i\left(\frac{1}{i!}\partial^i\phi\right)^{k_i}:.
\end{equation}


By the boson-fermion correspondence, a free boson is equivalent to a pair of fermions, that is
$$\psi=:e^{\phi}:,\quad \psi^{\dag}=:e^{-\phi}:\quad \text{and}\quad \partial\phi=:\psi\psi^{\dag}:.$$
where the OPE of the pair of fermions are given by
$$\psi(z)\psi^{\dag}(w)\sim \frac{1}{z-w}.$$
It is known that
$$:\psi(z)\psi^{\dag}(w):=\frac{1}{z-w}\left(:e^{\phi(z)-\phi(w)}:-1\right).$$

\noindent So we can also express $W^{(k)}(z)$ in terms of fermions,
$$W^{(k)}(z)=k:(\partial^{k-1}\psi)\psi^{\dag}:.$$
For simplicity, rescaling $W^{(k)}(z)$ by $\frac{1}{k}$, i.e.
$$\widetilde{W}^{(k)}(z):=\frac{1}{k}W^{(k)}(z)=:(\partial^{k-1}\psi)\psi^{\dag}:.$$


\begin{lem}\label{WOPE}$\Res_{z=w}\widetilde{W}^{(m)}(z) \widetilde{W}^{(n)}(w)$ is a total derivative, that is
\begin{align*}
\Res_{z=w}\widetilde{W}^{(m)}(z) \widetilde{W}^{(n)}(w)=~&\sum_{k=1}^{m-1}\binom{m-1}{k}(-1)^{k-1}\p^{k}\widetilde{W}^{(m+n-k-1)}(w)\\
                               =~&(m-1)\p \widetilde{W}^{(m+n-2)}(w)-\sum_{k=2}^{m-1}\binom{m-1}{k}(-\p)^{k}\widetilde{W}^{(m+n-k-1)}(w).
\end{align*}
\end{lem}

\begin{proof} Using the fermionic representation, we can compute
\begin{align*}
&\Res_{z=w}\widetilde{W}^{(m)}(z) \widetilde{W}^{(n)}(w)\\
=~&\Res_{z=w}\left(:(\partial^{m-1}\psi)\psi^{\dag}(z): ~:(\partial^{n-1}\psi)\psi^{\dag}(w):\right)\\
=~&\Res_{z=w}\left(\p_z^{m-1}\frac{1}{z-w}:\psi^{\dag}(z)\p^{n-1}\psi(w):+\p_w^{n-1}\frac{1}{z-w}:\p^{m-1}\psi(z)\psi^{\dag}(w):\right)\\
% &\pm \p_z^{m-1}\frac{1}{z-w}\p_w^{n-1}\frac{1}{z-w}\pm \p_z^{m-1}\frac{1}{z-w}\p_w^{n-1}\frac{1}{z-w}\\
=~&(-1)^{m-2}:\p^{n-1}\psi(w)\p^{m-1}\psi^{\dag}(w):+:\p^{m+n-2}\psi(w)\psi^{\dag}(w):\\
=~&\p\left[:\p^{m+n-3}\psi\psi^{\dag}:-:\p^{m+n-4}\psi\p\psi^{\dag}:+\cdots+(-1)^{m-2}:\p^{n-1}\psi\p^{m-2}\psi^{\dag}:\right](w).
\end{align*}
Furthermore, one can prove by induction that
\begin{align*}
&:\p^{m+n-3}\psi\psi^{\dag}:-:\p^{m+n-4}\psi\p\psi^{\dag}:+:\p^{m+n-5}\psi\p^2\psi^{\dag}:-\cdots+(-1)^{m-2}:\p^{n-1}\psi\p^{m-2}\psi^{\dag}:\\
=~&\sum_{k=1}^{m-1}\binom{m-1}{k}(-\p)^{k-1}:(\p^{m+n-2-k}\psi \psi^{\dag}):\\
=~&\sum_{k=1}^{m-1}\binom{m-1}{k}(-\p)^{k-1}\widetilde{W}^{(m+n-k-1)}. \qedhere
\end{align*}
\end{proof}


Note that each field $\widetilde{W}^{(i)}(z)$ has degree $i$. The algebra generated by $\{\widetilde{W}^{(i)}(z)\}_{i\geq2}$ is the $W_{\infty}$ algebra. By the bosonic defining equation \eqref{Wk} of $W_{1+\infty}$ algebra, for each $\widetilde{W}^{(i)}(z)$, there is an element $v_i\in V$, such that
$$\widetilde{W}^{(i)}(z)=Y(v_i,z),\quad i\geq 2.$$
Then we consider the subvertex algebra $\mathcal{A}\subset V$ spanned by the vacuum state $|0\rangle$ and $\{v_i\}_{i\geq2}$. It is obvious that the $W_{\infty}$ algebra $\mathcal{A}$ satisfies \emph{Dijkgraaf's condition} and the structure constants $c_{ij}^k=(j-1)\delta_{k,i+j-2}$ in terms of $\{v_i\}$.
\end{eg}




\subsection{The operations $B$, $C$ and contact term algebra}\label{BCcontact}

Inspired by Dijkgraaf's work \cite{Dijk1996master}, we consider the following definitions.
\begin{defn}\label{defBC}
Let $\mathcal{A}\subset V$ be a vertex subalgebra satisfying Dijkgraaf's condition. We define the following two operations
$$B:\mathcal{A}^{\otimes2}\rightarrow \mathcal{A}, \quad C:\mathcal{A}^{\otimes2}\rightarrow \mathcal{A}$$
by
\begin{equation}\label{BC1}
\begin{aligned}
&B(a_i,a_j)=T^{-1}(a_{i\ (0)}a_j), \quad\text{(It is well defined by Lemma \ref{T-Inverse}.)}\\
&C(a_i,a_j)=a_{i\ (1)}a_j-B(a_i,a_j).
\end{aligned}
\end{equation}
\end{defn}

By Proposition \ref{nthprod} (1), the formulas for $n=0,1$ give
\begin{align*}
&a_{i\ (0)}a_j+a_{j\ (0)}a_i=\sum_{k\geq 1}(-1)^{k+1}\frac{T^k(a_{i\ (k)}a_j)}{k!},\\
&a_{i\ (1)}a_j=\sum_{k\geq 0}(-1)^{k+2}\frac{T^k(a_{j\ (k+1)}a_i)}{k!}.
\end{align*}
Then, one can easily derive the important relation
\begin{equation}\label{BC2}
C(a_i,a_j)-B(a_j,a_i)\in \im T.
\end{equation}
Note also that $B(a_i,a_j), C(a_i,a_j)\in\mathcal{A}_{>0}$.


Furthermore, we can extend these operations on ${\mathcal{A}}^{\otimes n}$ by
\begin{align*}
T_{i}(a_{1}\otimes\cdots\otimes a_{n}):&=a_{1}\otimes \cdots\otimes\displaystyle \underset{\text{i-th}}{Ta_i}\otimes\cdots \otimes a_{n}, \ 1\leq i\leq n,\\
B_{i\rightarrow j}(a_{1}\otimes\cdots\otimes a_{n}):&=a_{1}\otimes \displaystyle \underset{\text{i-th}}{|0\rangle}\otimes\cdots \otimes\underset{\text{j-th}} {B(a_i,a_j)} \otimes \cdots\otimes a_{n}, \ 1\leq i\neq j\leq n,\\
C_{i\rightarrow j}(a_{1}\otimes\cdots\otimes a_{n}):&=a_{1}\otimes \displaystyle \underset{\text{i-th}}{|0\rangle}\otimes\cdots \otimes\underset{\text{j-th}} {C(a_i,a_j)} \otimes \cdots\otimes a_{n}, \ 1\leq i\neq j\leq n.
%G_{i\rightarrow j}(a_{1}\otimes\cdots\otimes a_{n}):&=a_{1}\otimes \displaystyle \underset{\text{i-th}}{1}\otimes\cdots \otimes\underset{\text{j-th}} {G(a_i,a_j)} \otimes \cdots\otimes a_{n}, \ 1\leq i\neq j\leq n.
\end{align*}


By definition, it is straight-forward to check that
\begin{lem}\label{trivialrel} Let $a=a_1\otimes\cdots\otimes a_n\in\mathcal{A}^{\otimes n}$, for distinct $i,j,k,l$, we have
\begin{align*}
    B_{i\rightarrow j}B_{k\rightarrow l}a= ~&B_{k\rightarrow l}B_{i\rightarrow j}a,\quad C_{i\rightarrow j}C_{k\rightarrow l}a=C_{k\rightarrow l}C_{i\rightarrow j}a;\\
    &B_{i\rightarrow j}C_{k\rightarrow l}a=C_{k\rightarrow l}B_{i\rightarrow j}a.
\end{align*}

\end{lem}


Next, we consider the remaining non-trivial relations between $B$ and $C$.

\begin{thm}[Contact term relations]\label{contrel}
For $a=a_1\otimes\cdots\otimes a_n\in\mathcal{A}^{\otimes n}$, and for distinct $i,j,k$, we have
\begin{enumerate}
\setlength{\itemsep}{2pt}
 \item $B_{i\rightarrow k} B_{j\rightarrow k}a=B_{j\rightarrow k}B_{i\rightarrow k}a.$
 \item $[C_{i\rightarrow k},B_{j\rightarrow k}]a+B_{i\rightarrow k}B_{j\rightarrow k}a=B_{j\rightarrow k}C_{i\rightarrow j}a.$
 \item $[C_{i\rightarrow k}, C_{j\rightarrow k}]a\equiv C_{j\rightarrow k}C_{i\rightarrow j}a-C_{i\rightarrow k}C_{j\rightarrow i}a~\mod(\im(T)).$
\end{enumerate}
\end{thm}

\begin{proof} (1) By definition, the $k$-th element of $B_{i\rightarrow k}B_{j\rightarrow k}a$ is
$$B(a_i,B(a_j,a_k))=T^{-1}(a_{i\ (0)}(T^{-1}(a_{j\ (0)}a_k))).$$
First, we compute $T(a_{i\ (0)}(T^{-1}(a_{j\ (0)}a_k)))$. By Proposition \ref{immediateconseq} (2), Lemma \ref{dijkcor} (1), we have
 \begin{align*}
     T(a_{i\ (0)}(T^{-1}(a_{j\ (0)}a_k)))& =a_{i\ (0)}(a_{j\ (0)}a_k)\quad\text{(Proposition \ref{immediateconseq}, $T(a_{(0)}b)=a_{(0)}Tb$.)}\\
     &=a_{j\ (0)}(a_{i\ (0)}a_k) \quad \text{(Lemma \ref{dijkcor}, $[a_{i\ (0)},a_{j\ (0)}]=0$.)}\\
     &=T(a_{j\ (0)}(T^{-1}(a_{i\ (0)}a_k))).
 \end{align*}

Since $\ker T\subset V_0$, by degree reason, we have
$$a_{i\ (0)}(T^{-1}(a_{j\ (0)}a_k))=a_{j\ (0)}(T^{-1}(a_{i\ (0)}a_k))\in\mathcal{A}_{>0}.$$
Furthermore,
$$T^{-1}(a_{i\ (0)}(T^{-1}(a_{j\ (0)}a_k)))=T^{-1}(a_{j\ (0)}(T^{-1}(a_{i\ (0)}a_k))).$$

\vskip 0.2cm
(2) By definition, the $k$-th elements of $C_{i\rightarrow k}B_{j\rightarrow k}a$ and $B_{j\rightarrow k}C_{i\rightarrow k}a$ are respectively given by
\begin{align*}
&C(a_i, B(a_j, a_k))=a_{i\ (1)}T^{-1}(a_{j\ (0)}a_k)-B(a_i,B(a_j,a_k)),\\
&B(a_j, C(a_i, a_k))=T^{-1}(a_{j\ (0)}(a_{i\ (1)}a_k))-B(a_j,B(a_i,a_k)).
\end{align*}
By Theorem \ref{contrel} (1) we just proved, the $k$-th element of $[C_{i\rightarrow k},B_{j\rightarrow k}]a$ is
\begin{equation}\label{keyone}
    a_{i\ (1)}T^{-1}(a_{j\ (0)}a_k)-T^{-1}(a_{j\ (0)}(a_{i\ (1)}a_k)).
\end{equation}
Applying $T$ to it and using Proposition \ref{immediateconseq}, Corollary \ref{Borcherdsspec}, Lemma \ref{T-Inverse}, we can compute
\begin{align*}
   & a_{j\ (0)}(a_{i\ (1)}a_k)-T(a_{i\ (1)}T^{-1}(a_{j\ (0)}a_k))  \\
  =~& a_{j\ (0)}(a_{i\ (1)}a_k)-a_{i\ (1)}(a_{j\ (0)}a_k)+a_{i\ (0)}T^{-1}(a_{j\ (0)}a_k) \quad \text{(Proposition \ref{immediateconseq} (2))}\\
  =~&-(a_{i\ (0)}a_j)_{(1)}a_k-(a_{i\ (1)}a_j)_{(0)}a_k+a_{i\ (0)}T^{-1}(a_{j\ (0)}a_k)\quad \text{(Corollary \ref{Borcherdsspec} (1))}\\
  =~&(T^{-1}(a_{i\ (0)}a_j))_{(0)}a_k-(a_{i\ (1)}a_j)_{(0)}a_k+a_{i\ (0)}T^{-1}(a_{j\ (0)}a_k)\quad \text{(Lemma \ref{T-Inverse})}\\
  =~&-(C(a_i,a_j))_{(0)}a_k+T(B(a_i, B(a_j, a_k))).
\end{align*}
Applying $T^{-1}$ to both sides, we get the desired equation.

\vskip 0.2cm
(3) By definition, the $k$-th elements of $C_{i\rightarrow k}C_{j\rightarrow k}a$ and $C_{j\rightarrow k}C_{i\rightarrow k}a$ are respectively given by
\begin{align*}
C(a_i, C(a_j, a_k))=~&a_{i\ (1)}(a_{j\ (1)}a_k)-a_{i\ (1)}T^{-1}(a_{j\ (0)}a_k)\\
                    &-T^{-1}\big(a_{i\ (0)}(a_{j\ (1)}a_k)\big)+B(a_i,B(a_j,a_k)),\\
C(a_j, C(a_i, a_k))=~&a_{j\ (1)}(a_{i\ (1)}a_k)-a_{j\ (1)}T^{-1}(a_{i\ (0)}a_k)\\
                    &-T^{-1}\big(a_{j\ (0)}(a_{i\ (1)}a_k)\big)+B(a_j,B(a_i,a_k)).
\end{align*}

By (1) (2) we just proved and Corollary \ref{Borcherdsspec}, we have
\begin{align*}
  &C(a_i, C(a_j, a_k))-C(a_j, C(a_i, a_k))\\
=~&a_{i\ (1)}(a_{j\ (1)}a_k)-a_{i\ (1)}T^{-1}(a_{j\ (0)}a_k)-T^{-1}\big(a_{i\ (0)}(a_{j\ (1)}a_k)\big)\\
&-\bigg(a_{j\ (1)}(a_{i\ (1)}a_k)-a_{j\ (1)}T^{-1}(a_{i\ (0)}a_k)-T^{-1}\big(a_{j\ (0)}(a_{i\ (1)}a_k)\big)\bigg)\\
=~&\big(a_{i\ (0)}a_j\big)_{(2)}a_k+\big(a_{i\ (1)}a_j\big)_{(1)}a_k+B(C(a_j,a_i),a_k)-B(C(a_i,a_j),a_k)\\
&\qquad\text{(By Corollary \ref{Borcherdsspec} and \eqref{keyone}, (1) (2).)}\\
=~&-2B(a_i,a_j)_{(1)}a_k+B(a_{i\ (1)}a_j,a_k)+C(a_{i\ (1)}a_j,a_k)+B(C(a_j,a_i),a_k)-B(C(a_i,a_j),a_k)\\
=~&-2B(B(a_i,a_j),a_k)-2C(B(a_i,a_j),a_k)+B(B(a_i,a_j),a_k)+B(C(a_i,a_j),a_k)\\
  &+C(B(a_i,a_j),a_k)+C(C(a_i,a_j),a_k)+B(C(a_j,a_i),a_k)-B(C(a_i,a_j),a_k)\\
=~&-B(a_i,a_j)_{(1)}a_k+C(C(a_i,a_j),a_k)-C(C(a_j,a_i),a_k)+C(a_j,a_i)_{(1)}a_k\\
\equiv~&C(C(a_i,a_j),a_k)-C(C(a_j,a_i),a_k)\quad \mod (\im(T)).
\end{align*}
The last step is obtained as follows. First, by \eqref{BC2}, there exists $b\in\mathcal{A}$ such that
\[C(a_j,a_i)_{(1)}a_k-B(a_i,a_j)_{(1)}a_k=(Tb)_{(1)}a_k.\]
Then by Proposition \ref{nthprod} (1), Proposition \ref{immediateconseq} (2) and the integrable condition, we have
\[(Tb)_{(1)}a_k\equiv a_{k~(1)}Tb\equiv a_{k~(0)}b\equiv0\quad\mod(\im(T)).\qedhere\]
\end{proof}


\begin{rmk} 
By the above relation (1), for any non-empty proper subset $I\subset\{1,\ldots,n\}$ and any $k\in\{1,\ldots,n\}\setminus I$, we can define
$$B_{I\rightarrow k}a:=\prod_{i\in I}B_{i\rightarrow k}a.$$
More generally, one can consider two disjoint sets $I$ and $M$, and a map $\phi:I\rightarrow M$, and define
$$B^{\phi}_{I\rightarrow M}:=\prod_{k\in M,\phi^{-1}(k)\neq \emptyset}B_{\phi^{-1}(k)\rightarrow k}.$$
Such a definition will appear in our study of contact iterations later. 

However for $B_{j\rightarrow k}B_{i\rightarrow j}$ and $B_{i\rightarrow k}B_{j\rightarrow i}$,  they are not equal to each other.
\end{rmk}

\begin{prop}\label{Useful}
Let $I\subset \{1,\dots,n\}-\{i,k\}$ be a non-empty subset, we have
$$
  [C_{i\rightarrow k}, B_{I\rightarrow k}]+|I|\cdot B_{I\cup\{i\}\rightarrow k}=\sum_{l\in I}B_{I\rightarrow k}C_{i\rightarrow l}.
  $$
\end{prop}
\begin{proof}
  We prove this lemma by induction on $|I|$. For $|I|=1$, this is exactly Theorem \ref{contrel} (2). For $|I|>1,j\in I$, we have
  \begin{align*}
     & [C_{i\rightarrow k}, B_{I\rightarrow k}]+|I|\cdot B_{I\cup\{i\}\rightarrow k} \\
   =~&\left([C_{i\rightarrow k}, B_{I-\{j\}\rightarrow k}]B_{j\rightarrow k}+(|I|-1)\cdot B_{I\cup\{i\}\rightarrow k}\right)+\left(B_{I-\{j\}\rightarrow k}[C_{i\rightarrow k}, B_{j\rightarrow k}]+B_{I\cup\{i\}\rightarrow k}\right)\\
   =~&\sum_{l\in I-\{j\}}B_{I-\{j\}\rightarrow k}C_{i\rightarrow l}B_{j\rightarrow k}+B_{I-\{j\}\rightarrow k}B_{j\rightarrow k}C_{i\rightarrow j}\\
    &\qquad\text{(By induction hypothesis and Theorem \ref{contrel} (2))}\\
   =~&\sum_{l\in I-\{j\}}B_{I\rightarrow k}C_{i\rightarrow l}+B_{I-\{j\}\rightarrow k}B_{j\rightarrow k}C_{i\rightarrow j} \quad\text{(Lemma \ref{trivialrel})}\\
   =~&\sum_{l\in I}B_{I\rightarrow k}C_{i\rightarrow l}.\qedhere
  \end{align*}
\end{proof}





\section{Genus one partition function and Dijkgraaf's master equation}\label{Genusoneandmasterequation}

In this section, we will discuss the mathematical definitions of various genus one partition functions via the following two-step construction.
\begin{itemize}
    \item \textbf{Step 1.} Using the conformal block (Definition \ref{genus1cb}) to get a meromorphic elliptic function on the configuration space of elliptic curves 
    $$(a_1,\ldots,a_n)\mapsto S_n((a_1,z_1),\ldots,(a_n,z_n),\tau).$$
    \item \textbf{Step 2.} Applying the various integrals on the function $S_n((a_1,z_1),\ldots,(a_n,z_n),\tau)$:
    \begin{itemize}
        \item (pure type 1). regularized integral (Subsection \ref{regularizedintegrals}, Equation \eqref{regint})
$$\dashint_{E_{\tau}^n}S_n((a_1,z_1),\ldots,(a_n,z_n),\tau)\vol;$$
        \item (pure type 2). interated $A$-cycle integral
$$\oint_{A_n}\cdots\oint_{A_1}S_n((a_1,z_1),\ldots,(a_n,z_n),\tau)~dz_1\cdots dz_n;$$
        \item (mixed type). regularized integral and modified iterated $A$-cycle integral (Definitions \ref{iteratedmodifiedA}, \ref{mixtype})
    \end{itemize}
\end{itemize}

The mixed type is very subtle, since the $A$-cycle integral does not preserve the elliptic property. We need to make some modifications if we want to combine the regularized integral with the $A$-cycle integral.  Such modifications turn out to be related to the contact operators $B$ and $C$. In Subsection \ref{1st2ndgenus1pf}, we define two pure types of partition functions. In Subsection \ref{secmodifiedA}, we introduce the key idea and construction on the modified $A$-cycle integral, and discuss the relation among the various iterated integrals and contact iterations. In Subsection \ref{mixDijk}, we define the mixed partition function, and state the main theorems about contact equation (Theorems \ref{ModifiedAcycleElliptic} and \ref{Contactequation}) which lead to Dijkgraaf's master equation (Theorem \ref{DijkgraafMaster}). In Subsection \ref{proofofpropthm}, we give the proof of Theorems \ref{ModifiedAcycleElliptic} and \ref{Contactequation}.




\subsection{Genus one conformal block}\label{g1block}

In this subsection, we recall the definition of the genus one conformal block \cite{1996Modular}. We first introduce some notations.

For $n\in\Z_{>0}$, let $\mathcal{F}_n$ denote the space of meromorphic functions $f(z_1,\dots, z_n, \tau)$ on $\mathbb{C}^n\times \mathbf{H}$  such that for fixed $\tau$, $f(z_1,\dots, z_n, \tau)$ is doubly periodic for each variable $z_i$ with periods $s+t\tau (s,t\in\mathbb{Z})$ and the possible poles of $f(z_1,\dots, z_n, \tau)$ lie in the set
$$
\{(z_1,\dots, z_n, \tau)|z_i=z_j+(s+t\tau), i\neq j; s,t\in\mathbb{Z}\}.
$$

\begin{defn}\label{genus1cb}
   Let $\{V, |0\rangle, T, Y(, z), \omega\}$ be a conformal vertex algebra. A system of $\operatorname{maps} S=\left\{S_{n}\right\}_{n=1}^{\infty}$
$$S_{n}: V^{\otimes n} \rightarrow {\mathcal{F}}_{n},\quad a_{1}\otimes\cdots\otimes a_{n} \mapsto S\left(\left(a_{1}, z_{1}\right), \ldots,\left(a_{n}, z_{n}\right), \tau\right)
$$
is said to satisfy the \emph{genus-one property} if the following axioms $(1)-(6)$ are satisfied.

(1) $S\left(\left(a_{1}, z_{1}\right),\left(a_{2}, z_{2}\right), \ldots,\left(a_{n}, z_{n}\right), \tau\right)$ is linear for each $a_{i}$;

(2) For every permutation $\sigma$ of $n$ letters,
$$
S\left(\left(a_{\sigma(1)}, z_{\sigma(1)}\right), \ldots,\left(a_{\sigma(n)}, z_{\sigma(n)}\right), \tau\right)=S\left(\left(a_{1}, z_{1}\right), \ldots,\left(a_{n}, z_{n}\right), \tau\right);
$$

(3)
$$
S\left((|0\rangle, z),\left(a_{1}, z_{1}\right), \ldots,\left(a_{n}, z_{n}\right), \tau\right)=S\left(\left(a_{1}, z_{1}\right), \ldots,\left(a_{n}, z_{n}\right), \tau\right);
$$

(4)
$$S\left(\left(L_{-1} a_{1}, z_{1}\right), \ldots,\left(a_{n}, z_{n}\right), \tau\right)=\frac{d}{d z_{1}} S\left(\left(a_{1}, z_{1}\right), \ldots,\left(a_{n}, z_{n}\right), \tau\right);$$

(5)
$$
\begin{array}{l}
\operatorname{Res}_{w=z} S\left((a, w),\left(a_{1}, z_{1}\right), \ldots,\left(a_{n}, z_{n}\right), \tau\right)\left(w-z_{1}\right)^{k} \\
=S\left(\left(a_{(k)}a_{1}, z_{1}\right), \ldots,\left(a_{n}, z_{n}\right), \tau\right);
\end{array}
$$
$\quad$(6) If $a_{i}(i=1, \ldots, n)$ are highest weight vectors for the Virasoro algebra with degree $\operatorname{deg} a_{i},$ write
$$
S=S\left(\left(\omega, w_{1}\right), \ldots,\left(\omega, w_{m}\right),\left(a_{1}, z_{1}\right), \ldots,\left(a_{n}, z_{n}\right), \tau\right),
$$
then
\begin{align*}
&S((\omega,w),(\omega,w_1),\ldots,(\omega,w_m),(a_1,z_1),\ldots,(a_n,z_n),\tau)\\
%&\eta(\tau)^{-1}\langle:T(w):,:T(w_1):,\ldots,:T(w_m):,:\p\phi(z_1):,\ldots,:\p\phi(z_n):;\tau\rangle\\
=~&2\pi i\frac{d}{d\tau}S+\sum_{k=1}^n(\wp_1(w-z_k,\tau)-(w-z_k)\frac{\pi^2}{3}E_2(\tau))\frac{d}{dz_k}S\\
&+\sum_{k=1}^m(\wp_1(w-w_k,\tau)-(w-w_k)\frac{\pi^2}{3}E_2(\tau))\frac{d}{dw_k}S\\
&+\sum_{k=1}^n(\wp_2(w-z_k,\tau)+\frac{\pi^2}{3}E_2(\tau))S\\
&+\sum_{k=1}^m(\wp_2(w-w_k,\tau)+\frac{\pi^2}{3}E_2(\tau))2S\\
&+\frac{1}{2}\sum_{k=1}^m\wp_4(w-w_k,\tau)S((\omega,w_1),\ldots,\widehat{(\omega,w_k)},\ldots,(a_n,z_n),\tau).
\end{align*}
Here $\left(\widehat{\omega, w_{k}}\right)$ means the term is omitted, and
\begin{align*}
&\wp_1(z;\tau)=\frac{1}{z}+\sum_{(m,n)\in(\Z\oplus\Z)\setminus \{(0,0)\}}\left(\frac{1}{z-m\tau-n}+\frac{1}{m\tau+n}+\frac{z}{(m\tau+n)^2}\right),\\
&\wp_{k+1}(z;\tau)=-\frac{1}{k}\frac{d}{dz}\wp_k(z;\tau),\quad\text{for }~k\geq1.
\end{align*}
\end{defn}

The linear space of $S$ satisfying the genus one property is called the \textit{ conformal block on the torus}.  We denote the space of conformal blocks associated to the conformal vertex algebra $(V, |0\rangle, T, Y(, z), \omega)$ by ${\mathcal{H}}_V$.


Here, we give an example of the explicit construction of $S$ as follows.
\subsubsection{Normal ordered Feynman graph}\label{normalorderedFG}
Introduce the free boson $\phi(z)$ with OPE and mode expansion
$$\phi(z)\phi(w)\sim\log(z-w),\quad \phi(z)=\sum_{n\neq0}-\frac{\phi_nz^{-n}}{n}+\phi_0+p,$$
where $p$ is the momentum creation operator as a conjugate of $\phi_0$.

Now we consider a normal ordered Feynman graph in the chiral boson theory on $E_\tau$. Let
$$P(z_1,z_2;\tau)=\wp(z_1-z_2;\tau)+\frac{\pi^2}{3}E_2(\tau)$$
be the propagator. Here $\wp(z;\tau)$ is the Weierstrass $\wp$-function and $E_2$ is the second Eisenstein series.

We also write $P(z_1,z_2;\tau)$ as $P(z_1-z_2;\tau)$ in the following. For convenience, we decompose the propagator $P$ into a singular part and a smooth part
$$P(z_1,z_2)=R(z_1,z_2)+Q(z_1,z_2),\quad \text{for }~ z_1\neq z_2,$$
where
\begin{enumerate}
\setlength{\itemsep}{1pt}
  \item $R(z_1,z_2)=1/(z_1-z_2)^2$;
  \item $Q(z_1,z_2)=\sum_{m\geq0}Q_m(z_1-z_2)^m$ is a power series of $(z_1-z_2)$, more explicitly,
  \begin{align*}
  &Q_0=\frac{\pi^2}{3}E_2(\tau),\qquad Q_{2m+1}=0,\quad m>0,\\
  &Q_{2m}=(2m+1)G_{2m+2}(\tau),\quad m>0,
  \end{align*}
  where $G_{2m+2}(\tau)$ is the Eisenstein series of weight $2m+2$.
\end{enumerate}



Let $\Gamma$ be an oriented graph with possible self-loops (it is not necessarily connected). Let $E(\Gamma)$ be its set of edges, and $V(\Gamma)$ be its set of vertices with $|V(\Gamma)|=n$. We can order the vertices by $\{1,2,\ldots, n\}$.
\begin{itemize}
  \item For the $i$-th vertex with valence $n_i$, we put the normal ordered fields
  $$:\L_i(z_i):=\sum_{k_1,\ldots,k_{n_i}>0}c_{k_1,\ldots,k_{n_i}}:\p^{k_1}\phi(z_i)\p^{k_2}\phi(z_i)\cdots\p^{k_{n_i}}\phi(z_i):,$$
  with only finite $c_{k_1,\ldots,k_{n_i}}$'s are non-vanishing.
  \item For each edge connecting $:\L_i(z_i):$ and $:\L_j(z_j):$, $z_i\neq z_j$, we put $$\sum_{k,l\geq0}\partial_{z_i}^k\partial_{z_j}^lP(z_i,z_j)\frac{\p}{\p(\p^{k+1}\phi(z_i))}\frac{\p}{\p(\p^{l+1}\phi(z_j))}.$$
  \item For each self-loop at the $i$-th vertex, we put
      $$\sum_{k,l\geq0}\partial_{z_i}^k\partial_{z_j}^lQ(z_i,z_j)\bigg|_{z_j=z_i}\frac{\p}{\p(\p^{k+1}\phi(z_i))}\frac{\p}{\p(\p^{l+1}\phi(z_i))}.$$
\end{itemize}

For each graph $\Gamma$, we can define a meromorphic function $\Phi_{\Gamma}(z_1,\ldots,z_n)$ on the configuration space as follows.
\begin{enumerate}
  \item If $\Gamma$ has tails, it is defined as zero.
  \item If $\Gamma$ has no tails, $\Phi_{\Gamma}(z_1,\ldots,z_n)$ is given by the Feynman rule above.
\end{enumerate}

By definition, $\Phi_{\Gamma}(z_1,\ldots,z_n)$ only has poles at the diagonal of the configuration space.
\begin{rmk}
    Similar construction has been discussed in \cite{Tuite2012, Mason2003, Takhtajan2005}. This is a mathematical reformulation of the point-splitting
 method used by physicists. See also \cite{Gui2021, Gui2023} for the case of free $\beta\gamma-bc$ systems.
\end{rmk}

\begin{defn}\label{defnnormalorderedFG} The normal ordered Feynman graph function for arbitrary fields $\L_1(z_1)$,\ldots, $\L_n(z_n)$ is defined to be
$$\langle :\L_1(z_1):,:\L_2(z_2):,\cdots,:\L_n(z_n):;\tau\rangle=\sum_{\Gamma}\frac{\Phi_{\Gamma}(z_1,\ldots,z_n)}{|\Aut(\Gamma)|},$$
where the summation is over all possible graphs as above, and $\Aut(\Gamma)$ is the automorphism group of $\Gamma$.
\end{defn}

