For the vertex algebra $V$ of chiral bosons
$$V=\Span\left\{\phi_{-i_1}^{k_1}\phi_{-i_2}^{k_2}\cdots\phi_{-i_n}^{k_n}|0\rangle~\big| i_1>i_2\cdots>i_n>0, k_1,\ldots,k_n\geq0, n\geq0\right\},$$
we define
\begin{equation*}
\begin{aligned}
S_n:~V^{\otimes n}~&\longrightarrow~\mathcal{F}_n\\
a_1\otimes\cdots\otimes a_n &\longmapsto S((a_1,z_1),\ldots,(a_n,z_n),\tau)
\end{aligned}
\end{equation*}
by the rescaled normal ordered Feynman graph function
\begin{equation}
S((a_1,z_1),\ldots,(a_n,z_n),\tau)~=~\eta(\tau)^{-1}\langle :\L_1(z_1):,:\L_2(z_2):,\cdots,:\L_n(z_n):;\tau\rangle,
\end{equation}
where $\L_i(z_i)=Y(a_i,z_i)$ and $\eta(\tau)$ is Dedekind eta function
$$\eta(\tau)=q_{24}\prod_{n=1}^{\infty}(1-q^n),\quad q_{24}=e^{\frac{2\pi i\tau}{24}},\quad q=e^{2\pi i\tau}.$$

\begin{prop}\label{normalcorrelation} $S=\{S_n\}_{n\geq1}$ defines an element in the conformal block on the torus.
\end{prop}
\begin{proof} See in Appendix \ref{proofnormal}.
\end{proof}



\subsection{Regularized integrals}\label{regularizedintegrals}
In this subsection, we will recall the necessary definition and results of regularized integrals introduced in \cite{SiJie2020} and apply them to the conformal block to obtain a mathematical definition of the genus one partition functions in \cite{Dijk1996master}.



Let $\Sigma$ be a smooth Riemann surface, and denote
\begin{itemize}
  \item $\Delta:=\cup_{i\neq j}\Delta_{ij}$, $\Delta_{ij}=\left\{(z_1,z_2,\ldots,z_n)\in\Sigma^n|z_i=z_j\right\}$.
  \item $A^{p,q}_{\Sigma^n}(\star\Delta)$: sheaf of smooth $(p,q)$-forms with arbitrary holomorphic poles along $\Delta$.
  \item $A^{p,q}_{\Sigma^n}(\log\Delta)$: sheaf of smooth $(p,q)$-forms with possible holomorphic log-poles along $\Delta$.
\end{itemize}

\begin{rmk}
    We follow the notation of \cite{SiJie2020}. A local section of $A^{p,q}_{\Sigma^n}(\log\Delta)$ is a linear combination of forms of type $\omega=\nu\cdot \frac{df_1}{f_1}\wedge\cdots \wedge \frac{df_l}{f_l}$ where $\nu$ is a smooth form and these $f_i$'s are local equations of some irreducible components of the diagonal divisor ($d$ is the holomorphic differential). For the detailed study of the logarithmic de Rham complex, see \cite[4.2.13]{Beilinson2004}.
\end{rmk}
For any $\omega\in A^{n,\bullet}_{\Sigma^n}(\star\Delta)$, there exists a decomposition (by reduction of poles)
$$\omega=\alpha+\partial\beta$$
where $\alpha\in A^{n,\bullet}_{\Sigma^n}(\log \Delta)$, $\beta\in A^{n-1,\bullet}_{\Sigma^n}(\star\Delta)$.
Then they define the regularized integral
\begin{equation}\label{regint}
\dashint_{\Sigma^n}\omega:=\int_{\Sigma^n}\alpha.
\end{equation}

The notion of regularized integrals satisfies nice properties, for example, see \cite{SiJie2020},
\begin{itemize}
  \item it works for Riemann surfaces with boundary;
  \item Stokes' theorem, Fubini theorem, Riemann-Hodge bilinear relation;
  \item There is a relative version.
\end{itemize}

Here we give the explicit description of Stokes' formula and Fubini Theorem for the regularized integrals, which we will mainly use in the following.

\begin{thm}[\cite{SiJie2020}, Theorem 2.13]\label{Stokes}
 Let $\Sigma$ be a compact Riemann surface possibly with boundary $\partial \Sigma$. Let $\alpha \in A_{\Sigma}^{1}(\star D)$, where $D\subset\Sigma$ is a subset of finite points which does not meet $\partial\Sigma$. Then we have the following version of Stokes' formula for the regularized integral
$$
\dashint_{\Sigma} d \alpha=-\sum_{p\in D}\operatorname{Res}_{z=p}(\alpha)+\int_{\partial \Sigma} \alpha.
$$
\end{thm}

\begin{thm}[Fubini Theorem: \cite{SiJie2020} Theorem 2.37, Corollary 2.39]\label{Fubini} Let $\sigma$ be any permutation of $\{1,2,\ldots,n\}$. Then the iterated regularized
integral
$$\dashint_{\Sigma_{\sigma(1)}}\dashint_{\Sigma_{\sigma(2)}}\cdots\dashint_{\Sigma_{\sigma(n)}}\omega,\quad\omega\in A_{\Sigma^n}^{2n}(\star\Delta)$$
does not depend on the choice of $\sigma$.
\end{thm}
\begin{rmk}
    The regularized integral can be viewed as an explicit realization of the trace map on the unit chiral chain complex \cite[4.3.3]{Beilinson2004}. This connection is established in \cite{Gui2021}.
\end{rmk}



In the rest of this section, we apply the theory of regularized integrals to the elliptic curve $E_{\tau}$
$$
E_{\tau}=\mathbb{C}/(\mathbb{Z}+\mathbb{Z}\tau),\quad \tau\in\mathbf{H}.
$$
Recall that $z$ is a linear holomorphic coordinate on the universal cover $\mathbb{C}$ in terms of which one has
$$
\int_{E_\tau}\frac{d^2z}{\operatorname{Im}\tau}=1,\quad d^2z:=\frac{\sqrt{-1}}{2}dz\wedge d\bar{z}.
$$
\begin{defn}\label{Almost-Meromorphic}
We say a function $\Psi$ on $\mathbb{C}^{n} \times \mathbf{H}$ is \emph{almost-meromorphic} if $\Psi$ can be written as a finite
sum
$$
\Psi\left(z_{1}, \cdots, z_{n} ; \tau\right)=\sum_{k_{1}, \cdots, k_{n}, m\geq0} \Psi_{k_{1}, \cdots, k_{n} ; m}\left(z_{1}, \cdots, z_{n} ; \tau\right)\left(\frac{\operatorname{Im} z_{1}}{\operatorname{Im} \tau}\right)^{k_{1}} \cdots\left(\frac{\operatorname{Im} z_{n}}{\operatorname{Im} \tau}\right)^{k_{n}}\left(\frac{1}{\operatorname{Im} \tau}\right)^{m}
$$
where each $\Psi_{k_{1}, \cdots, k_{n} ; m}\left(z_{1}, \cdots, z ; \tau\right)$ is a meromorphic function on $\mathbb{C}^{n} \times \mathbf{H}$.
\end{defn}

\begin{defn}\label{Elliptic-HolomorphicAway}
 Let $\mathcal{R}_{n}^{E_{\tau}}$ denote the space of functions $\Psi$ on $\mathbb{C}^{n} \times \mathbf{H}$ such that
\begin{itemize}
  \item $\Psi$ \text { is elliptic and almost-meromorphic. }
  \item { Each component } $\Psi_{k_{1}, \cdots, k_{n} ; m}$ \text { as in Definition \ref{Almost-Meromorphic}} \text { is holomorphic away from diagonals. }
\end{itemize}
\end{defn}

\begin{prop}[\cite{SiJie2020}, Proposition 3.15]
 The regularized integral defines a map
$$
\dashint_{E_{\tau}} \frac{d^{2} z_{n}}{\operatorname{Im} \tau}: \mathcal{R}_{n}^{E_{\tau}} \rightarrow \mathcal{R}_{n-1}^{E_{\tau}}.
$$
In particular, for $\Psi\in\mathcal{R}_n^{E_{\tau}}$,
\begin{equation}\label{keyeq}
\dashint_{E_{\tau}}\frac{d^{2} z_{n}}{\im\tau}\Psi(z)=\oint_Adz_n\Psi(z)+\sum_{j\neq n}\operatorname{Res}_{z_n=z_j}\frac{\im z_n}{\im\tau}\Psi(z).
\end{equation}
\end{prop}





\subsection{The two pure types of genus one partition functions}\label{1st2ndgenus1pf}

Now we will define two pure types of genus one correlators associated with $S\in\mathcal{H}_V$.


\begin{defn} Let $m\in\mathbb{N}$ and $S\in\mathcal{H}_V$. We define the first type of $m$-point correlators $\langle-\rangle_{E_{\tau},m}$ as follows:
\begin{equation}\label{1stkind}
\begin{aligned}
\langle-\rangle_{E_{\tau},m}:&~\mathcal{A}^{\otimes m}\longrightarrow\C\\
\langle a_1,\ldots,a_m\rangle_{E_{\tau},m}
=~&\prod_{k=1}^m\dashint_{E_{\tau}}\frac{d^2z_k}{\im\tau}S((a_1,z_1),\ldots,(a_m,z_m),\tau).
\end{aligned}
\end{equation}
By choosing a countable number of elements $\{v_i\}_{i\in\N}$ in Definition \ref{intcdt}, the first type of genus one partition function $Z_{E_{\tau}}(t)$ is defined to be
$$Z_{E_{\tau}}(t)=\sum_{m\geq0}\frac{1}{m!}\sum_{(i_1,\ldots,i_m)\in\N^m}~t^{i_1}\cdots t^{i_m}\langle v_{i_1},\ldots,v_{i_m}\rangle_{E_{\tau},m},$$
where $\{t^{i}\}$ are the coordinates of $\{v_i\}$ respectively.
\end{defn}

The correlators are well-defined by Fubini Theorem \ref{Fubini} of the regularized integral.

\vskip 0.2cm

On the other hand,  the iterated $A$-cycle integral in general depends on the order of integration. However, Dijkgraaf's integrable condition guarantees the following result.

\begin{lem}\label{Commutative} Let $\mathcal{A}$ be the subvertex algebra satisfying the Dijkgraaf's condition and let $S\in\mathcal{H}_V$. For any $a\in\mathcal{A}^{\otimes n}$, we have
$$\oint_Adz_i\oint_Adz_jS(a)=\oint_Adz_j\oint_Adz_iS(a).$$
\end{lem}
\begin{proof}
We use the axiom (5) for $S$
\begin{align*}
  \oint_Adz_i\oint_Adz_jS(a)-\oint_Adz_j\oint_Adz_iS(a) &=\oint_{A}dz_{j}\operatorname{Res}_{z_i=z_j}S(a) \\
   & =\oint_{A}dz_{j}\partial_{z_j}S(B_{i\rightarrow j}a)\\
   &=0.\qedhere
\end{align*}
\end{proof}

Thus, we arrive at the following definition.

\begin{defn}Let $n\in\mathbb{N}$ and $S\in\mathcal{H}_V$. We define the second type of $n$-point correlators $\langle-\rangle_{A,n}$ as follows:
\begin{equation}\label{2ndkind}
\begin{aligned}
\langle-\rangle_{A,n}:&~\mathcal{A}^{\otimes n}\longrightarrow\C\\
\langle a_1,\ldots,a_n\rangle_{A,n}
=~&\prod_{l=1}^n\oint_A{dz_l}S((a_1,z_1),\ldots,(a_n,z_n),\tau).
\end{aligned}
\end{equation}
Similarly, choosing $\{v_i\}$ as above, the second kind of genus one partition function $Z_{A}(s)$ is defined to be
$$Z_{A}(s)=\sum_{n\geq0}\frac{1}{n!}\sum_{(j_1,\ldots,j_n)\in\N^n}s^{j_1}\cdots s^{j_n}\langle v_{j_1},\ldots,v_{j_n}\rangle_{A,n},$$
where $\{s^j\}$ are the coordinates of $\{v_j\}$ respectively.
\end{defn}

We are interested in the relation between the first type and the second type correlators. Inspired by Dijkgraaf's work, we need to define a more general partition function $Z(s,t)$ including arbitrary iterated $A$-cycle integrals and iterated regular integrals. However, as we explained above, $\oint_A$ does not preserve the ellipticity in general, thus the mixed double integral $\dashint_{E_{\tau}}\oint_A$ does not make sense. In order to obtain a well-defined genus one partition function $Z(s,t)$ of mixed type, we need to do some modification of $A$-cycle integral with the help of the following equation (i.e. \eqref{keyeq} with $\Psi(z)$ being $S(a)$):
\begin{equation}\label{keyeq2}
\dashint_{E_{\tau}}\frac{d^{2} z_{i}}{\im\tau}S(a)=\oint_Adz_i S(a)+\sum_{j\neq i}\Res_{z_i=z_j}\frac{\im z_i}{\im\tau}S(a).
\end{equation}

By the relation of operations $B$, $C$ and the axiom of $S$, we have the nice decomposition for the residue term in \eqref{keyeq2}.
\begin{lem}\label{OPE} Let $S\in\mathcal{H}_V$, for any $a\in\mathcal{A}^{\otimes n}$, we have
\begin{equation}\label{modfiedBCD}
\Res_{z_i=z_j}\frac{\im z_i}{\im\tau}S(a)=\partial_{z_j}\left(\frac{\im z_j}{\im\tau}S(B_{i\rightarrow j}a)\right)+\frac{1}{2\sqrt{-1}\im\tau}S(C_{i\rightarrow j}a).
\end{equation}
\end{lem}
\begin{proof} This equation could also be decomposed into two equations
\begin{align*}
  \p_{z_j}S(B_{i\rightarrow j}a)&=\operatorname{Res}_{z_i=z_j}S(a),\\
  \operatorname{Res}_{z_i=z_j}(z_i-z_j)S(a)&=S(B_{i\rightarrow j}a)+S(C_{i\rightarrow j}a),
\end{align*}
which follow from the axioms (4) (5) for $S$ and the definition of $B,C$.
\end{proof}



The relation \eqref{BC2} of $B$ and $C$ also has an expression in terms of the $A$-cycle integral.
\begin{lem}\label{BCS}  Let $S\in\mathcal{H}_V$, for any $a\in {\mathcal{A}}^{\otimes n}$, we have
$$\oint_Adz_jS(C_{i\rightarrow j}a)=\oint_Adz_i S(B_{j\rightarrow i}a).$$
\end{lem}
\begin{proof} By \eqref{BC2}, we have
$$C(a_i,a_j)=B(a_j,a_i)+Tb,\quad \text{for some }b\in\mathcal{A}.$$
Since $\oint_Adz_j \partial_{z_j}S(a_1\otimes\underset{\text{i-th}}{|0\rangle}\otimes\underset{\text{j-th}} {b}\otimes\cdots\otimes a_n)=0$, and using the axioms (2) (3), we get
\begin{align*}
   \oint_Adz_j S(C_{i\rightarrow j}a)&=\oint_Adz_j S(a_{1}\otimes \displaystyle \underset{\text{i-th}}{|0\rangle}\otimes\cdots \otimes\underset{\text{j-th}} {B(a_j,a_i)} \otimes \cdots\otimes a_{n})
 \\
   &= \oint_Adz_i S(a_{1}\otimes \displaystyle \underset{\text{i-th}}{B(a_j,a_i)}\otimes\cdots \otimes\underset{\text{j-th}} {|0\rangle} \otimes \cdots\otimes a_{n})\\
   &= \oint_Adz_i S(B_{j\rightarrow i}a).\qedhere
\end{align*}
\end{proof}


\begin{thm} For any $a\in\mathcal{A}^{\otimes l}$, and 
any $0<m,n<l$,  $$
\dashint_{E_{\tau}^{m}}S(a)\frac{dz_{j_1}^2}{\im\tau}\cdots\frac{dz_{j_m}^2}{\im\tau}\quad  \text{and} \quad \oint_{A^{n}}S(a)dz_{k_1}\cdots dz_{k_n}$$ 
satisfy the axioms (1)-(5) of the genus one conformal block.
\end{thm}

\begin{proof} First, we look at the case $m,n=1$. It is obvious that both $\dashint_{E_{\tau}}\frac{dz_j^2}{\im\tau}S(a)$ and $\oint_Adz_kS(a)$ satisfy (1)-(3).
\begin{itemize}
    \item For $\dashint_{E_{\tau}}\frac{dz_j^2}{\im\tau}S(a)$,  
    \begin{itemize}
        \item the axiom (4) follows from \cite{SiJie2020} Lemma 2.26 that
        $$\left[\frac{d}{dz_i},~\dashint_{E_{\tau}}\frac{dz_j^2}{\im\tau}\right]=0,\quad i\neq j.$$ 
        \item the axiom (5) follows from \cite{SiJie2023} Corollary A.2 that
        \[\left[\Res_{z_a=z_b},~\dashint_{E_{\tau}}\frac{dz_j^2}{\im\tau}\right]=0,\quad\text{for distinct } ~a,b,j.\]
    \end{itemize}
    \item For $\oint_Adz_kS(a)$,
    \begin{itemize}
        \item the axiom (4) follows from the obvious identity 
        \[\left[\frac{d}{dz_i},~\oint_Adz_k\right]=0,\quad i\neq k.\]
        \item the axiom (5) follows from \cite{SiJie2023} Lemma A.1 that
        \[\left[\Res_{z_a=z_b},~\oint_Adz_k\right]=0,\quad \text{for distinct }~a,b,k.\]
    \end{itemize}
\end{itemize}
Then the desired results hold by induction.
\end{proof}
\begin{rmk}
The regularized integral $\dashint_{E_{\tau}^{m}}S(a)\frac{dz_{j_1}^2}{\im\tau}\cdots\frac{dz_{j_m}^2}{\im\tau}$ is not a genus one conformal block in the strict sense, as it involves $\im\tau$. However, since it is elliptic, one may interpret it as a smooth section of the bundle of (co)invariants over the moduli space of elliptic curves with marked points. The $A$-cycle integral $\oint_{A^{n}}S(a)dz_{k_1}\cdots dz_{k_n}$ is meromorphic but not elliptic, one can add corrections to make it elliptic, see Theorem \ref{ModifiedAcycleElliptic}.
\end{rmk}


\subsection{The modified $A$-cycle integrals}\label{secmodifiedA}
\subsubsection{Modified $A$-cycle integrals}
Now, by Equations \eqref{keyeq2} and \eqref{modfiedBCD}, we have
\begin{equation}\label{EmodifA}
\dashint_{E_{\tau}}\frac{d^{2} z_{i}}{\im\tau}S(a)=\oint_Adz_i S(a)+\sum_{j\neq i}\partial_{z_j}\left(\frac{\im z_j}{\im\tau}S(B_{i\rightarrow j}a)\right)+\sum_{j\neq i}\frac{1}{2\sqrt{-1}\im\tau}S(C_{i\rightarrow j}a).
\end{equation}

Thus, we can define the modified $A$-cycle integral by
\begin{equation}\label{modifiedAcycle}
\widehat{\oint}_Adz_iS(a)=\oint_Adz_i S(a)+\sum_{j\neq i}\partial_{z_j}\left(\frac{\im z_j}{\im\tau}S(B_{i\rightarrow j}a)\right).
\end{equation}
By Equation \eqref{EmodifA}, $\widehat{\oint}_A$ preserves the ellipticity. Unfortunately,
$$\left[\widehat{\oint}_{A}dz_n, \widehat{\oint}_{A}dz_m\right]S(a)\neq0.$$
There is a contact interaction between the two modified $A$-cycle integrals. So we need to make the second modification.

\begin{defn}\label{defn:notation}
For convenience, we simplify some notations and denote
\begin{itemize}
\setlength{\itemsep}{2pt}
\setlength{\parsep}{0pt}
\setlength{\parskip}{0pt}
\item For $I\subset\{1,\ldots,n\}$,
 $$E_I:=\dashint_{E_{\tau}^{|I|}}\prod_{i\in I}\frac{d^2z_i}{\operatorname{Im}\tau},\qquad A_I:=\prod_{i\in i}\oint_Adz_i$$
\item $\widehat{A}_i=\widehat{\oint}_Adz_i$.
\end{itemize}
\end{defn}

Now we want to define a modified (multi-)$A$-cycle integral $\widehat{A}_I$ associated to any subset $I\subset\{1,\ldots,n\}$, which preserves the ellipticity of functions. For $|I|=1$, this is done. Next we consider $I=\{1,2\}$ containing two indices.

\begin{defn} For $S\in\mathcal{H}_V$ and $a\in \mathcal{A}^{\otimes n}$, we define
\begin{equation}\label{modifiedA2}
\begin{aligned}
\widehat{A}_{\{1,2\}}S(a):=~&\widehat{\oint}_{A_1\times A_2}dz_1dz_2S(a)\\
                      =~&\oint_{A_1}dz_1\oint_{A_2}dz_2S(a)+\sum_{j\neq 1,2}\partial_{z_j}\left[\frac{\im z_j}{\im\tau}\oint_{A_2}S(B_{1\rightarrow j}a)\right]\\
                      &+\sum_{k\neq 1,2}\partial_{z_k}\left[\frac{\im z_k}{\im\tau}\oint_{A_1}S(B_{2\rightarrow k}a)\right]\\
                      &+\sum_{j,k\neq 1,2;j\neq k}\partial_{z_j}\left[\frac{\im z_j}{\im\tau}\partial_{z_k}\left(\frac{\im z_k}{\im\tau}S(B_{1\rightarrow j}B_{2\rightarrow k}a)\right)\right]\\
                      &+\sum_{k\neq 1,2}\partial_{z_k}\left[\left(\frac{\im z_k}{\im\tau}\right)^2\partial_{z_k}S(B_{1\rightarrow k}B_{2\rightarrow k}a)\right].
\end{aligned}
\end{equation}
\end{defn}


Inductively, one can define $\widehat{A}_I$ for any $I\subset\{1,2,\ldots,n\}$. To give the explicit definition, let us look at the terms in Equation \eqref{modifiedA2} carefully and introduce the following differential operators $D_{r,k}$, $r\geq1$,
$$D_{r,k}F:=\partial_{z_k}\left(\left(\frac{\im z_k}{\im\tau}\right)^r\partial_{z_k}^{r-1}F\right),\quad \text{for any }F\in\mathcal{R}_n^{E_{\tau}}.$$
Similarly, we will consider a general version of $D_{r,k}$ associated to any two disjoint sets $I$, $M$ and a map $\phi:I\rightarrow M$
$$D_{I\rightarrow M}^{\phi}:=\prod_{k\in M,\phi^{-1}(k)\neq \emptyset}D_{|\phi^{-1}(k)|,k}.$$

Now let $M$, $N$, $I$ and $I^c$ be sets as follows:
$$M=\{1,\ldots,m\},\quad N=\{m+1,\ldots,m+n\},\quad I\subset N,\quad I^c=N-I.$$
For $S\in \mathcal{H}_V$, we also use the notation $[a]$ instead of $S(a)$ for $a\in \mathcal{A}^{\otimes (m+n)}.$

\begin{defn}\label{iteratedmodifiedA} The modified $A$-cycle integral $\widehat{A}_N$ for the holomorphic conformal block on the torus is defined to be
$$
\widehat{A}_{N}[a]=\displaystyle \sum _{ \substack{I\subset N\\
\phi:I\rightarrow M}}D^{\phi}_{I\rightarrow M}A_{{I}^c} [B^{\phi}_{{I\rightarrow M}}a], \quad a\in \mathcal{A}^{\otimes (|M|+|N|)},\  I^c=N-I.
$$
In particular,
\begin{enumerate}
  \item $\lim\limits_{\im\tau\rightarrow\infty}\widehat{A}_N[a]=A_N[a]$.
  \item when $M=\emptyset$,
  $$\widehat{A}_N[a]=A_{N}[a]=\oint_Adz_1\cdots \oint_Adz_n[a].$$
\end{enumerate}

\end{defn}
\begin{rmk}
    It is clear that $\widehat{A}_N[a]$ can be written as $$\widehat{A}_N[a]=\sum\limits^{N_0}_{r=0}\frac{F_r(z,\tau)}{(\im\tau)^r},\quad\text{for some } N_0>0,$$
    where each $F_r(z,\tau)$ is meromorphic in $\tau$. We define the limit $\lim\limits_{\im\tau\rightarrow\infty}\widehat{A}_N[a]$ to be the constant term $F_0(z,\tau)$.
\end{rmk}

\subsubsection{Relations among the various iterated integrals $E_M$, $\widehat{A}_N$, $A_N$ and contact iterations}

Next we consider a generalization of \eqref{EmodifA}:
$$E_i[a]=\widehat{A}_i[a]+\sum_{j\neq i}\frac{1}{2\sqrt{-1}\im\tau}[C_{i\rightarrow j}a]$$
as in the next Theorem \ref{ModifiedAcycleElliptic}, which  explains the advantage of modified $A$-cycle integrals.

\begin{thm}\label{ModifiedAcycleElliptic} For any $a\in \mathcal{A}^{\otimes(|M|+|N|)}$, $\widehat{A}_{N}[a]$ is almost-meromorphic and elliptic, also satisfies the axioms (1)-(5) of the genus one conformal block. And we have
  $$
  E_{m}\widehat{A}_{N}[a]=\widehat{A}_{N\cup\{m\}}[a]+\frac{1}{2\sqrt{-1}\operatorname{Im}\tau}\sum_{1\leq j\leq m+n,j\neq m}\widehat{A}_{N}[C_{m\rightarrow j}a].
  $$
\end{thm}

\begin{proof} See in Subsection \ref{proofofpropthm}.
\end{proof}




\begin{cor}
  For $a\in \mathcal{A}^{\otimes (m+l)}$, we have 
  $$
  E_{\{1,\dots, m\}}[a]=\sum_{k\geq 0}\frac{1}{(2\sqrt{-1}\operatorname{Im}\tau)^k}\displaystyle \sum _{ \substack{I=\{i_1,\dots,i_k\}\\1\leq i_1<\cdots<i_k\leq m\\ 1\leq j_1,\dots,j_k\leq m+l}}\widehat{A}_{I^c}[C_{i_1\rightarrow j_1}\cdots C_{i_k\rightarrow j_k}a],
  $$
  here $C_{i\rightarrow i}:=0$, for any $i\leq m , I^c=\{1,\dots,m\}-I$. In particular, when $l=0, a\in\mathcal{A}^{\otimes m}$, we have
  $$
  E_{\{1,\dots, m\}}[a]=\sum_{k\geq 0}\frac{1}{(2\sqrt{-1}\operatorname{Im}\tau)^k}\displaystyle \sum _{ \substack{I=\{i_1,\dots,i_k\}\\1\leq i_1<\cdots<i_k\leq m\\ 1\leq j_1,\dots,j_k\leq m}}{A}_{I^c}[C_{i_1\rightarrow j_1}\cdots C_{i_k\rightarrow j_k}a].
  $$
\end{cor}
\begin{proof}
  We prove this corollary by induction on $m$. If $m=1$, we apply Proposition \ref{ModifiedAcycleElliptic} to the case when $N=\emptyset.$ Now suppose $m>1$, by induction hypothesis and Proposition \ref{ModifiedAcycleElliptic}, we have
  \begin{align*}
       E_1E_{\{2,\dots, m\}}[a]&=E_1\sum_{k\geq 0}\frac{1}{(2\sqrt{-1}\operatorname{Im}\tau)^k}\displaystyle \sum _{ \substack{I=\{i_1,\dots,i_k\}\\2\leq i_1<\cdots<i_k\leq m\\ 1\leq j_1,\dots,j_k\leq m+l}}{\widehat{A}}_{\{2,\dots,m\}-I}[C_{i_1\rightarrow j_1}\cdots C_{i_k\rightarrow j_k}a]\\
     &= \sum_{k\geq 0}\frac{1}{(2\sqrt{-1}\operatorname{Im}\tau)^k}\displaystyle \sum _{ \substack{I=\{i_1,\dots,i_k\}\\2\leq i_1<\cdots<i_k\leq m\\ 1\leq j_1,\dots,j_k\leq m+l}}{\widehat{A}}_{\{1,2,\dots,m\}-I}[C_{i_1\rightarrow j_1}\cdots C_{i_k\rightarrow j_k}a]\\
     &+\sum_{k\geq 0}\frac{1}{(2\sqrt{-1}\operatorname{Im}\tau)^{k+1}}\displaystyle \sum _{ \substack{I=\{i_1,\dots,i_k\}\\2\leq i_1<\cdots<i_k\leq m\\ 1\leq j, j_1,\dots,j_k\leq m+l}}{\widehat{A}}_{\{2,\dots,m\}-I}[C_{1\rightarrow j}C_{i_1\rightarrow j_1}\cdots C_{i_k\rightarrow j_k}a]\\
     &=\sum_{k\geq 0}\frac{1}{(2\sqrt{-1}\operatorname{Im}\tau)^k}\displaystyle \sum _{ \substack{I=\{i_1,\dots,i_k\}\\1\leq i_1<\cdots<i_k\leq m\\ 1\leq j_1,\dots,j_k\leq m}}{\widehat{A}}_{\{1,\dots,m\}-I}[C_{i_1\rightarrow j_1}\cdots C_{i_k\rightarrow j_k}a].\qedhere
  \end{align*}
\end{proof}




\subsection{The mixed type partition function and Dijkgraaf's master equation}\label{mixDijk}
\begin{defn}\label{mixtype}
 We define the genus one correlators of mixed type associated to an element $[-]\in \mathcal{H}_V$  as follows
\begin{align*}
 \langle -\rangle_{m,n}:&~{\mathcal{A}}^{\otimes(m+n)}\longrightarrow \mathbb{C},\\
    \langle a\rangle_{m,n}:&~=~  E_M\widehat{A}_{N}[a],
\end{align*}
where $a\in {\mathcal{A}}^{\otimes (m+n)}$, $M=\{1,\dots,m\}$, $N=\{m+1,\dots, m+n\}.$
\end{defn}

\begin{thm}\label{Contactequation}
Let  $v=v_{k_1}\otimes \cdots\otimes v_{k_{m+n}}$ with $v_{k_i}$ the element in the Dijkgraaf's condition. Then we have
$$
\langle v\rangle_{m,n}=\langle v\rangle_{m-1,n+1}+\frac{1}{2\sqrt{-1}\operatorname{Im}\tau}\sum_{1\leq j\leq m+n,j\neq m}\sum_{l\in\mathbb{N}}c^l_{k_mk_j}\langle v_{k_1}\otimes \displaystyle \underset{\text{m-th}}{1}\otimes\cdots \otimes\underset{\text{j-th}} {v_l} \otimes \cdots\otimes v_{k_{m+n}}\rangle_{m,n}.
$$
\end{thm}
We will prove this theorem in the next subsection.

\begin{defn}

We define the generating function of $\langle v\rangle_{m,n}$, i.e., the genus one partition function of mixed type to be
\begin{equation}\label{Zst}
Z(s,t):=\sum_{m\geq0}\sum_{n\geq0}\frac{1}{m!}\frac{1}{n!}\left\langle \left(\sum_{\alpha}{t^{\alpha}v_{\alpha}}\right)^{\otimes m}\otimes\left(\sum_{\beta}{s^{\beta}v_{\beta}}\right)^{\otimes n}\right\rangle_{m,n},
\end{equation}
where the two summations $\sum$ are taken over all the countable elements ${v_i}$ in the Dijkgraaf's condition, and $t^{\alpha}$, $s^{\beta}$ are formal variables.
\end{defn}

Theorem \ref{Contactequation} implies the following Dijkgraaf's master equation \cite{Dijk1996master}.
\begin{thm}\label{DijkgraafMaster}
The partition function $Z=Z(s,t)$ satisfies the following linear differential equation
\begin{equation}\label{Dijkmast}
\frac{\partial Z}{\partial t^i}=\left[\frac{\partial}{\partial s^i}+\frac{1}{2\sqrt{-1}\operatorname{Im}\tau}(L^{(s)}_i+L^{(t)}_i)\right]Z, \quad \forall ~i\in \mathbb{N},
\end{equation}
here
$$
L^{(s)}_i=\sum_{j,k\in\mathbb{N}}c^k_{ij}s^j\frac{\partial}{\partial s^k}, \quad L^{(t)}_i=\sum_{j,k\in\mathbb{N}}c^k_{ij}t^j\frac{\partial}{\partial t^k}.
$$
\end{thm}

\begin{proof} For any $m,n\geq0$, applying $\prod_{i=1}^m\prod_{j=1}^{n}\frac{\p}{\p t^{\alpha_i}}\frac{\p}{\p s^{\beta_j}}\bigg|_{s=t=0}$ to both sides of \eqref{Dijkmast}, we arrive at the identity of the form in Theorem \ref{Contactequation}.
\end{proof}

\subsection{Proof of Theorem \ref{ModifiedAcycleElliptic} and Theorem \ref{Contactequation}}\label{proofofpropthm}
In this subsection, we complete the proof of Theorem \ref{ModifiedAcycleElliptic} and Theorem \ref{Contactequation}. Throughout this section we denote
\begin{align*}
&M=\{1,\ldots,n\},\quad N=\{m+1,\ldots,m+n\},\\
&M'=M-\{m\},\quad M_k'=M'-\{k\},~\text{ for any }k\in M'\\
&I^c:=N-I,~\text{ for any } I\subset N.
\end{align*}

Since the computation of the proof is cumbersome, we explain the proof idea first. We want to prove Theorem \ref{ModifiedAcycleElliptic} by induction on $|N|$.
\begin{itemize}
  \item The first step ($|N|=0$) for induction is trivial.
  \item For the second step, we assume that $\hat{A}_N[a]$ is almost-meromorphic and elliptic, satisfies the axioms (1)-(5), and then prove the following identity holds
$$E_{m}\widehat{A}_{N}[a]=\widehat{A}_{N\cup\{m\}}[a]+\frac{1}{2\sqrt{-1}\operatorname{Im}\tau}\sum_{0\leq j\leq m+n,j\neq m}\widehat{A}_{N}[C_{m\rightarrow j}a].$$
It follows that $\widehat{A}_{N\cup\{m\}}[a]$ is almost-meromorphic and elliptic, satisfies the axioms (1)-(5).
\end{itemize}

One of the key points in the second step is that we have to compute the surface integral for an almost-meromorphic and elliptic function. There is such a formula in Lemma 3.26 \cite{SiJie2020}. But according to our definition of the modified $A$-cycle integral $\hat{A}_N$, we need a modified form of that formula. For completeness, we write our formula as follows and prove it based on the methods in Lemma 3.26 \cite{SiJie2020}.


\begin{lem}\label{RegIntegralF}
  Let $F(z_1,\dots,z_m;\tau)$ be an almost-meromorphic elliptic function on $\mathbb{C}^{m}\times \mathbf{H}$. Assume that $F$ can be written as
   $$
  F=F_0+\sum^n_{l=1}\partial_{z_m}\left(\left(\frac{\operatorname{Im}z_m}{\operatorname{Im}\tau}\right)^{l}\partial^{l-1}_{z_m}F_l\right),
  $$
  where $F_0(-,z_m;\tau),\dots, F_n(-,z_m;\tau)$ are meromorphic functions on $\mathbb{C}\times \mathbf{H}$ . Moreover, we assume that each $F_i$ is holomorphic way from diagonals. Then
$$
E_mF=\oint_Adz_m\left(F_0+\frac{1}{2\sqrt{-1}\operatorname{Im}\tau}F_1\right)+\sum_{1\leq k\leq m-1}\operatorname{Res}_{z_m=z_k}\left(\frac{\operatorname{Im}z_m}{\operatorname{Im}\tau}F_0\right).
$$

  \end{lem}
\begin{proof}
  We rewrite $F$ as
  $$
  F=F_0+\frac{1}{2\sqrt{-1}\operatorname{Im}\tau}F_1+\sum^{n-1}_{l=1} \left(\frac{\operatorname{Im}z_m}{\operatorname{Im}\tau}\right)^l\left(\partial^l_{z_m}F_{l}+\frac{l+1}{2\sqrt{-1}\operatorname{Im}\tau}\partial^l_{z_m}F_{l+1}\right)+\left(\frac{\operatorname{Im}z_m}{\operatorname{Im}\tau}\right)^n\partial^n_{z_m}F_n.
  $$
  Let
  \begin{align*}
  \Psi=~&\frac{\operatorname{Im}z_m}{\operatorname{Im}\tau}\left(F_0+\frac{1}{2\sqrt{-1}\operatorname{Im}\tau}F_1\right)+\sum^{n-1}_{l=1} \frac{1}{l+1}\left(\frac{\operatorname{Im}z_m}{\operatorname{Im}\tau}\right)^{l+1}\left(\partial^l_{z_m}F_{l}+\frac{l+1}{2\sqrt{-1}\operatorname{Im}\tau}\partial^l_{z_m}F_{l+1}\right)\\
  &+\frac{1}{n+1}\left(\frac{\operatorname{Im}z_m}{\operatorname{Im}\tau}\right)^{n+1}\partial^n_{z_m}F_n,
  \end{align*}
  then
  $$
  \Psi=\frac{\operatorname{Im}z_m}{\operatorname{Im}\tau}F_0+\sum^n_{l=1}\partial_{z_m}\left(\frac{1}{l+1}\left(\frac{\operatorname{Im}z_m}{\operatorname{Im}\tau}\right)^{l+1}\partial^{l-1}_{z_m}F_l\right), \quad \partial_{\bar{z}_m}\Psi=\frac{\sqrt{-1}}{2\operatorname{Im}\tau}F.
  $$
  It follows that 
\begin{itemize}
    \item the relation $F(z_m+1)=F(z_m)$ implies $\Psi(z_m+1)=\Psi(z_m)$;
    \item the relation $F(z_m+\tau)=F(z_m)$ implies
  $$
 \partial_{\bar{z}_m}( \Psi(z_m+\tau)-\Psi(z_m))=\frac{\sqrt{-1}}{2\operatorname{Im}\tau}(F(z+\tau)-F(z))=0.
  $$
  This further implies
  $$
  \Psi(z_m+\tau)-\Psi(z_m)=F_0+\frac{1}{2\sqrt{-1}\operatorname{Im}\tau}F_1+\sum^{n-1}_{l=1} \frac{\partial_{z_m}^lF_{l}+\frac{l+1}{2\sqrt{-1}\operatorname{Im}\tau}\partial_{z_m}^lF_{l+1}}{l+1}+\frac{\partial^n_{z_m}F_n}{n+1}.
  $$
\end{itemize}

Now using Theorem \ref{Stokes} (Stokes' Theorem), we have
\begin{align*}
   E_mF=& \dashint_{E_{\tau}}\frac{d^2z_m}{\operatorname{Im}\tau}F=-\dashint_{E_{\tau}}d(\Psi dz_m)\\
   =&\oint_Adz_m(\Psi(z_m+\tau)-\Psi(z_m))-\oint_Bdz_m(\Psi(z_m+1)-\Psi(z_m))+\sum_{1\leq k\leq m-1}\Res_{z_m=z_k}\Psi(z_m)\\
   =&\oint_Adz_m\left(F_0+\frac{1}{2\sqrt{-1}\operatorname{Im}\tau}F_1+\sum^{n-1}_{l=1} \frac{\partial_{z_m}^lF_{l}+\frac{l+1}{2\sqrt{-1}\operatorname{Im}\tau}\partial_{z_m}^lF_{l+1}}{l+1}+\frac{\partial^n_{z_m}F_n}{n+1}\right) \\
    &+\sum_{1\leq k\leq m-1}\operatorname{Res}_{z_m=z_k}\left(\frac{\operatorname{Im}z_m}{\operatorname{Im}\tau}F_0+\sum^n_{l=1}\partial_{z_m}\bigg(\frac{1}{l+1}\bigg(\frac{\operatorname{Im}z_m}{\operatorname{Im}\tau}\bigg)^{l+1}\partial^{l-1}_{z_m}F_l\bigg)\right)\\
   =&\oint_Adz_m\left(F_0+\frac{1}{2\sqrt{-1}\operatorname{Im}\tau}F_1\right)+\sum_{1\leq k\leq m-1}\operatorname{Res}_{z_m=z_k}\frac{\operatorname{Im}z_m}{\operatorname{Im}\tau}F_0. \qedhere
\end{align*}
\end{proof}

Now let us start with the proof of Theorem \ref{ModifiedAcycleElliptic}.

\begin{proof}[Proof of Theorem \ref{ModifiedAcycleElliptic}] We prove it by induction on $|N|$. When $|N|=0$, there is nothing to prove. Now we assume $\widehat{A}_N[a]$ is almost-meromorphic and elliptic for any $M$ and $a\in \mathcal{A}^{\otimes(m+n)},m=|M|.$
\vskip 0.1cm
We decompose $\widehat{A}_{N}[v]$ as the above lemma for $F$,
$$
\widehat{A}_{N}[v]=\displaystyle \sum _{ \substack{I\subset N,\\
\phi:I\rightarrow M'}}D^{\phi}_{I\rightarrow M'}A_{{I}^c} [B^{\phi}_{{I\rightarrow M'}}v]+\displaystyle \sum _{ \substack{I\cup I_1\subset N,I_1\neq\emptyset\\
\phi:I\rightarrow M'}}D_{I_1\rightarrow m}D^{\phi}_{I\rightarrow M'}A_{{(I\cup I_1)}^c} [B_{I_1\rightarrow m}B^{\phi}_{{I\rightarrow M}}v],
$$
and use Lemma \ref{RegIntegralF}, we get
\begin{align*}
    E_m\widehat{A}_N[a] =&\oint_Adz_m\displaystyle \sum _{ \substack{I\subset N,\\
\phi:I\rightarrow M'}}D^{\phi}_{I\rightarrow M'}A_{{I}^c} [B^{\phi}_{{I\rightarrow M'}}a]+\underbrace{\oint_Adz_m\displaystyle \sum _{ \substack{I\cup \{l\}\subset N\\
\phi:I\rightarrow M'}}D^{\phi}_{I\rightarrow M'}A_{{(I\cup \{l\})}^c} [B^{\phi}_{{I\rightarrow M'}}B_{l\rightarrow m}a]}_{\Circled{1}}\\
&+\sum_{k\in M'}\operatorname{Res}_{z_m=z_k}\frac{\operatorname{Im}z_m}{\operatorname{Im}\tau}\displaystyle \sum _{ \substack{I\subset N,\\
\phi:I\rightarrow M'}}D^{\phi}_{I\rightarrow M'}A_{{I}^c} [B^{\phi}_{{I\rightarrow M'}}a].
\end{align*}
To compute the residue term $\operatorname{Res}_{z_m=z_k}$, for each $k\in M'$, we decompose again
\begin{align*}
   & \displaystyle \sum _{ \substack{I\subset N,\\
\phi:I\rightarrow M'}}D^{\phi}_{I\rightarrow M'}A_{{I}^c} [B^{\phi}_{{I\rightarrow M'}}a] \\
=&\underbrace{\displaystyle \sum _{ \substack{I\subset N,\\
\phi:I\rightarrow M'_k}}D^{\phi}_{I\rightarrow M'_k}A_{{I}^c} [B^{\phi}_{{I\rightarrow M'_k}}a]}_{\Circled{2}}+\underbrace{\displaystyle \sum _{ \substack{I\cup I_1\subset N, I_1\neq \emptyset\\
\phi:I\rightarrow M'_k}}D_{I_1\rightarrow k}D^{\phi}_{I\rightarrow M'_k}A_{{I}^c} [B_{I_1\rightarrow k}B^{\phi}_{{I\rightarrow M'_k}}a]}_{\Circled{3}},
\end{align*}

The three terms $\Circled{1}$, $\Circled{2}$, and $\Circled{3}$ are computed by the following lemmas \ref{B=C}, \ref{SingleCollide} and \ref{MultipleCollide}, respectively. Then we get
\begin{align*}
    E_m\widehat{A}_N[a] =&\oint_Adz_m\displaystyle \sum _{ \substack{I\subset N,\\
\phi:I\rightarrow M'}}D^{\phi}_{I\rightarrow M'}A_{{I}^c} [B^{\phi}_{{I\rightarrow M'}}a]+ \underbrace{\frac{1}{2\sqrt{-1}\operatorname{Im}\tau}\displaystyle \sum _{ \substack{I\cup \{l\}\subset N\\
\phi:I\rightarrow M'}}D^{\phi}_{I\rightarrow M'}A_{{I}^c} [B^{\phi}_{{I\rightarrow M'}}C_{m\rightarrow l}a]}_{\Circled{1}}\\
   & +\underbrace{\sum_{k\in M'}\displaystyle \sum _{ \substack{I\subset N,\\
\phi:I\rightarrow M'_k}}D_{1,k}D^{\phi}_{I\rightarrow M'_k}A_{{I}^c} [B_{m\rightarrow k}B^{\phi}_{{I\rightarrow M'_k}}a]+\frac{1}{2\sqrt{-1}\operatorname{Im}\tau}\sum_{k\in M'}\displaystyle \sum _{ \substack{I\subset N,\\
\phi:I\rightarrow M'_k}}D^{\phi}_{I\rightarrow M'_k}A_{{I}^c} [B^{\phi}_{{I\rightarrow M'_k}}C_{m\rightarrow k}a]}_{\Circled{2}}\\
&\left.
\begin{aligned}
&+\sum_{k\in M'}\displaystyle \sum _{ \substack{I\cup I_1\subset N,I_1\neq \emptyset\\
\phi:I\rightarrow M'_k}}D_{I_1\cup \{m\}\rightarrow k}D^{\phi}_{I\rightarrow M'_k}A_{{I}^c} [B_{I_1\cup\{m\}\rightarrow k}B^{\phi}_{{I\rightarrow M'_k}}a]\\
&+\frac{1}{2\sqrt{-1}\operatorname{Im}\tau}\sum_{k\in M'}\displaystyle \sum _{ \substack{I\cup I_1\subset N,I_1\neq \emptyset\\
\phi:I\rightarrow M'_k}}D_{I_1 \rightarrow k}D^{\phi}_{I\rightarrow M'_k}A_{{I}^c} [B_{I_1\rightarrow k}B^{\phi}_{{I\rightarrow M'_k}}C_{m\rightarrow k}a]\\
&+\frac{1}{2\sqrt{-1}\operatorname{Im}\tau}\sum_{k\in M'}\displaystyle \sum _{ \substack{I\cup I_1\subset N, l\in I_1\\
\phi:I\rightarrow M'_k}}D_{I_1 \rightarrow k}D^{\phi}_{I\rightarrow M'_k}A_{{I}^c} [B_{I_1\rightarrow k}B^{\phi}_{{I\rightarrow M'_k}}C_{m\rightarrow l}a]\\
\end{aligned}
\right\}
~\Circled{3}\\
=~&\widehat{A}_{N\cup\{m\}}[a]+\frac{1}{2\sqrt{-1}\operatorname{Im}\tau}\sum_{0\leq j\leq m+n,j\neq m}\widehat{A}_{N}[C_{m\rightarrow j}a].
\end{align*}
The last equality is obtained by combining the $C$-terms and the remaining ones respectively.
Since the surface integral of an elliptic function is still elliptic and preserves the axioms (1)-(5), by the induction hypothesis and the above formula, $\widehat{A}_{N\cup\{m\}}$ is elliptic and obviously almost-meromorphic, satisfies the axioms (1)-(5).
\end{proof}



\begin{lem}\label{B=C}
We have
$$
\oint_Adz_m\displaystyle \sum _{ \substack{I\cup \{l\}\subset N\\
\phi:I\rightarrow M'}}D^{\phi}_{I\rightarrow M'}A_{{(I\cup \{l\})}^c} [B^{\phi}_{{I\rightarrow M'}}B_{l\rightarrow m}a]=\displaystyle \sum _{ \substack{I\cup \{l\}\subset N\\
\phi:I\rightarrow M'}}D^{\phi}_{I\rightarrow M'}A_{{I}^c} [B^{\phi}_{{I\rightarrow M'}}C_{m\rightarrow l}a]
$$
\end{lem}

\begin{proof} This lemma follows from Lemma \ref{BCS} and the fact that both $\oint_Adz_m$ and $\oint_Adz_l$ commute with the operations $D^{\phi}_{I\rightarrow M'}$ and $B^{\phi}_{I\rightarrow M'}$, since $l\notin I$ and $m\notin M'$.
\end{proof}

