\begin{lem}\label{SingleCollide}
We have
\begin{align*}
   & \operatorname{Res}_{z_m=z_k}\frac{\operatorname{Im}z_m}{\operatorname{Im}\tau}\displaystyle \sum _{ \substack{I\subset N,\\
\phi:I\rightarrow M'_k}}D^{\phi}_{I\rightarrow M'_k}A_{{I}^c} [B^{\phi}_{{I\rightarrow M'_k}}a] \\
   & =\displaystyle \sum _{ \substack{I\subset N,\\
\phi:I\rightarrow M'_k}}D_{1,k}D^{\phi}_{I\rightarrow M'_k}A_{{I}^c} [B_{m\rightarrow k}B^{\phi}_{{I\rightarrow M'_k}}v]+\frac{1}{2\sqrt{-1}\operatorname{Im}\tau}\displaystyle \sum _{ \substack{I\subset N,\\
\phi:I\rightarrow M'_k}}D^{\phi}_{I\rightarrow M'_k}A_{{I}^c} [B^{\phi}_{{I\rightarrow M'_k}}C_{m\rightarrow k}a].
\end{align*}
\end{lem}
\begin{proof}
Note that the operation $\operatorname{Res}_{z_m=z_k}\frac{\operatorname{Im}z_m}{\operatorname{Im}\tau}$ commutes with the operation $\displaystyle \sum _{ \substack{I\subset N,\\
\phi:I\rightarrow M'_k}}D^{\phi}_{I\rightarrow M'_k}A_{{I}^c} $, so we only need to compute
$$
 \operatorname{Res}_{z_m=z_k}\frac{\operatorname{Im}z_m}{\operatorname{Im}\tau}[B^{\phi}_{{I\rightarrow M'_k}}a], \quad \text{for } I\subset N, \phi:I\rightarrow M'_k.
$$
It is done by Equation \eqref{modfiedBCD}.
\end{proof}

