\begin{lem}\label{MultipleCollide}
  We have\begin{align*}
&\operatorname{Res}_{z_m=z_k}\frac{\operatorname{Im}z_m}{\operatorname{Im}\tau}\displaystyle \sum _{ \substack{I\cup I_1\subset N,\\
\phi:I\rightarrow M'_k}}D_{I_1\rightarrow k}D^{\phi}_{I\rightarrow M'_k}A_{{I}^c} [B_{I_1\rightarrow k}B^{\phi}_{{I\rightarrow M'_k}}a] \\
=~ & \displaystyle \sum _{ \substack{I\cup I_1\subset N,\\
\phi:I\rightarrow M'_k}}D_{I_1\cup \{m\}\rightarrow k}D^{\phi}_{I\rightarrow M'_k}A_{{I}^c} [B_{I_1\cup\{m\}\rightarrow k}B^{\phi}_{{I\rightarrow M'_k}}a]\\
&+\frac{1}{2\sqrt{-1}\operatorname{Im}\tau}\displaystyle \sum _{ \substack{I\cup I_1\subset N,\\
\phi:I\rightarrow M'_k}}D_{I_1 \rightarrow k}D^{\phi}_{I\rightarrow M'_k}A_{{I}^c} [B_{I_1\rightarrow k}B^{\phi}_{{I\rightarrow M'_k}}C_{m\rightarrow k}a]\\
&+\frac{1}{2\sqrt{-1}\operatorname{Im}\tau}\displaystyle \sum _{ \substack{I\cup I_1\subset N, l\in I_1\\
\phi:I\rightarrow M'_k}}D_{I_1 \rightarrow k}D^{\phi}_{I\rightarrow M'_k}A_{{I}^c} [B_{I_1\rightarrow k}B^{\phi}_{{I\rightarrow M'_k}}C_{m\rightarrow l}a].
\end{align*}

\end{lem}
\begin{proof}
For any $I\cup I_1\subset N,\phi:I\rightarrow M'_k$, the operation $\operatorname{Res}_{z_m=z_k}\frac{\operatorname{Im}z_m}{\operatorname{Im}\tau}D_{I_1\rightarrow k}$ commute with $D^{\phi}_{I\rightarrow M'_k}A_{{I}^c}$. Thus we only need to consider
$$
   \operatorname{Res}_{z_m=z_k}\frac{\operatorname{Im}z_m}{\operatorname{Im}\tau}D_{I_1\rightarrow k} [B_{I_1\rightarrow k}B^{\phi}_{{I\rightarrow M'_k}}a].
$$
By a direct computation, we have
\begin{align*}
  &\operatorname{Res}_{z_m=z_k}\frac{\operatorname{Im}z_m}{\operatorname{Im}\tau} D_{I_1\rightarrow k}[B_{I_1\rightarrow k}B^{\phi}_{{I\rightarrow M'_k}}a]\\
=~& D_{I_1\rightarrow k}\operatorname{Res}_{z_m=z_k}\frac{\operatorname{Im}z_m}{\operatorname{Im}\tau}[B_{I_1\rightarrow k}B^{\phi}_{{I\rightarrow M'_k}}a]\\
\overset{(1)}=~& D_{I_1\rightarrow k}\p_{z_k}\left(\frac{\operatorname{Im}z_k}{\operatorname{Im}\tau}[B_{m\rightarrow k}B_{I_1\rightarrow k}B^{\phi}_{{I\rightarrow M'_k}}a]\right)+\frac{1}{2\sqrt{-1}\operatorname{Im}\tau}D_{I_1\rightarrow k}[C_{m\rightarrow k}B_{I_1\rightarrow k}B^{\phi}_{{I\rightarrow M'_k}}a]\\
\overset{(2)}=~&D_{I_1\cup \{m\}\rightarrow k} [B_{I_1\cup\{m\}\rightarrow k}B^{\phi}_{{I\rightarrow M'_k}}a]+\frac{1}{2\sqrt{-1}\operatorname{Im}\tau}D_{I_1\rightarrow k}|I_1|[B_{m\rightarrow k}B_{I_1\rightarrow k}B^{\phi}_{{I\rightarrow M'_k}}a]\\
&+\frac{1}{2\sqrt{-1}\operatorname{Im}\tau}D_{I_1\rightarrow k}[C_{m\rightarrow k}B_{I_1\rightarrow k}B^{\phi}_{{I\rightarrow M'_k}}a]\\
\overset{(3)}=~&D_{I_1\cup \{m\}\rightarrow k} [B_{I_1\cup\{m\}\rightarrow k}B^{\phi}_{{I\rightarrow M'_k}}a]+\frac{1}{2\sqrt{-1}\operatorname{Im}\tau}D_{I_1\rightarrow k} [B_{I_1\rightarrow k}B^{\phi}_{{I\rightarrow M'_k}}C_{m\rightarrow k}a]\\
&+\frac{1}{2\sqrt{-1}\operatorname{Im}\tau}\sum_{l\in I_1}D_{I_1\rightarrow k} [B_{I_1\rightarrow k}B^{\phi}_{{I\rightarrow M'_k}}C_{m\rightarrow l}a],
\end{align*}
where (1) holds by Equation \eqref{modfiedBCD}; (2) holds by definition of $D_{I_1\rightarrow k}$ and
$$\left[\p_{z_k}^{|I_1|},\frac{\operatorname{Im}z_k}{\operatorname{Im}\tau}\right]=\frac{|I_1|}{2\sqrt{-1}\operatorname{Im}\tau}\p_{z_k}^{|I_1|-1};$$
and (3) holds by Lemma \ref{Useful}.
\end{proof}

