Now we turn to prove Theorem \ref{Contactequation}.
\begin{lem}\label{VanishTotal}
  We have
  $$
  E_M\widehat{A}_N(\partial_{z_k}[a])=0, \quad\forall~ k\in M, ~a\in\mathcal{A}^{\otimes(m+n)}.
  $$
\end{lem}
\begin{proof}
We prove this by induction on $|N|$. If $|N|=0,$ then
$$
E_M\partial_{z_k}[a]=E_{M-\{k\}}E_k\partial_{z_k}[a]=0.
$$
Now suppose $|N|>0$, we pick $l\in N$ and use Proposition \ref{ModifiedAcycleElliptic}
\begin{align*}
  E_M\widehat{A}_N\partial_{z_k}[a] &=E_M(E_l\widehat{A}_{N-\{l\}}[T_ka]-\frac{1}{2\sqrt{-1}\operatorname{Im}\tau}\sum_{i\neq l}\widehat{A}_{N-\{l\}}[C_{l\rightarrow i}T_ka]) .
\end{align*}
Now note that
\begin{itemize}
  \item For $i\neq k$, $[C_{l\rightarrow i}, T_k]=0$;
  \item For $i=k$, the $k$-th element of $C_{l\rightarrow k}T_ka$ is
  \begin{align*}
  C(a_l,Ta_k)&=T^{-1}((Ta_k)_{(0)}a_l)+Tb\quad\text{for some }b\in\mathcal{A}\\
           &=Tb.  \quad (\text{Proposition }\ref{immediateconseq}, (Ta_k)_{(0)}=0)
  \end{align*}
\end{itemize}
By the induction hypothesis
$$
E_M\frac{1}{2\sqrt{-1}\operatorname{Im}\tau}\sum_{i\neq l}\widehat{A}_{N-\{l\}}[C_{l\rightarrow i}T_ka]=0,
$$
$$
E_ME_l\widehat{A}_{N-\{l\}}[T_ka]=0,
$$
combining the above identities, we obtain the lemma.
\end{proof}
\begin{proof}[Proof of Theorem \ref{Contactequation}] It follows from the above lemma and $C(v_i,v_j)-\sum_{k\in \mathbb{N}_+}c^k_{ij}v_k\in \operatorname{Im}(T)$.
\end{proof}




