\section{Chiral boson}\label{proofnormal}

In Example \ref{Walg}, we show that the $W_{\infty}$ algebra as a subalgebra of the free boson vertex algebra satisfies Dijkgraaf's integrable condition. To define various types of genus one partition function using two-step constructions, we need to construct a genus one conformal block first. For the chiral boson, we use normal ordered Feynman graphs (Subsection \ref{normalorderedFG}) to define the desired functions (Definition \ref{defnnormalorderedFG} and Proposition \ref{normalcorrelation}). In this section, we will give the detailed proof of Proposition \ref{normalcorrelation}.

\subsection{Proof of Axiom (1)-(5)}
\begin{proof}[Proof of Axiom (1)-(5)]
The axioms (1) and (2), i.e., the linearity for each $a_i\in V$ and the invariance of permutation, are obvious by definition.

(3)~$S((|0\rangle,z),(a_1,z_1),\ldots,(a_n,z_n),\tau)=S((a_1,z_1),\ldots,(a_n,z_n),\tau)$:

It follows from $\L(z):=Y(|0\rangle,z)=\Id$, which corresponds to an isolated vertex without tails and self-loops in the graph. So, the input of $\L(z)$ does not change the Feynmann graph function $\Phi_{\Gamma}$.

(4)~$S((L_{-1}a_1,z_1),\ldots,(a_n,z_n),\tau)=\frac{d}{dz_1}S((a_1,z_1),\ldots,(a_n,z_n),\tau)$:
\begin{align*}
&S((L_{-1}a_1,z_1),\ldots,(a_n,z_n),\tau)\\
=~&\eta(\tau)^{-1}\langle :Y(L_{-1}a_1, z_1):,:Y(a_2,z_2):,\cdots,:Y(a_n,z_n):;\tau\rangle\\
=~&\eta(\tau)^{-1}\langle :\frac{d}{dz_1}Y(a_1, z_1):,:Y(a_2,z_2):,\cdots,:Y(a_n,z_n):;\tau\rangle\\
\overset{*}=~&\eta(\tau)^{-1}\frac{d}{dz_1}\langle :Y(a_1, z_1):,:Y(a_2,z_2):,\cdots,:Y(a_n,z_n):;\tau\rangle\\
=~&\frac{d}{dz_1}S((a_1,z_1),\ldots,(a_n,z_n),\tau).
\end{align*}
Here the equality $*$ follows from the fact that $\frac{d}{dz}$ commutes with the two types of propagators, more explicitly,
  \begin{align*} &\frac{d}{dz}\left(\sum_{k,l\geq0}\partial_{z}^k\partial_{w}^lP(z,w)\frac{\p}{\p(\p^{k+1}\phi(z))}\frac{\p}{\p(\p^{l+1}\phi(w))}\p^i\phi(z)\p^j\phi(w)\right)\\
     =~& \left(\sum_{k,l\geq0}\partial_{z}^k\partial_{w}^lP(z,w)\frac{\p}{\p(\p^{k+1}\phi(z))}\frac{\p}{\p(\p^{l+1}\phi(w))}\right)\p^{i+1}\phi(z)\p^j\phi(w).\\
\text{and }~&\\
  &\frac{d}{dz}\left(\sum_{k,l\geq0}\partial_{z}^k\partial_{w}^lQ(z,w)\bigg|_{w=z}\frac{\p}{\p(\p^{k+1}\phi(z))}\frac{\p}{\p(\p^{l+1}\phi(z))}\p^i\phi(z)\p^j\phi(z)\right)=0\\
  &\left(\sum_{k,l\geq0}\partial_{z}^k\partial_{w}^lQ(z,w)\bigg|_{w=z}\frac{\p}{\p(\p^{k+1}\phi(z))}\frac{\p}{\p(\p^{l+1}\phi(z))}\right)\bigg(\p^{i+1}\phi(z)\p^j\phi(z)+\p^i\phi(z)\p^{j+1}\phi(z)\bigg)=0.
  \end{align*}

The axiom (5) is given by the following lemma \ref{graphOPE}. \qedhere

\end{proof}


