\subsection{Proof of Axiom (6)}
The proof of (6) will depend on the properties of the Weierstrass $\wp$ function. In particular, the product formulas (Proposition \ref{prodformula}) of the propagator $P(z-w;\tau)$ play an important role. First, let us recall the relevant functions including the modified Weierstrass $\wp$ function (i.e. the propagator), the modified Weierstrass zeta function and the Jacobi theta function, and discuss their relations. For more details, see \cite{Lang}.


The modified Weierstrass elliptic function $P(z;\tau)$ is defined by
$$P(z;\tau)=\wp(z;\tau)+\frac{\pi^2}{3}E_2(\tau).$$
The corresponding modified Weierstrass zeta function is defined by
$$\zeta(z;\tau)=~\frac{1}{z}+\sum_{(m,n)\in(\mathbb{Z}+\mathbb{Z})\setminus\{(0,0)\}}\left(\frac{1}{z-m-n\tau}+\frac{1}{m+n\tau}+\frac{z}{(m+n\tau)^2}\right)-\frac{\pi^2}{3}zE_2(\tau).$$
The following lemma is obvious.
\begin{lem} The functions $P(z;\tau)$ and $\zeta(z;\tau)$ satisfy the following properties
\begin{enumerate}
  \item $P(z;\tau)$ is even and elliptic in $z$;
  \item $\zeta(z;\tau)$ is odd and quasi-elliptic in $z$:
  $$\zeta(z+1;\tau)=\zeta(z;\tau),\quad \zeta(z+\tau;\tau)=\zeta(z;\tau)-2\pi i.$$
  Clearly, $P(z;\tau)=-\p_z\zeta(z;\tau).$
\end{enumerate}
\end{lem}


Another important function is the Jacobi theta function $\theta(z;\tau)$, which is defined to be
$$\theta(z;\tau)=\sum_{n=-\infty}^{\infty}\exp(\pi in^2\tau+2\pi i n z).$$
It is 1-periodic in $z$ and $\tau$-quasi-periodic in $z$. More explicitly, for $m,n\in\mathbb{Z}$,
$$\theta(z+m+n\tau;\tau)=\exp(-\pi in^2\tau-2\pi i nz)\theta(z;\tau).$$

It is known that the Jacobi theta function $\theta(z;\tau)$ satisfies the heat equation
\begin{equation}\label{thetaheat}
\p_{\tau}\theta(z;\tau)=-\frac{i}{4\pi}\p_z^2\theta(z;\tau).
\end{equation}

The Jacobi theta function $\theta(z;\tau)$ is related to $\zeta(z;\tau)$ and $P(z;\tau)$ as follows. First, the Jacobi theta function defined above is also considered along with three auxiliary theta functions. Here we only consider
$$\theta_1(z;\tau)=-\exp\bigg(\frac{1}{4}\pi i\tau+\pi i(z+\frac{1}{2})\bigg)\theta(z+\frac{1}{2}+\frac{1}{2}\tau;\tau).$$
Then
$$\zeta(z;\tau)=-\p_z\log\theta_1(z;\tau),\quad P(z;\tau)=\p_z^2\log\theta_1(z;\tau).$$

Using the heat equation \eqref{thetaheat} for $\theta(z;\tau)$ and the above relations, we get
\begin{lem} The following identity holds
\begin{equation*}
2\pi i\frac{d}{d\tau}\zeta(z)=-\zeta(z)P(z)-\frac{1}{2}P'(z).
\end{equation*}
Moreover, taking derivatives with respect to $z$, the following identity holds
\begin{equation}\label{PDE}
2\pi i\frac{d}{d\tau}P=\zeta P'-P^2+\frac{1}{2}P''.
\end{equation}
\end{lem}


Furthermore, we give the following additional formulas for the Weierstrass $\wp$ functions and the modified zeta functions, which lead to the product formulas \ref{prodformula} for the propagators with some efforts.

\begin{lem}[additional formula]\label{wpeq} The Weierstrass $\wp$ function satisfies
$$\wp(z+w)=\frac{1}{4}\left\{\frac{\wp'(z)-\wp'(w)}{\wp(z)-\wp(w)}\right\}^2-\wp(z)-\wp(w).$$
\end{lem}

\begin{lem}
\begin{equation}\label{Peq}
\frac{P'(z)-P'(w)}{P(z)-P(w)}=2\zeta(z+w)-2\zeta(z)-2\zeta(w).
\end{equation}
\end{lem}

\begin{proof} This lemma follows from the results in Chapter 18 of \cite{Lang}. Recall that the Weierstrass sigma function $\sigma$ is defined by
$$\sigma(z)=z\prod_{\omega\in(\mathbb{Z}+\mathbb{Z}\tau)\setminus\{(0,0)\}}\left(1-\frac{z}{\omega}\right)e^{z/\omega+\frac{1}{2}(z/\omega)^2}.$$
It is known that $\sigma(z)$ is related to the modified Weierstrass zeta function as follows
$$\zeta(z;\tau)+\frac{\pi^2}{3}zE_2(\tau)=\frac{\sigma'(z)}{\sigma(z)}$$
Using the identity
$$P(z)-P(w)=\wp(z)-\wp(w)=-\frac{\sigma(z+w)\sigma(z-w)}{\sigma^2(z)\sigma^2(w)}.$$
Taking the logarithm of this identity and then taking derivatives with respect to $z$, we get
$$\frac{P'(z)}{P(z)-P(w)}=\zeta(z+w)+\zeta(z-w)-2\zeta(z).$$
Repeating the computation with respect to $w$, we get the desired equation.
\end{proof}




\begin{prop}[Product formulas]\label{prodformula} (1) For three distinct points $u$, $v$ and $w$, we have the product formula
\begin{align*}
P(u-w)P(w-v)=~&2\pi i\frac{d}{d\tau}P(u-v)+\big(P(w-u)+P(w-v)\big)P(u-v)\\
                 &+\big(\zeta(w-u)-\zeta(w-v))\frac{d}{du}P(u-v).
\end{align*}

(2) For two distinct points $u$, $w$, the following identity holds
$$P(w-u)P(w-u)=2\pi i\frac{d}{d\tau}\frac{\pi^2}{3}E_2(\tau)+\frac{2\pi^2}{3}E_2(\tau)P(w-u)+\frac{1}{6}\frac{d^2}{dw^2}P(w-u).$$
\end{prop}


\begin{proof}
(1) First, by Lemma \ref{wpeq}, $P(u-v)=\wp(u-v)+\frac{\pi^2}{3}E_2(\tau)$ satisfies
\begin{equation}\label{P(u-v)}
P(u-v)=\frac{1}{4}\left\{\frac{P'(u-w)-P'(w-v)}{P(u-w)-P(w-v)}\right\}^2-P(u-w)-P(w-v)+\frac{\pi^2}{3}E_2(\tau).
\end{equation}
Substituting Equation \eqref{Peq} into Equation $\eqref{P(u-v)}$, and then taking derivatives with respect to $u$ and $v$, we get
\begin{align*}
-P''(u-v)=&-2P(u-v)^2+2\zeta(u-v)P'(u-v)+2\big(P(u-w)+P(w-v)\big)P(u-v)\\
          &-2\big(\zeta(u-w)+\zeta(w-v)\big)P'(u-v)-2P(u-w)P(w-v).
\end{align*}
Finally, using the differential equation \eqref{PDE}, we get the first product formula.
\vskip 0.1cm

(2) By a direct computation,
\begin{align*}
P(w-u)P(w-u)=~&(\wp(w-u)+\frac{\pi^2}{3}E_2)^2\\
                =~&\wp(w-u)^2+\frac{2\pi^2}{3}E_2\wp(w-u)+\left(\frac{\pi^2}{3}E_2\right)^2\\
                \overset{(1)}=~&\frac{1}{6}\frac{d^2}{dw^2}\wp(w-u)+\frac{1}{9}\pi^4E_4+\frac{1}{9}\pi^4E_2^2+\frac{2}{3}\pi^2E_2\wp(w-u)\\
                \overset{(2)}=~&2\pi i\frac{d}{d\tau}\left(\frac{\pi^2}{3}E_2\right)+\frac{2\pi^2}{3}E_2P(w-u)+\frac{1}{6}\frac{d^2}{dw^2}\wp(w-u).
\end{align*}
Here in the equality (1), we use the defining equation of the Weierstrass $\wp$ function
$$\wp'(z)^2=4\wp^3-g_2\wp-g_3,\quad g_2(\tau)=\frac{4}{3}\pi^4E_4(\tau),$$
and in the equality (2), we use the Ramanujan identity
$$\frac{1}{2\pi i}\p_{\tau}E_2=\frac{1}{12}(E_2^2-E_4).\qedhere$$


\end{proof}


\begin{lem}\label{Axiom(6)} Let $a_i=\phi_{-1}1, i=1,\ldots, n$ be the primary vectors for the Virasoro algebra, then
\begin{align*}
S=~&S((\omega,w_1),\ldots,(\omega,w_m),(a_1,z_1),\ldots,(a_n,z_n),\tau)\\
 =~&\eta(\tau)^{-1}\langle:T(w_1):,\ldots,:T(w_m):,:\p\phi(z_1):,\ldots,:\p\phi(z_n):;\tau\rangle
\end{align*}
satisfies the axiom (6):
\begin{align*}
&S((\omega,w),(\omega,w_1),\ldots,(\omega,w_m),(a_1,z_1),\ldots,(a_n,z_n),\tau)\\
=~&2\pi i\frac{d}{d\tau}S+\sum_{k=1}^n(\wp_1(w-z_k,\tau)-(w-z_k)\frac{\pi^2}{3}E_2(\tau))\frac{d}{dz_k}S\\
&+\sum_{k=1}^m(\wp_1(w-w_k,\tau)-(w-w_k)\frac{\pi^2}{3}E_2(\tau))\frac{d}{dw_k}S\\
&+\sum_{k=1}^n(\wp_2(w-z_k,\tau)+\frac{\pi^2}{3}E_2(\tau))S\\
&+\sum_{k=1}^m(\wp_2(w-w_k,\tau)+\frac{\pi^2}{3}E_2(\tau))2S\\
&+\frac{1}{2}\sum_{k=1}^m\wp_4(w-w_k,\tau)S((\omega,w_1),\ldots,\widehat{(\omega,w_k)},\ldots,(a_n,z_n),\tau).
\end{align*}
\end{lem}

\begin{proof} We consider the graph change by adding the new vertex $T(w)=\frac{1}{2}:(\p\phi(w))^2:$. The changes include the following three cases:

\noindent\textbf{Case 1.} $T(w)=\frac{1}{2}:(\p\phi(w))^2:$ connects to itself, i.e., for each original graph, adding an isolated self-loop:
