By Proposition \ref{prodformula}, we obtain
\begin{align*}
&P(u-w)P(w-v)\\
=~&2\pi i\frac{d}{d\tau}P(u-v)+\zeta(w-u)\frac{d}{du}P(u-v)+P(w-v)P(u-v)\\
 ~&+\zeta(w-v)\frac{d}{dv}P(u-v)+P(w-u)P(u-v).\\
=~&2\pi i\frac{d}{d\tau}P(u-v)\\
  &+\bigg(\wp_1(w-u)-(w-u)\frac{\pi^2}{3}E_2\bigg)\frac{d}{du}P(u-v)+\bigg(\wp_1(w-v)-(w-v)\frac{\pi^2}{3}E_2\bigg)\frac{d}{dv}P(u-v)\\
  &+\bigg(\wp_2(w-u)+\frac{\pi^2}{3}E_2\bigg)P(u-v)+\bigg(\wp_2(w-v)+\frac{\pi^2}{3}E_2\bigg)P(u-v).
\end{align*}

\noindent\textbf{Case 3.} The new vertex is added in the self-loop based on the vertex $w_i$:
