  \includegraphics[scale=0.5]{Fig4.png}
  \caption{Histogram of dihedral angles of 2048 5CB molecules after 200 ns MD simulation with ISO(6OBA)${}_2$ (blue dots) and the other enantiomer (red dots).}
  \label{fig:fig4}
\end{figure}

