	\section{preliminaries}
	In this section, we define various set convergences and introduce other key concepts. For a metric space $(X,d)$, a nonempty family $\mathcal{S}$ of nonempty subsets of $X$ which is hereditary, stable under finite union, and that forms a cover of $X$ is called a \textit{bornology} on $X$. The smallest bornology on a metric space $(X,d)$ is $\mathcal{F}(X)$, the family of all nonempty finite subsets of $X$, and the largest is $\mathcal{P}_0(X)$, the family of all nonempty subsets of $X$. Some other classical bornologies on a metric space $(X,d)$ are
	\begin{itemize}
		\item $\mathcal{B}_d(X)$ = the family of all nonempty $d$-bounded subsets of $(X,d)$; 
		\item $\mathcal{K}(X)$ = the set of all nonempty relatively compact subsets of $(X,d)$; 
		\item $\mathcal{T}\mathcal{B}_{d}(X)$  = the set of all nonempty $d$-totally bounded subsets of $(X,d)$.
	\end{itemize}  

	The open ball centered at $x\in X$ and radius $\epsilon > 0$ in $(X,d)$ is denoted by $B_d(x, \epsilon)$. For $A \subseteq X$ and $\epsilon > 0$, the \textit{$\epsilon$-enlargement of $A$}, denoted by $B_d(A, \epsilon)$, is defined as $B_d(A, \epsilon) = \{x \in X: d(x, A) < \epsilon\} = \cup_{x\in A}B_d(x,\epsilon)$. More generally, for a function $f:(X,d) \to (0,\infty)$, we define the \textit{functional enlargement} (or \textit{pointwise enlargement}) of $A\subseteq X$ by $B_d(A,f) = \cup_{x\in A}B_d(x,f(x))$. It is easy to see that $\overline{A} \subseteq B_d(A, \epsilon)$ for any $\epsilon > 0$, while $\overline{A}$ need not be contained in $B_d(A, f)$ for a general function $f:(X,d) \to (0,\infty)$. Recently in \cite{agarwal2024set}, the authors exhibited that functional enlargements arise naturally in the study of $\tau_{\mathcal{S},d}$-convergence.% In the next section, we use these enlargements to give a hit-type characterization of $\tau_{\mathcal{S},d}^{-}$-convergence.   %For nonempty subsets $A$ and $B$ of $X$, the \textit{excess of $A$ over $B$} is defined as, $e_d(A,B)= \sup\{d(a,B): a \in A\}$.   


	%	Beer et al. in \cite{Idealtopo} gave a unified approach to study hyperspace topologies through uniform convergence of distance functionals on members of a family $\mathcal{S} \subseteq \mathcal{P}_0(X)$. 
	\begin{definition}\label{definition T_S,d}\normalfont (\cite{cao})
		Let $(X,d)$ be a metric space and $\mathcal{S} \subseteq \mathcal{P}_0(X)$. Then a net $(A_\lambda)$ in $\mathcal{P}_0(X)$ is \textit{$\tau_{\mathcal{S},d}^-$-convergent} to a nonempty set $A$ if for any $\epsilon > 0$ and $S \in \mathcal{S}$, eventually, $d(x,A_{\lambda}) - d(x, A) < \epsilon$ for all $x \in S$. The corresponding topology is denoted by  $\tau_{\mathcal{S},d}^-$.
		Similarly, a net $(A_{\lambda})$ in $\mathcal{P}_0(X)$ is \textit{$\tau_{\mathcal{S},d}^+$-convergent} to a nonempty set $A$ if and only if for any $\epsilon > 0$ and $S \in \mathcal{S}$, eventually, $d(x,A) - d(x, A_{\lambda}) < \epsilon$ for all $x \in S$. The corresponding topology is denoted by  $\tau_{\mathcal{S},d}^+$. 
		%Then for any $S\in \mathcal{S}$ and $\epsilon > 0$ sets of the form $$ [S,\epsilon]^- = \{(A,C) \in \mathcal{P}_0(X) \times \mathcal{P}_0(X) : d(x,C) - d(x,A) < \epsilon ~~ \forall x \in S \}$$ forms a base for a quasi-uniformity on $\mathcal{P}_0(X)$. The corresponding topology is denoted by  $\tau_{\mathcal{S},d}^-$. Similarly, $\tau_{\mathcal{S},d}^+$ is the topology on $\mathcal{P}_0(X)$ generated by the quasi-uniformity given by sets of the form 
		%$$ [S,\epsilon]^+ = \{(A,C) \in \mathcal{P}_0(X) \times \mathcal{P}_0(X) : d(x,A) - d(x,C) < \epsilon ~~ \forall x \in S \}.$$
	\end{definition}
	The topology $\tau_{\mathcal{S},d}$ is the join of $\tau_{\mathcal{S},d}^-$ and $\tau_{\mathcal{S},d}^+$. A base for a compatible uniformity for $\tau_{\mathcal{S},d}$ is given by the family $\{U_{\mathcal{S},\epsilon} : S \in \mathcal{S}, \epsilon > 0\}$, where $$ U_{\mathcal{S},\epsilon} = \{(A,B) \in \mathcal{P}_0(X) \times \mathcal{P}_0(X) : |d(x,A) - d(x,B)| < \epsilon\ \ \forall x \in S\}.$$ 


	%So a net $(A_\lambda)$ in $\mathcal{P}_0(X)$ is $\tau_{\mathcal{S},d}$-convergent to a nonempty set $A$ if and only if for any $\epsilon > 0$ and $S \in \mathcal{S}$, eventually, $|d(x,A) - d(x, A_\lambda)| < \epsilon$ for all $x \in S$, that is, if the net $(d(\cdot, A_{\lambda}))$ converges to $d(\cdot, A)$ uniformly on members of $\mathcal{S}$. 

	\begin{definition}\label{S-convergence}\normalfont(\cite{BCL})
		Suppose $\mathcal{S}$ is a nonempty family of subsets of a metric space $(X,d)$. A net $(A_\lambda)$ is said to be \textit{lower bornological convergent} to $A$ in $\mathcal{P}_0(X)$ denoted by $\mathcal{S}^-$-convergence, if for each $\epsilon > 0$ and $S \in \mathcal{S}$, eventually $ A \cap S \subseteq B_d(A_\lambda, \epsilon)$.

		We say $(A_\lambda)$ is \textit{upper bornological convergent} to $A$ in $\mathcal{P}_0(X)$ denoted by $\mathcal{S}^+$-convergence, if for each $\epsilon > 0$ and $S \in \mathcal{S}$, eventually $ A_\lambda \cap S \subseteq B_d(A, \epsilon)$.

		A net $(A_\lambda)$ $\mathcal{S}$-converges to $A$ provided it is both $\mathcal{S}^-$-convergent and $\mathcal{S}^+$-convergent to $A$. The $\mathcal{S}$-convergence is known as the bornological convergence.
	\end{definition}
	Note that $e_d(A,B) \leq \epsilon \Leftrightarrow A \subseteq B_d(B, \epsilon)$, where $A,B \in \mathcal{P}_0(X)$ and $\epsilon > 0$. So a net $(A_{\lambda})$ is $\mathcal{S}$-convergent to $A$ in $CL(X)$ if and only if 
	for each $S \in \mathcal{S}$, $\lim_{\lambda}e_d(A\cap S, A_{\lambda})  = 0$ and $\lim_{\lambda}e_d(A_{\lambda}\cap S, A)  = 0$. 

	Indeed, for $\mathcal{S} = \mathcal{B}_d(X)$ the $\mathcal{S}$-convergence corresponds to the Attouch-Wets topology $\tau_{AW_d}$. However, in general, the $\mathcal{S}$-convergence may not correspond to a topology. In the last two decades, several researchers have explored structural properties of $\mathcal{S}$ under which $\mathcal{S}$-convergence becomes topological \cite{Bcas,PbciAWc,BCL}.

	\begin{definition}\normalfont (\cite{beer2014excess})\label{definition leftexcess}
		Let $(X,d)$ be a metric space and let $\mathcal{S}\subseteq \mathcal{P}_0(X)$. Then the \textit{left excess convergence} on $\mathcal{P}_0(X)$ is the convergence corresponding to the weakest topology on $\mathcal{P}_0(X)$ such that for each $S \in \mathcal{S}$, $$A \mapsto e_d(S, A) \quad(A \in \mathcal{P}_0(X))$$ is a continuous extended real-valued function on $\mathcal{P}_0(X)$. This convergence is denoted by $\mathcal{LE}_{\mathcal{S},d}$. It can be split into two parts:
		\begin{enumerate}[(i)]
			\item \textit{Upper left excess convergence}: It is the convergence corresponding to the weakest topology on $\mathcal{P}_0(X)$ such that each member of the family $\{e_d(S, \cdot): S \in \mathcal{S}\}$ is lower semi-continuous. It is denoted by $\mathcal{LE}_{\mathcal{S},d}^+$. 
			\item \textit{Lower left excess convergence}: It is the convergence corresponding to the weakest topology on $\mathcal{P}_0(X)$ such that each member of the family $\{e_d(S, \cdot): S \in \mathcal{S}\}$ is upper semi-continuous. It is denoted by $\mathcal{LE}_{\mathcal{S},d}^-$. 
		\end{enumerate}
	\end{definition} 

	It is well-known that for a family $\mathcal{S}$ of nonempty subsets of $(X,d)$ containing all singleton subsets of $X$, the $\mathcal{LE}_{\mathcal{S},d}^+$-convergence always coincides with the upper Wijsman convergence. But  $\mathcal{LE}_{\mathcal{S},d}^-$-convergence is sensitive to the choice of family $\mathcal{S}$ (see the end of this section). %For example,  when $\mathcal{S} = \mathcal{F}(X)$, $\mathcal{B}_d(X)$, $\mathcal{P}_0(X)$, the lower left excess convergence reduces to lower parts of the Wijsman, the Attouch-Wets, and the Hausdorff metric convergences, respectively. 

	As mentioned in pg $115$ of \cite{ToCCoS}, the full $\mathcal{LE}_{\mathcal{S},d}$-convergence in particular cases such as $\mathcal{S} = \mathcal{B}_d(X)$ and $\mathcal{P}_0(X)$ form natural dual convergences to the bounded proximal and proximal convergences, respectively. Therefore, for $\mathcal{S} = \mathcal{B}_d(X)$ and $\mathcal{P}_0(X)$, $\mathcal{LE}_{\mathcal{S},d}$-convergences are called as \textit{dual bounded proximal convergence} and \textit{dual proximal convergence}, respectively. In fact the join of bounded proximal convergence (proximal convergence) and dual bounded bounded proximal convergence (dual proximal convergence) amounts to the Attouch-Wets convergence (Hausdorff metric convergence) on $CL(X)$. %Similar is the case with join of proximal and dual proximal convergences which amounts to the Hausdorff metric topology on $CL(X)$. Further, for $\mathcal{S} = \mathcal{F}(X)$, $\mathcal{LE}_{\mathcal{S},d}$-convergence reduces to the Wijsman convergence on $\mathcal{P}_0(X)$.  

	%In \cite{Idealtopo}, the authors gave a characterization for the equivalence of $\tau_{\mathcal{S},d}^{-}$-convergence and $\mathcal{S^{-}}$-convergence. This characterization was given in terms of multifunctions (or set valued functions). In \cite{beer2023bornologies}, Beer gave another criterion for the equivalence of $\tau_{\mathcal{S},d}^{-}$-convergence and $\mathcal{S^{-}}$-convergence (Theorem ..., \cite{beer2023bornologies}). In the present paper, we reinvestigate this equivalence and provide a criterion in terms of underlying bornology $\mathcal{S}$. 


	In general, we have the following relations among the above defined set convergences (see Proposition $2$ of \cite{gapexcess}). $$ \mathcal{S}^- \leq \mathcal{LE}_{\mathcal{S},d}^- \leq \tau_{\mathcal{S},d}^-; \text{ and }   \mathcal{S}^+ \leq \tau_{\mathcal{S},d}^+.$$ However, $\mathcal{LE}_{\mathcal{S},d}^+$ and $\mathcal{S}^+$ may not be related in general. It is to be noted that many set convergences such as hit-and-miss, proximal hit-and-miss and gap convergences have their lower parts same as well-known lower Vietoris convergence. But this is not true for the convergences under consideration in the present paper. In fact, in the three standard cases when $\mathcal{S} = \mathcal{F}(X), \mathcal{B}_d(X)$, and $\mathcal{P}_0(X)$, we have 
	\begin{itemize}
		\item $\tau_{\mathcal{S},d}^{-} = \mathcal{S}^{-} = \mathcal{LE}_{\mathcal{S},d}^{-} = \tau_{W_d}^{-}$ for $\mathcal{S} = \mathcal{F}(X)$;
		\item $\tau_{\mathcal{S},d}^{-} = \mathcal{S}^{-} = \mathcal{LE}_{\mathcal{S},d}^{-} = \tau_{{AW}_d}^{-}$ for $\mathcal{S} = \mathcal{B}_d(X)$;
		\item $\tau_{\mathcal{S},d}^{-} = \mathcal{S}^{-} = \mathcal{LE}_{\mathcal{S},d}^{-} = \tau_{H_d}^{-}$ for $\mathcal{S} = \mathcal{P}_0(X)$;
	\end{itemize}   



	\section{$\tau_{\mathcal{S},d}$-convergence vis-\'a-vis $\mathcal{S}$-convergence}
	The  main aim of this section is to examine the equivalence of $\tau_{\mathcal{S},d}$-convergence and $\mathcal{S}$-convergence. It is shown that $\tau_{\mathcal{S},d} = \mathcal{S}$ if and only if $\tau_{\mathcal{S},d}^+ = \mathcal{S}^+$ and $\tau_{\mathcal{S},d}^- = \mathcal{S}^-$.  In \cite{agarwal2024set}, the authors present a necessary and sufficient condition on the structure of the bornology $\mathcal{S}$ for $\tau_{\mathcal{S},d}^+ = \mathcal{S}^+$ on $CL(X)$. In this section, we provide a characterization for the coincidence  $\tau_{\mathcal{S},d}^- = \mathcal{S}^-$. We also give some stability  conditions on the underlying bornology that enforce the equivalence of the above mentioned convergences. 

	 %Here we would like to mention that these coincidences were first characterized by Beer et al. in \cite{Idealtopo}. However, in the above study the role of the members of the underlying bornology was not completely transparent. Moreover, new concepts of Lip-selection and bornology being stable under Lip-selections (see, Definition \ref{stable under lip-selections}) have been introduced.
	We start with the following perspective of $\mathcal{S}^-$-convergence on $CL(X)$.
	\begin{theorem}[Hit-type characterization for $\mathcal{S}^-$-convergence]\label{Hit-type characterization for S-convergence}
		Let $(X,d)$ be a metric space and  let $\mathcal{S}$ be a bornology on $X$. Suppose $(A_{\lambda})$ is a  net in $CL(X)$ and $A \in CL(X)$. Then the following statements are equivalent:
		\begin{enumerate}[(i)]
			\item $(A_{\lambda})$ is $\mathcal{S}^-$-convergent to $A$;
			\item for $S \in \mathcal{S}$ and $\epsilon > 0$, whenever $A \cap S \neq \emptyset$ then eventually $A_{\lambda}\cap B_d(x, \epsilon) \neq \emptyset$ $\forall x \in A\cap S$. 
		\end{enumerate}
	\end{theorem}
	\begin{proof}
		$(i)\Rightarrow(ii).$ Let $S \in \mathcal{S}$ and  $\epsilon > 0$. If $A \cap S = \emptyset$, then we are done.  Otherwise by $(i)$, there is an $\lambda_0$ such that $A \cap S \subseteq B_d(A_{\lambda}, \epsilon)$ $\forall \lambda \geq \lambda_0$. Consequently, for $x \in A\cap S$ and $\lambda \geq \lambda_0$, $d(x, A_{\lambda}) < \epsilon$. Thus $(ii)$ follows. 

		$(ii)\Rightarrow (i).$ Let $S \in \mathcal{S}$ and $\epsilon > 0$. If $A \cap S =\emptyset$, then we are done. Otherwise choose $\lambda_0$ such that $\lambda \geq \lambda_0$, we have $A_{\lambda} \cap B_d(x, \epsilon) \neq \emptyset$ $\forall x \in A \cap S$. Pick $x \in A \cap S$. Then for each $\lambda \geq \lambda_0$, there is an $a_{\lambda} \in A_{\lambda}$ such that $d(x, a_{\lambda}) < \epsilon$. Consequently, $A \cap S \subseteq B_d(A_{\lambda}, \epsilon)$ $\forall \lambda \geq \lambda_0$.  
	\end{proof}
	It is evident that Theorem \ref{Hit-type characterization for S-convergence} holds for an arbitrary family $\mathcal{S}\subseteq \mathcal{P}_0(X)$. Moreover, it follows that for any $A \in CL(X)$ the net $(A \cap S)_{A\cap S \neq \emptyset}$ is $\mathcal{S}^-$-convergent to $A$, where $\mathcal{S}$ is directed by set inclusion.

	Now, we have the following hit-and-miss type characterization for $\mathcal{S}$-convergence which follows from Theorem $6.1$ of \cite{agarwal2024set} and Theorem \ref{Hit-type characterization for S-convergence}.  

	\begin{theorem}[Hit-and-Miss type characterization of $\mathcal{S}$-convergence]
		Let $(X,d)$ be a metric space and let $\mathcal{S}$ be a bornology on $X$. Suppose $(A_{\lambda})$ is a net in $CL(X)$ and $A \in CL(X)$. Then the following statements are equivalent:
		\begin{enumerate}[(i)]
			\item $(A_{\lambda})$ $\mathcal{S}$-converges to $A$;
			\item for $S_1, S_2 \in \mathcal{S}$ and $\alpha$, $\epsilon > 0$, whenever $A \cap B_d(S_1, \alpha) = \emptyset$ and $A \cap S_2 \neq \emptyset$, then eventually $A_{\lambda} \cap S_1 = \emptyset$ and $A_{\lambda} \cap B_d(x, \epsilon) \neq \emptyset$ $\forall x \in A\cap S_2$. 
		\end{enumerate}
	\end{theorem}

	%It is to be noted that the conditions $(i)$ and $(ii)$ of the above result are not equivalent for an arbitrary family $\mathcal{S} \subseteq \mathcal{P}_0(X)$. For counterexample, see Example $6$ of \cite{agarwal2024set}.

 Recall that for a bornology $\mathcal{S}$ on $(X,d)$, $\mathcal{S}^- \leqslant \mathcal{LE}_{\mathcal{S},d}^-\leqslant \tau_{\mathcal{S},d}^-$ on $CL(X)$.	For the sake of readers' interest, we state some results from the literature regarding the equivalence of  $\mathcal{S}^-$-convergence with $\mathcal{LE}_{\mathcal{S},d}^-$ and  $\tau_{\mathcal{S},d}^-$.   A strong sufficient condition for the coincidence of $\tau_{\mathcal{S},d}^-$ and $\mathcal{S}^-$ is that $\mathcal{S} \subseteq \mathcal{TB}_d(X)$. As $\mathcal{S}^- = \tau_{W_d}^- = \tau_{\mathcal{S},d}^-$ provided $\mathcal{S} \subseteq \mathcal{TB}_d(X)$ (see, Corollary 27 of \cite{Idealtopo}). 

	 The necessary and sufficient conditions for the coincidence of $\mathcal{LE}_{\mathcal{S},d}^-$ and $\tau_{\mathcal{S},d}^-$ with $\mathcal{S}^-$-convergence were explored by Beer et al. in \cite{gapexcess, Idealtopo}. More precisely, they characterized these coincidences in terms of convergence of certain nets as given in the following result.% A particular necessary and sufficient condition for the coincidence of $\tau_{\mathcal{S},d}^-$ with $\mathcal{S}^{-}$ and $\mathcal{LE}_{\mathcal{S},d}^-$ with $\mathcal{S}^-$ is  given in the following result.
	  \begin{proposition}\label{beercoincidenceresult} $($\cite{gapexcess, Idealtopo}$)$
	  	Let $(X,d)$ be a metric space and let $\mathcal{S}$ be a bornology on $X$.
	  	 Then the following statements are equivalent:
	  	 \begin{enumerate}[(i)]
	  	 	\item for each $A \in CL(X)$, the net $(A\cap S)_{A\cap S \neq \emptyset}$ is $\tau^-$-convergent to $A$;
	  	 	\item $\tau^- = \mathcal{S}^-$,

	  	 \end{enumerate}
	  	  where $\tau^- = \tau_{\mathcal{S},d}^-$ and $\mathcal{LE}_{\mathcal{S},d}^-$, respectively. 
	  \end{proposition}

	   The condition $(i)$ of Proposition \ref{beercoincidenceresult} does not picture out any structural property of bornology $\mathcal{S}$ for the coincidence of these convergences. However, for a bornology $\mathcal{S}$ on $(X,d)$, the coincidence of $\mathcal{S}^-$ and $\mathcal{LE}_{\mathcal{S},d}^-$ have the following nice characterization.

	   \begin{theorem}$($Theorem 4, \cite{gapexcess}$)$
	   	Let $(X,d)$ be a metric space and let $\mathcal{S}$ be a bornology on $X$.
	   	Then the following statements are equivalent:
	   	\begin{enumerate}[(i)]
	   		\item for each $A \in CL(X)$, $S \in \mathcal{S}$, whenever $0< \alpha< \epsilon$ such that $S \subseteq B_d(A,\alpha)$, then $\exists$ $S' \in \mathcal{S}$ such that $S \subseteq B_d(A\cap S', \epsilon)$;   
	   		\item $\mathcal{LE}_{\mathcal{S},d}^- = \mathcal{S}^-$.
	   		\end{enumerate}
	   \end{theorem}  
	    A comparatively less technical sufficient condition for the coincidence of $\mathcal{LE}_{\mathcal{S},d}^-$ and $\mathcal{S}^-$ is stated in the next result.
	    \begin{proposition}\label{stable under enlargement implies bornological and excess convergenec are same}$($Corollary $3$ of \cite{gapexcess}$)$
	    	Let $(X,d)$ be a metric space and let $\mathcal{S}$ be a bornology on $X$. If $\mathcal{S}$ is stable under enlargements, that is, if for each $S \in \mathcal{S}$ and $\epsilon > 0$ $B_d(S, \epsilon) \in \mathcal{S}$, then $\mathcal{LE}_{\mathcal{S},d}^- = \mathcal{S}^-$.
	    	\end{proposition}  
    	In Theorem \ref{lowerexcessandSselections}, we give a weaker condition than the stability of $\mathcal{S}$ under enlargements for the coincidence $\mathcal{LE}_{\mathcal{S},d}^- = \mathcal{S}^-$.

    	For the coincidence of $\mathcal{S}^-$ and $\tau_{\mathcal{S},d}^-$-convergences, the stability of $\mathcal{S}$ under constant enlargements is not enough. This can be seen through the following example. 

	    \begin{example}\label{counterexampleTsdandSlowerexcess}
	    	Let $(X,d) = (\mathbb{R}^2, d_e)$, where $d_e$ denotes the Euclidean metric. Consider the bornology $\mathcal{B}(\mathbb{R}^2)$ having base $\mathcal{B}_0 = \{S \subseteq \mathbb{R}^2:  \exists m \in \mathbb{N} \text{ such that }S \subseteq [-m,m] \times \mathbb{R}\}$. One can easily verify that $\mathcal{B}(\mathbb{R}^2)$ is stable under all constant enlargements. However, $\tau_{\mathcal{B}(\mathbb{R}^2),d}^- \neq \mathcal{B}(\mathbb{R}^2)^-$ on $CL(X)$. To see this, let $A$ be the set of all points on the line $y = x$ in the first quadrant and for each $n \in \mathbb{N}$, let $A_n = \{(x,x+ \frac{x}{n}): x \in [0,n]\}$. Take $S \in \mathcal{B}_0$ and $\epsilon > 0$. Choose $m, n_0\in \mathbb{N}$ such that $S \subseteq [-m,m]\times \mathbb{R}$ and $n_0 > \frac{m}{\epsilon}$. Pick $(x,x) \in A \cap S$. Then $d_e((x,x), (x,x+\frac{x}{n})) < \epsilon$ $\forall$ $n \geq n_0$. So $A_n \cap B_d((x,x), \epsilon) \neq \emptyset$ $\forall$ $n \geq n_0$. Thus, $(A_n)$ is $\mathcal{B}(\mathbb{R}^2)^-$-convergent to $A$ in $CL(X)$. On the other hand, for $S=\{(0,n): n \in \mathbb{N}\}$, $d_e((0,2n), A_n)- d_e((0,2n), A) > \frac{1}{2}$. Therefore, $(A_n)$ is not $\tau_{\mathcal{B}(\mathbb{R}^2),d}^-$-convergent to $A$. 
	    	\qed 
	    \end{example}

	In order for further investigations, we first introduce the following terminology. Let $\mathcal{Z}^+ = \{f:(X,d)\to \mathbb{R}: f(x) > 0 \text{ for all } x\in X\}$ and $L(\mathcal{Z}^+) = \{f\in \mathcal{Z}^+: f \text{ is Lipschitz}\}$. 
		\begin{definition}\normalfont
		Let $(X,d)$ be a metric space. Given nonempty subsets $A$ and $C$ of $X$ and $f \in \mathcal{Z}^+$, we call \textit{$A$ hits $f$-enlargement of $C$ pointwise} if $A \cap B_d(x,f(x)) \neq \emptyset$ $\forall x \in C$.    
	\end{definition}
	Note that if $f \in \mathcal{Z}^+$ is a constant function, then $A$ hits $B_d(C,f)$ pointwise provided $C \subseteq B_d(A,f)$. 

		\begin{theorem}\label{coincicdence of lower Tsd and S}
		Let $(X,d)$ be a metric space and let $\mathcal{S}$ be a bornology on $X$. Then the following statements are equivalent:
		\begin{enumerate}[(i)]
			\item $\tau_{\mathcal{S},d}^- = \mathcal{S}^-$;
			\item for $S \in \mathcal{S}$, $A \in CL(X)$, and $f,g \in \mathcal{Z}^+$ with $\displaystyle{\inf_{x \in S}(g(x)- f(x))>0}$, whenever $A$ hits $B_d(S,f)$ pointwise, then there exists $S' \in \mathcal{S}$ such that $A \cap S'$ hits $B_d(S,g)$ pointwise;  
			\item for $S \in \mathcal{S}$, $A \in CL(X)$, and $f,g \in L(\mathcal{Z}^+)$ with $\displaystyle{\inf_{x \in S}(g(x)- f(x))>0}$, whenever $A$ hits $B_d(S,f)$ pointwise, then there exists $S' \in \mathcal{S}$ such that $A \cap S'$ hits $B_d(S,g)$ pointwise.   
		\end{enumerate}
	\end{theorem}	 

	\begin{proof}
		$(i) \Rightarrow (ii)$. Suppose $(ii)$ fails. Then there exist $S_0 \in \mathcal{S}$, $A \in CL(X)$ and $f,g \in \mathcal{Z}^+$ such that $\inf_{x \in S_0}(g(x)-f(x)) = \epsilon>0$ and $A$ hits $B_d(S_0,f)$ pointwise but for any $S \in \mathcal{S}$, $A \cap S$ does not hit $B_d(S_0,g)$ pointwise. So for any $S \in \mathcal{S}$, we can find an $x_S \in S_0$ satisfying $A \cap S \cap B_d(x_S, g(x_S)) = \emptyset$. Direct $\mathcal{S}$ by set inclusion. For each $S \in \mathcal{S}$, define $A_S = \overline{A \cap S}$. Then $(A_S)_{A\cap S \neq \emptyset}$ is a net in $CL(X)$. We know that the net $(A_S)_{A\cap S \neq \emptyset}$ is $\mathcal{S}^-$-convergent to $A$. We show that it fails $\tau_{\mathcal{S},d}^-$-convergence. To see this, observe that $g(x_S) \leq d(x_S,A_S)$ for any $S \in \mathcal{S}$ and $f(x_S) > d(x_S,A)$. So $d(x_S,A_S) - d(x_S,A) > \epsilon$ for any $S \in \mathcal{S}$. Thus $(A_S)$ is not $\tau_{\mathcal{S},d}^-$-convergent to $A$. 

		$(ii)\Rightarrow (iii)$. It is immediate.

		$(iii) \Rightarrow (i)$. Let $(A_\lambda)$ be a net in $CL(X)$ which is $\mathcal{S}^-$-convergent to $A \in CL(X)$. Take $S \in \mathcal{S}$ and $\epsilon > 0$. Define $f = d(\cdot,A) + \epsilon$ and $g = d(\cdot, A) + 2 \epsilon$, so $f,g \in L(\mathcal{Z}^+)$ with $\inf_{x \in S}(g(x)-f(x)) = \epsilon$. Clearly $A$ hits $B_d(S,f)$ pointwise. By $(iii)$, there exists $S' \in \mathcal{S}$ such that $A \cap S'$ hits $B_d(S,g)$ pointwise. Also $(A_{\lambda})$ is $\mathcal{S}^-$-convergent to $A$, $\exists$ $\lambda_0$ such that $A\cap S' \subseteq B_d(A_{\lambda}, \epsilon)$ $\forall$ $\lambda \geq \lambda_0$. Take $x \in S$ and $\lambda \geq \lambda_0$. Then we can find a $y_x \in A \cap S'$ such that $d(x,y_x) < g(x)$. Also $d(y_x, A_{\lambda}) < \epsilon$. Then $d(x,A_{\lambda}) \leq d(x,y_x)+d(y_x, A_{\lambda}) < g(x)+ \epsilon$. Consequently, $d(x,A_{\lambda}) < d(x, A) + 3 \epsilon$ $\forall$ $\lambda \geq \lambda_0$ and $x \in S$. Therefore, $(A_{\lambda})$ is $\tau_{\mathcal{S},d}^-$-convergent to $A$.     
	\end{proof} 

	\begin{corollary}
		Let $(X,d)$ be a metric space. Then $\tau_{H_d}^- = \mathcal{P}_0(X)^-$. 
	\end{corollary}
	The proof of the following corollary highlights a reason for considering Lipschitz functions ($L(\mathcal{Z}^+)$) in Theorem \ref{coincicdence of lower Tsd and S}.

\begin{corollary}\label{coincidence lower BdX Tsd and S} $($see Proposition 3.1.6 of \cite{ToCCoS}$)$
Let $(X,d)$ be a metric space. Then $\tau_{AW_{d}}^- = \mathcal{B}_d(X)^-$ on $CL(X)$. 
\end{corollary}

	\begin{proof}
		Let $S \in \mathcal{B}_d(X)$, $A\in CL(X)$ and $f,g \in L(\mathcal{Z}^+)$ such that $\displaystyle{\inf_{x \in S}}\{g(x)-f(x)\}> 0$
		and $A$ hits $B_d(S,f)$ pointwise. For each $x \in S$, choose $a_x \in A\cap B_d(x,f(x))$. Set $S' = \{a_x: x \in S\}$. Note that $A\cap S'$ hits $B_d(S,g)$ pointwise. To finish the proof, we show that $S' \in \mathcal{B}_d(X)$. Take $a_x,a_{x'} \in S'$. Then  $d(a_x, a_{x'}) \leq d(a_x,x)+d(x,x')+d(x',a_{x'}) < f(x)+f(x')+$ diam $(S)$, where diam $(S)$ is diameter of $S$. Since $f \in L(\mathcal{Z}^+)$, by Theorem $9.1$ of \cite{beer2023bornologies}, $f(S)$ is bounded in $\mathbb{R}$. Also diam $(S) < \infty$. So $d(a_x,a_{x'}) < \infty$. Consequently, $S' \in \mathcal{B}_d(X)$. Therefore, by Theorem \ref{coincicdence of lower Tsd and S}, $\tau_{AW_{d}}^- = \mathcal{B}_d(X)^-$.   
		\end{proof}


\begin{corollary}\label{lowerTsd and S}
Let $(X,d)$ be a metric space and let $\mathcal{S}$ be a bornology on $X$. Then the following statements are equivalent:
\begin{enumerate}[(i)]
\item $\mathcal{S}^- \geqslant \tau_{\mathcal{S},d}^-$;				
\item $\mathcal{S}$-convergence $\geqslant \tau_{\mathcal{S},d}^-$-convergence;
\item for $S \in \mathcal{S}$, $A \in CL(X)$, and $f,g \in \mathcal{Z}^+$ with $\displaystyle{\inf_{x \in S}(g(x)- f(x))>0}$, whenever $A$ hits $B_d(S,f)$ pointwise, then there exists $S' \in \mathcal{S}$ such that $  A \cap S'$ hits $B_d(S,g)$ pointwise.
\end{enumerate}
\end{corollary}

\begin{proof}
The implication	$(i) \Rightarrow (ii)$ is trivial, and $(iii) \Rightarrow (i)$ follows from Theorem \ref{coincicdence of lower Tsd and S}.
We only need to show $(ii) \Rightarrow (iii)$. Suppose $(iii)$ fails. Observe that the net $(A_S)$ constructed in Theorem \ref{coincicdence of lower Tsd and S} is also $\mathcal{S}^+$-convergent to $A$. Consequently, $(A_S)$ is $\mathcal{S}$-convergent to $A$ while the $\tau_{\mathcal{S},d}^-$-convergence of $(A_S)$ to $A$ fails. Thus, we arrive at a contradiction.
\end{proof}
From the proof of Corollary \ref{coincidence lower BdX Tsd and S}, a property of $\mathcal{B}_d(X)$ can be extracted. To do this, we first define a selection of a set.

Consider a nonempty subset $S$ of a metric space $(X,d)$ and $f \in \mathcal{Z}^+$. For each $x \in S$, choose $y_x \in B_d(x, f(x))$. Then $S' = \{y_x:  x\in S\}$  is called an \textit{$f$-selection of $S$}. Moreover, when $f \in L(\mathcal{Z}^+)$, then an $f$-selection of $S$ is also phrased as \textit{Lip-selection of $S$}. 
\begin{definition}\label{stable under lip-selections}\normalfont
If a family $\mathcal{S}$ contains Lip-selections of all of its members, then we say \textit{$\mathcal{S}$ is stable under Lip-selections}.
\end{definition} Note that for each $f \in \mathcal{Z}^+$ and $S$ is always an $f$-selection of itself. 

\begin{proposition}\label{selectionsforBdX}
Let $(X,d)$ be a metric space. Then $\mathcal{B}_d(X)$ is stable under Lip-selections.
\end{proposition}
\begin{proof}
Let $S \in \mathcal{B}_d(X)$ and $f \in L(\mathcal{Z}^+)$. Let $S'$ be an $f$-selection of $S$. Take $y_x, y_{x'} \in S'$. Then $d(y_x,y_{x'}) \leq d(y_x,x)+ d(x,x')+d(x',y_{x'})\leq f(x)+f(x)+$ diam $(S)$. Proceeding now as in Corollary \ref{coincidence lower BdX Tsd and S}, we get $S' \in \mathcal{B}_d(X)$.
\end{proof}
If for any $S\in \mathcal{S}$ and any constant function $f \in \mathcal{Z}^+$ every $f$-selection of $S$ belongs to $\mathcal{S}$, then we say \textit{$\mathcal{S}$ is stable under constant selections}. Note that if $\mathcal{S}$ is stable under enlargements, then $\mathcal{S}$ is stable under constant selections.  However, the converse is not true. For example each selection of every member of the bornology $\mathcal{F}(\mathbb{R})$ is finite. 


Our next result gives a sufficient condition for the coincidence $\mathcal{S}^-=\mathcal{LE}_{\mathcal{S},d}^-$  which is weaker than the condition of Proposition \ref{stable under enlargement implies bornological and excess convergenec are same}. 

\begin{theorem}\label{lowerexcessandSselections}
Let $(X,d)$ be a metric space and let $\mathcal{S}$ be a bornology on $X$. If $\mathcal{S}$ is stable under constant selections, then $\mathcal{LE}_{\mathcal{S},d}^- = \mathcal{S}^-$ on $CL(X)$. 
\end{theorem} 
\begin{proof}
Let $(A_{\lambda})$ be $\mathcal{S}^-$-convergent to $A$ in $CL(X)$. Let $S \in \mathcal{S}$ and $\epsilon > 0$ be such that $e_d(S,A) < \epsilon$. Then for each $x \in S$, $\exists$ $a_x \in A$ such that $d(x, a_x) < \frac{\epsilon}{3}$. Set $S' =\{a_x: x \in S\}$, so $S'$ is a constant selection of $S$. By hypothesis, $S' \in \mathcal{S}$. Since $(A_{\lambda})$ is $\mathcal{S}^-$-convergent to $A$, by Theorem \ref{Hit-type characterization for S-convergence} $ \exists$ $\lambda_0$ such that for each $\lambda \geq \lambda_0$, we have $A_{\lambda} \cap B_d(a_x, \frac{\epsilon}{3}) \neq \emptyset$ $\forall$ $x \in S$. Fix $x \in S$ and $\lambda \geq \lambda_0$. Then $d(x, A_{\lambda}) \leq d(x,a_x)+d(a_x, A_{\lambda}) < \frac{2\epsilon}{3}$. Consequently, $e_d(S, A_{\lambda}) < \epsilon$. Therefore, $(A_{\lambda})$ is $\mathcal{LE}_{\mathcal{S},d}^-$-convergent to $A$ in $CL(X)$.    
\end{proof}

