		\begin{proof}The implications $(i) \Rightarrow (ii)$ follows from Theorem \ref{suff Tsd and S} and $(ii) \Rightarrow (iii)$ is immediate.

			$(iii) \Rightarrow (i)$. Let $S \in \mathcal{S}$ and $f \in L(\mathcal{Z}^+)$. By Theorem 6.4 of \cite{agarwal2024set}, either $B_d(S,f) \in \mathcal{S}$ or $B_d(S,f+\epsilon) = X$ for any $\epsilon > 0$. By the assumption, $B_d(S,f+\epsilon) \neq X$, thus we have $B_d(S,f) \in \mathcal{S}$. 
		\end{proof}
		Observe that for any unbounded metric space $(X,d)$ and $\mathcal{S} \subseteq \mathcal{B}_d(X)$, no Lipschitz enlargement of any $S \in \mathcal{S}$ is equal to $X$. In particular, for a normed linear space $(X,\parallel\cdot\parallel)$, to show $\mathcal{B}_d(X)$-convergence is compatible with $\tau_{AW_d}$-convergence, it is enough to prove that $\tau_{{AW}_d}^+ = \mathcal{B}_d(X)^+$. 


		We now deduce an another necessary and sufficient condition on the structure of bornology $\mathcal{S}$ for the coincidence $\tau_{\mathcal{S},d} = \mathcal{S}$. Before that, we first see when $\mathcal{S}$-convergence is stronger than $\tau_{\mathcal{S},d}^+$ on $CL(X)$. 
		\begin{theorem}\label{upperTsd and S}        
			Let $(X,d)$ be a metric space and let $\mathcal{S}$ be a bornology on $X$. Then the following statements are equivalent:
			\begin{enumerate}[(i)]                      
				\item $ \mathcal{S}^+$-convergence $\geqslant \tau_{\mathcal{S},d}^+$-convergence;
				\item $ \mathcal{S}$-convergence $\geqslant \tau_{\mathcal{S},d}^+$-convergence;
				\item for $S \in \mathcal{S}$ and $f,g \in \mathcal{Z}^+$ with $\displaystyle{\inf_{x \in S}(g(x) -  f(x)) > 0}$ whenever $B_d(S,g) \neq X$, then $B_d(S,f) \in \mathcal{S}$. 
			\end{enumerate}
		\end{theorem}
		\begin{proof}
			The implication	$(i) \Rightarrow (ii)$ is immediate, and $(iii) \Rightarrow (i)$ follows from Theorem $6.4$ of \cite{agarwal2024set}.

			$(ii) \Rightarrow (iii)$. Suppose $(iii)$ fails. Then by following the proof of Theorem 6.4 of \cite{agarwal2024set}, we can construct a net $(A_\lambda)$ in $CL(X)$ such that $(A_\lambda)$ is $\mathcal{S}^+$-convergent to  some $A \in CL(X)$ and $A\subseteq A_\lambda$ for each $\lambda$ but $(A_\lambda)$ is not $\tau_{\mathcal{S},d}^+$-convergent to $A$.  Since $A\subseteq A_\lambda$ for each $\lambda$, $(A_\lambda)$ is $\mathcal{S}^-$-convergent to $A$. Therefore, $(A_\lambda)$  is $\mathcal{S}$-convergent to $A$. Hence we arrive at a contradiction.  	\end{proof}

		We now give a necessary and sufficient condition for the coincidence $\tau_{\mathcal{S},d} = \mathcal{S}$ on $CL(X)$.  We would like to mention that in Theorem $34.3$ of \cite{beer2023bornologies}, another necessary and sufficient condition, in terms of convergence of certain nets, for the coincidence $\tau_{\mathcal{S},d} = \mathcal{S}$ has been given.

		\begin{theorem}\label{Tsd and S}
			Let $(X,d)$ be a metric space and let $\mathcal{S}$ be a bornology on $X$. Then the following statements are equivalent:
			\begin{enumerate} [(i)]
				\item $\tau_{\mathcal{S},d}^+ = \mathcal{S}^+$, $\tau_{\mathcal{S},d}^- = \mathcal{S}^-$;
				\item $\mathcal{S}$-convergence is compatible with $\tau_{\mathcal{S},d}$;

				\item the bornology $\mathcal{S}$ has following characteristics:
				\begin{enumerate}[(a)]
					\item for $S \in \mathcal{S}$ and $f,g\in \mathcal{Z}^+$ with $\displaystyle{\inf_{x \in S}(g(x) - f(x))> 0}$ whenever $B_d(S,g)$  $\neq X$, then $B_d(S,f) \in \mathcal{S}$, and;
					\item for $S \in \mathcal{S}$ and $p,q \in \mathcal{Z}^+$ with $\displaystyle{\inf_{x \in S}(q(x) - p(x))> 0}$ whenever $A \in CL(X)$ satisfying $ A$ hits $B_d(S,p)$ pointwise, then there exists $S' \in \mathcal{S}$ such that $A \cap S'$ hits $B_d(S,g)$ pointwise.  			\end{enumerate} 		\end{enumerate}
		\end{theorem}

		\begin{proof}
			The implication $(i) \Rightarrow (ii)$ is straightforward. 

			$(ii) \Rightarrow (iii)$. Since $\mathcal{S}$-convergence $\geqslant \tau_{\mathcal{S},d}^+$, by Theorem \ref{upperTsd and S}, $(iii)(a)$ follows. Similarly, $\mathcal{S}$-convergence $\geqslant \tau_{\mathcal{S},d}^-$, by Corollary \ref{upperTsd and S}, $(iii)(b)$ follows.

			$(iii)\Rightarrow (i)$. By Theorem \ref{upperTsd and S}, $(iii)(a)$ implies $\tau_{\mathcal{S},d}^+ = \mathcal{S}^+$ and by Theorem \ref{coincicdence of lower Tsd and S}, $(iii)(b)$ implies $\tau_{\mathcal{S},d}^- = \mathcal{S}^-$. Thus, $(i)$ follows. 
		\end{proof}
		Note that the bornologies $\mathcal{B}_d(X)$ and $\mathcal{P}_0(X)$ satisfy Theorem \ref{Tsd and S}$(iii)$. So we have the following known result as a corollary to Theorem \ref{Tsd and S} (see \cite{ToCCoS}).  
		\begin{corollary}
			Let $(X,d)$ be a metric space. Then the following statements hold:
			\begin{enumerate}[(i)]
				\item $\mathcal{B}_d(X)$-convergence is compatible with $\tau_{AW_{d}}$;
				\item $\mathcal{P}_0(X)$-convergence is compatible with $\tau_{H_d}$.
			\end{enumerate}  
		\end{corollary}
