	If we consider functional enlargements of members of $\mathcal{S}$ in place of their constant enlargements in $(ii)$ of Theorem \ref{lowerleftexcesschracterization} we obtain a new representation for $\tau_{\mathcal{S},d}^-$-convergence. Unlike the usual function space definition of $\tau_{\mathcal{S},d}^-$-convergence, this representation laid emphasis on the hitting behavior of an $\tau_{\mathcal{S},d}^-$-convergent net with functional enlargements of members of $\mathcal{S}$.
	% Now, we give a hit-type characterization for $\tau_{\mathcal{S},d}^-$-convergence which is similar to the one given in Theorem \ref{lowerleftexcesschracterization}. %The idea of this hit-type characterization is embedded in the proof of Theorem \ref{coincicdence of lower Tsd and S}.% hints a hit-type characterization for $\tau_{\mathcal{S},d}^-$-convergence via functional enlargements of members of $\mathcal{S}$. In same vein to Theorem \ref{lowerleftexcesschracterization}, it shows how the members of a net $(A_\lambda)$ and $A$ interact in a similar fashion with the functional enlargements of members of $\mathcal{S}$ whenever $(A_\lambda)$ is $\tau_{\mathcal{S},d}^{-}$-converging to $A$. 
		\begin{theorem}[Hit-type characterization for $\tau_{\mathcal{S},d}^-$]\label{Hittypetheoremforlowertsd}
		Let $(X,d)$ be a metric space and let $\mathcal{S}$ be a bornology  on $X$. Suppose $(A_{\lambda})$ is a net in $CL(X)$ and $A \in CL(X)$. Then the following statements  are equivalent:
		\begin{enumerate}[(i)]

			\item  $(A_{\lambda})$ $\tau_{\mathcal{S},d}^-$-converges to $A$;
			\item for $S \in \mathcal{S}$ and $f,g \in \mathcal{Z}^+$ with $\displaystyle{\inf_{x \in S}(g(x)-f(x))> 0}$, whenever $A$ hits $B_d(S, f)$ pointwise, then eventually $(A_{\lambda})$ hit $B_d(S, g)$ pointwise; 
			\item for $S \in \mathcal{S}$ and $f,g \in L(\mathcal{Z}^+)$ with $\displaystyle{\inf_{x \in S}(g(x)-f(x))> 0}$, whenever $A$ hits $B_d(S, f)$ pointwise, then eventually $(A_{\lambda})$ hit $B_d(S, g)$ pointwise.
			%\item for $S \in \mathcal{S}$ and $f,g \in \mathcal{Z}^+$ with $\displaystyle{\inf_{x \in S}(g(x)-f(x))> 0}$, whenever $A \cap B_d(x, f(x)) \neq \emptyset$ $\forall x \in S$, then eventually $A_{\lambda} \cap B_d(x, g(x)) \neq \emptyset$ $\forall x \in S$; 
			%\item for $S \in \mathcal{S}$ and $f,g \in L(\mathcal{Z}^+)$ with $\displaystyle{\inf_{x \in S}(g(x)-f(x))> 0}$, whenever $A \cap B_d(x, f(x)) \neq \emptyset$ $\forall x \in S$, then eventually $A_{\lambda} \cap B_d(x, g(x)) \neq \emptyset$ $\forall x \in S$.
		\end{enumerate}
	\end{theorem}
	\begin{proof}
		$(i)\Rightarrow (ii)$. Let $S \in \mathcal{S}$ and $f,g \in \mathcal{Z}^+$ be such that $\displaystyle{\inf_{x \in S}(g(x) - f(x))}= r > 0$ and $A \cap B_d(x, f(x)) \neq \emptyset$ $\forall x \in S$. By $(i)$, there is a $\lambda_0$ such that $\forall \lambda \geq \lambda_0$, we have $d(x, A_{\lambda}) < d(x, A) + \frac{r}{2}$ $\forall x \in S$. Fix $\lambda \geq \lambda_0$ and $x \in S$. Then $d(x, A_{\lambda}) < d(x, A) + \frac{r}{2} \leq f(x) + \frac{r}{2}$. So $d(x, A_{\lambda}) < g(x)$ $\forall x \in S$. Consequently, for all $\lambda \geq \lambda_0$, we have $A_{\lambda} \cap B_d(x,g(x)) \neq \emptyset$ $ \forall x \in S$. 

		$(iii) \Rightarrow (i)$. Let $ S \in \mathcal{S}$ and $ \epsilon > 0$. Define $f(x) = d(x, A) + \frac{\epsilon}{3}$ and $g(x) = d(x, A) + \frac{\epsilon}{2}$ for every $x \in S$. Clearly, $f,g \in L(\mathcal{Z}^+)$ and $A \cap B_d(x, f(x)) \neq \emptyset$ $\forall x \in S$. Then by the hypothesis, $A_{\lambda} \cap B_d(x, g(x)) \neq \emptyset$ $\forall x \in S$ eventually. Consequently, $d(x, A_{\lambda}) \leq g(x) <  d(x, A) + \epsilon$ $\forall x \in S$. Therefore, eventually $\forall x \in S$, we have $d(x, A_{\lambda}) - d(x, A) < \epsilon$. 
	\end{proof}
	\begin{remark}
		Note that the previous theorem holds for an arbitrary family $\mathcal{S} \subseteq \mathcal{P}_0(X)$.
	\end{remark}


	 We now come to one of the main results of our section. Before that we fix some preliminary notations. For a nonempty subset $A$ of $(X,d)$ and $f \in \mathcal{Z}^+$, define $H_d^-(A,f) = \{C \in CL(X): C \text{ hits } B_d(A,f)\text{ pointwise}\}$. When $f$ is a constant function say, $f(x) = \epsilon$ $\forall x$, then $H_d^-(A, \epsilon) = \{C \in CL(X): e_d(A, C) \leq \epsilon\}$. Now Theorem \ref{Hittypetheoremforlowertsd} can be reformulated as: a net $(A_{\lambda})$ is $\tau_{\mathcal{S},d}^-$-convergent to $A$ in $CL(X)$ if and only if whenever $S \in \mathcal{S}$ and $f,g \in \mathcal{Z}^+$ such that $\displaystyle{\inf_{x \in S}}(g(x)-f(x))>0$ and $A \in H_d^-(S,f)$, then $A_{\lambda} \in H_d^-(S,g)$ eventually.  

	 \begin{theorem}\label{lower Tsd and excess}
	 	Let $(X,d)$ be a metric space and let $\mathcal{S}$ be a bornology on $X$. Then the following statements are equivalent. 
	 	\begin{enumerate}[(i)]
	 		\item for  $S \in \mathcal{S}$ and $f,g \in \mathcal{Z}^+$ with $\displaystyle{\inf_{x \in S}(g(x) - f(x))>0}$, whenever $A \in H_d^-(S,f)$ then there exist $0 < \lambda_i < \sigma_i$ and $S_i \in \mathcal{S}$, $i = 1, \ldots, n$ such that $$ A \in \bigcap_{i=1}^{n}H_d^-(S_i, \lambda_i) \subseteq \bigcap_{i=1}^{n}H_d^-(S_i, \sigma_i) \subseteq H_d^-(S,g);$$

	 		\item for  $S \in \mathcal{S}$ and $f,g \in L(\mathcal{Z}^+)$ with $\displaystyle{\inf_{x \in S}(g(x) - f(x))>0}$, whenever $A \in H_d^-(S,f)$ then there exist $0 < \lambda_i < \sigma_i$ and
	 		$S_i \in \mathcal{S}$, $i = 1, \ldots, n$ such that $$ A \in \bigcap_{i=1}^{n}H_d^-(S_i, \lambda_i) \subseteq \bigcap_{i=1}^{n}H_d^-(S_i, \sigma_i) \subseteq H_d^-(S,g);$$

	 		\item $\tau_{\mathcal{S},d}^- = \mathcal{LE}_{\mathcal{S},d}^-$ on $CL(X)$.

	 		\item $\tau_{\mathcal{S},d}^-$ is the weakest topology on $CL(X)$ such that each member of the family of excess functionals $\{e_d(S, \cdot): S \in \mathcal{S}\}$ is upper semicontinuous.  
	 	\end{enumerate}
	 \end{theorem}
	 \begin{proof} It is enough to show $(ii) \Rightarrow (iii)$ and $(iii) \Rightarrow (i)$.


	 	$(ii)\Rightarrow (iii)$. 
	 	Let $(A_{\lambda})$ be a net that $\mathcal{LE}_{\mathcal{S},d}^-$-convergent to $A$ in $CL(X)$. Let $S \in \mathcal{S}$ and $f,g \in L(\mathcal{Z}^+)$ such that $\displaystyle{\inf_{x \in S}(g(x)-f(x) )> 0}$ and $A \in H_d^-(S,f)$. By the hypothesis, there exist $0 < \lambda_i < \sigma_i$ and $S_i \in \mathcal{S}$, $i = 1, \ldots, n$ such that $$ A \in \bigcap_{i=1}^{n}H_d^-(S_i, \lambda_i) \subseteq \bigcap_{i=1}^{n}H_d^-(S_i, \sigma_i) \subseteq H_d^-(S,g).$$ 
	 	By above inclusions, $e_d(S_i, A) < \sigma_i$ $\forall i = 1, \ldots, n$. Since $(A_{\lambda})$ is $\mathcal{LE}_{\mathcal{S},d}^-$-convergent to $A$, $e_d(S_i, A_{\lambda}) < \sigma_i$ eventually $\forall 1\leq i \leq n$. Consequently, $A_{\lambda} \in H_d^-(S_i, \lambda_i)$ eventually for each $i = 1, \ldots, n$. So $A_{\lambda} \in H_d^-(S,g)$ eventually. Hence, $(A_{\lambda})$ is $\tau_{\mathcal{S},d}^-$-convergent to $A$. 


	 	$(iii)\Rightarrow (i)$. Suppose $(i)$ fails. Then there exist $S_0 \in \mathcal{S}$, $f,g \in \mathcal{Z}^+$ with $\displaystyle{\inf_{x \in S}(g(x)- f(x))>0}$, and $A \in CL(X)$ such that $A \in H_d^-(S_0,f)$ but for every $0 < \lambda_i < \sigma_i$ and $S_i$, $i = 1, \ldots, n$ satisfying $\displaystyle{A \in  \bigcap_{i=1}^nH_d^-(S_i, \lambda_i)}$ we have $\displaystyle{\bigcap_{i=1}^nH_d^-(S_i, \sigma_i)\nsubseteq H_d^-(S_0,g)}$. 
	 	Set $\mathcal{A} = \{S \in \mathcal{S}: \exists \text{ } \epsilon > 0 \text{ such that } S \subseteq B_d(A, \epsilon)\}$. For $S \in \mathcal{A}$, let $\alpha_S = \min\{\epsilon > 0: S \subseteq B_d(A, \epsilon)\}$. 
	 	%Define $$\Omega = \{(F, \alpha_F) \in \mathcal{F}(\mathcal{S}) \times \mathcal{F}(\mathbb{R}^+): A \in \bigcap_{S \in F}H_d^-(S, \alpha_S)\}.$$ Clearly $\Omega$ is nonempty, as $(\{a\}, \{\epsilon\}) \in \Omega$ for any $a \in A$ and $\epsilon > 0$. So for $(F, \alpha_F) \in \Omega$ whenever $\epsilon_F \in \mathcal{F}(\mathbb{R})^+$ with $\alpha_S < \epsilon_S$ for $S \in F$, by the assumption, there exists a $\displaystyle{C_{(F, \alpha_F)} \in \bigcap_{S \in F}H_d^-(S, \epsilon_S) \setminus H_d^-(S_0,g)}$. Direct $\Omega$ by the relation $\leqslant$: $(F, \alpha_F) \leqslant (F', \epsilon_{F'})$ if and only if $F \subseteq F'$ and $\alpha_S \leq \epsilon_S$ for $S \in F$. It is easy to verify that $\Omega$ is a directed set under the relation $\leqslant$. Consequently, $(C_{(F, \alpha_F)})_{(F, \alpha_F) \in \Omega}$ is a net in $CL(X)$. We show that $(C_{(F, \alpha_F)})$ is $\mathcal{LE}_{\mathcal{S},d}^-$- convergent to $A$ while fails $\tau_{\mathcal{S},d}^-$-convergence.
