		We deduce the following results of Beer and Lucchetti \cite{beer1993weak} as corollaries to Theorem \ref{lower Tsd and excess}.
	 \begin{corollary}\label{lowerattouchexcess}
	 	Let $(X,d)$ be a metric space. Then $\tau_{AW_{d}}^-$ on $CL(X)$ is the weakest topology such that each member of the family of excess functionals $\{e_d(S, \cdot): S \in \mathcal{B}_d(X)\}$ is upper semicontinuous.   
	 \end{corollary}
	 \begin{proof}
	 	It is enough to show that the condition $(ii)$ of Theorem \ref{lower Tsd and excess} holds for $\mathcal{B}_d(X)$.  
	 	Let $S \in \mathcal{B}_d(X)$, $f,g  \in L(\mathcal{Z}^+)$ with $\displaystyle{\inf_{x\in S}}(g(x)-f(x))>0$, and $A \in CL(X)$ such that $A \in H_d^-(S,f)$. Then choose a $f$-selection of $\mathcal{S}$, say $S_A$ such that $S_A \subseteq A$. By Proposition \ref{selectionsforBdX}, $S_A \in \mathcal{B}_d(X)$. Set $2r = \displaystyle{\inf_{x \in S}}(g(x)-f(x))$. So $A \in H_d^-(S_A,r)$. We show that $H_d^-(S_A,2r) \subseteq H_d^-(S,g)$. Let $C \in H_d^-(S_A,2r)$ and $x \in S$. Then $\exists$ $x' \in S_A$ such that $d(x,x')< f(x)$. Consequently, $d(x,C)\leq d(x,x')+ d(x', C)< f(x)+ 2r < g(x)$. So $C \in H_d^-(S,g)$.
	 	\end{proof}


	 		\begin{corollary}
	 		Let $(X,d)$ be a metric space. Then $\tau_{H_d}^-$ on $CL(X)$ is the weakest topology such that each member of the family of excess functionals $\{e_d(S, \cdot): S \in \mathcal{P}_0(X)\}$ is upper semicontinuous. 
	 	\end{corollary}
	 	\begin{proof}
	 		Let $S \in \mathcal{B}_d(X)$, $f,g  \in L(\mathcal{Z}^+)$ with $\displaystyle{\inf_{x\in S}}(g(x)-f(x))>0$, and $A \in CL(X)$ such that $A \in H_d^-(S,f)$. Take $S_A = A \cap B_d(S,f)$. Clearly $S_A \in \mathcal{P}_0(X)$. The rest of the proof is similar to the proof of Corollary \ref{lowerattouchexcess}.
	 	\end{proof}

	 		Beer et al. in \cite{beer2013gap}, introduced a covering condition on a bornology to study the coincidence  $\mathsf{G}_{\mathcal{S},d}^+ = \mathsf{G}_{\mathcal{S},\rho}^+$ for two metrics $d, \rho$ on $X$, and the coincidence $\mathsf{G}_{\mathcal{S},d}^+ = \mathsf{G}_{\mathcal{T},d}^+$  for two families $\mathcal{S}, \mathcal{T}$ of subsets of $X$. Recently in \cite{agarwal2024set}, the authors used this notion to study the coincidence $\tau_{\mathcal{S},d}^+ = \mathsf{G}_{\mathcal{S},d}^+$.

	 	% This notion concerns the inclusion of a subset in another subset of $X$ for an arbitrary family $\mathcal{S}$ and metric $d$ on $X$.  

	 	\begin{definition}\normalfont (\cite{beer2013gap})\label{Strictlyincluded}
	 		Let $(X,d)$ be a metric space and let $\mathcal{S}$ be an arbitrary family of nonempty subsets of $X$. We say a subset $A$ of $X$ is \textit{strictly $(\mathcal{S}-d)$ included} in another nonempty subset $C$ of $X$ if there exists a finite subset $\{S_1,\ldots,S_n\}$ of $\mathcal{S}$, and for every $i \in \{1,\ldots,n\}$ there are $\alpha_i, \epsilon_i$ with $0 < \alpha_i < \epsilon_i$, such that $$A \subseteq \cup_{i=1}^nB_d(S_i, \alpha_i)  \subseteq \cup_{i=1}^nB_d(S_i, \epsilon_i) \subseteq C. $$
	 	\end{definition}

 	From the proof of Theorem $5.5$ of \cite{agarwal2024set} it can be derived that the coincidence $\tau_{\mathcal{S},d}^+ = \mathsf{G}_{\mathcal{S},d}^+$ holds on $CL(X)$ provided for $S\in \mathcal{S}$ and $f,g \in L(\mathcal{Z}^+)$ such that $\inf_{x \in S}(g(x) - f(x))>0$ either $B_d(S,g) = X$ or $B_d(S,f)$ is strictly $(\mathcal{S}-d)$ included in $B_d(S,g)$. 

 	The following theorem provides a two-sided result for the coincidences $\tau_{\mathcal{S},d}^+  = \mathsf{G}_{\mathcal{S},d}^+$ , $\tau_{\mathcal{S},d}^-  = \mathcal{LE}_{\mathcal{S},d}^-$ which follows from Theorem $5.5$ of \cite{agarwal2024set} and Theorem \ref{lower Tsd and excess}.
	 	\begin{theorem}
	 		Let $(X,d)$ be a metric space and let $\mathcal{S}$ be a bornology on $X$. Then the following statements are equivalent:
	 		\begin{enumerate}[(i)]
	 			\item $\tau_{\mathcal{S},d}^+  = \mathsf{G}_{\mathcal{S},d}^+$ , $\tau_{\mathcal{S},d}^-  = \mathcal{LE}_{\mathcal{S},d}^-$; 
	 			\item the bornology $\mathcal{S}$ has the following characteristics:
	 			\begin{enumerate}[(a)]
	 				\item for each $S \in \mathcal{S}$ and $f, g \in L(\mathcal{Z}^+)$ with $\inf\{g(x) - f(x) : x \in S\} > 0$, either $B_d(S , g) = X$ or $B_d(S,f)$ is strictly $(\mathcal{S}-d)$-included in $B_d(S,g)$;
	 				\item for each $S \in \mathcal{S}$ and $f,g \in \mathcal{Z}^+$ with $\displaystyle{\inf_{x \in S}(g(x) - f(x))>0}$, whenever $A \in H_d^-(S,f)$ then there exist $0 < \lambda_i < \sigma_i$ and $S_i \in \mathcal{S}$, $i = 1, \ldots, n$ such that $$ A \in \bigcap_{i=1}^{n}H_d^-(S_i, \lambda_i) \subseteq \bigcap_{i=1}^{n}H_d^-(S_i, \sigma_i) \subseteq H_d^-(S,g).$$
	 			\end{enumerate}

	 		\end{enumerate}

	 	\end{theorem}
	 	A less technical sufficient condition for the coincidence $\tau_{\mathcal{S},d}^- = \mathcal{LE}_{\mathcal{S},d}^-$ on $CL(X)$ is given by the following result. 

	 	\begin{proposition}\label{suffconditionlowerTsdandleftexcess}
	 		Let $(X,d)$ be a metric space and let $\mathcal{S}$ be a bornology on $X$. If $\mathcal{S}$ is stable under Lip-selections, then $\tau_{\mathcal{S},d}^- = \mathcal{LE}_{\mathcal{S},d}^-$ on $CL(X)$. 
	 	\end{proposition}
	 	\begin{proof}
	 		Since $\mathcal{LE}_{\mathcal{S},d}^-$-convergence is stronger than $\mathcal{S}^-$-convergence, Theorem \ref{lowerTsdandSselection} and Proposition \ref{gapexcessTsdbasicresult} together imply that $\tau_{\mathcal{S},d}^- = \mathcal{LE}_{\mathcal{S},d}^- = \mathcal{S}^-$ on $CL(X)$.	 	\end{proof}

	 	  The stability condition in Proposition \ref{suffconditionlowerTsdandleftexcess} need not be necessary (see, Example \ref{counterexampleselections}).	 

	 	\begin{remark}\begin{enumerate}[(i)]
	 			\item From Corollary \ref{lowerattouchexcess} and Theorem \ref{lowerleftexcesschracterization}, a net $(A_{\lambda})$ is $\tau_{{AW}_d}^-$-convergent to $A$ provided for each $S \in \mathcal{B}_d(X)$ and $0< \alpha< \epsilon $ whenever $A$ hits $B_d(S, \alpha)$ pointwise, then eventually $(A_{\lambda})$ hits $B_d(S, \epsilon)$ pointwise.

	 			\item More generally, for a bornology $\mathcal{S}$ on $(X,d)$ which is stable under Lip-selections, it is enough to consider  constant functions in $\mathcal{Z}^+$ to imply $\tau_{\mathcal{S},d}^-$-convergence in Theorem \ref{Hittypetheoremforlowertsd}.  
	 		\end{enumerate}	
	 	\end{remark}

	 	To see the coincidence of $\tau_{\mathcal{S},d}$ and $\tau_{GE}^{\mathcal{S}}$, we need a stronger stability condition on $\mathcal{S}$ than the one given in Proposition \ref{suffconditionlowerTsdandleftexcess}. 
