 	\begin{remark}
 		The covering condition on a bornology $\mathcal{S}$ given in Definition \ref{Strictlyincluded} is generally weaker than $\mathcal{S}$ being stable under Lipschitz enlargements. However, if $\mathcal{S}$ is stable under enlargements, then these conditions are easily seen to be equivalent. 	 	\end{remark}

 	We end this paper by giving a covering criterion that provides a sufficient condition for the coincidence  $\tau_{\mathcal{S},d} = \tau_{GE}^{\mathcal{S}}$ on $CL(X)$. This criterion is a stronger form of the covering condition of Definition \ref{Strictlyincluded}.
	 \begin{theorem}
	 Let $(X,d)$ be a metric space and let $\mathcal{S}$ be a bornology on $X$. Suppose for any $S \in \mathcal{S}$, no Lipschitz enlargement of $S$ is equal to $X$. Consider the following statements:
	 	\begin{enumerate}[(i)]
	 		\item for $S \in \mathcal{S}$ and $f,g \in L(\mathcal{Z}^+)$ with $\inf_{x \in S}(g(x)-f(x))> 0$, $\exists$ $S_1, \ldots, S_n \in \mathcal{S}$ and $0 < \alpha_i < \epsilon_i$, $i = 1, \ldots, n$ such that $\max_{1 \leq i \leq n}2 \epsilon_i< \inf_{x \in S}(g(x)-f(x))> 0$ and $$B_d(S,f) \subseteq \cup_{i=1}^nB_d(S_i, \alpha_i) \subseteq \cup_{i=1}^nB_d(S_i, \epsilon_i) \subseteq B_d(S,g);$$
	 		\item $\tau_{\mathcal{S},d}^+ = \mathsf{G}_{\mathcal{S},d}^+$, $\tau_{\mathcal{S},d}^- = \mathcal{LE}_{\mathcal{S},d}^-$ on $CL(X)$;
	 		\item $\tau_{\mathcal{S},d} = \tau_{GE}^{\mathcal{S}}$ on $CL(X)$.
	 	\end{enumerate}
	 	Then $(i) \Rightarrow (ii) \Rightarrow (iii)$ holds.
	 \end{theorem}	
	 \begin{proof}
	 By Proposition \ref{TsdGapexcessnecessary} and the assumption, we have $\tau_{\mathcal{S},d}^+ = \mathsf{G}_{\mathcal{S},d}^+$. It remains to show that $\tau_{\mathcal{S},d}^- = \mathcal{LE}_{\mathcal{S},d}^-$. Let $(A_{\lambda})$ be a net in $CL(X)$ such that $A_{\lambda} \xrightarrow{\mathcal{LE}_{\mathcal{S},d}^-} A \in CL(X)$. Let $S \in \mathcal{S}$ and $f,g \in L(\mathcal{Z}^+)$ such that $\inf_{x \in S}(g(x)-f(x)) = 2 \gamma> 0$ and $A$ hits $B_d(S,f)$ pointwise.  By $(i)$, choose $S_1, \ldots, S_n \in \mathcal{S}$ and $0 < \alpha_i < \epsilon_i$, where $1 \leq i \leq n$ such that $\max_{1\leq i \leq n}\epsilon_i < \gamma$ and $$B_d(S,f) \subseteq \cup_{i = 1}^nB_d(S_i, \alpha_i) \subseteq \cup_{i = 1}^nB_d(S_i, \epsilon_i) \subseteq B_d(S,g).$$  For each $x \in S$, choose $a_x \in A \cap B_d(x, f(x))$.  Take $S' = \cup_{i=1}^nS_i$, $\alpha = \max_{1 \leq i \leq n}\alpha_i$ and $\epsilon = \max_{1 \leq i \leq n}\epsilon_i$. Then for each $x \in S$, there exists $z_x \in S'$ such that $d(a_x, z_x)< \alpha$. Set $S'' = \{z_x: x \in S\}$. So $A$ hits $B_d(S'',\alpha)$ pointwise. Since $A_{\lambda} \xrightarrow{\mathcal{LE}_{\mathcal{S},d}^-} A$, by Theorem \ref{lowerleftexcesschracterization}, we can find $\lambda_0$ such that $\forall$ $\lambda \geq \lambda_0$ $A_\lambda$ hits $B_d(S'', \epsilon)$ pointwise. Then for any $x \in S$ and $\lambda \geq \lambda_0$, we have \begin{eqnarray*}
	 	d(x, A_{\lambda}) \leq d(x, a_x) + d(a_x,z_x) + d(z_x, A_{\lambda})\\ 
	 	< f(x) + \alpha + \epsilon < g(x).	 	 
	 \end{eqnarray*} So eventually $(A_{\lambda})$ hits $B_d(S,g)$ pointwise. Consequently, by Theorem \ref{Hittypetheoremforlowertsd}, $A_{\lambda} \xrightarrow{\tau_{\mathcal{S},d}^-} A \in CL(X)$.  \end{proof}





