\section{Leaf-like geometry calculations}


Here we solve the Laplace equation in the leaf-like villi case. Starting from equation 1 of the main text and with the rescaled $\tilde x=x/R$, $\tilde y=y/h,c=C/C_0$, $\xi=R/h$ and $\Theta=D/(kh)$, the differential equation to solve is:
\begin{equation}
    \frac{\partial^2 \tilde c}{\partial \tilde x^2} + \xi^2\frac{\partial^2 \tilde c}{\partial \tilde y^2} = 0
\end{equation}
With the following boundary conditions:
\begin{equation}
    c(\tilde x, 1)=1
\end{equation}
\begin{equation}
    \Theta \left( \xi^{-1} \frac{\partial c}{\partial \tilde x} \vec e_x + \frac{\partial c}{\partial \tilde y}\vec e_y\right)\vec n + c = 0, (\tilde x, \tilde y) \in S,
\end{equation}

where $S$ is either $\tilde x=-1$, $\tilde x=1$ or $\tilde y=0$. We solve the Laplace equation using separation of variables. We can write $c$ as the product of two functions such that:
\begin{equation}
    c(\tilde x,\tilde y) = f(\tilde x)g(\tilde y)
\end{equation}
Substituting equation 4 into equation 1 yields:
\begin{equation}
    f''(\tilde x)g(\tilde y) + \xi^2f(\tilde x)g''(\tilde y) = 0
\end{equation}
\begin{equation}
    \frac{f''(\tilde x)}{f(\tilde x)} = -\xi^2\frac{g''(\tilde y)}{g(\tilde y)} = -\lambda
\end{equation}
Where $f'(\tilde x)$ is the derivative of $f(\tilde x)$ with respect to $\tilde x$, $g'(\tilde y)$ is the derivative of $g(\tilde y)$ with respect to $\tilde y$ and $\lambda$ a constant which must be positive; otherwise, non-physical solutions are found. We define $\mu$ such that $\mu^2=\lambda$.

We first solve for $f(\tilde x)$:
\begin{equation}
    f''(\tilde x)+\mu^2 f(\tilde x) = 0
\end{equation}
\begin{equation}
    f(\tilde x) = C \cos(\mu \tilde x)+D \sin(\mu \tilde x)
\end{equation}

We then use the boundary equation from equation 3 to find $C$ and $D$. The left-right symmetry implies that $D=0$. For an arbitrary non-zero $C$ we find:
\begin{equation}
    \tan(\mu) = \frac{\xi}{\Theta \mu}
\end{equation}
There exists an infinite number of solutions $\mu_n$ to equation 9, where $n$ is a positive integer. So, we define $f_n(\tilde x)$ as:
\begin{equation}
    f_n(\tilde x) = \cos(\mu_n\tilde x)
\end{equation}
Where $\mu_n$ is the nth solution to eq 9 and $g_n$ such that $c_n(\tilde x,\tilde y)=f_n(\tilde x)g_n(\tilde y)$. Each solution $f_n(\tilde x)$ form an orthogonal basis because integration over the space $[-1,1]$ of $\cos(\mu_n x)\cos(\mu_m x)=0$ if $n\neq m$. The full solution to the differential equation is a superposition of these solutions that form an orthogonal basis: $c(\tilde x,\tilde y)=\sum_{n=1}^\infty c_n(\tilde x, \tilde y)$. We now solve for $g_n(\tilde y)$ using equation 5:
\begin{equation}
    \xi^2g_n''(\tilde y)-\lambda g_n(\tilde y) = 0
\end{equation}
\begin{equation}\frac{\mu_n}{\xi}
    g_n(\tilde y) = B_n \cosh(\frac{\mu_n}{\xi} \tilde y)+A_n \sinh(\frac{\mu_n}{\xi} \tilde y)
\end{equation}
We then use the boundary conditions 3 in $\tilde y=0$ to find the constants $A_n$ and $B_n$:
\begin{equation}
    -\frac{\Theta}{\xi} \mu_n A_n + B_n = 0
\end{equation}

\begin{equation}
    B_n = \Theta \frac{\mu_n}{\xi} A_n
\end{equation}

We then obtain $g_n(\tilde y)$ for a non-zero $A_n$:
\begin{equation}
    g_n(\tilde y) =\left( \Theta\frac{\mu_n}{\xi} \cosh(\frac{\mu_n}{\xi} \tilde y) + \sinh(\frac{\mu_n}{\xi} \tilde y)\right)A_n
\end{equation}
Then,
\begin{equation}
    c_n(\tilde x,\tilde y) = A_n \cos(\mu_n x)(\Theta\frac{\mu_n}{\xi} \cosh(\frac{\mu_n}{\xi} \tilde y) + \sinh(\frac{\mu_n}{\xi} \tilde y))
\end{equation}
And:
\begin{equation}
    c(\tilde x,\tilde y) = \sum_{n=1}^{n=\infty}A_n \cos(\mu_n x)(\Theta\frac{\mu_n}{\xi} \cosh(\frac{\mu_n}{\xi} \tilde y) + \sinh(\frac{\mu_n}{\xi} \tilde y))
\end{equation}

We now calculate $A_n$. To do so we use the final boundary condition (equation 2) $c(\tilde x,1)=1$.
\begin{equation}
    c(\tilde x,1) = 1=\sum_{n=1}^{n=\infty} A_n \cos(\mu_n x)(\Theta\frac{\mu_n}{\xi} \cosh(\frac{\mu_n}{\xi}) + \sinh(\frac{\mu_n}{\xi}))
\end{equation}
Substituting $\tilde A_n = A_n(\Theta \frac{\mu_n}{\xi}\cosh(\frac{\mu_n}{\xi}) + \sinh(\frac{\mu_n}{\xi}))$ we obtain the following equation:
\begin{equation}
    1 = \sum_{n=1}^{n=\infty}\tilde A_n \cos(\mu_n x)
\end{equation}
We recognize a generalized Fourier series. Multiplying both sides of equation 19 by $\cos(\mu_nx)$ and integrating for $x$ between $-1$ and $1$, we find that:
\begin{equation}
    \tilde A_n = \frac{\int_{-1}^1\cos(\mu_n x)dx}{\int_{-1}^1\cos^2(\mu_n x)dx}=\frac{4\sin(\mu_n)}{2\mu_n+\sin(2\mu_n)}
\end{equation}
So the full expression of $c(\tilde x,\tilde y)$ is:
\begin{equation}
    c(\tilde x, \tilde y) = \sum_{n=1}^\infty \frac{4 \sin(\mu_n)\cos(\mu_n \tilde x)(\Theta\frac{\mu_n}{\xi}\cosh(\frac{\mu_n}{\xi}\tilde y)+\sinh(\frac{\mu_n}{\xi}\tilde y))}{(2\mu_n+\sin(2\mu_n))(\Theta\frac{\mu_n}{\xi}\cosh(\frac{\mu_n}{\xi})+\sinh(\frac{\mu_n}{\xi}))}
\end{equation}
This expression is plotted figure \ref{figconcentrationleaf}.

