\section{Finger-like geometry calculations}

Here we solve the Laplace equation in the finger-like villi case. We approximate the hexagonal repeating geometry to a cylindrical one by keeping a constant surface area as seen in the figure S1. The differential equation 1 in this geometry with the rescaled parameters $\tilde r=r/R$, $\tilde z=z/h$, $c=C/C_0$, $\xi=R/h$ and $\Theta=D/(kh)$ is:
\begin{equation}
    \frac{1}{\tilde r}\frac{\partial c}{\partial \tilde r}+\frac{\partial^2 \tilde c}{\partial \tilde r^2} + \xi^2\frac{\partial^2 \tilde c}{\partial \tilde z^2} = 0
\end{equation}

\begin{figure}[h]
    \centering
    \includegraphics[width=0.5\linewidth]{geometry.pdf}
    \caption{Sketch of how the hexagon is converted to a circle. We keep an equivalent surface such that $R_1=\sqrt{\frac{3\sqrt{3}}{2\pi}}R_2$.}\label{hexa}
\end{figure}

with the following boundary conditions:
\begin{equation}
    c(\tilde r, 1)=1
\end{equation}
\begin{equation}
    \Theta\left(\xi^{-1} \frac{\partial c}{\partial \tilde r} \vec e_r + \frac{\partial c}{\partial \tilde z}\vec e_z\right)\vec n + c = 0, (\tilde r, \tilde z) \in S,
\end{equation}

\begin{equation}
    \vec n \cdot \vec \nabla c(1+\frac{\tilde e}{2\xi},\tilde z) = 0
\end{equation}

where $S$ is either $\tilde r=\tilde e/2$ or $\tilde z=0$. We solve the Laplace equation using separation of variables. We can write $c$ as the product of two functions such that:
\begin{equation}
    c(\tilde r,\tilde z) = f(\tilde r)g(\tilde z)
\end{equation}
Substituting equation 29 into equation 25 yields:
\begin{equation}
    \frac{1}{\tilde r}f'g+f''g+fg''=0
\end{equation}
\begin{equation}
    \frac{1}{\tilde r}\frac{f'}{f}+\frac{f''}{f}=-\xi^2\frac{g''}{g}=-\lambda
\end{equation}
Where $f'(\tilde r)$ is the derivative of $f(\tilde r)$ with respect to $\tilde r$, $g'(\tilde z)$ is the derivative of $g(\tilde z)$ with respect to $\tilde z$ and $\lambda$ is chosen positive; otherwise, non-physical solutions are found.

We first solve for $f(\tilde r)$:
\begin{equation}
    \frac{1}{\tilde r}f'(\tilde r)+ f''(\tilde r)+\lambda f(\tilde r) = 0
\end{equation}
As in the previous case, $\lambda>0$ for physical solutions, and we define $\mu$ such that $\lambda=\mu^2$.
\begin{equation}
    f(\tilde r) = C J_0(\mu \tilde r)+D Y_0(\mu \tilde r)
\end{equation}

Using equation 28 we find:
\begin{equation}
    C= -D\frac{Y_1(\mu(1+\frac{\tilde e}{2\xi}))}{J_1(\mu(1+\frac{\tilde e}{2\xi}))}
\end{equation}
We then use the boundary equation from equation 27:
\begin{equation}
    \Theta \frac{\mu_n}{\xi} = -\frac{Y_1(\mu_n(1+\frac{\tilde e}{2\xi}))J_0(\mu_n\frac{\tilde e}{2\xi})-J_1(\mu_n(1+\frac{\tilde e}{2\xi}))Y_0(\mu_n\frac{\tilde e}{2\xi})}{Y_1(\mu_n(1+\frac{\tilde e}{2\xi}))J_1(\mu_n\frac{\tilde e}{2\xi})-J_1(\mu_n(1+\frac{\tilde e}{2\xi}))Y_1(\mu_n\frac{\tilde e}{2\xi})}
\end{equation}
There exist an infinite number of solutions $\mu_n$ to equation 35, where $n$ is a positive integer. So, we define \begin{equation}
    f_n(\tilde r)=-\frac{Y_1(\mu_n(1+\frac{\tilde e}{2\xi}))}{J_1(\mu_n(1+\frac{\tilde e}{2\xi}))}J_0(\mu_n \tilde r)+Y_0(\mu_n \tilde r)
\end{equation}
Where $\mu_n$ is the nth solution to eq 35. We now solve for $g_n(\tilde z)$:
\begin{equation}
    \xi^2g_n''(\tilde z)-\lambda g_n(\tilde z) = 0
\end{equation}
\begin{equation}
    g_n(\tilde z) = B_n \cosh(\frac{\mu_n}{\xi} \tilde z)+A_n \sinh(\frac{\mu_n}{\xi} \tilde z)
\end{equation}
We then use the boundary conditions to find $A_n$ and $B_n$:
\begin{equation}
    -\Theta \frac{\mu_n}{\xi} A_n + B_n = 0
\end{equation}

\begin{equation}
    B_n = \Theta \frac{\mu_n}{\xi} A_n
\end{equation}

We then obtain $g_n(\tilde z)$ for a non-zero $A_n$:
\begin{equation}
    g_n(\tilde z) =\left( \Theta\frac{\mu_n}{\xi} \cosh(\frac{\mu_n}{\xi} \tilde z) + \sinh(\frac{\mu_n}{\xi} \tilde z)\right)A_n
\end{equation}
Then,
\begin{equation}
    c_n(\tilde x,\tilde y) = A_n (-\frac{Y_1(\mu_n(1+\frac{\tilde e}{2\xi}))}{J_1(\mu_n(1+\frac{\tilde e}{2\xi}))}J_0(\mu_n \tilde r)+Y_0(\mu_n \tilde r))(\Theta\frac{\mu_n}{\xi} \cosh(\frac{\mu_n}{\xi} \tilde y) + \sinh(\frac{\mu_n}{\xi} \tilde y))
\end{equation}
And:
\begin{equation}
    c(\tilde x,\tilde y) = \sum_{n=1}^{n=\infty}A_n (-\frac{Y_1(\mu_n(1+\frac{\tilde e}{2\xi}))}{J_1(\mu_n(1+\frac{\tilde e}{2\xi}))}J_0(\mu_n \tilde r)+Y_0(\mu_n \tilde r))(\Theta\frac{\mu_n}{\xi} \cosh(\frac{\mu_n}{\xi} \tilde y) + \sinh(\frac{\mu_n}{\xi} \tilde y))
\end{equation}

We now calculate $A_n$. To do so we use the final boundary condition (equation 26) $c(\tilde r,1)=1$.
\begin{equation}
    c(\tilde r,1) = 1=\sum_{n=1}^{n=\infty}A_n (-\frac{Y_1(\mu_n(1+\frac{\tilde e}{2\xi}))}{J_1(\mu_n(1+\frac{\tilde e}{2\xi}))}J_0(\mu_n \tilde r)+Y_0(\mu_n \tilde r))(\Theta\frac{\mu_n}{\xi} \cosh(\frac{\mu_n}{\xi} \tilde y) + \sinh(\frac{\mu_n}{\xi} \tilde y))
\end{equation}
Substituting $\tilde A_n = A_n(\Theta \frac{\mu_n}{\xi}\cosh(\frac{\mu_n}{\xi}) + \sinh(\frac{\mu_n}{\xi}))$, we obtain the following equation:
\begin{equation}
    1 = \sum_{n=1}^{n=\infty}\tilde A_n (-\frac{Y_1(\mu_n(1+\frac{\tilde e}{2\xi}))}{J_1(\mu_n(1+\frac{\tilde e}{2\xi}))}J_0(\mu_n \tilde r)+Y_0(\mu_n \tilde r))
\end{equation}
We recognize a generalized Fourier series. It is possible to find $\tilde A_n$ as:
\begin{equation}
    \tilde A_n = \frac{\int_{\frac{\tilde e}{2\xi}}^{1+\frac{\tilde e}{2\xi}}rf_n(r)dr}{\int_{\frac{\tilde e}{2\xi}}^{1+\frac{\tilde e}{2\xi}}rf_n(r)^2dr}
\end{equation}

So the full expression of $c(\tilde r,\tilde z)$ is:
\begin{equation}
    c(\tilde r,\tilde z)=\sum_{n=1}^\infty \frac{(\int_{\frac{\tilde e}{2\xi}}^{1+\frac{\tilde e}{2\xi}}rf_n(r)dr)(-\frac{Y_1(\mu_n(1+\frac{\tilde e}{2\xi}))}{J_1(\mu_n(1+\frac{\tilde e}{2\xi}))}J_0(\mu_n \tilde r)+Y_0(\mu_n \tilde r))(\Theta\frac{\mu_n}{\xi} \cosh(\frac{\mu_n}{\xi} \tilde y) + \sinh(\frac{\mu_n}{\xi} \tilde y))}{(\int_{\frac{\tilde e}{2\xi}}^{1+\frac{\tilde e}{2\xi}}rf_n(r)^2dr)(\Theta \frac{\mu_n}{\xi}\cosh(\frac{\mu_n}{\xi}) + \sinh(\frac{\mu_n}{\xi}))}
\end{equation}
It is plotted figure \ref{figureconcentrationfinger}.

