\section{Crypt geometry calculations}


Here we solve the Laplace equation in the colonic crypt case. Starting from equation 1 of the main text and with the rescaled parameters $\tilde r=r/R$, $\tilde z=z/h$, $c=C/C_0$, $\xi=R/h$, $\Theta=D/(kh)$, the differential equation to solve is:
\begin{equation}
    \frac{1}{\tilde r}\frac{\partial \tilde c}{\partial \tilde r} + \frac{\partial^2 \tilde c}{\partial \tilde r^2}+\xi^2\frac{\partial^2 \tilde c}{\partial \tilde z^2} = 0
\end{equation}
With the following boundary conditions:
\begin{equation}
    c(\tilde r, 1)=1
\end{equation}
\begin{equation}
    \Theta(\xi^{-1} \frac{\partial c}{\partial \tilde r} \vec e_r + \frac{\partial c}{\partial \tilde z}\vec e_z)\vec n + c = 0, (\tilde r, \tilde z) \in S
\end{equation}


where $S$ is either $\tilde r= 1$ or $\tilde z=0$. We solve the cylindrical Laplace assuming $c$ is the product of two functions such that:
\begin{equation}
    c(\tilde r,\tilde z) = f(\tilde r)g(\tilde z)
\end{equation}
Substituting equation C4 into equation C1 yields:
\begin{equation}
    \frac{1}{\tilde r} f'(\tilde r)g(\tilde z)+ f''(\tilde r)g(\tilde z) + \xi^2f(\tilde r)g''(\tilde z) = 0
\end{equation}
\begin{equation}
    \frac{1}{\tilde r} \frac{f'(\tilde r)}{f(\tilde r)}+ \frac{f''(\tilde r)}{f(\tilde r)} = -\xi^2\frac{g''(\tilde z)}{g(\tilde z)} = -\lambda
\end{equation}
Where $f'(\tilde r)$ is the derivative of $f(\tilde r)$ with respect to $\tilde r$, $g'(\tilde z)$ is the derivative of $g(\tilde z)$ with respect to $\tilde z$ and $\lambda$ is chosen positive otherwise non-physical solutions are found. We define $\lambda=\mu^2$


We first solve for $f(\tilde r)$:
\begin{equation}
    \frac{1}{\tilde r}f'(\tilde r) + 1 f''(\tilde r)+\lambda f(\tilde r) = 0
\end{equation}
We recognize a Bessel differential equation:
\begin{equation}
    f(\tilde r) = A J_0(\mu \tilde r) + B Y_0(\mu \tilde r)
\end{equation}

Finiteness of the solution implies that $B=0$. Using the imperfect absorption boundary condition:
\begin{equation}
    \Theta \xi^{-1} \frac{\partial c}{\partial \tilde r}\vert_{\tilde r=1} + c(1,z)=0
\end{equation}
We find for a non-zero $A$:
\begin{equation}
    \Theta\frac{\mu}{\xi} = \frac{J_0(\mu)}{J_1(\mu)}
\end{equation}
There exists an infinite number of solutions $\mu_n$, where n is a positive integer. So, for a non-zero B we have $f_n(\tilde r)$:
\begin{equation}
    f_n(\tilde r) = J_0(\mu_n\tilde r)
\end{equation}
Where $\mu_n$ is the nth solution to eq C10. We now solve for $g(\tilde z)$:
\begin{equation}
    g''(\tilde z)-\xi^2\lambda g(\tilde z) = 0
\end{equation}
\begin{equation}
    g(\tilde z) = A \cosh(\frac{\mu_n}{\xi} \tilde z)+B \sinh(\frac{\mu_n}{\xi} \tilde z)
\end{equation}
We then use the boundary conditions to find A and B:
\begin{equation}
    -\Theta \frac{\mu_n}{\xi} B + A = 0
\end{equation}

\begin{equation}
    A = \Theta \frac{\mu_n}{\xi} B
\end{equation}

We then obtain $g_n(\tilde z)$ for a non-zero B:
\begin{equation}
    g_n(\tilde z) = B(\Theta\frac{\mu_n}{\xi} \cosh(\frac{\mu_n}{\xi} \tilde z) + \sinh(\frac{\mu_n}{\xi} \tilde z))
\end{equation}
Then,
\begin{equation}
    c_n(\tilde r,\tilde z) = A_n J_0(\mu_n\tilde r)(\Theta\frac{\mu_n}{\xi} \cosh(\frac{\mu_n}{\xi} \tilde z) + \sinh(\frac{\mu_n}{\xi}\tilde z))
\end{equation}
And:
\begin{equation}
    c(\tilde r,\tilde z) = \sum_{n=1}^{n=\infty}A_n J_0(\mu_n\tilde r)(\Theta\frac{\mu_n}{\xi} \cosh(\frac{\mu_n}{\xi} \tilde z) + \sinh(\frac{\mu_n}{\xi} \tilde z))
\end{equation}

We now calculate $A_n$. To do so, we use the final boundary condition $c(\tilde r,1)=1$. The equation becomes:
ù\begin{equation}
    1 = \sum_{n=1}^{n=\infty}\tilde A_n J_0(\mu_n\tilde r)
\end{equation}

Where $\tilde A_n = A_n(\Theta\frac{\mu_n}{\xi} \cosh(\frac{\mu_n}{\xi}) + \sinh(\frac{\mu_n}{\xi}))$. It is possible to find $\tilde A_n$:
\begin{equation}
    \int_0^1rJ_0(\mu_n r)dr = \sum_{n=1}^{n=\infty}\tilde A_n \int_0^1rJ_0(\mu_n r)J_0(\mu_n r)dr
\end{equation}

\begin{equation}
    \tilde A_n=\frac{2J_1(\mu_n)}{\mu_n(J_0(\mu_n)^2+J_1(\mu_n)^2)}
\end{equation}

So, the complete expression of $c(\tilde r,\tilde z)$ is:
\begin{equation}
    c(\tilde r,\tilde z) = \sum_{n=1}^{n=\infty} \frac{2 J_1(\mu_n)J_0(\mu_n\tilde r)(\Theta\frac{\mu_n}{\xi} \cosh(\frac{\mu_n}{\xi} \tilde z)+\sinh(\frac{\mu_n}{\xi} \tilde z))}{\mu_n(J_0(\mu_n)^2+ J_1(\mu_n)^2)(\Theta\frac{\mu_n}{\xi} \cosh(\frac{\mu_n}{\xi}) + \sinh(\frac{\mu_n}{\xi}))}
\end{equation}
This expression is plotted figure \ref{figconcentrationcrypt}



