\begin{equation}
    \tilde J = \sum_{n=1}^\infty \frac{4\pi J_1^2(\mu_n)(\Theta \frac{\mu_n}{\xi} \sinh(\frac{\mu_n}{\xi})+\cosh(\frac{\mu_n}{\xi}))}{\mu_n(J_0^2(\mu_n)+J_1^2(\mu_n))(\Theta \frac{\mu_n}{\xi} \cosh(\frac{\mu_n}{\xi})+\sinh(\frac{\mu_n}{\xi}))}
\end{equation}
