    \centering
    \subfloat[Total FL time with weak-scaling, using clusters with different \# of client in Docker-208.]{
    \includegraphics[height=5cm]{images/UPDATED_PLOTS/TEST-PLOT-SCALABILITY_JPDC.pdf}~
