\subsection{FedAT Pseudo-code for Client Selection and Aggregation}
FedAT is implemented in \FL using the following simple pseudo-code, using the state objects for coordination:
\begin{lstlisting}[basicstyle=\small\ttfamily, language=python]
def |\textbf{clientSelectFedAT}(\textit{sessionID, availableClients, client\-Sel\-StateRW, aggStateRO, clientTrainStateRO, client\-Info\-StateRO, trainSessionStateRO, clientSelUserConfig}):|

    |\em Get round\_no from clientSelUserConfig.|
    clientsPerTier = clientSelUserConfig.get(clientsPerTier)
    if round_no ==0 and aggStateRO.is_empty():
        numTiers = clientSelUserConfig.get(numTiers)
        clientLatencies = 
            clientInfoStateRO[availableClients.benchmark]
        clientTiers = |\em Agglomerative clustering using clientLatencies. |
        Put clientTiers in clientSelStateRW.
        for tierID, tier in clientTiers
            selClients = |\em Randomly pick clientsPerTier \# of clients from tier.|
            clientSelStateRW[tierID.selected] = selClients
            allSelClients += selClients
            clientSelStateRW[tierID.tierAggNum] = 0
        return allSelClients, None
    else
        |\em Get clientTiers from clientSelStateRW.|
        for tierID, tier in clientTiers:
            cs_tier_agg_num = clientSelStateRW[tier.tierAggNum]
            agg_tier_agg_num = aggStateRO[tier.tierAggNum]
            if cs_tier_agg_num < agg_tier_agg_num:
                clientSelStateRW[tierID.tierAggNum+= 1
                selClients = |\em Randomly pick clientsPerTier \# of clients from tier.|
                clientSelStateRW[tierID.selected] = selClients
                return selClients, None
        return None, None

def |\textbf{aggregateFedAT}(\textit{sessionID, clientID, localModel, aggStateRW, client\-Sel\-StateRO, clientTrainStateRO,client\-Info\-StateRO, trainSessionStateRO, aggUserConfig}|):
    if aggStateRW is empty:
        |\em Put| aggStateRW[tierID.tierAggNum]=0 |\em for all tierIDs|
        globalModel = trainSessionStateRO[sessionID.globalModel]
        |\em Intialize | aggStateRW[tierID.tierModel] = globalModel|\em for all tierIDs|

    |\em Put localModel and clientID in aggStateRW.|
    |\em Get tierID of clientID from clientSelStateRW.|
    selClients = |\em Get selected clients for tierID from clientSelStateRO.|

    if all selClients in aggStateRW:
        aggStateRW[tierID.tierAggNum+= 1
        tierModel = |\em Aggregate tier model from localModel for clients in selClients and amount of data per client from clientInfoStateRO.|
        aggStateRW[tierID.tierModel] = tierModel
        newModel = |\em Aggregate tierModel for all tierIDs into a single model using tierAggNum from aggStateRW.|
        |\em Delete clientID for all clients in selClients from aggStateRW.|
        return newModel
    else
        return None
\end{lstlisting}


%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{TiFL Pseudo-code for Client Selection and Aggregation}
TiFL is implemented in \FL using the following simple pseudo-code, using the state objects for coordination:
\begin{lstlisting}[basicstyle=\small\ttfamily, language=python]
def |\textbf{clientSelectTiFL}(\textit{sessionID, availableClients, client\-Sel\-StateRW, aggStateRO, clientTrainStateRO, client\-Info\-StateRO, trainSessionStateRO, clientSelUserConfig}):|
    |\em Get round from clientSelUserConfig.|
    numClients = |\em Get \# clients to select per tier from clientSelUserConfig.|

    if aggStateRO is Empty:
        |\em Get valRoundInterval from clientSelUserConfig.|
        if round == 0:
            num_tiers = |\em Get \# tiers  from clientSelUserConfig.|
            creditsPerTier = |\em Get credits per tier from clientSelUserConfig.|
            tierProbs = |\em Equal for all tiers.|
            clientLatencies = |\em Get benchmark data for availableClients from clientInfoStateRO.|
            clientTiers = |\em Cluster clients using Agglomerative clustering.|
            |\em Put clientTiers in clientSelStateRW.|
            |\em Put valOngoing to be False in  clientSelStateRW.|
            |\em Put tierCredits to be 0 for all tiers in clientSelStateRW|
        else if round % valRoundInterval:
            |\em Get ValOngoing from clientSelStateRW.|
            if ValOngoing if False:
                |\em Put valOngoing to be True in clientSelStateRW.|
                return None, availableClients
            else: 
                |\em Put clientID, ValidationMetrics in clientSelStateRW.|
                if |\em all clientIDs in availableClients are in clientSelStateRW|:
                    |\em Put valOngoing to be False in clientSelStateRW.|
                    tierProbs = |\em Calculate tier probabilities using val metrics tierCredits.|
                    |\em Clear ClientIDs and metrics from clientSelStateRW.|
        |\em Get ValOngoing from clientSelStateRW.|
        if ValOngoing is False:
            chosenTier = |\em Choose tier using tierProbs.|
            clientTiers = |\em Get clientTiers from clientSelStateRW.|
            |\em Decrement tierCredits of chosenTier by 1.|
            selClients = |\em Randomly select numClients number of clients from chosenTier of clientTiers.|
            |\em Put selClients in clientSelStateRW.|

            return selClients, None
    return None, None

def |\textbf{aggregateTiFL}(\textit{sessionID, clientID, localModel, aggStateRW, client\-Sel\-StateRO, clientTrainStateRO,client\-Info\-StateRO, trainSessionStateRO, aggUserConfig}|):
    |\em Put localModel and clientID in aggStateRW.|
    |\em Get selClients from clientSelStateRO.|
    if all selClients are in aggStateRW: 
        globalModel = |\em Aggregate global model from localModels and amount of data per client from clientInfoStateRO.|
        |\em Clear aggStateRW.|
    return globalModel
  else:
    return None
\end{lstlisting}



