  \section{Proof of Theorem  \ref{Th. main} }
 The proof uses Baum--Bott residues, and by definition, these are elements in the homology groups of $\Sing(\F)$. Yet, it is convenient in the sequel to use these residues  in cohomology, so we consider the following commutative diagram: 
 {\small
 \[
\begin{tikzcd}[row sep=2em, column sep=2.5em]
& H^{2(n-k+1)}(X, X\setminus Z) \arrow[r, "\phi"] \arrow[dd, "A" pos=0.3] \arrow[dl, "j^*_{U_i}"'] &  H^{2(n-k+1)}(X) \arrow[dd, "P"'] \arrow[dl, "j^*_{U_i}"'] \\
H^{2(n-k+1)}(U_i,  U_i \setminus Z_i) \arrow[r, crossing over, "\phi_i" pos=0.3] \arrow[dd, "A_i"] &  H_c^{2(n-k+1)}(U_i) \arrow[dd,bend right=50,"P_{i}"'] \\
& H_{2k-2}(Z) \arrow[r, "(i_Z)_*"]  & H_{2k-2}(X) \arrow[uu, bend right=50, "P^{-1}"']  \\
H_{2k-2}(Z_i) \arrow[ur, "(i_{Z_i})_*"] 
\arrow[r, "(j_{Z_i})_*"'] 
\arrow[rru,bend  right=35,"(i_{Z_i})_*"'  ] \arrow[uu, bend left=50, "A_{i}^{-1}"] 
&  H_{2k-2}(U_i) \arrow[ur, "(j_{U_i})_*"] \arrow[uu, bend right=50,"P_{i}^{-1}"' pos=0.6]
\end{tikzcd}
\]}where  all the cohomology and homology groups are with coefficients in 
$\mathbb{C}$; $P=\, \cap [X]$ is    Poincar\'e duality;  the $U_i$ are pairwise disjoint smooth regular neighborhoods (as in \cite{Hirsch}) of the \textit{connected} components $Z_1, \dots,Z_s$  of $Z$, $A$ is Alexander duality,  all the other homomorphisms are induced by the inclusion. The  morphism $\phi$ comes from the following long exact sequence of relative cohomology
 $$
 \begin{tikzcd}
  H^{2(n-k+1)}(X, X\setminus Z) \arrow[r, "\phi"]  & H^{2(n-k+1)}(X)  \arrow[r] & H^{2(n-k+1)}(X\setminus Z).
\end{tikzcd}
 $$




Recall that $c_1(N_{\F}) = c_1({\rm det}(N_{\F}))$, see  \cite[Section 5.6]{Kobayashi}.
The residues that we  consider are   localizations of $c_1(N_{\F})^{n-k+1}$ in $H_{2k-2}(Z_i)$. Given one such residue $$ {{\rm Res} }_{c_1^{n-k+1}}(\F ,Z_i):={{\rm Res} }(\F ,Z_i)\in H_{2k-2}(Z_i),$$ we can push it (by the inclusions) to $H_{2k-2}(X)$ and lift it by the Poincar\'e isomorphism to $H^{2(n-k+1)}(X)$. Denote it by  $ {\widehat  {\rm Res} } (\F ,Z_i)$. That is: 
$${\widehat  {\rm Res} } (\F ,Z_i) = P^{-1}\big( (i_{(Z_i)})_*  {\rm Res} (\F ,Z_i)\big) \,,$$
where  ${(i_{(Z_i)_*})} $ denotes the morphism $H_*(Z_i)  \to H_*(Z) \to H_*(X)$. 
Then we have the Baum--Bott formula in the cohomology group $H^{2(n-k+1)}(X)$:
$$c_1(N_{\F})^{n-k+1} = \sum_{i=1}^s \; {\widehat  {\rm Res} } (\F ,Z_i) \,.$$


First of all, we observe that the previous formula implies that the ampleness of \( c_1(N_{\F}) \) ensures that the component \( Z = \bigcup_{i=1}^s Z_i \) of dimension \( k-1 \) is non-empty, since \( c_1(N_{\F})^{n-k+1} \neq 0 \), and component $Z_-$ of dimension smaller than \( k-1 \) does not contribute to ${\widehat  {\rm Res} }$.



Now,  consider the above pairwise disjoint smooth regular neighborhoods   of the connected components of $Z$. That is, for each connected component $Z_i\subset Z$, we  take an open neighborhood $U_i$ with a retraction 
\centerline{
\xymatrix{
Z_i  \ar[rr]_{i_{Z_i}} \ar@/^2pc/[rrrr]^{} &&  U_i \ar[rr]_{\rho_i } && Z_i  \\
}
}  with a smooth boundary $\partial U_i$, such that 
\[
 \text{for all } j \neq i\quad \overline{U_i} \cap \overline{U_j} = \emptyset, \quad (\overline{U_i}\setminus Z_i)\cap Sing(\F)=\emptyset.
\]



Let $  {\rm Res}  (\F ,Z_i)$ be the Baum--Bott residue in $H_{2k-2}(Z_i)$. Define:
 $$ \widehat {\rm Res}  (\F  |_{U_i},Z_i) = P_i^{-1}\big((i_{Z_i})_* {\rm Res} (\F ,Z_i)\big)  \,.
 $$


 By the commutativity of the diagram above, we have the following equality in $H_c^{2(n-k+1)}(U_i)$:
 \begin{equation}\label {eq 1}
  \widehat {\rm Res}  (\F  |_{U_i},Z_i) = j^*_{U_i} \big( \widehat  {\rm Res}  (\F ,Z_i) \big) \;.
 \end{equation}

We can   take a neighborhood $V_i$ of  $ \partial U_i $ such that $\F$ is  regular  on $V_i$, i.e.,  the tangent sheaf of $\F$ is locally free on $V_i$, where     $U_i$   is  a retraction of $Z_i$. Then, we can apply Theorem 1.4 from \cite{SS1} and, using the naturality of Chern classes, we obtain
\begin{equation} \label{eq 2}
\begin{aligned}
\widehat{\mathrm{Res}}(\F|_{U_i}, Z_i) &= c_1(\det(N_{\F})|_{U_i})^{n-k+1} \\
\\
&= c_1(j^*_{U_i} \det(N_{\F}))^{n-k+1} \\
\\
&= j^*_{U_i}\big(c_1(N_{\F})^{n-k+1}\big) \;.
\end{aligned}
\end{equation}
  Since $Z_i$ is connected, we have  that 
  $H_{2(k-1)}(Z_i)\simeq H_{2(k-1)}(U_i)$ is generated by the fundamental cycle $ [Z_i]$,  it follows that the residue of $\F |_{U_i}$ at $Z_i$ satisfies:
 $$ {\rm Res}  (\F  |_{U_i},Z_i)  = \lambda_i [Z_i]  = {\rm Res}  (\F  ,Z_i) \,, $$
 for some $ \lambda_i \in \C$. Thus,
 $$ P_i^{-1}\big((i_{Z_i})_* {\rm Res} (\F ,Z_i)\big) 
 =  \lambda_i \widehat {[Z_i]} \in H^{2(n-k+1)}(X) \;,$$
 where   
$$\widehat {[Z_i]}:= P^{-1} \big((i_{Z_i})_*[Z_i]\big)\,
$$
the Poincar\'e dual of $[Z_i]$.


 Applying $j^*_{U_i}$ to the previous equation we get the following equality in $\in H_c^{2(n-k+1)}(U_i)$:
\begin{equation}\label{eq 4}
j^*_{U_i} \big(\widehat {\rm Res}(\F ,Z_i)\big) \,=\, \lambda_i \cdot  j^*_{U_i} \big(\widehat {[Z_i]}\big)  \,=\,  j^*_{U_i}  \big( c_1({\rm det}(N_{\F})\big)^{n-k+1} \;,
\end{equation}
where the last equality follows from equation (\ref{eq 2}). 
The ampleness  says us that here there  is an embedding 
$
i: X  \hookrightarrow \mathbb{P}^N,
$
for some $N$, such that 
$
\det(N_{\F}) = \mathcal{O}_X(r) = i^*\bigl( \mathcal{O}_{\mathbb{P}^N}(r)\bigr).
$ 
 Therefore 
 $$c_1({\rm det} (N_{\F}))^{n-k+1} = r^{n-k+1} h^{n-k+1} \in  H^{2(n-k+1)}(\mathbb{P}^n)  \,,$$
 where  $h := c_1(\O_X(1))$. Hence:
 $$ j^*_{U_i} \big(c_1({\rm det} (N_{\F}))^{n-k+1}\big) = r^{n-k+1}  j^*_{U_i} (h^{n-k+1}) \in  H^{2(n-k+1)}(U_i)\,. $$
 Let $ {[Z_i]}$ be the fundamental cycle. 
 Substituting in (\ref {eq 4}) we get: 
 $$ \lambda_i \cdot  j^*_{U_i}\big( \widehat {[Z_i]}\big)  = j^*_{U_i}\big( c_1(N_{\F})^{n-k+1} \big)=  r^{n-k+1}  j^*_{U_i} (h^{n-k+1}) \,, $$
Since $k>1$, we can  apply  $j^*_{U_i} (h^{k-1})$ in this equation and  we get:
  $$ \lambda_i \cdot (j^*_{U_i} \widehat {[Z_i]}) \smile    j^*_{U_i}( h^{k-1})  = r^{n-k+1}  j^*_{U_i} (h^{n-k+1})\smile   j^*_{U_i} (h^{k-1}) \,, $$
 That implies:
   $$ \lambda_i \cdot  j^*_{U_i} ( \widehat {[Z_i]} \smile    h^{k-1})  =  r^{n-k+1}  j^*_{U_i} (h^{n}) \,. $$
 Hence 
 $$ \widehat {[Z_i]} \smile   h^{k-1}= P^{-1}[Z_i]\smile P^{-1}[W_i] = P^{-1}([Z_i\cap W_i]) =d_i\cdot P^{-1}[p_i],$$ where $\{p_i\}=Z_i \cap W_i$ is the intersection point of $Z_i$ with a generic complete   intersection
 $W_i = H_1^{i} \cap \cdots \cap H_{n-k+1}^{i},$
 with $$H_1^{i},\dots,H_{n-k+1}^{i} \in H^0(X, \mathcal{O}_X(1)),$$ where $d_i$ is the multiplicity of this intersection.  
 Notice that $p_i\in U_i$ can be defined in general by the intersection of hyperplane sections:
 $$ P^{-1}[p_i] = [ \widetilde H_1 \cap ... \cap  \widetilde H_n] = h^n,$$
 for generic  $\widetilde H_1 \cap ... \cap  \widetilde H_n \in H^0(X, \mathcal{O}_X(1))$. 
Thus we have 
 $$ \lambda_i \cdot j^*_{U_i} ( \widehat {[Z_i]} \smile   h^{k-1})  = \lambda_i \cdot  j^*_{U_i} (d_i \big(P^{-1}[p_i]\big)) = r^{n-k+1}  j^*_{U_i} (h^{n}),$$
 and $j^*_{U_i} h^n  = j^*_{U_i}\big(P^{-1}[p_i]\big)\neq 0$, since $p_i\in Z_i\subset  U_i$.
  Hence, 
  \begin{equation}\label{eq 5}
\lambda_i d_i =  r^{n-k+1}. 
 \end{equation}
 Recall that Baum--Bott says:
 $$c_1(N_{\F})^{n-k+1} = \sum_{i=1}^s \lambda _i  \widehat {[Z_i]}.$$
Since  $c_1(N_{\F})^{n-k+1} =  r^{n-k+1} h^{n-k+1} $,  then by (\ref{eq 5})
 $$ r^{n-k+1}   h^{n-k+1} =  \sum_{i=1}^s \left( \frac{r^{n-k+1}} {d_i}\right) 
  \widehat {[Z_i]} \, .$$
 Applying $h^{k-1}$  we get 
  \begin{equation*} 
\begin{aligned}
r^{n-k+1}   h^{n}&= \sum_{i=1}^s  \left(\frac{r^{n-k+1}} {d_i} \right)\cdot 
  \widehat {[Z_i]} \smile   h^{k-1} &= \sum_{i=1}^s r^{n-k+1}     \frac{d_i h^n}{d_i}
  \\
   & &=  \sum_{i=1}^s  r^{n-k+1} h^n,
\end{aligned}
\end{equation*}
since  $\widehat {[Z_i]} \smile   h^{k-1}  = d_i h^n$. Thus
$$
h^n =  \sum_{i=1}^s    h^n=sh^n
$$
implies that  $(s-1)h^n=0$, so  $s=1$, since $h$ is ample. Therefore, $Z$ is connected.

\qed







 \section{Proof Corollary 1}

  Theorem \ref{Th. main}  guarantees that the curve $C$   is connected. Applying \cite[Theorem 5]{CCJ2}, we conclude that $$h^2(\F\otimes\det(N_\F)^*)=c_3(\F)\cap [X],$$ and by 
\cite[Proposition 3.6]{Gholampour-Kool}
$$
c_3(\F)\cap [X]= h^0(X,\mathscr{E}xt^1(\F,\mathcal{O}_X) )
$$
which is the number of isolated singularities of $\F$ counted with multiplicities, since by \cite[Lemma 2.1]{CCJ}, the foliation $\F$ has tangent sheaf locally free along $C$. Note that since  $C$ is reduced, then  it has no embedded points.

Now, suppose \( X = \mathbb{P}^3 \). Then, the dual of the determinant of the normal sheaf \( N_{\mathscr{F}} \) is given by 
$
\mathcal{O}_{\mathbb{P}^3}(-2 - d),
$
where \( d \) denotes the degree of the foliation \( \mathscr{F} \), see Remark \ref{remark:Pn}. Applying Bott's formulae \cite[pg.12]{AMM}, we deduce
\[
h^1(\mathcal{O}_{\mathbb{P}^3})  = h^1(T\mathbb{P}^2(-2 - d))\simeq h^1(\Omega_{\mathbb{P}^2}^1(2 - d))  = 0 \quad \text{for all } d \geq 0.
\]
Furthermore, following the proof of Proposition 14 in \cite{CCJ2}, we obtain
\[
h^2(T\mathbb{P}^3 \otimes \det(N_{\mathscr{F}})^*) = h^2(T\mathbb{P}^3(-2 - d)) = h^1(\mathscr{I}_C) = h^0(\mathcal{O}_C) - 1,
\]
which vanishes whenever \( C \) is a reduced and connected curve.


\qed

  \section{Proof Corollary 2}
According to \cite[Theorem 3.11]{CCJ}, a codimension one distribution $\F$ of positive degree on $\mathbb{P}^3$ with a locally free tangent sheaf and a smooth, connected singular scheme cannot be integrable. Remark \ref{remark:Pn} below states that Theorem \ref{Th. main} applies to this situation. Therefore, if \( \F \) is integrable, then either \( \F \) has degree zero and is a pencil of planes in which case \( \Sing(\F) \) is a line, or \( \Sing(\F) \) cannot be smooth.












\section{Examples and remarks}\label{Examples-remarks}

In this section, we will present examples and observations that demonstrate the necessity of the hypotheses, in particular that Theorem 1 is sharp.


\begin{exe}
Let $X$ be the classical Hopf manifold of dimension $n$. This is obtained from $\C^n \setminus \{0\}$ dividing it by the group of automorphisms generated by a contraction, say $z \mapsto z/2 $. It is clear that  $X$ fibers over $\P^{n-1}$ with fiber an elliptic curve, the quotient of $\C^*$ by the contraction. So one has 
an elliptic fibration $X  \buildrel {\pi} \over {\to} \P^{n-1}$. 


Consider now a 1-dimensional foliation $\F$  on $\P^{n-1}$ with isolated singularities. Its pull back  $\pi^{\ast}\F$ is a 2-dimensional foliation  on $X$ with 
 singular set, a union of disjoint elliptic curves:
\[
\operatorname{Sing}(\pi^*\F) = \bigsqcup_{p \in \operatorname{Sing}(\F)} \pi^{-1}(p).
\]
 If $\operatorname{Sing}(\F)$ is reduced, then $\operatorname{Sing}(\pi^*\F)$ has $d^{n-1}+ \cdots + d+1$ connected components, see for instance \cite[Theorem A]{Soares}.

In this example, neither the manifold in question is projective, nor is $\det(N_\F)$ ample. 
\end{exe}


\begin{exe}(Foliations on  products) 
Let $\F$ be a holomorphic foliation of dimension $1$ with isolated singularities on a projective manifold $X$  of dimension $n$. If $Y$ is a projective manifold of dimension $k-1$, then we have a foliation $\pi_2^*\F$ on $X\times Y$ of dimension $k$,  with singular set the  disjoint union 
\[
\operatorname{Sing}(\pi_2^*\F) = \bigsqcup_{p \in \operatorname{Sing}(\F)} \pi_2^{-1}(p),
\]
where $\pi_2^{-1}(p)=Y$ for all $p \in \operatorname{Sing}(\F)$. Then $c_1(\det(N(\pi_2^*\F)))=\pi_2^*c_1(\det(N_\F)) $, and 
\[
c_1(\det(N_\F(\pi_2^*\F)))^{n+k-1}=0
\]
since $n+k-1>n$.  So the determinant of the normal bundle is not ample. 
\end{exe}

The next example is a 2-dimensional foliation on \(\mathbb{P}^n\), induced by the action of the affine group, whose singular set is the connected union of \(n\) rational curves intersecting at a single point.

\begin{exe} The next example generalizes to high dimensions an example from \cite{CCGL} for $n=3$; the foliation $\widetilde{\F}_{3,d}$ described below defines a rigid irreducible component of the space of foliations of codimension one on  $\P^3$ of degree $d+1$, and $\widetilde{\F}_{3,1}$ generates the \emph{exceptional component} of foliations of degree 2 \cite[Cor. 3, p 1007]{CCGL}. 

In the affine space $\{[1:z]\}\simeq\C^n\subset\P^n,\, n\geq3$, let us denote $c_k(d)=c_k(T\P^k(d-1))$, and we define the complete vector fields 
\[
\xymatrix@R=1mm{ u_{n,d}(z) = z_1\partial_{z_1}+c_1(d)\cdot z_2\partial_{z_2}+\cdots+ c_{n-1}(d)\cdot z_n\partial_{z_n} \\
v_{n,d}(z)= \partial_{z_1}+c_1(d)\cdot z_1^d\partial_{z_2}+\cdots+ c_{n-1}(d)\cdot 
z_{n-1}^d\partial_{z_n}. } 
\]  

Since  
$[v_{n,d},u_{n,d}]=v_{n,d},$ they are the infinitesimal generators of an action of the affine group, $ \mathfrak{aff}(\mathbb{C})\times \C^n\longrightarrow\C^n.$

The vector field $u_{n,d}$ is linear, it extends as a holomorphic section $\widetilde{u}_{n,d}$ of $T\P^n$. On the other hand,  
$v_{n,d}$ is polynomial of degree $d$, it extends as a holomorphic bundle map $\widetilde{v}_{n,d}:\O_{\P^n}(1-d)\longrightarrow T\P^n$, with a unique singularity at the point $p=[0:\cdots:0:1]\in \P^n$, with Milnor number
\[
\mu(\widetilde{v}_{n,d}(p))=c_n(T\P^n(d-1))=c_{n}(d).
\]
We define the foliation of dimension 2:
\[
\xymatrix{ 0\ar[r] & \widetilde{\F}_{n,d}=\O_{\P^n}\oplus\O_{\P^n}(1-d) 
\ar[rr]^-{\widetilde{u}_{n,d}\oplus\widetilde{v}_{n,d} } && T\P^n \ar[r] & N_{\widetilde{\F}_{n,d}}\ar[r] &0   }
\]
The singular set $\Sing(\widetilde{\F}_{n,d})=\Lambda_{1,d}\cup\Lambda_{2,d}\cup\dots\cup\Lambda_{n,d}$ is a union of rational curves
$\Lambda_{j,d}$ of degrees $\deg(\Lambda_{1,d})=1$ and for $j>1,\quad \deg(\Lambda_{j,d})=c_{j-1}(d).$ Moreover 
\[
\bigcap_{j=1}^n \Lambda_{j,d}=\{ [0:\cdots:0:1] \},
\]
hence, $\Sing(\widetilde{\F}_{n,d})$ is connected. 
Notice that the restriction $\widetilde{\F}_{n,d}|_{\{Z_n=0\}}$ is $\widetilde{\F}_{n-1,d}$, and 
\[
 \Sing(\widetilde{\F}_{n,d})=\Sing(\widetilde{\F}_{n-1,d})\cup \Lambda_{n,d}.
\] 
Denote $C_k=c_k(d)$, so  the curve $\Lambda_{n,d}$ is parameterized by 
\[
\Lambda_{n,d}([s:t])=[ s^{C_{n-1}}:s^{(C_{n-1}-1)}t:s^{(C_{n-1}-C_1)}t^{C_1}:\cdots :t^{C_{n-1}}].
\]  
\end{exe}




\begin{remark}
Let \( \F \) be a holomorphic foliation on \( \mathbb{P}^n \) of dimension \( k > 1 \), with \( Z \subset \Sing(\F) \) the  non-empty component of dimension \( k - 1 \). We can write
\[
Z = \bigcup_{j=1}^{s} Z_{j},
\]
where \( Z_{j} \) are the connected components. In this case, we have
\[
[Z_i \cap Z_k] = (d_j h^{n-k+1}) \smile (d_k h^{n-k+1}) = d_j d_k h^{2(n-k+1)} \in H^{2(n-k+1)}(\mathbb{P}^n),
\]
with \( d_j = \deg(Z_j) \) and \( d_k = \deg(Z_k) \). Thus, \( [Z_i \cap Z_k] \neq 0 \) whenever \( n \leq 2k - 2 \), implying that \( Z \) is connected in this case. Consequently, the statement of Theorem \ref{Th. main}   is not immediate in the case where  \( n > 2k - 2 \). Recently, in \cite{CorreaSuwa2025}, it was shown that \( \dim(\Sing(\F)) \geq k - 1 \), whenever \( n \geq 2k \), meaning that \( Z_- \) is empty.
\end{remark}


\begin{remark}
We note that the hypothesis that $k>1$ is also necessary: a generic foliation by curves on a complex projective manifold has 0-dimensional singularities consisting of several distinct points. In addition, \cite{CJM} contains various examples of foliations by curves on $\mathbb{P}^3$ whose singular set is the union of two or more skew lines.
\end{remark}

\begin{remark}\label{remark:Pn}
Consider a holomorphic foliation \(\F \subset TX\) of dimension \(k\).  
By taking the maximal exterior power of the dual morphism 
\[
\Omega^1_X \longrightarrow \F^*,
\] 
one obtains a morphism
$
\wedge^k \phi^\vee: \Omega^k_X \longrightarrow \det(\F)^*.
$
This, in turn, yields an induced morphism
$$
\Omega^k_X \otimes \det(\F) \longrightarrow \mathcal{O}_X,
$$
whose image is an ideal sheaf \(\mathcal{I}_Z\) defining the  singular set of the foliation \(Z=\Sing(\F) \subset X\).  
Moreover, this construction determines a global section
$
\nu_{\F} \in H^0\left(X, \wedge^k TX \otimes \det(\F)^*\right). 
$
By the isomorphism 
$
\wedge^k TX \simeq \Omega_X^{n-k} \otimes \det(TX)
$
and the relation 
$
\det(N_\F) \simeq \det(TX) \otimes K\F,
$
we conclude that the isomorphism
\[
\wedge^k TX \otimes K\F 
\simeq \Omega_X^{n-k} \otimes \det(TX) \otimes K\F 
\simeq \Omega_X^{n-k} \otimes \det(N_\F)
\]
shows that the section \(\nu_{\F}\) corresponds to a twisted \((n-k)\)-form
\[
\omega_{\F} \in H^0\left(X, \Omega_X^{n-k} \otimes \det(N_\F)\right)
\]
with values in \(\det(N_\F)\).
A holomorphic foliation \(\F\) of dimension \(k\) on \(\mathbb{P}^n\) can be described by a twisted \((n-k)\)-form
\[
\omega \in H^0\left(\mathbb{P}^n, \Omega_{\mathbb{P}^n}^{n-k}(d+n-k+1)\right),
\]
where \(d \geq 0\) is referred to as the \emph{degree} of the foliation \(\F\). Then, \(\det(N_\F)=\mathcal{O}_{\mathbb{P}^n}(d+n-k+1)\)   is   ample. See for instance  \cite[Section 2.5]{CJV}.
\end{remark}

\begin{remark}
Observe that, a priori, each connected component is such that 
\[
Z_i = \bigcup_{j=1}^{j(i)} Z_{ij}
\]
where \( Z_{ij} \) are its irreducible components, for $i=1,\dots,s$.  
Theorem \ref{Th. main} implies  the component of dimension \( k-1 \) of the singular set of the foliation \( Z \) is connected. That is,    $Z=Z_i$, for all $i$,  and  by Baum--Bott
$$c_1(N_{\F})^{n-k+1} \cap [X] = \sum_{j=1}^\ell \lambda _j  [Z_j] \in H_{2k-2}(Z),$$
where \( Z_{j} \) are  the irreducible components of $Z$ and \(\lambda_j\) are complex numbers that depend only on the local behavior of the leaves of \(\F\) near \(Z_j\).
\end{remark}











