\begin{defn}\label{reduced} A diagram is \textit{reduced} if there are no cells $C_1,C_2$ sharing an edge $E$ such that the words along their boundaries, starting at $E$, are inverses. Two cells $C_1,C_2$ satisfying this property are called \textit{cancelling cells}.  Every word that represents $1$ in a finitely presented group admits a reduced van~Kampen diagram over that presentations.  Every pair of words that represent conjugate elements admits a reduced annular diagram.
\end{defn}

\subsection{Dehn functions}\label{Dehnfn} 

We define $\Area(\Delta)$ to be the number of faces in a van~Kampen diagram $\Delta$.  For a word  $w$ on $X$ representing the identity of $G=\langle X\mid R\rangle$, we define $\Area(w)$ to be the minimum of $\Area(\Delta)$ among all van~Kampen diagrams for $w$.  A word $w$ on $X$ represents the identity in $G$ if and only if $w$ freely equals a product of the form $$\prod_{i=1}^kw_ir_i^{\delta_i}w_i^{-1},$$ where $r_i\in R$, $\delta_i\in \{\pm1\}$, and $w_i$ is a word on $X$ for all $i$.  It follows from the standard proof of van~Kampen's Lemma that for any word $w$ representing the identity in $G$, $\Area(w)$ is also the smallest $k$ such that $w$ freely equals a word of this form. 

Define the \emph{Dehn  function} $\Area : \N \to \N$ of $G$ relative to  a finite presentation $\langle X \mid R \rangle$ for $G$ by $$\Area(n) = \max  \set{ \Area(w) : |w|\leq n \text{ and } w=1 \text{ in  } G}.$$ 
See, for example, \cite{Bridson6, BrH, brady2007geometry} for  more details.  




\subsection{Conjugator length functions and annular Dehn functions}\label{CL_and_ann}


Suppose $G$ is a group with finite generating set $X$.  Suppose words $u$ and $v$   on $X$   represent conjugate elements in $G$.  Define $\CL(u,v)$ to be  $\min_{}|\g|$ over all   words $\gamma$ such that $\g u\g^{-1}=v$ in $G$.  

Suppose now that $G=\langle X\mid R\rangle$ is a finitely presented group. By Lemma 3.3 and the argument of Lemma 3.2 in \cite{BRS},  $\CL(u,v)$ is equivalently the minimal length $L$ such that there is a annular diagram  $\Omega$ for $u$ and $v$, as per  Lemma~\ref{annulardiagramlemma}, for which there is an edge-path of length $L$ from $p_1$ to $p_2$.  

Define $\Ann(u,v)$ to be the minimum of  $\Area(\Omega)$  over all over  all annular diagrams  $\Omega$ for $u$ and $v$, or similarly equivalently,  the minimum of $\Area(\g u\g^{-1}v^{-1})$  over all words $\gamma$ such that $\g u\g^{-1}=v$ in $G$.     

A priori, a diagram witnessing $\CL(u,v)$ may not witness $\Ann(u,v)$.   



Define the \emph{conjugator length function} $\CL : \N \to \N$ and the \emph{annular Dehn function} $\Ann~:~\N \to~\N$ of $G$ by 
$$\begin{array}{rl}
\CL(n)  \!\!\! & = \ \max \CL(u,v) \\ \Ann(n)  \!\!\! & = \ \max \Ann(u,v),
\end{array}$$
where both maxima are taken over all pairs of words $u$ and $v$ such that $|u|+|v|\leq n$ and $u$ and $v$ represent conjugate elements in $G$. 

Up to $\simeq$,   $\Area(n)$ and $\Ann(n)$ do not depend on the choice of finite presentation for $G$, and $\CL(n)$ does not depend on the choice of finite generating set.  

 We will call on these two technical results. 
\begin{lemma} \label{triangle ineq for A}
    If $u=v=w$ in $G=\langle X\mid R\rangle$, then $$\Area(uv^{-1})-\Area(vw^{-1}) \ \leq \  \Area(uw^{-1}) \ \leq \   \Area(uv^{-1})+\Area(vw^{-1}).$$
\end{lemma}
\begin{proof}
    The second inequality follows from the fact that $uw^{-1}$ freely equals $uv^{-1}vw^{-1}$. The first follows from the second after interchanging the roles of $v$ and $w$.
\end{proof}

\begin{lemma}\label{Gluing van Kampen to annular diagram}
    If $u \sim v$ in $G$ and $v=w$ in $G$, then $$\Ann(u,v)-\Area(vw^{-1}) \ \leq \  \Ann(u, w) \ \leq \  \Ann(u,v)+\Area(vw^{-1}).$$
\end{lemma}
\begin{proof}
This follows by a similar argument as the previous lemma, using the fact that $\Ann(u,v)=\Area(\gamma u\gamma ^{-1} v^{-1})$ for some $\gamma$.
\end{proof}



 \subsection{Direct products and free products}

The behaviour of $\CL(n)$, $\Ann(n)$ and $\Area(n)$ for direct and free products of finitely generated groups is summarized in the next two propositions, which in large part are from \cite{brick_corson_1998}. We will not call on \eqref{Ann better upper bound}, but we include it here as the natural improvement on the upper bound of \eqref{Ann bad bounds} in circumstances when the optimal conjugator length and annular Dehn function can  be simultaneously realized.



\begin{prop}[]\label{dirprodannular}
Assuming for  \eqref{CL bounds} that $G_1$ and $G_2$ are finitely generated groups,  for  \eqref{Ann bad bounds} and \eqref{Area bounds}   they are finitely presented, and further for \eqref{Area bounds}  that   $\Area_{G_1}(n)$ or $\Area_{G_2}(n)$ grows   $\succeq \! n^2$, we have 
    \begin{flalign}   
    \CL_{G_1\times G_2}(n) & \ \simeq \ \max\{\CL_{G_1}(n),\CL_{G_2}(n)\}, \label{CL bounds} \\ 
          \max \{ \Ann_{G_1}(n), \Ann_{G_2}(n) \}    \  \preceq  \ \Ann_{G_1\times G_2}(n) \hspace*{-13mm} &  \hspace*{13mm}  \ \preceq \   \max\{ n \Ann_{G_1}(n), n \Ann_{G_2}(n)\}+n^2, \label{Ann bad bounds}  \\
           \Area_{G_1\times G_2}(n) & \ \simeq \ \max\{\Area_{G_1}(n),\Area_{G_2}(n)\}.  \label{Area bounds} 
       \end{flalign}
Further, suppose there exists a constant $D$ such that for all $u,v\in G_i$ with $|u|+|v|\leq n$, there exists $w$ where $w uw^{-1}=v$, $|w|\leq D \, \CL_{G_i}(n)+D$, and $\Area(w uw^{-1}v^{-1})\leq D \, \Ann_{G_i}(n)+D$. Then
           \begin{flalign}   
       \Ann_{G_1\times G_2}(n)  \  & \preceq \  \Ann_{G_1}(n) +\Ann_{G_2}(n) + n \CL_{G_1}(n) + n \CL_{G_2}(n).  \label{Ann better upper bound}  
       \end{flalign}
\end{prop}


\begin{proof} The proofs of (\ref{CL bounds}) and (\ref{Area bounds}) are straight-forward.      

The first inequality of (\ref{Ann bad bounds}) follows directly from Theorem 2.1 of \cite{brick_corson_1998}. For the second, let $u,v\in G_1\times G_2$ be conjugate words such that $|u|+|v|=n$. Then there exist $u_1,v_1\in G_1$ and $u_2, v_2\in G$  such that $u=u_1u_2$ and $v=v_1v_2$ in $G_1\times G_2$, $u_1$ is conjugate to $v_1$ in $G_1$, and $u_1$ is conjugate to $u_2$ in $G_2$. Without loss of generality we may assume $|u_1|+|u_2|+|v_1|+|v_2|=~|u|+|v|=n$, and that our presentation for $G_1\times G_2$ contains a relator $[g_1,g_2]$ for all generators $g_1$ of $G_1$ and $g_2$ of $G_2$. 

For $i=1,2$, let $w_i$ be a word that conjugates $u_i$ to $v_i$ in $G_i$ and has $\Area(w_i u_i w_i^{-1} v_i^{-1}) = \Ann(u_i, v_i)$. Then $w=w_1w_2$ conjugates  $u$ to $v$. Then $|w_i|\leq M\cdot \Ann_{G_i}(n)+n$, where $M$ is the length of the longest defining relation in our presentations for $G_1$ and $G_2$. 
    We can transform $$w_1w_2 u_1u_2  \ \to \  w_1u_1w_2 u_2  \ \to \  w_1u_1 v_2 w_2 \ \to \  v_1 w_1 v_2  w_2 \ \to \  v_1v_2 w_1 w_2,$$
at a cost of applying at most $|w_2|\cdot |u_1|\leq nM\cdot \Ann_{G_2}(n)+n^2$, then $M\cdot \Ann_{G_2}(n)+n$, then $M\cdot \Ann_{G_1}(n)+n^2$, and then  $|v_2|\cdot|w_1|\leq nM\cdot \Ann_{G_1}(n)+n^2$ defining relations. 

The proof of (\ref{Ann better upper bound}) is similar.
\end{proof}

The corresponding result for free products requires additional notation.
\begin{defn}\label{subnegClosure}
    For a finitely presented group $G$, define $\overline{\Ann_{G}}(n)$ to be the minimal integer such that $\overline{\Ann_{G}}(n) \geq \Ann_G(n)$  and  $\overline{\Ann_{G}}(n+\tilde{n})\geq \overline{\Ann_{G}}(n)+\overline{\Ann_{G}}(\tilde{n})$ for all $n, \tilde{n} \in \N$.  
\end{defn}

\begin{prop}[]\label{freeprodannular}
Suppose  for  \eqref{free prod CL bounds}  that $G_1$ and $G_2$ are finitely generated groups, and for \eqref{free prod Ann bounds}   that they are finitely presented,  and for  \eqref{free prod  Area bounds} further suppose that one of $\Area_{G_1}(n)$ and $\Area_{G_2}(n)$ grows   $\succeq \! n$. Let $F_i(n)$ be the smallest function such that $F_i(n)\geq \Ann_{G_i}(n)$ and $F_i(n+n')\geq F_i(n)+F_i(n')$ for $i=1,2$. Then, for $i=1,2$, 
    \begin{flalign}   
    \CL_{G_1 \ast G_2}(n) & \ \simeq \ \max\{\CL_{G_1}(n),\CL_{G_2}(n)\}, \label{free prod CL bounds} \\ 
            \Ann_{G_1 \ast G_2}(n)   & \ \simeq \     \max\{ \overline{\Ann_{G_1}}(n), \overline{\Ann_{G_2}}(n)\}, \label{free prod Ann bounds}  \\
           \Area_{G_1 \ast G_2}(n) & \ \simeq \ \max\{\Area_{G_1}(n),\Area_{G_2}(n)\}.  \label{free prod Area bounds} 
       \end{flalign}
\end{prop}
\begin{proof}
For (\ref{free prod CL bounds}) and (\ref{free prod Ann bounds}), the claim is a restatement \cite{brick_corson_1998}[Corollary 3.3]. The upper bound for (\ref{free prod Area bounds}) is straightforward, and the lower bound follows from the existence of retracts $G_1\ast G_2\to G_i$ for $i=1,2$.
\end{proof}



\section{Proof of Theorem~\ref{MainTheorem}} \label{Proof of main thm} 



That $G_1= \mathcal{H}_{3}(\ZZ)$ satisfies $\Area_{G_1}(n)\simeq n^3$ is proved in \cite[Chapter~8.1]{epstein1992word}. 
That $\CL_{G_1}(n) \simeq n^2$ is shown in \cite{BRS}. We postpone proof that $\Ann_{G_1}(n)\simeq  n^4$ to Section~\ref{heisensec}.

The Baumslag-Solitar group $G_2$  is well known to have $\Area_{G_2}(n) \simeq 2^n$ (e.g.\  \cite[Chapter~7.4]{epstein1992word}, \cite[Theorem~8.8]{RileyDehn}).  That $\CL_{G_2}(n)\simeq n$  was proved first by \cite{Sale3}; there is an elementary proof in \cite{BRS}.  That $\Ann_{G_2}(n)\simeq 2^n$ then follows from Theorem~\ref{BCineq}.

Our estimates for $G_3$ will follow from  those for $G_1$ and $G_2$ by Proposition~\ref{dirprodannular}.  

We postpone the estimates concerning $G_4$ to Section~\ref{graphofgroups_BS12_and_heisenberg}.


That  $\Area_{G_{5,d}}(n) \simeq n^{d+1}$ is  \cite[Theorem 6.3]{BridsonPittet}.  That $\Area_{G_{6,m}}(n) \preceq n^3$ follows from \cite{GHR} since the groups are class-2 nilpotent.  Inspecting the presentation for $G_{6,m}$ given in Definition~\ref{G6m}, we see that killing all generators other than $a_1$, $b_1$, and $c_1$ retracts $G_{6,m}$ onto a copy of the Heisenberg group $G_1$, and thereby $\Area_{G_{6,m}}(n) \succeq n^3$  follows from $\Area_{G_1}(n)\simeq n^3$.  
That $\CL_{G_{5,d}}(n) \simeq n^{d}$ and $\CL_{G_{6,m}}(n) \simeq n^{m+1}$ are the main results of \cite{BrRi2} and \cite{BrRi1}, respectively. 

The computations of $\Area_{G_7}$, $\Area_{G_8}$, $\CL_{G_7}$, and $\CL_{G_8}$ follow via Proposition~\ref{freeprodannular}. Towards $\Ann_{G_7}(n)\simeq \Ann_{G_8}(n)$, using the notation of Definition~\ref{subnegClosure},    
    \begin{flalign}   \label{Ann n21 upper bound}
\overline{\Ann_{G_{6,20}}}(n) & \succeq \  \Ann_{G_{6,20}}(n) \ \succeq \  n^{21} \  \text{ and } \\  
 n^{21} & \succeq \ \max\{\Ann_{G_{5,3}}(n),\Ann_{G_{5,4}}(n)\}. \label{n21bound}
    \end{flalign}   
where the second inequality of \eqref{Ann n21 upper bound} combines    Theorem~\ref{BCineq}\eqref{CL by Ann} and $\CL_{G_{6,20}}(n) \simeq n^{21}$ discussed above, and  \eqref{n21bound} holds because from Theorem~\ref{BCineq}\eqref{ann by area and cl} applied to the bounds given above tells us that $\Ann_{G_{5,3}}(n) \preceq (n^3)^4$ and  $\Ann_{G_{5,4}}(n) \preceq (n^4)^5$.  Because  $(n+\tilde{n})^{21}\geq n^{21}+\tilde{n}^{21}$ for all $n, \tilde{n} \in \N$,  \eqref{n21bound} gives $n^{21}\succeq \max\left\{\overline{\Ann_{G_{5,3}}}(n),\overline{\Ann_{G_{5,4}}}(n)\right\}$. Since $G_7=G_{5,3}\ast G_{6,20}$ and $G_8=G_{5,4}\ast G_{6,20}$, Proposition~\ref{freeprodannular} then gives $\Ann_{G_7}\simeq \overline{\Ann_{G_{6,20}}}(n)=\Ann_{G_8}$.




Aside from the  estimates postponed to Sections~\ref{heisensec} and \ref{graphofgroups_BS12_and_heisenberg}, this completes our proof of Theorem~\ref{MainTheorem}




\section{The Heisenberg Group}\label{heisensec}

\begin{prop}\label{Heisenberg_upper}
    The annular Dehn function of $G_1$ satisfies $\Ann_{G_1}(n) \simeq n^4$.
\end{prop}



\begin{proof} 
We begin by proving that $\Ann_{G_1}(n) \preceq n^4$. 
Suppose $n>0$ and that $u$ and $v$ are words on the generators of $$G_1  \ = \  \mathcal{H}_3(\ZZ) \ = \  \langle a ,b,c\mid [a,c], [b,c], [a,b]c^{-1} \rangle$$  such that $|u|+|v| \leq n$. By shuffling the $a$-letters to the front (at the expense of creating a $c$ or $c^{-1}$ whenever an $a$ passes a $b$) and shuffling all the $c$-letters to the end, we can transform $u$ to $a^{\alpha_1}b^{\beta_1}c^{\gamma_1}$ and $v$ to $a^{\alpha_2}b^{\beta_2}c^{\gamma_2}$ where $|\alpha_1|+|\alpha_2|+|\beta_1|+|\beta_2|\leq n$ and $|\gamma_1|+|\gamma_2|\leq n^2$ using at most $2n^3$ defining relations. This is the well-known normal form for $G_1$ (see the discussion in \cite{epstein1992word}), so $\alpha_1,\alpha_2,\beta_1,\beta_2,\gamma_1,\gamma_2$ are uniquely determined by $u$ and $v$.

Since $c$ is central in  $G_1$, if $\hat{w} = a^xb^yc^z$ satisfies $\hat{w} u = v \hat{w}$ in $G_1$, then  $w = a^xb^y$ satisfies $w u  =  v w$ in $G_1$. We follow the strategy of \cite{BRS} for finding $x$ and $y$ to suit our purposes. Computing the the normal form of $w u w^{-1}$: \begin{subequations}
\label{all}
\begin{align}
w u w^{-1} & = \  a^xb^ya^{\alpha_1}b^{\beta_1}c^{\gamma_1}b^{-y}a^{-x}\label{eqn0}\\  
& = \  a^xb^ya^{\alpha_1}b^{\beta_1}b^{-y}a^{-x}c^{\gamma_1}\label{eqn1}\\
& = \ a^xa^{\alpha_1}c^{\alpha_1y}b^yb^{\beta_1}b^{-y}a^{-x}c^{\gamma_1}\label{eqn2}\\
& = \ a^xa^{\alpha_1}c^{-\alpha_1y}b^{\beta_1}a^{-x}c^{\gamma_1}\label{eqn3}\\
& = \ a^xa^{\alpha_1}b^{\beta_1}a^{-x}c^{-\alpha_1y+\gamma_1}\label{eqn4}\\
& = \ a^xa^{\alpha_1}a^{-x}b^{\beta_1}c^{-\alpha_1y-\beta_1x+\gamma_1}\label{eqn5}\\
& = \ a^{\alpha_1}b^{\beta_1}c^{-\alpha_1y-\beta_1x+\gamma_1}\label{eqn6},
\end{align}
\end{subequations}
   we see that  $w u  =  v w$ in $G_1$ if and only if $\alpha_1 = \alpha_2$, $\beta_1 = \beta_2$, and \begin{equation} \label{eq: y version}\alpha_1 y + \beta_1 x = \gamma_1 - \gamma_2.\end{equation} If $|\alpha_1|=0=|\beta_1|$, then $u=v$ and we are done; otherwise we have two cases. For the first case, if $|\alpha_1|=|\beta_1|\neq 0$, then $\alpha_1$ divides $\gamma_1-\gamma_2,$ so $x=0,y=(\gamma_1-\gamma_2)/\alpha_1$, satisfies~\eqref{eq: y version} and $|y|\leq 2n^2$. For the second case, suppose $ |\alpha_1|\neq |\beta_1|$. Since there is an automorphism of $G_1$ interchanging $a$ and $b$, we may assume without loss of generality that $|\alpha_1| > |\beta_1|\geq 0$. Let $y' = y +  \lfloor (\gamma_1 - \gamma_2)/\alpha_1 \rfloor$. Then \begin{equation} \label{eq: y' version} \alpha_1 y' + \beta_1 x = \gamma \end{equation} for some $\gamma$ satisfying $|\gamma| \leq |\alpha_1|$.  Equation \eqref{eq: y' version} has a solution $(x,y')$ with $|x|, |y'| \leq \max \set{|\alpha_1|, |\beta_1|}$  by a quantification of Bezout's identity which can be found in  e.g.\ \cite{BFRT-Diophantine, BrRi2, Kornhauser}. Therefore \eqref{eq: y version} has a solution $(x,y)$ with $$|x|  \leq \max \set{|\alpha_1|, |\beta_1|} \ \text{ and }  \ |y|  \leq \max \set{|\alpha_1|, |\beta_1|} + |(\gamma_1 - \gamma_2)/\alpha_1|.$$  Thus there exist $x$ and $y$ such that $a^xb^yub^{-y}a^{-x}=v$, $|x| \leq n$, and $|y| \leq 2n^2$.




The equality (\ref{eqn1}) holds using $|\gamma_1|(|x|+|y|)\leq Cn^4$ defining relations of the form $[a,c]=1$ and $[b,c]=1$, (\ref{eqn2}) using $|\alpha_1|^2|y| \leq 2n^4$ defining relations of the form $[a,b]c^{-1}=1$, and (\ref{eqn3}) holds freely. Also, (\ref{eqn4}) holds using $|\beta_1||x|^2 \leq n^3$ defining relations of the form $[b,c]=1$, (\ref{eqn5}) holds using $|x||\beta_1|^2 \leq n^3$ defining relations of the form $[a,b]c^{-1}=1$, and (\ref{eqn6}) holds freely. Summing  gives   $\Ann_{G_1}(n) \preceq n^4$, as desired.



    We now turn to proving that $\Ann_{G_1}(n) \succeq n^4$.  For $n \in \N$, let $u_n=b$ and $v_n=b[a^n,b^n]$. Then $|u_n|+|v_n| = 4n+2$   and $u_n$ and $v_n$ are conjugate in $G_1$: 
    \begin{equation} \label{un and uv conjugate}
    v_n   \ = \ a^{n^2}u_na^{-n^2}.
    \end{equation}



We will show that $\Ann(b,bc^{n^2}) \succeq n^4$. By applying  defining relations for $G_1$ approximately $n^3$ times, $v_n$ can be shown to equal $bc^{n^2}$ in $G_1$, so, via Lemma~\ref{Gluing van Kampen to annular diagram}, it will follow that    $\Ann(u_n,v_n) \succeq n^4$, which will prove that  $\Ann_{G_1}(n) \succeq n^4$.

  Let $\Omega$ be any annular diagram witnessing the conjugacy of $u_n$ and $v_n$, and let $\gamma$ be any path from the starting point of $u_n$ to the starting point of $v_n$ such that $\gamma$ crosses every non-contractible $a$-corridor precisely once. Let $w$ be the word along $\gamma$. By cutting $\Omega$ along $\gamma$, we obtain a van Kampen diagram $\Delta$ for $w b w^{-1} (bc^{n^2})^{-1}$ such that $\Area(\Delta)=\Area(\Omega)$.  Say that an $a$-corridor in $\Delta$ is \emph{positively} (resp.\ \emph{negatively}) \emph{oriented} and {vertical} if it connects an $a$ (resp.\ an $a^{-1}$) in the $w$-portion of $\partial \Delta$ to an $a^{-1}$ (resp.\ an $a$) in the $w^{-1}$-portion.         (There may also be $a$-corridors that connect an $a$ to an $a^{-1}$ that are both in the $w$-portion or are both in the $w^{-1}$-portion, and there may be $a$-corridors in $\Delta$ may form annuli.)       

In \cite{BRS}, it is shown that the exponent sum of the  $a$-letters in any word $w$ conjugating $b$ to $bc^{n^2}$  is precisely $n^2$. It follows that there are precisely $n^2$ more positively-oriented than negatively-oriented vertical corridors in $\Delta$.   


    There thus exist $n^2$ positively-oriented vertical $a$-corridors $Q_1,Q_2,\ldots,Q_{n^2}$, between any two of which, there are an equal number of positively-oriented and negatively-oriented  vertical $a$-corridors. Let $\beta_i$ and $\alpha_{i+1}$ be the words along the sides of $Q_i$, respectively, as shown in Figure~\ref{fig: Heisenberg_min_area_diagram}. Since $\gamma$ intersects each non-contractible $a$-corridor only once, the words $w_i$ between $Q_{i-1}$ and $Q_{i}$ along the top and bottom of $\Delta$ are the same for all $i$.




