For all $0 \leq i \leq n^2$, the exponent sum  of the $a^{\pm 1}$ in $w_i$ is $0$, so $w_i\in \langle b,c\rangle=\ZZ^2$. This group is abelian, and $\alpha_i$ is a word on $\{b,c\}$, so $w_i$ commutes with $\alpha_i$. Thus, $\beta_i=\alpha_{i-1}$, and proceeding inductively from $\alpha_1=b$ we see that $\alpha_i=\beta_{i-1}^a=bc^i$. Every word on $\{b,c\}$ equal to $bc^i$ has at least $i$ many $c$-letters, therefore $Q_i$ at least $i$ many cells. So $Q_1,\ldots,Q_{n^2}$ have total area at least $1 + 2 + \cdots + (n^2-1) + n^2 = n^2(n^2+1)/2$, giving the desired quartic lower bound.
\end{proof}











\section{Computations of $\Area_{G_4}(n)$, $\CL_{G_4}(n)$, and $\Ann_{G_4}(n)$}\label{graphofgroups_BS12_and_heisenberg}


We begin with a lemma describing the structure of $G_4$.  



\begin{lemma}\label{structureG4}  
The group   $$G_4 \ = \ \langle a,b,c,d,s\mid [a,b]c^{-1}, [a,c], [b,c], [b,d], s^a s^{-2}, s^d   s^{-2} \rangle$$
is a free product with amalgamation $A *_C B$ of its subgroups  $A=\langle a,b,c,d\rangle$ and $B=\langle a,d,s\rangle$ along the subgroup $C=\langle a,d\rangle$.  It is also an HNN-extension of $$E   \ = \   \langle a, c,d,s \mid  [a,c],  s^a s^{-2}, s^d   s^{-2} \rangle$$  with stable letter $b$ and an HNN-extension of  $$\langle a,b,c,s\mid [a,b]c^{-1}, [a,c], [b,c],  s^a s^{-2}  \rangle$$ with stable letter $d$.  Moreover, 
    \begin{enumerate}
        \item \label{A subgroup property} $A = \langle a,b,c,d \mid [a,b]c^{-1}, [a,c], [b,c], [b,d]  \rangle$  is the HNN-extension of $K =  \langle a, c,d  \mid   [a,c]   \rangle \cong \ZZ^2 * \ZZ$ with stable letter $b$ acting via the automorphism of $K$ that maps  $a \mapsto c^{-1}a$,  $c \mapsto c$, and $d \mapsto d$;
        \item  \label{B subgroup property} $B = \langle a, d,s\mid  s^a s^{-2}, s^d   s^{-2} \rangle$, the amalgamated free product of two copies of $\BS(1,2)$, denoted $D_1=\langle a,s\mid s^a=s^2\rangle$ and $D_2=\langle d,s\mid s^d=s^2\rangle$, along   $\langle s \rangle \cong \Z$.
           \item \label{C subgroup property} $C = \langle a, d \mid \ \rangle$ is free of rank 2.
        \item \label{Heisenberg retract} Killing $d$ and $s$ retracts $G_4$ onto a subgroup $\langle a ,b,c\mid [a,c], [b,c], [a,b]c^{-1} \rangle$, which is the Heisenberg group.
          \item \label{BS retract} Killing $b$ and $c$ and mapping $d \mapsto a$ retracts $G_4$ onto its subgroup $D_1 = \langle a, s \mid  s^as^{-2} \rangle$.
        \item \label{L property} The subgroup $L=\langle b,c,s\rangle$ is $\ZZ^2 \ast \ZZ =\langle b,c,s \mid [b,c] \rangle$.      
    \end{enumerate}
\end{lemma}



\begin{proof}
Killing $s$ retracts $G_4$ onto $A$, which therefore has the presentation claimed in \eqref{A subgroup property}, and the remaining claims of  \eqref{A subgroup property} then follow, as does the claim that $G_4$ is an HNN-extension with stable letter $b$.   Similarly killing $b$ and $c$ retracts $G_4$ onto $B$ so as to give  \eqref{B subgroup property}.  That $G_4 =  A *_C B$ follows from \eqref{A subgroup property} and \eqref{B subgroup property}.  Killing $b$ and $c$ retracts $A$ onto $C = \langle a, d \mid \ \rangle$, giving \eqref{C subgroup property}.  That $G_4\cong A *_C B$ follows.  Claims \eqref{Heisenberg retract} and \eqref{BS retract} are straight-forwardly verified.  
Claim \eqref{L property} holds on account of a free-product-with-amalgamation normal form for $A *_C B$, given that  $[b,c]=1$ in $G_4$ and  $\langle b,c \rangle \cap C = \langle s \rangle \cap C = \set{1}$.     It follows  that $b$ and $s$ generate a free subgroup and mapping $b \mapsto b$ and $s \mapsto s^2$ defines an isomorphism between rank-2 free subgroups of $G_4$, and so $G_4$ an HNN-extension with stable letter $d$.  
\end{proof}




\begin{cor}\label{G4Cor} ${}$ 
\vspace*{-2mm}
\begin{enumerate}
    \item\label{ABUndistorted} $A$ and $B$ are undistorted in $G_4$.
    \item\label{conjInA} If $x,y\in A$ are conjugate in $G_4$, then they are conjugate in $A$.
    \item \label{conjInB} If $x,y\in B$ are conjugate in $G_4$, then they are conjugate in $B$.
\end{enumerate}
\end{cor}

\begin{proof}
These properties are consequences of   $A$ and $B$ being  retracts of $G_4$.
\end{proof}





\begin{cor}\label{cor_base}
 $2^n\preceq\Area_{G_4}(n)$ and  $n^2\preceq \CL_{G_4}(n)$.
\end{cor}
\begin{proof}
    We  noted that $2^n\preceq \Area_{\BS(1,2)}(n)$  and $ n^2 \preceq\CL_{\mathcal{H}_3(\ZZ)}(n)$  in Section~\ref{Proof of main thm}.  By \eqref{BS retract} and  \eqref{Heisenberg retract}, respectively, of  Lemma~\ref{structureG4}, $D_1 \cong \BS(1,2)$ and $\mathcal{H}_3(\ZZ)$ are retracts of $G_4$.  The claimed   bounds follow.
\end{proof}




  Next we will prove that $\Area_{G_4}(n) \preceq 2^n$ by means of the following three lemmas.  We write $\text{exp}_x(u)$ for the exponent sum of the letters $x$ in a word $u$, and $|u|_x$ for the number of letters $x^{\pm 1}$.     


\begin{lemma} \label{length detail} If $g \in \langle a ,c,d \rangle \leq G_4$ and $|g|_{G_4} =n$, then there is a word $\sigma$ on $a,c,d$ such that $g=\sigma$ in $G_4$, $| \sigma |_a + | \sigma |_d  \leq n$, and  $| \sigma |_c  \leq 3 n^2$.  
\end{lemma}

\begin{proof}
  Let $\tau$ be a minimal length word on $a, b,c,d$ representing $g$.  Then $|\tau|=n$, because $g \in A$ and killing $s$ retracts $G_4$ onto $A$.

 The subgroup $\langle a ,c,d \rangle$ is  $\Z^2 \ast \Z$ with $a$ and $c$ generating the $\Z^2$-factor and $d$ the $\Z$-factor.  Since $g\in \langle a,c,d\rangle$, there exists a representative word $\sigma$ of $g$ of the form $\sigma = \sigma_0 d^{\delta_1} \sigma_1 \cdots  d^{\delta_m} \sigma_m$ where  $\delta_i \neq 0$ and $\sigma_i = a^{\alpha_i} c^{\gamma_i}$ for $i=0,\ldots, m$, and  $\sigma_j \neq 1$ for $j=1,\ldots, m-1$.  Since $\sigma=\tau$ in $A$, there exists a reduced van~Kampen diagram $\Delta$ for $\sigma \tau^{-1}$ over $A$. 

 We claim that there is no  $a$- or $d$-corridor connecting an $a$ to an $a^{-1}$ or a $d$ to a $d^{-1}$ in $\sigma$. Suppose, for a contradiction, that there is such a corridor $Q$.  Let  $\sigma'$ be the subword of $\sigma$ whose first and last letters label the edges at the ends of $Q$.  Then $Q$ bounds a subdiagram $\Delta'$ of $\Delta$. No $a$-corridor can cross a $d$-corridor, so there is an \emph{innermost} such $Q$---that is, a $Q$ such that no  $a$- or $d$-corridors connects an $a$ to an $a^{-1}$ or a $d$ to a  $d^{-1}$ in $\sigma'$. The first and last edges of $Q$ cannot be contained in the same subword $\sigma_i$, nor in the same subword $d^{\delta_i}$, since $\sigma_i$ and $d^{\delta_i}$  are both freely reduced. So, if $Q$ is an $a$-corridor, then $\sigma'$ contains at least one $d$-letter, and if $Q$ is a $d$-corridor then $\sigma'$ contains at least one $a$-letter. This $a$- or $d$-letter in $\sigma'$ must be part of an $a$- or $d$-corridor $Q'$. However $Q'$ can neither cross $Q$ nor connect two letters of $\sigma'$. This contradiction proves our claim. 
 Thus, every $a$ or $d$ in $\sigma$ is connected to an  $a$ or $d$ in $\tau$ by an $a$- or $d$-corridor in $\Delta$.    So $| \sigma |_a + | \sigma |_d  \leq n$. 






