 Per Figure~\ref{fig:acd diagram}, for $i=1,\ldots, m-1$, let $\Delta_i$ be the subdiagram of $\Delta$   between the pair of $d$-corridors starting at the last letter of $d^{\delta_{i}}$ and the first letter of $d^{\delta_{i+1}}$. Let $\Delta_0$ be the subdiagram to the left of  
the $d$-corridor starting at the first $d$-letter of $d^{\delta_1}$ and let $\Delta_m$ be that 
to the right of the $d$-corridor starting at the last $d$-letter of $d^{\delta_m}$.   
Thereby, $\sigma = \sigma_0  d^{\delta_{1}} \sigma_1   \cdots  d^{\delta_{m}} \sigma_m$ and  $\tau = \tau_0 \mu_1 \tau_1   \cdots  \mu_m \tau_m $ (as words) so that   $\Delta_i$ is a subdiagram for $b^{\ell_{i}} \sigma_i  b^{-r_{i}}  \tau_i^{-1}$ where the $b^{\ell_i}$ and $b^{r_i}$ are words along the sides of $d$-corridors, as shown, and $\ell_0=r_m=0$. 


Now, for all $i$, as witnessed by the subdiagram of $\Delta$ to the left of the path labelled by $b^{\ell_i}$, we have that $b^{\ell_i} = \hat{\tau}_i^{-1}\hat{\sigma}_i$ and $b^{r_i} = \bar{\tau}_i^{-1}\bar{\sigma}_i$ in $G_4$ for some  prefixes  $\hat{\sigma}_i$ and $\hat{\tau}_i$ and suffixes    $\bar{\sigma}_i$ and $\bar{\tau}_i$  of $\sigma$ and $\tau$, respectively.    So mapping $A \onto \langle b \rangle = \Z$ by killing $a,c,d$ gives that
$|\ell_i|+|r_i| \leq n$.   



 Let $\overline{\tau_i}$ be $\tau_i$ with all $d$-letters removed.
Because  $\sigma_i   = b^{\ell_{i}}  \tau_i b^{-r_{i}}$ in $G_4$, we learn  from Lemma~\ref{structureG4}\eqref{Heisenberg retract} that $\sigma_i   = b^{\ell_{i}}  \overline{\tau_i} b^{-r_{i}}$  in $\mathcal{H}_3(\ZZ)$.
 Therefore $$|\sigma_i| \ \leq \ |\tau_i|_c +  \abs{\text{exp}_a ( \overline{\tau_i})}  \,  \abs{\text{exp}_b (b^{\ell_i} \overline{\tau_i}  b^{-r_{i}})}.$$ The result follows.
\end{proof}


\begin{lemma} \label{no b-rings}
Every word $w$ representing the identity $G_4$ admits a reduced van~Kampen diagram with no $b$-rings. Further, every pair of words representing conjugate $G_4$ admits a reduced annular diagram with no contractible $b$- or $d$-rings. 
\end{lemma}




\begin{proof}
Given that $G_4$ is, by Lemma~\ref{structureG4}, an HNN-extension with stable letter $b$ and an HNN-extension with stable letter $d$, this claim then follows results in \cite{BRS} explaining how contractible $b$- or $d$-rings can be eliminated.
\end{proof}



\begin{lemma} \label{area detail in E}
If $u=1$ in  $E   =   \langle a, c,d,s \mid  [a,c],  s^a s^{-2}, s^d   s^{-2} \rangle$, then  $$\Area_E(u) \leq (|u|_c + |u|_s) 2^{( |u|_a + |u|_d )}.$$  
\end{lemma}

\begin{proof}

Let $E_0=\langle c,s\mid\rangle$,   let $\varphi_a$ be the monomorphism $E_0\hookrightarrow E_0$ given by $c\mapsto c, s\mapsto s^2$, and let $\varphi_d$ be the monomorphism $\langle s\rangle_{E_0}$ given by $s\mapsto s^2$. Then $E$ is the multiple HNN-extension of $E_0$ along $\varphi_a$ and $\varphi_d$ with stable letters $a$ and $d$, respectively. Our claim now follows from Britton's lemma, observing that $\varphi_a$ and $\varphi_d$ increase the length of a word by at most a factor of 2, that, for $e\in \{a,d\}$, $x\in E_0$, a subword of $u$ of the form $e^{\pm1}\varphi_e^{\mp1}(x)e^{\pm1}$ requires $\abs{\varphi_e^{\mp1}(x)}$ relations to transform into the word $x$, and that this transformation strictly decreases the number of $a$- or $d$-letters in $u$.
\end{proof}


\begin{lemma}\label{area detail A} If $u=1$ in $A$, then $\Area_A(u)\leq \lambda|u|^3$ for some constant $\lambda>0$.
\end{lemma}
\begin{proof}
    This follows immediately from \cite[Lemma III.$\Gamma$.6.20]{BrH}, the Dehn function for $\mathcal{H}_{3}(\Z)$, and the fact that $A$ is a trivial HNN-extension of $\mathcal{H}_{3}(\Z)$ with stable letter $d$ along the undistorted subgroup $\langle b\rangle_{A}$.
\end{proof}

\begin{prop} \label{Dehn exp upper bound G4}
$\Area_{G_4}(n) \preceq 2^n$
\end{prop}


\begin{proof}
Suppose $w$ is a word of length $n$ representing $1$ in $G_4$.  By Lemma~\ref{no b-rings}, $w$ admits a reduced van~Kampen diagram $\Delta$ in which there are no $b$-rings. 


Consider a $b$-corridor $\beta$ in $\Delta$. If $w_1$ is the subword of $w$ along the portion of $\partial \Delta$ between the first and last $b$-edges of $\beta$ (inclusive), then $w_1$ represents an element of $\langle a,c,d\rangle_{G_4}$ and so, by Lemma~\ref{length detail}, there exists a word $w_2$ on $\{a,c,d\}$ that equals $w_1$ in $G_4$ and has   $|w_2|_a + |w_2|_d  \leq |w_1|$ and $|w_2|_c  \leq 3|w_1|^2$. So $|w_2| \leq 4|w_1|^2$.  Then, per Lemma~\ref{area detail A}, $$\Area(w_2 w_1^{-1})  \ \leq \ \lambda |w_1 w_2^{-1}|^3 \  \leq  \  \lambda(|w_1|+|w_2|)^3 \  \leq \ \lambda ( |w_1| + 4|w_1|^2)^3 \  \leq  \ 5^3 \lambda |w_1|^6.$$



There is a family  of disjoint subwords  in $w$ of the form of $w_1$ described above that together include all the $b$-letters in $w$. After replacing each one with its corresponding $w_2$, we get a word $w'$ on $a$, $c$, $d$, and $s$ such that $w = w'$ in $G_4$,  $|w'|_a + |w'|_d + |w'|_s  \leq n$,  $|w'|_c  \leq 3 n^2$, and $\Area_{G_4}(w'  w ^{-1}) \leq 5^3 \lambda n^6$.       

Because $w'$ contains no $b$-letters, it represents $1$ in  $E$ (by Lemma~\ref{structureG4}).  So  Lemma~\ref{area detail A} applies and tells us that  $\Area_E(w') \leq (3 n^2 + n) 2^n$. 
But  $\Area_{G_4}(w') \leq \Area_E(w')$ and, by Lemma~\ref{triangle ineq for A},  $\Area_{G_4}(w) \leq \Area_{G_4}(w'  w^{-1})  + \Area_{G_4}(w')$.  The result follows.  
\end{proof}




\begin{lemma} \label{Aquadratic}  $\CL_A(n) \preceq n^2$ for $A = \langle a,b,c,d \mid [a,b]c^{-1}, [a,c], [b,c], [b,d]  \rangle$.
\end{lemma}



\begin{proof} 
Recall that we denote  the Heisenberg group $\langle a,b,c  \mid [a,b]c^{-1}, [a,c], [b,c]  \rangle$ by $G_1$.  The group $A$ is an HNN-extension of $G_1$ with stable letter $d$.  Let   $\psi:A \to G_1$ be  the surjection   killing $d$.   

Let $u$ and $v$ be words on $\set{a,b,c,d}$ which represent conjugate elements of $A$, and let $n=|u|+|v|$. Let $\Omega$ be a reduced annular diagram witnessing $u\sim v$ in $A$.  We have two cases. 


Suppose first that there are no radial $d$-corridors in $\Omega$. 
Then $u = \psi(u)$ and $v = \psi(v)$ in $A$ and the result then  follows in this case from the fact that $\CL_{G_1}(n)\preceq n^2$ and the fact that $|\psi(u)|+|\psi(v)|\leq |u|+|v|$. 



Suppose, on the other hand, that $\Omega$ has $m \geq 1$ radial $d$-corridors.
Then, after replacing $u$ and $v$ with cyclic conjugates,  we can express them as concatenations of subwords $$\begin{array}{rl} u  & \!\!\! = \   d^{\epsilon_1} u_1 \cdots d^{\epsilon_m} u_m \\ v &  \!\!\! = \    d^{\epsilon_1} v_1 \cdots d^{\epsilon_m} v_m \end{array}$$ where, for all $i$, $\epsilon_i = \pm 1$ and the edge labelled by the $d^{\epsilon_i}$ in  $u$ is joined by a radial $d$-corridor to the edge labelled by the $d^{\epsilon_i}$ in $v$. 



Every element of $G_1$ can be expressed uniquely as  $a^{\alpha}b^{\beta}c^{\gamma}$ for some $\alpha, \beta, \gamma \in \Z$.  Let $\bar{u}_i = a^{\alpha_i}b^{\beta_i}c^{\gamma_i}$ and $\bar{v}_i = a^{\alpha'_i}b^{\beta'_i}c^{\gamma'_i}$ be the normal forms of $\psi(u_i)$ and $\psi(v_i)$.  


For all $i$, any $d$-corridor in $\Omega$ emanating from a letter $d^{\pm 1}$ in $u_i$ (or $v_i$) must be a $d$-arch ending at some letter $d^{\mp 1}$ in $u_i$ (or $v_i$). So $\psi(u_i) = u_i$ and $\psi(v_i) = v_i$ in $A$, and therefore  
\begin{equation}
u_i  \ = \  \bar{u}_i \ \text{ and }  \ v_i  \ = \  \bar{v}_i  \ \text{ in } \  A \label{uuinA}
\end{equation}
for all $i$.  A word on $\set{a,b,c}$ can be converted to its $G_1$-normal form by shuffling letters,  with the proviso that interchanging an $a$ and $b$ introduces a $c^{\pm 1}$.   So, because   $\bar{u}_i$ and $\bar{v}_i$ can be obtained from $u_i$ and $v_i$ by deleting their $d$-letters and shuffling letters in this manner, 
\begin{equation}
\sum_{i=1}^m \left( |\alpha_i| + |\beta_i| + |\alpha_i'| + |\beta_i'| \right) \leq n  \  \text{ and } \   \sum_{i=1}^m \left( |\gamma|+|\gamma'| \right) \leq n^2. \label{sizes of exponents}
\end{equation}

Let $b^{k_i}$ be the word read along the sides of the $i$-th radial $d$-corridor in $\Omega$ so that 
\begin{equation} \label{bu=vb}
b^{k_i} u_i \ = \  v_i b^{k_{i+1}}
\end{equation}
in $A$ for all $i$ (subscripts modulo $m$). Now, \eqref{uuinA} and \eqref{bu=vb} imply that       
\begin{flalign} \label{bu=vb in H3}
b^{k_i} \ a^{\alpha_i}b^{\beta_i}c^{\gamma_i} \ = \  a^{\alpha'_i}b^{\beta'_i}c^{\gamma'_i} \ b^{k_{i+1}} 
\end{flalign}
in $A$, and therefore in $G_1$.  
The normal forms of left and right sides of \eqref{bu=vb in H3} are $a^{\alpha_i} b^{\beta_i+ k_i}c^{\gamma_i - \alpha_i k_i}$ and  $a^{\alpha'_i}b^{\beta'_i + k_{i+1}}c^{\gamma'_i}$, respectively.  So, for all $i$ (subscripts modulo $m$),
\begin{flalign}  
\alpha_i & = \alpha'_i,  \label{alphas}  \\ 
\beta_i+ k_i & = \beta'_i + k_{i+1}, \\ 
\gamma_i - \alpha_i k_i  & = \   \gamma'_i.   \label{gamma eqn}
\end{flalign}

Suppose $\alpha_i \neq 0$ for some $i$.  Then \eqref{gamma eqn} gives $k_i = (\gamma_i'-\gamma_i)/ \alpha_i$, whence $|k_i| \leq |\gamma_i'| + |\gamma_i| \leq n^2$, which proves the result in this case because $b^{k_i}$ conjugates a cyclic conjugate of $u$ to  a cyclic conjugate of $v$.    

Suppose, on the other hand, that $\alpha_i = 0$ for all $i$.   Then  $\alpha'_i=0$ for all $i$ by \eqref{alphas}. 
Define
 $$\begin{array}{rl} \bar{u}  & \!\!\! = \   d^{\epsilon_1} \bar{u}_1 \cdots d^{\epsilon_m} \bar{u}_m \\ \bar{v} &  \!\!\! = \    d^{\epsilon_1} \bar{v}_1 \cdots d^{\epsilon_m} \bar{v}_m. \end{array}$$ 
 Then  $u = \bar{u}$ and $v = \bar{v}$ in $A$ by \eqref{uuinA}. 


Let $M = \langle b,c,d \mid  [b,c], [b,d]  \rangle$.  Mapping $b \mapsto cb$ and $c \mapsto c$ defines an automorphism of the subgroup $\Z^2 = \langle b, c \rangle$ of $M$. Thereby, $A$ is an HNN-extension of $M$ with stable letter $a$.  Because there are no $a$-letters in $\bar{u}$ and $\bar{v}$, they are conjugate in $M$.  The  conjugator length function of $M$ is linear per  Servatius' solution to the conjugacy problem for RAAGs in \cite{Servatius}.  The required bound then follows: for some constant $C >0$, $$\CL_A(u,v)  \ \leq  \ \CL_M(\bar{u},\bar{v}) \ \leq  \  C \left( |\bar{u}| + |\bar{v}| \right)  \ \leq  \  C (n+ n^2),$$ with the final inequality following from  \eqref{sizes of exponents}.        
\end{proof}


\begin{lemma} \label{Blinear}
$\CL_B(n) \preceq n$ for  $B = \langle a, d,s\mid  a s a^{-1} = s^{2}, d s d^{-1} =   s^{2} \rangle$.
\end{lemma}



          \begin{proof}
Suppose $g$ and $h$ are conjugate elements of $B$.  
  Let $u_0$ and $v_0$ be minimal length words  representing $g$ and $h$, respectively, let  $n := |u_0|+|v_0|$, and let $\Delta$ be an  annular van~Kampen diagram for the pair $u_0$ and $v_0$.        

\emph{Case: $\Delta$ has no radial $a$- or $d$-corridors.}  In this event, all the $a$- or $d$-corridors originating at a boundary component must be arches of $\Delta$. Indeed, we claim that there exist some cyclic conjugates $u_1$ and $v_1$ of $u_0$ and $v_0$ equal to $s^{k}$ and $s^{\ell}$, respectively,  for some integers $k$, $\ell$ such that $|k|+|\ell| \leq 2^n$. To see this, take $u_1$ and $v_1$ to be the cyclic conjugates of $u_0$ and $v_0$ such that there exists a simple path in the 1-skeleton of $\Delta$ from the initial vertex of $u_1$ to the initial vertex of $v_1$ which crosses no $a$- or $d$-arch. Then $u_1$ and $v_1$ can be converted to $s^{k}$ and $s^{\ell}$, respectively, by eliminating all \emph{pinches}: that is, if $u_1$ or $v_1$ contains a subword of the form $a s^{i} a^{-1}$, $d s^{i} d^{-1}$, $a^{-1} s^{2i} a$, or $d^{-1} s^{2i} d$, where $i \in \Z$, then replace it with $s^{2i}$, $s^{2i}$, $s^{i}$, or, $s^{i}$, respectively.  Arches in $\Delta$ correspond to pinches in cyclic conjugates of $u_0$ and $v_0$, and our choices of $u_1$ and $v_1$ guarantee that they contain all such pinches. Therefore, we may exhaustively freely reduce and make such substitutions until no such subwords remain. In particular, every $a$- or $d$-letter will be removed from $u_1$ and $v_1$, so the result will be powers $s^{k},s^{\ell}$ of $s$; respectively. Moreover, since at most $n$ pinches are present in $u_1$ and $v_1$, and every substitution at most doubles the total number of $s$-letters on both boundary components, so $|k|+|\ell|\leq 2^n$ as desired.


But then there exists a  word $w$ such that  $w s^{k} w^{-1} = s^{\ell}$ in $B$. So $w s^{k} w^{-1}$ can be converted to $s^{\ell}$ by successively eliminating pinches, and therefore    $s^{\ell} =  s^{2^r k} = a^{r} s^k a^{-r}$  for $r = \exp_a(w) + \exp_d(w)$.  So $\ell = 2^r k$ and $r \preceq n$, which implies $\CL(u, v) \preceq n$.     




\emph{Case: there is a radial $a$- or $d$-corridor in $\Delta$.}   Take cyclic conjugates $u_1$ and $v_1$ of  $u_0$ and $v_0$, respectively,  beginning at the same radial $a$- or $d$-corridor $Q$.  Then $u_1 = \alpha_1 e_1 \cdots \alpha_m e_m$ and $v_1 = \beta_1 f_1 \cdots \beta_m f_m$ for some number $m \in \N$, some letters $e_1, \ldots, e_m, f_1, \ldots, f_m \in \set{a^{\pm 1},d^{\pm 1}}$, and some words $\alpha_1, \ldots, \alpha_m, \beta_1, \ldots, \beta_m$ on $a,d,s$.  The power of $s$ read along one side of $Q$ conjugates $u_1$ to $v_1$ in $B$.  Furthermore, for all $i$, a radial corridor connects the edge labelled by $e_i$ in $u_1$ to that labelled by $f_i$ in $v_1$, and each $\alpha_i$ and $\beta_i$ can be converted to a power of $s$ by eliminating pinches.  Accordingly, $u_1$ and $v_1$ are equal in $B$ to words $u = s^{\chi_1} e_1 \cdots s^{\chi_m} e_m$ and $v = s^{\xi_1} e_1 \cdots s^{\xi_m} e_m$, respectively, for some $\chi_1, \ldots, \chi_m, \xi_1, \ldots, \xi_m \in \Z$ such that $|u| + |v| = 2^n$. So $u_1 s^k v_1^{-1}  = u s^k v^{-1}  = s^k$ in $B$ for some $k \in \Z$.    Let $\mu = \exp_a(u) + \exp_d(u)$.  

\emph{Subcase: $\mu =0$.} By a propitious choice of which radial $a$- or $d$-corridor to read $u_1$ and $v_1$ from, we may assume that every suffix $\hat{u}$ of $u$ has the property that $\exp_a(\hat{u}) + \exp_d(\hat{u}) \geq 0$. This ensures that $u s u^{-1}$ can be converted to a power of $s$ by replacing the pinch between $e_m$ in $u$ and $e_m^{-1}$ in $u^{-1}$ by a power of $s$, then likewise replacing the pinch between $e_{m-1}$  and $e_{m-1}^{-1}$, and so on.  Indeed, we get $u s u^{-1} =s$.  And then, given that $u s^k v^{-1}  = s^k$, we deduce that $u=v$ in $B$. This implies $\CL(g,h) \preceq n$, as desired.   


\emph{Subcase: $\mu  \neq 0$.}  Then no non-zero power of $s$ commutes with $u$ and so the $k \in \Z$ such that  $u s^k v^{-1}  = s^k$ is unique.  For $i=1, \ldots, m$ let $\mu_i$ be the exponent sum of $e_1 \cdots e_{i-1}$.  The existence of the diagram $\Delta$  implies that  $$u s^k v^{-1} \ = \ s^{\chi_1} e_1 \cdots s^{\chi_m} e_m  \ s^k \  e_m^{-1} s^{-\xi_m} \cdots e_1^{-1} s^{-\xi_1}$$ can be converted to $s^k$ by eliminating the pinch bookended by $e_m$ and $e_m^{-1}$, then eliminating that  bookended by $e_{m-1}$ and $e_{m-1}^{-1}$, and so on.  Doing so, we calculate that $$k \ = \  2^\mu k  + \sum_{i=1}^m 2^{\mu_i}( \chi_i - \xi_i).$$ 
Now $|\mu|, |\mu_i| \leq |n|$ for all $i$ and $\sum_{i=1}^m ( |\chi_i| + |\xi_i|) \leq 2^n$, and so $k = \frac{1}{1-2^{\mu}} \sum_{i=1}^m 2^{\mu_i}( \chi_i - \xi_i)  \preceq 2^n$.  Therefore $|s^k|_B \preceq n$, from which we deduce that $\CL(g,h)  \preceq n$.           
\end{proof}




\begin{lemma} \label{CL of E}
$\CL_E(n) \preceq n$ for
 $E   =   \langle a, c,d,s \mid  [a,c],  s^a s^{-2}, s^d   s^{-2} \rangle$.  
\end{lemma}

\begin{proof}
Suppose $u$ and $v$ are words representing conjugate elements of $E$ and that $\Delta$ is a reduced annular diagram for $u$ and $v$.  If there are no radial $c$-corridors in $\Delta$ then, perhaps after replacing $u$ and $v$ by cyclic conjugates, $u,v\in B$. Also, since the only relation involving $c$ is $[a,c]=1$, we see $|u|_B+|v|_B=|u|_E+|v|_E\leq n$. Thus $\CL(u,v)\leq \CL_B(n)$, which is linear by Lemma~\ref{Blinear}.  If there is at least one radial $c$-corridor, then the word $\tau$ along its sides is a reduced power of $a$, any canceling pair $a^{\pm1}a^{\mp1}$ would have to lie on the boundary of two cancelling cells. Up to cyclic conjugation, $u$ is therefore conjugated to $v$ by a power $\tau=a^p$ of $a$ for some $p\in \ZZ$.  If there is a radial $d$-corridor in $\Delta$, then every letter in $\tau$ is connected to a different  $a$-letter in the boundary words $u$ or $v$  by an $a$-corridor, since they cannot cross the $d$-corridor nor, because $\tau$ is reduced, return to cross the $c$-corridor. So $|\tau| \leq |u| + |v|$.  If there are no radial $d$-corridors in $\Delta$, then by excising the $d$-arches of $\Delta$ we may replace $u,v$ with $u',v'$ such that $u',v'$ contain no $d$-letters, $u'=u,v'=v$ in $E$, $|u'|+|v'|\leq 2^{n}$, and $|u'|_a+|v'|_a\leq n$. Moving each instance of $a$ in $u'$ and $v'$ to the right and each instance of $a^{-1}$, we have $u'=a^{-k_1}w_1(c,s)a^{\ell_1},v'=a^{-k_2}w_2(c,s)a^{\ell_2}$, for some $k_1,k_2,\ell_1,\ell_2\in\Naturals$ and words $w_1,w_2$ on $c$ and $s$ such that $|w_1|+|w_2|\leq 2^{2n}$. Conjugating $u'$ and $v'$ by $a^{\ell_1}$ and $a^{\ell_2}$ respectively, we obtain the words $u''=a^{-k_1+\ell_1}w_1,v''=a^{-k_2+\ell_2}w_2$, which are also conjugate by a power $a^{p-\ell_1+\ell_2}$ of $a$. Since $|-\ell_1+\ell_2|\leq |u'|_a+|v'|_a\leq n$ and $\CL(u,v)\leq p$, to show $\CL(u,v)\preceq n$ it suffices to find a linear bound for $p'=p-\ell_1+\ell_2$. Indeed, since $E$ is an HNN-extension with stable letter $a$ (see Lemma \ref{area detail in E}), we must have $-k_1+\ell_1=-k_2+\ell_2$, so $a^{p'}w_1a^{-p'}=w_2$. Applying to this equation the retraction $E\onto B$ given by killing $c$, we have $a^{p'}s^{q_1}a^{-p'}=s^{q_2}$ in $B$, where $|q_1|+|q_2|\leq |w_1|+|w_2|\leq 2^{2n}$. This gives $|p'|=\log_2\left(\abs{q_1-q_2}\right)\leq 2n$, and we are done.
\end{proof} 

Per Lemma~\ref{structureG4}\eqref{L property}, the subgroup $L=\langle b,c,s\rangle$ of $G_4$ is $\ZZ^2 \ast \ZZ =\langle b,c,s \mid [b,c] \rangle$.  The following lemma 
provides quantitative details of the normal form for elements $L$: 
\begin{equation} 
u  \ = \ b^{\beta_0} c^{\gamma_0} s^{\mu_1} b^{\beta_1} c^{\gamma_1} \cdots s^{\mu_{k}} b^{\beta_{k}} c^{\gamma_{k}}, \label{L normal form}
\end{equation}
where  $\mu_1, \ldots, \mu_{k}$ are non-zero and none of $b^{\beta_1} c^{\gamma_1}, \ldots, b^{\beta_{k -1}} c^{\gamma_{k -1}}$ are the identity in $\Z^2$. 

\begin{lemma} \label{length detail for L} If  $u$ of \eqref{L normal form} equals in $G_4$ a word  $v$ on $\set{a^{\pm 1}, b^{\pm 1}, c^{\pm 1}, d^{\pm 1}, s^{\pm 1}}$, then  $| \beta_0 | + \cdots + | \beta_k | \leq |v|$, $| \gamma_0| + \cdots + | \gamma_k |  \leq |v|^2$ and  $| \mu_1 | + \cdots + | \mu_k |  \leq 2^{|v|}$.  
\end{lemma}




\begin{proof}
We proceed by induction on $|v|$. The base case of $|v|=1$ is trivial. For the inductive step, we have by Britton's Lemma that $$v=\alpha_1e_1\beta_1e_1^{-1}\alpha_2\cdots \alpha_me_m\beta_me_m^{-1}\alpha_{m+1},$$ where $\alpha_i$ is a word on $\{b,c,s\}$, $e_i\in \{a^{\pm1},d^{\pm1}\}$, and  $\beta_i$ is a word representing:\begin{itemize} \item  an element of $\langle b,c,s\rangle_{G_4}$ if $e_i=a$, \item an element of $\langle b,c,s^2\rangle_{G_4}$ if $e_i=a^{-1}$, \item an element of $\langle b,s\rangle_{G_4}$ if $e_i=d$, or\item an element of $\langle b,s^2\rangle_{G_4}$ if $e_i=d^{-1}$\end{itemize} for all $i$. In any of these cases, the inductive hypothesis gives that $\beta_i$ is equal to a word on $\{b,c,s\}$ with $|\beta_i|$ many $b$-letters, $|\beta_i|^2$ many $c$-letters, and $2^{|\beta_i|}$ many $s$-letters. Conjugating by $e_i$ adds at most $|\beta_i|$ many $c$-letters and $2^{|\beta_i|}$ many $s$-letters, so $e_1\beta_1e_1^{-1}$ can be written as a word on $\{b,c,s\}$ with $|\beta_i|$ many $b$-letters, $|\beta_i|^2+|\beta_i|\leq (|\beta_i|+1)^2\leq |e_1\beta_1e_1^{-1}|^2$ many $c$-letters, and $2^{|\beta_i|+1}\leq 2^{|e_1\beta_1e_1^{-1}|}$ many $s$-letters. The claim then follows by the total number of each letter and by the structure of $L$.  \end{proof}

Our next lemma  concerns manipulations of  words in the  normal form \eqref{L normal form}.  


\begin{lemma} \label{block}
Suppose $z = f_m f_{m-1} \cdots f_1$ is a reduced word where  $f_1, \ldots, f_m \in \set{a^{\pm 1}, d^{\pm 1}}$.  Suppose that $u_0, \ldots, u_m$ are words  in the  normal form \eqref{L normal form} and that 
\begin{equation} \label{normal form of u_0}  
u_0  \ = \ b^{\beta_0} c^{\gamma_0} s^{\mu_1} b^{\beta_1} c^{\gamma_1} \cdots s^{\mu_{k}} b^{\beta_{k}} c^{\gamma_{k}}. 
\end{equation} 
Assume that  $u_i = f_i u_{i-1} f_i^{-1}$ in $G_4$ for $i=1, \ldots, m$ and that some (and so every) $u_i$ is not an element of $\langle s \rangle$.  
Then 
\begin{itemize}
\item either $z = a^{\lambda}$ (as words) for some $\lambda \in \Z$ such that $m = |\lambda|$ and   
$$\begin{array}{rl} 
u_m   & \!\! = \ b^{\beta_0} c^{\gamma_0 + \lambda \beta_0} s^{2^{\lambda} \mu_1} b^{\beta_1} c^{\gamma_1 + \lambda \beta_1} \cdots s^{2^{\lambda} \mu_{k}} b^{\beta_{k}} c^{\gamma_k + \lambda \beta_k},
\end{array}$$
\item or  $z= a^{\lambda_2}d^{\xi} a^{\lambda_1}$ (as words) for some $\lambda_1, \xi, \lambda_2 \in \Z$ such that $m = |\lambda_1|+ |\xi| + |\lambda_2|$ and
$$\begin{array}{rl} 
u_{|\lambda_1|}   & \!\! = \ b^{\beta_0}   s^{2^{\lambda_1} \mu_1} b^{\beta_1}   \cdots s^{2^{\lambda_1} \mu_{k}} b^{\beta_{k}} , \\ 
u_{|\lambda_1| + |\xi|}   & \!\! = \ b^{\beta_0}   s^{2^{\lambda_1 + \xi} \mu_1} b^{\beta_1}   \cdots s^{2^{\lambda_1 + \xi} \mu_{k}} b^{\beta_{k}}  , \\ 
u_m   & \!\! = \ b^{\beta_0} c^{\gamma'_0} s^{2^{\lambda_1 + \xi + \lambda_2} \mu_1} b^{\beta_1} c^{\gamma'_1} \cdots s^{2^{\lambda_1 + \xi + \lambda_2} \mu_{k}} b^{\beta_{k}} c^{\gamma'_{k}}m
\end{array}$$
and $\gamma_i= -\beta_i \lambda_1$ and $\gamma'_i= \beta_i \lambda_2$ for $i=0, \ldots, k$.  
\end{itemize}
\end{lemma}

\begin{proof}
Here are the key points.  When $f_i = d^{\pm 1}$, the relation $u_i = f_i u_{i-1} f_i^{-1}$ in $G_4$ necessitates that there be no $c$-letters in the normal form of $u_{i-1}$.  And when $f_i = a^{\pm 1}$, we can relate the $c$-letters in $u_{i-1}$ to those in $u_{i}$---for example, because $u_{i-1} , u_{i} \notin \langle s \rangle$, at least one of $u_{i-1}$ and $u_{i}$ contains $c$-letters. 
\end{proof}






We are now ready to bound the lengths of conjugators.   

\begin{lemma} \label{quadratic bound from stack}
Suppose $x$ and $y$ are words on $\set{a^{\pm 1}, b^{\pm 1}, c^{\pm 1}, d^{\pm 1}, s^{\pm 1}}$.  Let  $n = |x|+|y|$.  If there exists a word $w$ on $\set{a^{\pm 1},  d^{\pm 1}}$ such that $wx = y w$ in $G_4$, then there exists such a $w$ for which $|w| \leq 2n +  8 n^2$.
\end{lemma}




\begin{proof}
Suppose $w$ is a word on $\set{a^{\pm 1},  d^{\pm 1}}$ such that $wx = y w$ in $G_4$. Further assume that $w$ is of minimal length among all such $w$ (so in particular is reduced). Let $\Delta$ be a van~Kampen diagram for $w x w^{-1} y^{-1}$.  

No two $a$- or $d$-corridors in $\Delta$ can cross. No pair of $a$-edges in one of the two portions of $\partial \Delta$ labelled by $w$ can be connected by an $a$-corridor, and ditto no pair of $d$-edges by a $d$-corridor.  So, per Figure~\ref{vK diagram with corridor block}, $w$ can be expressed in two ways as concatenations of subwords:  $$w \ = \  w_0 z w_1   \  = \  \tilde{w}_0  z \tilde{w}_1$$  where $m = |z|$  and the  $z = f_m f_{m-1} \cdots f_1$ subwords label two portions of $\partial \Delta$  so that for all $1 \leq i \leq m$,  the  letter $f_i$ in the $z$ in one copy of $w$ is joined by an $a$- or $d$-corridor to the $f_i$ in the other, and  all $a$- and $d$-corridors starting from $w_0$ or $\tilde{w}_0$ end in $y$, and those starting from $w_1$ or $\tilde{w}_1$ end in $x$.  The latter implies that for $x_1 := w_1 x \tilde{w}_1^{-1}$ and  $y_1 := w_0^{-1} y \tilde{w}_0$ (as words),
      \begin{align}
    |w_0| + |w_1| + |\tilde{w}_0| + |\tilde{w}_1|  &  \ \leq \ n, \text{ and}  \label{u1}  \\
    |x_1| + |y_1|  & \ \leq \ 2n.  \label{u2}
    \end{align}

For $i=0, 1, \ldots, m$, the word $$f_i  f_{i-1} \cdots f_1  \, x_1 \,  f_1^{-1}   \cdots  f^{-1}_{i-1}  f^{-1}_{i}$$ around part of  $\partial \Delta$ equals in $G_4$ a word along one side of  one such corridor, so represents an   element of $L$.  Let $u_i$ be its normal form per \eqref{L normal form}.  Then $x_1 = u_0$ and $y_1= u_m$ in $G_4$ and $z u_0 =u_m z$ in $L$.  



