\begin{align}
|\tilde{u}|_A, |\tilde{v}|_A & \leq \lambda n + \lambda, \label{tildeu bound} \\ 
\CL(u', \tilde{u}), \CL(v', \tilde{v}) & \leq   3\lambda n^2. \label{utilde u bound} 
