		\frac{dA_c}{dt} &= \epsilon_c LC+\Phi_c A_pC+ \rho_c\left(1-\frac{C}{C_0}\right)C - \beta_c A_c - \delta_c \frac{A_c^nA_c}{\alpha_c^nC^n+A_c^n} + \delta_s\left(1-\frac{A_s^n}{\alpha_s^n S^n+A_s^n}\right)A_s \label{Ac}\\
		\frac{dS}{dt} &= \delta_c\frac{ A_c^nC}{\alpha^nC^n+A_c^n} + \rho_s S - \beta_s S - \delta_s\left(1-\frac{A_S^n}{\alpha^n S^n+A_S^n}\right)S\\
		\frac{dA_s}{dt}& = \left(\epsilon_sL-\zeta_sH+\Phi_s A_p +\Theta_s N + \rho_s \right)S - \beta_s A_s + \delta_c \frac{A_c^n A_c}{\alpha_c^n C^n+A_c^n} - \delta_s\left(1-\frac{A_s^n}{\alpha_s^n S^n+A_s^n}\right)A_s\\
		\frac{dM}{dt} &= \frac{L+\tau_m(A_m-M)+\tau_s(A_s-S)}{\Gamma+L+\tau_m(A_m-M)+\tau_s(A_s-S)} + \rho_m M - M - \gamma M\\
		\frac{dA_m}{dt} &= \frac{L+\tau_m(A_m-M)+\tau_s(A_s-S)}{\Gamma+L+\tau_m(A_m-M)+\tau_s(A_s-S)} +\left( \epsilon_mL-\zeta_mH+\Phi_m A_p +\Theta_m N + \rho_m \right)M - \left(1+ \gamma\right)A_m\\
		\frac{dA_p}{dt} &= A_M + \beta_s A_S + \beta_c A_C - \left(\Phi_m M + \Phi_s S + \Phi_c C\right)A_p - \nu A_p\\
		\frac{dN}{dt} &= \nu A_p - \left(\Theta_m M + \Theta_s S\right)N
	\end{align} \label{MS}
\end{subequations}


\section{Reduction to two equations---SMC dynamics} \label{s3}
In this section, we set $\delta_s = 0$ and assume that lipid uptake by SMCs is at a constant rate.  This decouples equations (12c) and (12b) from the rest of the system in equations (12) and allows us to analyse the subsystem of the model for the cap smooth muscle cells, $\displaystyle{C}$, and their total lipid load, $\displaystyle{A_c}$, in detail.  We examine how cap smooth muscle cells respond dynamically to their lipid uptake and loss via phenotype switching, assuming that there is no restoration to the original SMC phenotype after phenotypic change to SDM ($\displaystyle{\delta_s = 0}$). 

