and $\pp=\{(a,\fa),(c,\fa),(e,\fa),(a,\tr),(d,\tr),(f,\tr),(a,a),(a,d),(a,f),(b,b),(b,d),(b,f),(c,d),(d,a),\\ (d,b),(d,c),(d,e),(d,f),(e,d),(e,f),(f,a),(f,b),(f,d),(f,e),(f,f)\}$.
 Customary calculations yield that $\mathcal{M}$ is an $\mathfrak{N}$-model.  
\end{example}

\begin{remark}\label{rem:prop1}Let $\mathcal{M}=(\alga,\perp,\{\tr,\fa\})$ be a $\mathfrak{N}_{w}$-model. Then, for any $x,y\in A$: $x\perp y$ {implies} $x\circ y^{*}\perp{\fa}$. Indeed, assume that $x\perp y$. By Definition \ref{def:nmod}(c), one has $x\circ y\pp\tr$ and so, by 
Definition \ref{def:nmod}(e), $(x\circ y)^{*}\pp\fa$. By Definition \ref{def:nmod}(f),(g), one has $(x\circ y^{*})^{*}\pp\tr$ and so $x\circ y^{*}\pp\fa$. 
\end{remark}
It is interesting to point out that in any $\mathfrak{N}_{w}$-model $\mathcal{M}=(\alga,\pp,\{\tr,\fa\})$, one can define a notion of a true or false proposition upon considering $x\in A$ true if $x\pp\fa$, i.e. if $x$ is incompatible with falsehood, and  false if $x\pp\tr$, namely if $x$ is incompatible with truth. 

\noindent Given a $\mathfrak{N}_{w}$-model $\mathcal{M}=(\alga,\perp,\{\tr,\fa\})$, let $F^{\mathcal{M}}_{\pp}=\{a\in A:a\perp{\fa}\}$. Let us define $\models_{\mathfrak{N}_{w}}\ \subseteq\mathcal{P}(\mathrm{Fm}_{\mathcal{L}})\times\mathrm{Fm}_{\mathcal{L}}$ upon setting, for any $\Gamma\cup\{\varphi\}\subseteq\mathrm{Fm}_{\mathcal{L}}$,
$\Gamma\models_{\mathfrak{N}_{w}}\varphi$ iff there is $\Gamma'\subseteq\Gamma,\ |\Gamma'|<\omega$, such that, for any $\mathcal{M}=(\alga,\perp,\{\tr,\fa\})\in\mathfrak{N}_{w},$ and  $h\in\mathbf{Hom}(\mathbf{Fm}_{\mathcal{L}},\alga)$: $$h(\Gamma')\subseteq F^{\mathcal{M}}_{\pp}\text{ implies }h(\varphi)\in F^{\mathcal{M}}_{\pp}.$$ Whenever the reference to $\mathcal{M}$ will be clear from the context, we will write just $F_{\pp}$ in place of $F^{\mathcal{M}}_{\pp}$. 
Moreover, if $\mathcal{M}=(\alga,\perp,\{\tr,\fa\})\in\mathfrak{N}_{w}$,  $\mathcal{M}\models \varphi$ will be short for $(h(\varphi),\fa)\in\perp$, for any 
$h\in\mathbf{Hom}(\mathbf{Fm}_{\mathcal{L}},\alga)$. Furthermore, we set $\models_{\mathfrak{N}_{w}} \varphi$ provided that $\mathcal{M}\models\varphi$, for any $\mathcal{M}\in\mathfrak{N}_{w}$. 

\noindent The following remark is obvious.
\begin{remark}\label{rem:models}$\langle\mathbf{Fm}_{\mathcal{L}},\models_{\mathfrak{N}_{w}}\rangle$ is a sentential logic.
\end{remark}

The proof of the next theorem can be carried out by means of a slight modification of well known techniques. However, since the models we deal with are, in some sense, non-standard for algebraic logic, we will run a bit more into details.
\begin{theorem}\label{thm:compl}For any $\Gamma\cup\{\varphi\}\subseteq\mathrm{Fm}_{\mathcal{L}}$, the following holds: 
\[\Gamma\vdash_{\nel}\varphi\text{ iff }\Gamma\models_{\mathfrak{N}_{w}}\varphi.\]
\end{theorem}
\begin{proof}The left-to-right-direction can be proven by means of a customary induction on the length of proofs. Let $(\mathbf{A},\pp,\{\tr,\fa\})\in\mathfrak{N}_{w}$, $\varphi,\psi,\chi\in\mathrm{Fm}_{\mathcal{L}}$, and $h\in\mathbf{Hom}(\mathbf{Fm}_{\mathcal{L}},\alga)$ with $h(\varphi)=a,\ h(\psi)=b,\ h(\chi)=c$. Concerning (A1), one has that $a\perp a^{*}$ implies $a\circ a^{*}\perp\tr$ (Definition \ref{def:nmod}(c)) and so $(a\circ a^{*})^{*}\perp\fa$ (Definition \ref{def:nmod}(d)). (A2), (A3), \eqref{a5bis} and (A7) are straightforward and so they are left to the reader. As regards (A4), note that, by Definition \ref{def:nmod}(f), $(a\circ b^{*})^{*}\perp(a\circ b)^{*}$ which, in turn, entails $(a\ra b)\ra(a\circ b)=((a\circ b^{*})^{*}\circ(a\circ b)^{*})^{*}\pp\fa$. Concerning (A6), one has:
\begin{align*}
h(((\varphi\otimes\psi)\ra\chi)\ra((\varphi\otimes\chi^{*})\ra\psi^{*}))\pp\fa &\text{ iff }((a\otimes b)\ra c)\ra((a\otimes c^{*})\ra b^{*})\pp\fa\\
&\text{ iff }((a\otimes b)\circ c^{*})^{*}\ra((a\otimes c^{*})\ra b^{*})\pp\fa\\
&\text{ iff }((a\otimes c^{*})\circ b^{**})^{*}\ra((a\otimes c^{*})\ra b^{*})\pp\fa\\ 
&\text{ iff }((a\otimes c^{*})\ra b^{*})\ra((a\otimes c^{*})\ra b^{*})\pp\fa
\end{align*}
As the last condition obviously holds, the desired conclusion obtains.\\
As regards proper inference rules of $\nel$, we confine ourselves to consider $\mathrm{(Eq)}_{1}^{s}$ leaving cases involving $\mathrm{(MP)}^{s}$, $\mathrm{(Adj)}^{s}$ and \Ces\ to the reader. Suppose that $h(\chi)\pp\fa$ and  $h(\varphi\Leftrightarrow\psi)\pp\fa$. $h(\varphi\Leftrightarrow\psi)\pp\fa$ implies $(a\ra b)\otimes(b\ra a)=a\Leftrightarrow b\pp\fa $. So, by Definition \ref{def:nmod}(e) one has $(a\circ b^{*})^{*}=a\ra b\pp\fa$ and $(b\circ a^{*})^{*}=b\ra a\pp\fa$ and, by Definition \ref{def:nmod}(c),(d) also $a\pp b^{*}$ and $b\pp a^{*}$. Therefore $h(\chi')=h(\chi)\pp\fa$, for any $\chi'\in\mathrm{Fm}_{\mathcal{L}}$ obtained upon replacing one or more occurrences of $\varphi$ by $\psi$ in $\chi$.
\\
As regards the converse direction, we proceed through a customary Lindenbaum-Tarski type construction. Let $\Gamma\cup\{\varphi\}\subseteq\mathrm{Fm}_{\mathcal{L}}$. Suppose that $\Gamma\not\vdash_{\nel}\varphi$ and let $\mathrm{Cn}^{\nel}(\Gamma)$ be the theory generated by $\Gamma$ in $\nel$. For any $\psi,\chi\in\mathrm{Fm}_{\mathcal{L}}$, let
\[\psi\equiv_{\Gamma}\chi\text{ iff }\psi\ra\chi,\chi\ra\psi\in\mathrm{Cn}^{\nel}(\Gamma).\]
Let us show that $\equiv_{\Gamma}$ (henceforth $\equiv$, in brief) is a congruence over $\mathbf{Fm}_{\mathcal{L}}$. Reflexivity and symmetry are trivial. As regards  transitivity, suppose that $\psi_{1}\equiv\chi_{1}$ and $\chi_{1}\equiv\psi_{2}$, i.e. $\psi_{1}\ra\chi_{1},\chi_{1}\ra\psi_{1},\chi_{1}\ra\psi_{2},\psi_{2}\ra\chi_{1}\in\mathrm{Cn}^{\nel}(\Gamma)$. Note that $\psi_{1}\ra\chi_{1},\chi_{1}\ra\psi_{1}\vdash_{\nel}(\chi_{1}\ra\psi_{2})\ra(\psi_{1}\ra\psi_{2})$, by \Eqts,$\mathrm{(Adj)}^{s}$ and \Ces, so $(\chi_{1}\ra\psi_{2})\ra(\psi_{1}\ra\psi_{2})\in\mathrm{Cn}^{\nel}(\Gamma)$ and also $\psi_{1}\ra\psi_{2}\in\mathrm{Cn}^{\nel}(\Gamma)$, by \Mps. Similarly, one proves that $\psi_{2}\ra\psi_{1}\in\mathrm{Cn}^{\nel}(\Gamma)$. Consequently, one has $\psi_{1}\equiv\psi_{2}$. As regards the compatibility of $\equiv$ with respect to operations, one has e.g. that $\psi_{1}\ra\chi_{1},\chi_{1}\ra\psi_{1},\psi_{2}\ra\chi_{2},\chi_{2}\ra\psi_{2}\in\mathrm{Cn}^{\nel}(\Gamma)$ implies $\psi_{1}\otimes\psi_{2}\ra\psi_{1}\otimes\chi_{2},\psi_{1}\otimes\chi_{2}\ra\chi_{1}\otimes\chi_{2}\in\mathrm{Cn}^{\nel}(\Gamma)$, i.e. $\psi_{1}\otimes\psi_{2}\ra\chi_{1}\otimes\chi_{2}\in\mathrm{Cn}^{\nelw}(\Gamma)$, by several applications of \Eqts, \Mps, $\mathrm{(Adj)}^{s}$. The converse can be obtained analogously. So $\psi_{1}\otimes\psi_{2}\equiv\chi_{1}\otimes\chi_{2}$. Cases for the remaining connectives can be handled similarly, and so they are left to the reader.\\
We show that $(\mathbf{Fm}_{\mathcal{L}}/{\equiv},\otimes,\circ,{}^{*})$ is a weak $\mathcal{N}$-algebra. Showing that ${}^{*}$ is an involution can be easily done as in \cite{MarPa}, upon proving that $\vdash_{\nel}\psi^{**}\ra\psi$ holds. Proving that $(\mathbf{Fm}_{\mathcal{L}}/{\equiv},\otimes)$ is a commutative groupoid is almost obvious, as it follows from \eqref{a5bis}. That $(\mathbf{Fm}_{\mathcal{L}}/{\equiv},\circ)$ is a commutative groupoid as well is granted by (A2). Condition \eqref{ex} follows by (A6) and the fact that $\equiv$ is a congruence. Let $\perp_{\Gamma}\ \subseteq\ \overline{\mathrm{Fm}_\mathcal{L}/{\equiv}}\times\overline{\mathrm{Fm}_\mathcal{L}/{\equiv}}$ be defined upon setting, for any $\psi/{\equiv},\chi/{\equiv}\in\mathrm{Fm}_\mathcal{L}/{\equiv}$, $$\psi/{\equiv}\pp_{\Gamma}\chi/{\equiv}\text{ iff }\psi\ra\chi^{*}\in\mathrm{Cn}^{\nel}(\Gamma).$$ Moreover, we set $$\psi/{\equiv}\pp_{\Gamma}\fa\text{ iff }\psi\in\mathrm{Cn}^{\nel}(\Gamma),\text{ and }\psi/{\equiv}\pp_{\Gamma}\tr\text{ iff }\psi^{*}\in\mathrm{Cn}^{\nel}(\Gamma).$$ First, one has to prove that $\pp_{\Gamma}$ (henceforth denoted by $\pp$, for short) is independent from representatives. However, it can be easily shown this is a consequence of \Mps,\Eqts, $\mathrm{(Adj)}^{s}$ and \Ces. Next, we show that $\pp$ satisfies conditions (a)-(h) of Definition \ref{def:nmod}. As regards (a), note that $\psi\ra\psi^{**}$ is a theorem of $\nel$, and so one has $\psi/{\equiv}\pp\psi^{*}/{\equiv}$. (b), (e), (f), (g), (h) are obvious, while (d) is a consequence of $\varphi\equiv \varphi^{**}$. As regards (c), one has $\psi/{\equiv}\perp\chi/{\equiv}$ iff $(\psi\circ\chi^{**})^{*}=\psi\ra\chi^{*}\in\mathrm{Cn}^{\nel}(\Gamma)$ iff $(\psi\circ\chi)^{*}\in\mathrm{Cn}^{\nel}(\Gamma)$ iff   $\psi\circ\chi/{\equiv}\pp\tr$, since $(\psi\circ\chi^{**})^{*}\equiv (\psi\circ\chi)^{*}$. (h) is an easy consequence of (A7). Therefore, $\mathcal{M}=(\mathbf{Fm}_{\mathcal{L}}/{\equiv},\pp,\{\tr,\fa\})\in\mathfrak{N}_{w}$. Moreover, Let $h:\mathbf{Fm}_{\mathcal{L}}\to\mathbf{Fm}_{\mathcal{L}}/{\equiv}$ be the homomorphism obtained upon extending the (usual) mapping such that, for any $x\in Var$, $x\mapsto x/{\equiv}$, to the whole $\mathrm{Fm}_{\mathcal{L}}$. One clearly has that, for any $\Gamma'\subseteq\Gamma$, $|\Gamma'|<\omega$, $h(\Gamma')\subseteq F_{\pp}$ but $h(\varphi)\notin F_{\pp}$. In other words, $\Gamma\not\models_{\mathfrak{N}_{w}}\varphi$.
\end{proof}

In general, building on the proof strategy from Theorem \ref{thm:compl}, one can prove analogous results for \emph{finite} extensions of $\nel$. Let $\Theta\subseteq\mathcal{P}(\mathrm{Fm}_{\mathcal{L}})\times\mathrm{Fm}_{\mathcal{L}}$. We say that $\Theta$ is \emph{finite} provided that $|\Theta|<\omega$ and, for any $(\Gamma,\varphi)\in\Theta$, $|\Gamma|<\omega$. The extension $\nel+\Theta$ is said to be finite provided that $\Theta$ is finite. {Now, for any $\varphi\in\mathrm{Fm}_{\mathcal{L}}$, let us write $\varphi(x_{1},\dots,x_{n})$ to highlight that $\varphi$ contains all and only  propositional variables among  $x_{1},\dots,x_{n}$.  For any $(\Gamma,\varphi)\in\mathcal{P}(\mathrm{Fm}_{\mathcal{L}})\times\mathrm{Fm}_{\mathcal{L}}$ ($|\Gamma|<\omega$), let $(\Gamma,\varphi)^{\pp}$ be the condition  
\[\forall x_{1},\dots,x_{n}[\gamma_{1}(x_{1},\dots,x_{n})\pp\fa\text{ and }\dots\text{ and }\gamma_{m}(x_{1},\dots,x_{n})\pp\fa\text{ imply }\varphi(x_{1},\dots,x_{n})\pp\fa]\label{firstordcondition}
\]
if $\Gamma=\{\gamma_{1}(x_{1},\dots,x_{n}),\dots,\gamma_{m}(x_{1},\dots,x_{n})\}\ne\emptyset$, and \[\forall x_{1},\dots,x_{n}[\varphi(x_{1},\dots,x_{n})\pp\fa],\] otherwise.} Moreover, let $\mathfrak{N}_{w}^{\Theta}$ be the class of all and only the $\mathfrak{N}_{w}$-models satisfying $(\Gamma,\varphi)^{\pp}$, for any $(\Gamma,\varphi)\in\Theta$. Note that, for any $\Theta\subseteq\mathcal{P}(\mathrm{Fm}_{\mathcal{L}})\times\mathrm{Fm}_{\mathcal{L}}$, $\mathfrak{N}_{w}^{\Theta}$ is always non-empty as it contains at least a trivial $\mathfrak{N}_{w}$-model. Furthermore, let $\langle\mathbf{Fm}_{\mathcal{L}},\models_{\mathfrak{N}_{w}^{\Theta}}\rangle$ be defined as at p. \pageref{rem:models}. Upon making good use of the proof strategy from Theorem \ref{thm:compl}, one has the following result.
\begin{theorem}\label{thm:compl2}For any finite extension $\nel+\Theta$ and, for any $\Gamma\cup\{\varphi\}\subseteq\mathrm{Fm}_{\mathcal{L}}$:\[\Gamma\vdash_{\nel+\Theta}\varphi\text{ iff }\Gamma\models_{\mathfrak{N}_{w}^{\Theta}}\varphi.\]
\end{theorem}
Now, it can be seen that $\mathfrak{N}=\mathfrak{N}_{w}^{\{\eqref{as1},\eqref{as2}\}}$. Therefore, in view of Proposition \ref{prop:odifreddi}, one has also the following theorem.

\begin{theorem}\label{thm:compl3}For any $\Gamma\cup\{\varphi\}\subseteq\mathrm{Fm}_{\mathcal{L}}$, and for any $\Theta\subseteq\mathcal{P}(\mathrm{Fm}_{\mathcal{L}})\times\mathrm{Fm}_{\mathcal{L}}$:
\begin{enumerate}
\item $\vdash_{\nl}\varphi$ iff $\models_{\mathfrak{N}_{w}}\varphi$;
\item $\vdash_{\nlas}\varphi$ iff $\models_{\mathfrak{N}}\varphi$;
\item $\vdash_{\nl+\Theta}\varphi$ iff $\models_{\mathfrak{N}_{w}^{\Theta}}\varphi$;
\item $\vdash_{\nlas+\Theta}\varphi$ iff $\models_{\mathfrak{N}^{\Theta}}\varphi$. 
\end{enumerate}
\end{theorem}

It can be shown that, actually, $\mathfrak{N}_{w}$-models are into bijective  correspondence with reduced matrix models of $\nel$. 
Indeed, let $\alga=(A,\otimes,\circ,{}^{*})$ be an $\mathcal{L}$-algebra. 
We can trivially define a logical $\nel$-filter over $\alga$ to be a set $\emptyset\ne F\subseteq A$ such that, for any $h\in\mathbf{Hom}(\mathbf{Fm}_{\mathcal{L}},\alga)$, any axiom $\varphi$ of $\nel$, $\psi,\chi\in\mathrm{Fm}_{\mathcal{L}}$, 
and any term $\delta(x,\vec{z})\in\mathrm{Fm}_{\mathcal{L}}$, one has\footnote{See \cite[pp. 6]{Font16} for details about the notation.}
\begin{enumerate}
\item $h(\varphi)\in F$;
\item $h(\psi), h(\psi\ra\chi)\in F$ implies $h(\chi)\in F$;
\item $h(\varphi),h(\psi)\in F$ iff $h(\varphi\otimes\psi)\in F$;
\item $h(\psi\ra\chi),h(\chi\ra\psi)\in F$ implies $\delta^{\alga}(h(\psi),\vec{c})\ra\delta^{\alga}(h(\chi),\vec{c})\in F$, for any $\vec{c}\in \vec{A}$. 
\end{enumerate}
The class of  matrix models of $\nel$ coincides with the class of pairs $\langle\alga,F\rangle$, where $\alga=(A,\otimes,\circ,{}^{*})$ is an $\mathcal{L}$-algebra  and $F$ is a $\nel$-filter over $\alga$. Of course, $\nel$ is complete w.r.t. the class of all its matrix models, as this holds for any logic (cf. \cite[Theorem 4.16]{Font16}). Let $\langle\alga,F\rangle$ be a matrix model of $\nel$ and define $\equiv\ \subseteq A^{2}$ upon setting, for any $a,b\in A$:
\[a\equiv b\text{ iff }a\ra b,b\ra a\in F.\] Putting in good use clauses (1)-(4) defining logical filters of $\nel$, it is easily seen that $\equiv$ is actually a congruence relation. Moreover, items (1)-(4) ensure that, for any $a,b\in A$, $a\equiv b$ if and only if, for any $\delta(x,\vec{z})\in\mathrm{Fm}_{\mathcal{L}}$, and any $\vec{c}\in \vec{A}$, it holds that $$\delta^{\alga}(a,\vec{c})\in F\text{ iff }\delta^{\alga}(b,\vec{c})\in F.$$ Consequently, by \cite[Theorem 4.23]{Font16}, $\equiv\ =\ \Omega^{\alga}(F)$.\\
Given a matrix $\langle\alga,G\rangle$, where $\alga$ is an $\mathcal{L}$-algebra, and $G\subseteq A$, we define a relation $\pp_{G}\ \subseteq \overline{A}\times\overline{A}$, where $\overline{A}$ has to be meant as at p. \pageref{pippo}, upon setting
\[\pp_{F}:=\{(a,b)\in A^{2}:a\ra b^{*}\in G\}\cup\{(a,\fa):a\in G\}\cup\{(a,\tr):a^{*}\in G\}.\] Moreover, for any structure $(\alga,\pp,\{\tr,\fa\})$, where $\alga$ is an $\mathcal{L}$-algebra and $\pp\ \subseteq\overline{A}\times\overline{A}$, we set $F_{\pp}:=\{a\in A: a\pp\fa\}$.
\begin{proposition}\label{equivmatrixnelsonmo}For any pair $\langle\alga,G\rangle$, and any structure $(\alga,\pp,\{\tr,\fa\})$ such that $\alga$ is an $\mathcal{L}$-algebra, $\pp\ \subseteq \overline{A}\times\overline{A}$ and $G\subseteq A$, one has:
\begin{enumerate}
\item $\langle\alga, G\rangle$ is a reduced model of $\nel$ if and only if $(\alga,\pp_{G},\{\tr,\fa\})\in\mathfrak{N}_{w}$;
\item $(\alga,\pp,\{\tr,\fa\})\in\mathfrak{N}_{w}$ if and only if $\langle\alga,F_{\pp}\rangle$ is a reduced model of $\nel$ and $\pp=\pp_{F_{\pp}}$.
\end{enumerate}
Consequently, $\mathsf{Alg}^{*}\nel$ coincides with the class of algebraic reducts of $\mathfrak{N}$-models. Moreover, for any reduced matrix $\langle\alga,G\rangle$ of $\nel$ and any $\mathfrak{N}_{w}$-model $(\alga,\pp,\{\tr,\fa\})$, one has $$\langle\alga,G\rangle=\langle\alga,F_{\pp_{G}}\rangle\text{ and }(\alga,\pp,\{\tr,\fa\})=(\alga,\pp_{F_{\pp}},\{\tr,\fa\}).$$
\end{proposition}
\begin{proof}
(1). As regards the left-to-right direction, we first show that $\alga$ is a weak $\mathcal{N}$-algebra. That $(A,\otimes)$ is a commutative groupoid is ensured by noticing that, since $G$ is a logical filter and $\Omega^{\alga}(G)=\Delta$, for any $a,b\in A$, $a\otimes b\ra b\otimes a\in G$ and $b\otimes a\ra a\otimes b\in G$, so $a\otimes b\equiv b\otimes a$ and $a\otimes b = b\otimes a$. The commutativity of $\circ$, the involutivity of ${}^{*}$, as well as \eqref{ex}, can be proven exactly in the same way. To see that $\pp_{G}$ satisfies conditions from Definition \ref{def:nmod}, we confine ourselves to show (a) and (c) leaving the remaining clauses to the reader.  As regards (a), note that $a\ra a\in G$. This means that $a\ra a^{**}\in G$ and so $a\pp_{G}a^{*}$. Concerning (c), note that $a\pp_{G}b$ iff $a\ra b^{*}\in G$ iff $(a\circ b)^{*}\in G$ iff $a\circ b\pp_{G}\tr$.\\
Conversely, first note that $G=F_{\pp_{G}}$ as $x\in G$ iff $x\pp_{G}\fa$ iff $x\in F_{\pp_{G}}$. Moreover, $F_{\pp_{G}}$ is a logical filter by Theorem \ref{thm:compl} (soundness). The fact that $\Omega^{\alga}(G)=\Delta$ is ensured by Definition \ref{def:nmod}(b). \\
To prove (2), observe that if $(\alga,\pp,\{\tr,\fa\})\in\mathfrak{N}_{w}$, then $x\pp_{F_{\pp}}y$ iff $x\ra y^{*}\in F_{\pp}$ iff $x\ra y^{*}\pp\fa$ iff $x\circ y\pp\tr$ iff $x\pp y$. Moreover, $x\pp_{F_{\pp}}\fa$ iff $x\in F_{\pp}$ iff $x\pp\fa$ and, similarly, one has $x\pp_{F_{\pp}}\tr$ iff $x\pp\tr$. So $(\alga,\pp,\{\tr,\fa\})=(\alga,\pp_{F_{\pp}},\{\tr,\fa\})$. Consequently, we conclude that $\langle\alga,F_{\pp}\rangle$ is a reduced model by item (1). Conversely,  if $\langle\alga,F_{\pp}\rangle$ is a reduced model of $\mathsf{NeL}$, then (again by item (1)), $(\alga,\pp_{F_{\pp}},\{\tr,\fa\})\in\mathfrak{N}_{w}$ and the desired conclusion follows by $\pp_{F_{\pp}}=\pp$.\\
The moreover part is clear.
\end{proof}
\noindent In the light of Proposition \ref{equivmatrixnelsonmo}, we conclude that the map $\langle\alga,F\rangle\mapsto(\alga,\pp_{F},\{\tr,\fa\})$, where $\langle\alga,F\rangle$ is a reduced model of $\mathsf{NeL}$ is a bijection between the class of reduced models of $\nel$ and $\mathfrak{N}_{w}$. 

Due to \cite[Theorem 6.7]{Font16} and the presence of (A1) and \Mps, it follows that $\mathsf{NeL}$ is protoalgebraic (see \cite[Definition 6.1]{Font16}). This means, among other things, that $\mathsf{NeL}$ satisfies the \emph{Parameterised Local Deduction-Detachment Theorem} (\cite[Theorem 6.22]{Font16}). Therefore, we believe that the following problem, whose analysis is postponed to a future work, is worth of investigation.
\begin{question}Characterize a family of Deduction-Detachment sets (see \cite[Definition 6.21]{Font16}) for $\nel$.
\end{question}
Moreover, it can be seen that the set $\Delta(x,y):=\{x\ra y,y\ra x\}$ is a set of \emph{congruence formulas} for $\nel$ and $\nelas$. This is a consequence of \cite[Theorem 6.60]{Font16} and the proof of Theorem \ref{thm:compl} (completeness), since e.g. it can be seen that conditions
\begin{enumerate}
\item[(R)] $\vdash_{\nel}\Delta(x,x)$;
\item[(MoP)] $x,\Delta(x,y)\vdash_{\nel}y$;
\item[(Re)] $\Delta(x_{1},y_{1}), \Delta(x_{2},y_{2})\vdash_{\nel}\Delta(x_{1}\star x_{2}, y_{1}\star y_{2})$, for each $\star\in\{\circ,\otimes\}$, and $\Delta(x_{1},y_{1})\vdash_{\nel}\Delta(x_{1}^{*},y_{1}^{*})$.
\end{enumerate}
Therefore, $\nel$ and its extensions are \emph{equivalential} (see \cite[Definition 6.63]{Font16}).  
However, it naturally raises the question whether they are also \emph{algebraizable}.  
\begin{question}\label{prob:algebraiz} Prove or disprove that $\nel$ is algebraizable.  
\end{question}

\subsection{Remarks on (NSY) and hyperconnexivity}
Logics encountered so far have Aristotle's and Boethius' theses as theorems, namely for any $\mathsf{L}\in\{\nl,\nlas,\nel,\nelas\}$, and so for any finite extension thereof, one has $\vdash_{\mathsf{L}}(\varphi\ra\varphi^{*})^{*}$, $\vdash_{\mathsf{L}}(\varphi^{*}\ra\varphi)^{*}$ (Aristotle's Theses), and both $\vdash_{\mathsf{L}}(\varphi\ra\psi)\ra(\varphi\ra\psi^{*})^{*}$ and $\vdash_{\mathsf{L}}(\varphi\ra\psi^{*})\ra(\varphi\ra\psi)^{*}$ (Boethius' Theses). These are easy consequences of the definition of $\ra$, axioms (A3) and its converse (which can be derived as in \cite[pp. 419--420]{MarPa}), (A4), $\mathrm{(MP)}^{s}$ (or (MP)) and $\mathrm{(Eq)}_{1}^{s}$ (or $\mathrm{(Eq)}_{1}$).\\ In the light of these facts, it raises the question whether Nelson's logics outlined so far are also \emph{hyper-connexive}.\\ A logic $\mathsf{L}$ over a language containing a binary connective $\ra$ for implication, and a unary connective ${}^{*}$ for negation is said to be hyper-connexive provided that it is connexive and, moreover, the following hold, for any pair of formulas $\varphi,\psi$:
\[\mathrm{(HC1)}\ \vdash_{\mathsf{L}}(\varphi\ra\psi)^{*}\ra(\varphi\ra\psi^{*})\text{ and }\mathrm{(HC2)}\ \vdash_{\mathsf{L}}(\varphi\ra\psi^{*})^{*}\ra(\varphi\ra\psi).\]
There are well known connexive logics satisfying hyper-connexive theses, think e.g. to H. Wansing's connexive logic $\mathsf{C}$ (\cite{wansingstanford,Wans2}). However, some doubts concerning their plausibility have been raised, in particular when it comes to formalize natural language conditionals, see \cite[pp. 446--447]{mccall2012}.\\ 
Actually, if $\ra$ is meant according to Nelson's perspective on entailment, then the failure of hyper-connexive principles is arguably a natural \emph{desideratum}. Indeed, the validity of (HC1) or (equivalently)  of (HC2), would entail, for any $x,y\in Var$, the validity of \[(x \circ y)\ra(x\ra y),\] namely that if $x$ and $y$ are compatible, then $x\ra y$ holds. This is of course unacceptable as, for example, the proposition ``$4$ is even'' ($p$) and ``$3$ is prime'' ($q$) are compatible but ``If $4$ is even, then $3$ is prime'' need not hold, since $q$ is arguably not obtainable from $p$ by ``logical analysis'', at least in Nelson's sense (cf. \cite[p. 447]{Nelson1}). {A further motivation for a Nelsonian rejection of hyperconnexivity is provided by the following example. Let us consider the statements ($p$)``John has an even number of children'', ``John has more boys than girls''($q$). Since $p$ is compatible with \emph{both} $q$ and $q^{*}$, one would have that both $p\ra q$ and $p\ra q^{*}$ hold true. In other words, hyperconnexivity, together with axioms and inference rules Nelson's systems (think to (MP) and (A4)),  yields inconsistencies\footnote{We thank an anonymous referee for pointing this fact out to us.}. This fact is mirrored by the next proposition. It shows that any non-trivial $\mathfrak{N}_{w}$-model provides a counterexample to hyperconnexivity.} 

\begin{proposition}\label{prop:df}Let $\mathcal{M}=(\alga,\pp,\{\tr,\fa\})\in\mathfrak{N}_{w}$. Then, $\mathcal{M}\models (x\circ y)\ra x\ra y$ if and only if $\alga$ is trivial.
\end{proposition}
\begin{proof}
Note that $\mathcal{M}\models(x\circ y)\ra(x\ra y)$ if and only if $\alga\models x\circ y\approx x\ra y$. Now, if this is the case, one has 
\begin{align*}
\fa &\pp((x\ra x)\otimes(x\ra y))\ra((x\ra x)\otimes(x\ra y))\\
&=((x\ra x)\otimes(x\ra y))\circ((x\ra x)\otimes(x\ra y))\\
&=((x\ra y)\otimes((x\ra x)\otimes(x\ra y)))\circ(x\ra x)\\
&=(x\ra x)\ra((x\ra y)\otimes((x\ra x)\otimes(x\ra y))).  
\end{align*}
Since $x\ra x\pp\fa$, one has also $(x\ra y)\otimes((x\ra x)\otimes(x\ra y))\pp\fa$ and so $(x\ra y)=x\circ y=y\circ x=y\ra x\pp\fa$. We conclude that $x=y$.
\end{proof}
\noindent As a consequence, any $\mathfrak{N}_{w}$-model yields a counterexample to the symmetry of $\ra$.

\begin{proposition}\label{prop:df1}Let $\mathcal{M}=(\alga,\pp,\{\tr,\fa\})\in\mathfrak{N}_{w}$. Then, $\mathcal{M}\models (x\ra y)\ra(y\ra x)$ if and only if $\alga$ is trivial.
\end{proposition}
\begin{proof}
The statement follows by Proposition \ref{prop:df} upon noticing that $\mathcal{M}\models (x\ra y)\ra(y\ra x)$ entails that $\mathcal{M}\models (x\circ y)\ra(x\ra y)$. 
\end{proof}
\noindent Therefore, $\ra$, as axiomatized by $\nl,\nlas,\nel$ or $\nelas$ can be understood as a genuine full-fledged connexive implication. Even more, these logics can be somewhat regarded as \emph{strongly} non-symmetric, in the sense that each of their non-trivial models provide a counterexample to the symmetry of $\ra$. As a consequence, one has that there is no non-trivial superlogic of $\nel$ yielding a symmetric implication and which is complete in the sense of Theorem \ref{thm:compl} w.r.t. a subclass of $\mathfrak{N}_{w}$. This property is not shared e.g. by Connexive Heyting Logic $\mathsf{CHL}$ introduced in \cite{FaLePa}, and which turns out to be deductively equivalent to Intuitionistic Logic $\mathsf{IL}$. Indeed, $\mathsf{CHL}$ admits a largest non trivial superlogic $\mathsf{CBL}$ that is deductively equivalent to Classical Logic, and which yields a symmetric implication, cf. \cite[p. 113]{FaLePa}. 



\section{Some extensions of Nelsonian logics}\label{sec:variantsNL}
\subsection{On strong connexivity  and the irreflexivity of $\pp$}\label{sec:strongsupconn} 
As we have recalled in the Introduction, one of the cornerstones of Nelson's perspective about logic is that consistency/compatibility is always reflexive, while inconsistency/incompatibility is always \emph{irreflexive}. Indeed, once meaning is taken into account, even contradictions are at least compatible with themselves.  However, Example \ref{ex:1} shows that axioms and inference rules of $\nel$ are not strong enough to ensure that, on the semantical side, $\mathfrak{N}_{w}$-models are endowed with an irreflexive incompatibility relation. 
 A further consequence of this fact is that there are $\mathfrak{N}_{w}$-models satisfying the formula $x\ra x^{*}$. So, $\nel$ is not \emph{strongly connexive} in the sense of A. Kapsner (see e.g. \cite{Kap1,Wans1}). Indeed, strong connexivity can be rendered by the following conditions (cf. \cite[p. 3]{Kap1}):
\begin{itemize}
\item[](Unsat1) In no (non-trivial) model, $\varphi\ra\varphi^{*}$ is satisfiable (for any $\varphi$);
\item[](Unsat2) In no (non-trivial) model $\varphi\ra\psi$ and $\varphi\ra\psi^{*}$ are satisfiable (for any $\varphi$ and $\psi$).
\end{itemize}
We observe that, in the present framework, (Unsat1) is equivalent to the irreflexivity of $\pp$. 
\begin{remark}Let $\nel^{\Theta}=\langle\mathbf{Fm}_{\mathcal{L}},\vdash_{\nel^{\Theta}}\rangle$ be a finite extension of $\nel$. Then $\nel^{\Theta}$ satisfies (Unsat1) if and only if, for any non-trivial $\mathcal{M}=(\alga,\pp,\{\tr,\fa\})\in\mathfrak{N}_{w}^{\Theta}$, $\pp$ is irreflexive. Indeed, $\nel^{\Theta}$ satisfies (Unsat1) if and only if, for any non-trivial $\mathcal{M}=(\alga,\pp,\{\tr,\fa\})\in\mathfrak{N}_{w}^{\Theta}$ and, for any $a\in A$, it never holds that $(a\circ a)^{*}\pp\fa$, i.e. that $a\pp a$.
\end{remark}
However, we have also something more. Indeed, we will see that the irreflexivity of $\pp$ has, as a syntactical counterpart, a weak form of \emph{superconnexivity} first introduced by A. Kapsner in \cite{Kap1}. To explain and motivate this concept, we refer to his words:
\begin{quote}
Now, one might wonder whether the criterion of strong connexivity can be expressed
in some manner in the object language itself, given that ARISTOTLE and BOETHIUS are
not up to this task.\\
A look at an analogous problem might bring us to some interesting ideas here. Classical logic and most non-classical logics validate the principle of explosion, $(A\land\neg A)\to B$. Let us remind ourselves of a philosophical argument that is sometimes given in favor of the validity of $(A\land\neg A)\to B$. This validity, it is claimed, is the most we can do to express, in the object language itself, the thought that a contradiction is unsatisfiable.
In analogy to this use of explosion to express the unsatisfiability of any contradiction, we might try to ask that $(A\to\neg A)\to B$ should be valid, in order to express in the object language that $(A\to\neg A)$ is unsatisfiable (and similarly for the rest of the connexive theses).
Call a logic that validates all of these schemata and satisfies all the requirements for strong connexivity superconnexive. \cite[pp. 3-4]{Kap1}
\end{quote}
Unfortunately, it turns out that, even under a \emph{modicum} of assumptions, like e.g. substitutivity and Modus Ponens (which are sound inference rules, in our setting), a superconnexive logic is \emph{trivial}. Nevertheless, if one relaxes the superconnexive axiom by substituting it with the weaker \emph{inference rule}
\[\varphi\ra\varphi^{*}\vdash\psi,\tag{I}\label{i}\]
then one may still hope of encoding  strong connexivity by means of superconnexive principles. And actually, in the framework we are dealing with, this is the case. 

To characterize the class of $\mathfrak{N}_{w}$-models whose non-trivial members are all and only those endowed with an irreflexive incompatibility relation it is sufficient to consider the class $\mathfrak{N}_{w}^{\mathrm{I}}$ of $\mathfrak{N}_{w}$-models  satisfying the condition
\[x\pp x\text{ implies }x\approx y.\tag{I}\] 
\begin{remark}\label{rem:giardino}For any $\mathfrak{N}_{w}$-model $\mathcal{M}=(\alga,\pp,\{\tr,\fa\})$, $\mathcal{M}$ satisfies \eqref{i} if and only if it satisfies the condition
 \[x\ra x^{*}\pp\fa\ \text{implies}\ y\pp\fa.\] Indeed, as regards the left-to-right direction, one has that $x\ra x^{*}\pp\fa$ implies $x\circ x\pp\tr$ and so $x\pp x$. Therefore, $\alga$ is trivial and one has $y\pp\fa$, for any $y\in A.$ Conversely, $x\pp x$ implies $x\ra x^{*}\pp\fa$. So $x\ra y\pp\fa$ and $y\ra x\pp\fa$ hold. This entails that $x\approx y$ must hold in $\alga$ and so $\alga$ is trivial.  
\end{remark}

\noindent Upon considering the extension $\nel+\{(I)\}$, one has the following
\begin{theorem}
For any $\Gamma\cup\{\varphi\}\subseteq\mathrm{Fm}_{\mathcal{L}}$, the following holds: 
\[\Gamma\vdash_{\nel+\{\mathrm{I}\}}\varphi\text{ iff }\Gamma\models_{\mathfrak{N}_{w}^{\mathrm{I}}}\varphi.\] 
\end{theorem}

\noindent Furthermore, to have a fully strongly connexive extension of $\nel$, and so satisfying also (Unsat2), one has to consider the logic obtained upon extending $\nel$ with the further inference rule schema 
\[\varphi\ra\psi^{*},\varphi\ra\psi\vdash\chi.\tag{I2}\label{i2}\] 
Indeed, take the class $\mathfrak{N}_{w}^{\mathrm{I+}}$ of $\mathfrak{N}_{w}$-models satisfying the condition
\[x\pp y^{*}\text{ and }x\pp y\quad\text{imply}\quad x\approx z.\tag{$\mathrm{I2}$}\label{i2}\]
\begin{remark}Upon reasoning as in Remark \ref{rem:giardino}, one has that \eqref{i2} is equivalent to the condition
\[x\ra y\pp\fa\text{ and } x\ra y^{*}\pp\fa\text{ imply } z\pp\fa.\]

\end{remark}
Clearly, $\mathfrak{N}_{w}^{\mathrm{I}}\subseteq\mathfrak{N}_{w}^{\mathrm{I+}}$ and $\mathfrak{N}_{w}^{\mathrm{I+}}$ is the class of $\mathfrak{N}_{w}$-models whose non-trivial members are all and only those not satisfying both $\varphi\ra\psi$, $\varphi\ra\psi^{*}$ (for any $\varphi$ and $\psi$), and so also $\varphi\ra\varphi^{*}$ (for any $\varphi\in\mathrm{Fm}_{\mathcal{L}}$).
\begin{theorem}
For any $\Gamma\cup\{\varphi\}\subseteq\mathrm{Fm}_{\mathcal{L}}$, the following holds: 
\[\Gamma\vdash_{\nel+\{\mathrm{I2}\}}\varphi\text{ iff }\Gamma\models_{\mathfrak{N}_{w}^{\mathrm{I+}}}\varphi.\] 
\end{theorem}
Considerations made so far give further substance to Kapsner's intuitions, as they show that concepts he introduces are entailed by, somewhat ``hidden'' below, ideas raised at the very dawn of modern connexive logic. However, as the same author points out:
\begin{quote}
[...]one might well have doubts concerning superconnexivity. A superconnexive logic requires an implication that always turns out to be true if the antecedent is unsatisfiable; many implicational connectives in the literature indeed behave this way, but there have also been deep reservations about those conditionals voiced by relevant and paraconsistent logicians. In the case at hand, they would balk at the validity of $(A\to\neg A)\to B$ because there is no connection between the antecedent and the consequent at all. Likewise, $(A\to\neg A)\models B$ would not meet what they would require of a decent consequence relation. \cite[pp. 4]{Kap1}.
\end{quote}
Actually, Kapsner's remark is relevant to our discourse since, as a consequence of previous results, in order to have a logic capable of  coping with Nelson's intuition about the irreflexivity of incompatibility, one has to endorse (at least one half of) Kapsner' strong connexivity and, in turn, the weakly superconnexive principle he recognizes as incompatible with a relevantist approach. And this may represent a challenge for Nelson's view of logic since, due to the way Nelson means its intensional nature, it is supposed to adhere to  kind of relevantist principles.\footnote{We highlight that we are not claiming that $\nel$ or any of the logics outlined in this paper are relevant logics in the narrow sense. Instead, as already remarked in the Introduction, we confine ourselves to point out that Nelson's conception of intensional logic is strongly tied to notions like e.g. ``real use in proof'' that most logicians accept as hallmarks of the relevantist  paradigm, see e.g. \cite{Mares}.} 
 However, we observe that in $\nel$ (as in all the logics we deal with in this work) two \emph{distinct} notions of entailment coexist. The first, embodied by $\vdash_{\nel}$, calls into question \emph{truth} (or incompatibility with falsehood). Such a consequence relation,  that we may call \emph{external}, establishes a relationships between sets of formulas and formulas to the effect that, whenever the former hold true in a model, the latter do. The second notion of ``consequence'', this time embodied by $\ra$, and that we may call \emph{internal}, is what Nelson really considers the true concept of intensional (relevant, as we might understand it) entailment. Therefore, if one confines oneself to considering the latter notion of entailment as the one whose ``relevant features'' should truly be taken into account (which might be reasonable, see Remark \ref{rem:explosionnoparad} and Remark \ref{prop:superconn} below), then assuming \emph{at least} $\nel+\{\mathrm{I}\}$ as a suitable extension of $\nel$,  capable of better aligning with Nelson’s intuition, might be worth considering..

In the light of the above remarks, if one aims at obtaining a full fledged strongly connexive logic, one may also consider extending $\nel$ with the further inference rule 
\[\varphi,\varphi^{*}\vdash\psi.\tag{ECQ}\label{encq}\]
The logic thus obtained, that we denote by $\nel^{\mathrm{ECQ}}$, is sound and complete w.r.t. the class $\mathfrak{N}_{w}^{S}\subseteq\mathfrak{N}_{w}$ of $\mathfrak{N}$-models $\mathcal{M}=(\alga,\pp,\{\tr,\fa\})$ satisfying the condition:
\[x\pp\tr\text{ and }x\pp\fa\text{ imply }z\pp\fa\tag{s}\label{str}.\]

\begin{example}\label{ex:efq} The structure $\mathcal{M}$ from Example \ref{ex.ceci} (see below) is a member of $\mathfrak{N}_{w}^{S}$. 
\end{example}

\begin{theorem} For any $\Gamma\cup\{\varphi\}\subseteq\mathrm{Fm}_{\mathcal{L}}$, the following holds: 
\[\Gamma\vdash_{\nel^{\mathrm{ECQ}}}\varphi\text{ iff }\Gamma\models_{\mathfrak{N}_{w}^{S}}\varphi.\]
\end{theorem}
\begin{remark}\label{rem:explosionnoparad}
It is worth observing that, even if we assume \emph{explosion}, the logic one obtains still avoids some paradoxes of material implication. For example, one has $\not\vdash_{\nel^{\mathrm{ECQ}}}x\ra(x^{*}\ra y)$. Indeed, upon considering the model provided by Example \ref{ex:efq}, one has that $a\ra(a^{*}\ra a)=(a\circ(b\circ b))^{*}=(a\circ a)^{*}=a^{*}=b\not\pp\fa$. The same counterexample shows e.g. that $\not\vdash_{\nel^{\mathrm{ECQ}}}x\ra(y\ra x)$. 
\end{remark}
\noindent Of course, the next further remark is in order. We leave its simple proof to the reader.
\begin{remark}\label{prop:superconn} \eqref{i2} (and so \eqref{i}) holds in $\nel^{\mathrm{ECQ}}$.
\end{remark}
\noindent Actually, although essential for the irreflexivity of $\pp$, we are not aware if Nelson considered (I), (I2) or EFQ as valid inference rules, at least whenever truth is in question. However, as it will be shown in the sequel, they are consequences of principles he accepts explicitly.

As already recalled in the Introduction, in several works Nelson assumes a neat position against the axiom of disjunction introduction
\[\varphi\ra\varphi\oplus\psi,\tag{D}\label{d}\]
where, {as it can be inferred from the use of De Morgan laws in some of his arguments} (see e.g. \cite[p. 269]{Nelson2}) $$\varphi\oplus\psi:=(\varphi^{*}\otimes\psi^{*})^{*}.$$
{We highlight  that, by $\oplus$, we are referring to the ``mere'' factual disjunction $\lor$ (using  Nelson's terms and notation, see \cite[p. 446]{Nelson1}, cf. \cite{Nelson2}) and not to Nelson's \emph{intensional logical sum} $\bigvee$ that he defines in terms of entailment upon setting $$\varphi\bigvee\psi:=\varphi^{*}\ra\psi,$$ and which is essentially different from $\lor$, although related to it. Indeed, as Nelson states in several venues (\cite[p. 132]{Nelson3}, cf. \cite[p. 446]{Nelson1}), if $p\bigvee q$ is true, then $p\oplus q$ must hold as well, although the converse is false, in general.\footnote{We observe that J. Woods in \cite[p. 65]{Woods1} interprets the relationship between Nelson's intensional disjunction and ``factual'' disjunction differently. Indeed, he  writes: ``$p$ or $q$ [\emph{intensional disjunction}], if true, is necessarily true, whereas, even if true, $p\lor q$ could be false''.}}\\
As Nelson observes (see e.g. \cite[pp. 273]{Nelson2}), there is no way of deducing $\varphi\oplus\psi$ from $\varphi$ by logical analysis since, although $\varphi\oplus\psi$ asserts less than $\varphi$ from the perspective of truth, once meaning is considered, what it asserts is \emph{more} than $\varphi$. 
Actually, beside its incompatibility with Nelson's philosophy, as a consequence of analogous results concerning conjunction simplification, \eqref{d} yields inconsistencies. 

\begin{proposition}$\nl+\{\eqref{d}\}$ is trivial. 
\end{proposition}
\begin{proof}
Note that, (a) $\vdash_{\nl}(\varphi\ra\psi)\ra(\psi^{*}\ra\varphi^{*})$. Consequently, $\vdash_{\nl+\{\eqref{d}\}}\varphi\ra\varphi\oplus\psi$ entails (by (a), (MP), and $\mathrm{(Eq)}_{1}$) $\vdash_{\nl+\{\eqref{d}\}}\varphi^{*}\otimes\psi^{*}\ra\varphi^{*}$ which, in turn, entails $\vdash_{\nl+\{\eqref{d}\}}\varphi\otimes\psi\ra\varphi$. Therefore, $\nl+\{\eqref{d}\}$ is trivial by Proposition \ref{prop:trivial}.
\end{proof}
\noindent Nevertheless, Nelson argues, like conjunction loses its ``unity'', namely its intensional character, when considered from the perspective of truth (and so outside the scope of entailment), to the effect that (CE) or $\mathrm{(CE)^{s}}$ become acceptable inference rules, the same holds for \emph{disjunction}. Indeed, as Nelson points out in \cite[p. 272]{Nelson2}, ``when we deal with truth-values we may disjoin to any true proposition any proposition and assert the whole thing. This is because the resulting disjunctive proposition ``$p$ or $q$'' is less determinate than the proposition with which we start'' (cf. \cite[p. 448]{Nelson1}). {Among other things, this passage provides a further evidence for concluding that what Nelson is referring to is not intensional disjunction as, otherwise, this would led us to admit that, if a proposition $\varphi$ is true, then $\varphi\bigvee\varphi=\varphi^{\star}\ra\varphi=(\varphi^{*}\circ\varphi^{*})^{*}$ is true. And this is, of course, unacceptable from Nelson's perspective.}

Therefore, let us consider the logics $\nl_{d}$ ($\nlas_{d}$) and $\nel_{d}$ ($\nelas_{d}$) obtained upon extending $\nl$ ($\nlas$) and $\nel$ ($\nelas$) with the inference rule schemas
\begin{center}
\AxiomC{$\vdash\varphi$}\RightLabel{$\mathrm{(DI)}$}
\UnaryInfC{$\vdash\varphi\oplus\psi$}
\DisplayProof and  
\AxiomC{$\varphi$}\RightLabel{$\mathrm{(DI)}^{s}$}
\UnaryInfC{$\varphi\oplus\psi$}
\DisplayProof,
\end{center}
respectively. Upon considering the class $\mathfrak{N}_{w}^{d}$ ($\mathfrak{N}^{d}$) of $\mathfrak{N}_{w}$-models ($\mathfrak{N}$-models) satisfying the further condition 
\begin{equation}
x\pp\fa\text{ implies }x\oplus y\pp\fa,\tag{di}\label{dis} 
\end{equation}
by Theorem \ref{thm:compl2} and Theorem \ref{thm:compl3}, one has the following
\begin{theorem}For any $\Gamma\cup\{\varphi\}\subseteq\mathrm{Fm}_{\mathcal{L}}$, the following hold:
\begin{enumerate}
\item $\Gamma\vdash_{\mathsf{NeL}+\{\mathrm{(DI)}^{s}\}}\varphi\text{ iff }\Gamma\models_{\mathfrak{N}_{w}^{\mathrm{d}}}\varphi$;
\item $\Gamma\vdash_{\nelas+\{\mathrm{(DI)}^{s}\}}\varphi\text{ iff }\Gamma\models_{\mathfrak{N}^{\mathrm{d}}}\varphi$;
\item $\vdash_{\nl+\{\mathrm{(DI)}\}}\varphi$ iff $\models_{\mathfrak{N}_{w}^{\mathrm{d}}}\varphi$;
\item $\Gamma\vdash_{\nlas+\{\mathrm{(DI)}\}}\varphi\text{ iff }\Gamma\models_{\mathfrak{N}^{\mathrm{d}}}\varphi$.
\end{enumerate}

\end{theorem}

\begin{example}\label{ex.ceci}
Let us consider the structure $\mathcal{M}=(\alga=(\{a,b,c,d,e,f\},\otimes,\circ,{}^{*}),\pp,\{\tr,\fa\})$ such that $\circ$, $\otimes$ and ${}^{*}$ are defined according to the following Cayley tables
