\subsection{Building Prediction Model}\label{sec: pretrain}


We now focus on the pre-training phase of our prediction model. The data generation and model training process can be outlined through the following key steps:

\begin{enumerate}
    \item We first define a parameter space $\boldsymbol\Theta$ that encompasses all combinations of $\boldsymbol{\theta}:=(\boldsymbol{\theta}_{\text{model}},\boldsymbol{\theta}_{\text{simulation}},\boldsymbol{\theta}_{\text{payoff}})$ that are of practical interest. This space covers the range of parameters that would likely be encountered in real-world pricing scenarios on a daily, weekly or monthly basis, depending on the model update frequency.

    \item We then draw samples of $\boldsymbol{\theta}_i$ from $\boldsymbol\Theta$, using uniform sampling or any measure that ensures comprehensive coverage. For each sampled parameter set, we generate one pair \footnote{You could also generate multiple pair of $(\boldsymbol{Y}(\boldsymbol{\theta}_i),\boldsymbol{X}(\boldsymbol{\theta}_i))$ under the same sampled $\boldsymbol{\theta}_i$.} of $\boldsymbol{Y}(\boldsymbol{\theta}_i)$ and its corresponding $\boldsymbol{X}(\boldsymbol{\theta}_i) := \phi(\boldsymbol{Y}(\boldsymbol{\theta}_i))$. It is important to note that $\boldsymbol{X}$ and $\boldsymbol{Y}$ are coupled in this generation process. 

    \item For each generated pair, we compute the payoff $f_{\boldsymbol\theta_{i,\text{payoff}}}(\boldsymbol{Y}(\boldsymbol{\theta}_i))$, which serves as a \textit{label} in our training data. The corresponding \textit{feature} vector is comprised of $(\boldsymbol{\theta}_{i,\text{model}},\boldsymbol{\theta}_{i,\text{simulation}},\boldsymbol{\theta}_{i,\text{payoff}}, \boldsymbol{X}(\boldsymbol{\theta}_i))$.

    \item This process is repeated $N_{\text{train}}$ times to generate training dataset which consists of $N_{\text{train}}$ pairs of  
    \begin{align*}
        \textit{feature}_i:=&(\boldsymbol{\theta}_{i,\text{model}},\boldsymbol{\theta}_{i,\text{simulation}},\boldsymbol{\theta}_{i,\text{payoff}}, \boldsymbol{X}(\boldsymbol{\theta}_i))\nonumber\\
        \textit{label}_i:=&f_{\boldsymbol\theta_{i,\text{payoff}}}(\boldsymbol{Y}(\boldsymbol{\theta}_i))
    \end{align*}
    for $i\in[N_{\text{train}}]$. 

    \item The ML model $g$ is then trained to minimize the MSE loss and saved:
    \begin{equation}\label{erm}
    	\min_{g}\frac{1}{N_{\text{train}}}\sum_{i\in[N_{\text{train}}]}(\text{label}_i-g(\text{feature}_i))^2.
    \end{equation}
\end{enumerate}
\begin{algorithm}
\begin{algorithmic}[1]
\caption{Prediction Model Training in PEMC}\label{sddd}
\Procedure{DataGeneration}{$N_{\text{train}}, \boldsymbol{\Theta}$}
   \State Initialize empty datasets ($\textit{features}, \textit{labels}$)

    \For{$i = 1$ \textbf{to} $N_{\text{train}}$}
        \State Sample parameters $\boldsymbol{\theta}_i\sim\Theta$ uniformly
        \State Generate $\boldsymbol{X}(\boldsymbol{\theta}_i), \boldsymbol{Y}(\boldsymbol{\theta}_i)\sim\mathbb E_{\text{ risk neutral measure}(\boldsymbol{\theta}_i)}$
        \State $\textit{label}_i \gets f_{\boldsymbol\theta_{i,\text{payoff}}}(\boldsymbol{Y}(\boldsymbol{\theta}_i))$
        \State $\textit{feature}_i \gets (\boldsymbol{\theta}_{i,\text{model}}, \boldsymbol{\theta}_{i,\text{simulation}}, \boldsymbol{\theta}_{i,\text{payoff}}, \boldsymbol{X}(\boldsymbol{\theta}_i))$
        \State Store $(\textit{feature}_i, \textit{label}_i)$ to $(\textit{features}, \textit{labels})$
    \EndFor
    \State \textbf{return} datasets ($\textit{features}, \textit{labels}$)
\EndProcedure
\Statex
\Procedure{Training}{$\textit{features}, \textit{labels}$}
    \State Initialize model $g$
    \State $N_{\text{train}} \gets \text{length}(\textit{features})$
    \State Minimize: $\min_{g}\frac{1}{N_{\text{train}}}\sum_{i\in[N_{\text{train}}]}(\text{label}_i-g(\text{feature}_i))^2$
    \State \textbf{return} trained model $g$
\EndProcedure
\end{algorithmic}
\end{algorithm}

The essential steps are summarized in Algorithm \ref{sddd}. While the data generation process can be time-intensive due to the complexity of $\boldsymbol{Y}$, it is conducted offline during the pre-training phase. This approach minimizes its impact on real-time pricing applications by effectively trading memory usage for computational speed during execution. 

This pre-training setup presents an ideal scenario for ML applications. It is important to also note that PEMC does not require $g$ to take specific forms. However, the convex and differentiable nature of the loss function (i.e., squared loss), the large supply of data (i.e., from Monte Carlo simulation), and the need for expressiveness of the model family make neural networks (NNs) an ideal choice. For training NNs, various optimization techniques and architectural enhancements—such as the Adam optimizer \citep{kingma2014adam}, batch normalization \citep{ioffe2015batch}, and skip connections \citep{he2016deep}—can be employed to improve performance. In fact, recent advancements in ML technologies have made the training process remarkably accessible and efficient. The availability of open-source, user-friendly frameworks like PyTorch \citep{paszke2019pytorch}, TensorFlow \citep{abadi2016tensorflow}, and JAX \citep{jax2018github}—coupled with GPU acceleration and highly optimized C++ backends—has dramatically simplified the process of training models on large datasets. These frameworks support recent neural network architectures, such as Convolutional Neural Networks (CNNs) \citep{lecun1998gradient}, Residual Networks (ResNets) \citep{he2016deep}, and Transformers \citep{vaswani2017attention}, as well as various Stochastic Gradient Descent (SGD) optimization algorithms \citep{bottou2010large}. In applications, we only utilized well-established and widely recognized NN structures that are now considered common. These models can typically be implemented using just a few lines of code, as they have been incorporated into existing packages and extensively optimized.

% Finally, regarding the choice of loss function, we note that the goal of the prediction model $g$ is to produce an approximation of the underlying regression function: $g (\boldsymbol \theta, \boldsymbol{X}(\boldsymbol{\theta}))
% 	\approx \mathbb E_{\text{risk neutral measure}(\boldsymbol{\theta})}\bigg[f_{\boldsymbol\theta_{\text{payoff}}}(\boldsymbol{Y}(\boldsymbol{\theta}))\bigg|(\boldsymbol{\theta}, \boldsymbol{X}(\boldsymbol{\theta}))\bigg]$. As we will see, the quality of this approximation will impact the effectiveness of variance reduction, which we shall explore in subsequent sections. 


 \subsection{Evaluation}
% Having completed the training phase of PEMC, we now turn our attention to the evaluation procedure. This stage employs the pre-trained model to enhance the efficiency of MC simulations, and we will demonstrate how CVs are judiciously constructed to achieve variance reduction. 
Once we finish the pre-training phase, the prediction model is stored and used on-the-fly in the evaluation process as follows:
\begin{enumerate}
        \item A specific parameter $\boldsymbol{\theta}:=(\boldsymbol{\theta}_{\text{model}},\boldsymbol{\theta}_{\text{simulation}},\boldsymbol{\theta}_{\text{payoff}})\in\boldsymbol\Theta$ is given, e.g., calibrated from market data in real time, and needs to be used for pricing.    
    \item Generate $n$ pairs of $(\boldsymbol{Y}_i,\boldsymbol{X}_i)_{i \in [n]}$, from $\mathbb E_{\text{risk neutral measure}(\boldsymbol{\theta})}$. Here we have suppressed $\boldsymbol{Y}$'s dependency on $\boldsymbol{\theta}$ for convenience.
    % , as in the evaluation stage only one fixed $\boldsymbol{\theta}$ is considered. 

    \item Based on the marginal distribution of $\boldsymbol{X}$, independently generate $N$ additional samples of $(\boldsymbol{\tilde X}_j)_{j\in [N]}$ from $\mathbb E_{\text{risk neutral measure}(\boldsymbol{\theta})}$, directly according to its marginal distribution. These samples are independent of the previous data $(\boldsymbol{Y}_i,\boldsymbol{X}_i)_{i \in [n]}$.

     \item Utilize the pre-trained model ${g}$ to evaluate the PEMC estimator:
    \begin{equation}\label{estimator}
        PEMC:=\frac{1}{n}\sum_{i=1}^n(f(\boldsymbol{Y}_i)- g(\boldsymbol{X}_i))+\frac{1}{N}\sum_{j=1}^N g(\boldsymbol{\tilde X}_j)
    \end{equation}
\end{enumerate}
For notational simplicity, we have written ${g}(\boldsymbol{X})$ instead of ${g}(\boldsymbol{\theta}_{\text{model}},\boldsymbol{\theta}_{\text{simulation}},\boldsymbol{\theta}_{\text{payoff}},\boldsymbol{X})$, and $f(\boldsymbol{Y})$ instead of $f_{\boldsymbol{\theta}_{\text{payoff}}}(\boldsymbol{Y})$. A key aspect of this procedure is the relationship between $N$ and $n$. Typically, we choose $N$ to be one, or several orders of magnitude larger than $n$. The optimal choice of $N$ versus $n$, will be discussed Section \ref{theoryresult}. The PEMC evaluation step is summarized in Algorithm \ref{alg:pemc}. 

\begin{algorithm}[H]
\begin{algorithmic}[1]
\caption{Evaluation Procedure in PEMC}
\label{alg:pemc}
\Procedure{Evaluation}{$\boldsymbol{\theta}, n, N, g$}
   \State Generate i.i.d. $(\boldsymbol{Y}_i,\boldsymbol{X}_i)_{i \in [n]}$ from $\mathbb E_{\text{risk neutral measure}(\boldsymbol{\theta})}$
   \State Generate i.i.d. $(\boldsymbol{\tilde X}_j)_{j\in [N]}$ independently from its marginal in $\mathbb E_{\text{risk neutral measure}(\boldsymbol{\theta})}$
   \State Compute $PEMC:= \frac{1}{n}\sum_{i=1}^n(f(\boldsymbol{Y}_i)- g(\boldsymbol{X}_i))+\frac{1}{N}\sum_{j=1}^N g(\boldsymbol{\tilde X}_j)$
   \State \textbf{return} $PEMC$ 
\EndProcedure
\end{algorithmic}
\end{algorithm}

 % Application in Asian Options Pricing
\subsection{Overall Methodology}\label{sec:illustration}
We now summarize our overall PEMC methodology applied to the Asian option under the Heston model, i.e., \eqref{asian payoff}, 
% We now return to our example on arithmetic Asian option under the Heston model:\begin{equation*}
%             P_A(\{S_t\}_t) = \max\left(\frac{1}{n_D}\sum_{i=1}^{n_D} S_{t_i} - K, 0\right)
% \end{equation*}
 with $\boldsymbol{\theta_{\text{payoff}}}$ specifying the strike level $K$, the sampling frequency $n_D$ and the observation dates $\{t_i\}_{i\in[n_D]}$. The Heston model is described in \eqref{heston} which requires $\boldsymbol{\theta}_{\text{model}} := (r,\eta,\delta,\rho,\kappa)\in\mathbb R^5$. Suppose we use an NN as the prediction model. Then, the PEMC framework could proceed as follows:

\begin{enumerate}
    \item Define the parameter space $\boldsymbol\Theta$ that encompasses realizations of $$\boldsymbol{\theta}:=(\underbrace{r,\eta,\delta,\rho, \kappa}_{\boldsymbol{\theta}_{\text{model}}}, \underbrace{S_0, \nu_0, \Delta t, T}_{\boldsymbol{\theta}_{\text{simulation}}},\underbrace{K, n_D, \{t_i\}_{i\in[n_D]}}_{\boldsymbol{\theta}_{\text{payoff}}} )$$ which are of practical interest. 

    \item Uniformly sample $\boldsymbol{\theta}$ from $\boldsymbol{\Theta}$. This step is straightforward if the parameter space is a Cartesian product of intervals. For each sampled $\boldsymbol{\theta}$, generate process $\boldsymbol{Y}:=(S_t,\nu_t)_t$ using a discretization scheme with step size $\Delta t$, with the Heston model specified by $\boldsymbol{\theta}$.

    \item During the sampling of $\boldsymbol{Y}$, we collect $\boldsymbol{X}$ to be the sum of Brownian increment $$W_T^S:=\sum_{j=1}^{T/\Delta t}\Delta W^S_{j\Delta t} \quad\text { and } \quad W_T^\nu:=\sum_{j=1}^{T/\Delta t}\Delta W^\nu_{j\Delta t},$$ simulated during each step of the Euler scheme. This makes the marginal of $\boldsymbol{X}$ simply a two-dimensional Gaussian: $\frac{\boldsymbol{X}}{\sqrt{T}}\sim \mathcal{N}\Big(\mathbf{0},[\begin{smallmatrix} 1 & \rho  \\ \rho  & 1 \end{smallmatrix}]\Big)$.

    \item Save 
    \begin{align}\label{asianopt}
        \textit{label}:=&(\frac{1}{n_D}\sum_{i=1}^{n_D} S_{t_i} - K)^+ \nonumber\\
        \textit{feature}:=&({r,\eta,\delta,\rho, \kappa}, {S_0, \nu_0, \Delta t, T},{K, n_D, \{t_i\}_{i\in[n_D]}}, W_T^S, W_T^\nu).
    \end{align}

    \item Repeat steps 2-4 $N_{\text{train}}$ times to generate dataset $(\textit{feature}_i,\textit{label}_i)_{i\in[N_{\text{train}}]}$ of size $N_{\text{train}}$.

    \item Train a NN with weights $\boldsymbol{w}$ to minimize the MSE loss:
    $$\min_{{\boldsymbol{w}}}\frac{1}{N_{\text{train}}}\sum_{i\in[N_{\text{train}}]}(\text{label}_i-NN_{\boldsymbol{w}}(\text{feature}_i))^2$$ and use $\hat w$ to 
    approximate $$NN_{\boldsymbol{\hat w}}\approx\mathbb E\bigg[(\frac{1}{n_D}\sum_{i=1}^{n_D} S_{t_i} - K)^+\bigg|{r,\eta,\delta,\rho, \kappa}, {S_0, \nu_0, \Delta t, T},{K, n_D, \{t_i\}_{i\in[n_D]}}, W_T^S, W_T^\nu\bigg].$$
    \item At evaluation, given a specific $\boldsymbol{\theta}=({r,\eta,\delta,\rho, \kappa}, {S_0, \nu_0, \Delta t, T},{K, n_D, \{t_i\}_{i\in[n_D]}}, W_T^S, W_T^\nu)\in\Theta$, we generate $n$ paired samples $(\textit{label}_i, \textit{feature}_i)_{i\in[n]}$ as in \eqref{asianopt}. We also generate $N$ i.i.d. $\sqrt{T}\mathcal{N}\Big(\mathbf{0},[\begin{smallmatrix} 1 & \rho  \\ \rho  & 1 \end{smallmatrix}]\Big)$ samples and store them as $(\tilde{\textit{feature}})_{j\in[N]}$.


    \item Output $PEMC:=\frac{1}{n}\sum_{i=1}^n(\textit{label}_i- NN_{\boldsymbol{\hat{w}}}(\textit{feature}_i))+\frac{1}{N}\sum_{j=1}^NNN_{\boldsymbol{\hat{w}}}(\tilde{\textit{feature}}_j)$   \end{enumerate}


