\subsection{Proof of Lemma \ref{ratio}}

\begin{proof}{Proof}
By relaxing the constraints to $n,N\in\mathbb R^+$, the optimization problem
\begin{align*}
\underset{n> 0, N> 0}{\text{min}} \quad & \frac{1}{n}\sigma_{f-{g}}^2+\frac{1}{N}\sigma_{ g}^2. \\
\text{s.t.} \quad & nc_{f-g} + Nc_g \leq B,
\end{align*}
is jointly convex in $n,N\in\mathbb R^+$. The objective value also approaches infinity as $N\to0$ or $n\to0$. Consequently, the strict convexity ensures the existence of a global minimizer in the interior and directly solving the Lagrangian gives us the result.
\end{proof}

\subsection{Proof of Lemma \ref{ratioofvariance}}
\begin{proof}{Proof}
   Based on the results of Lemma \ref{ratio}, we can deduce that this ratio again does not depend on the budget $B$, so we omit its dependence in the statement. Moreover, we can conveniently choose a budget of the form $B=n_0c_{f-g}+n_0\frac{\sigma_{g}}{\sigma_{f-g}}\cdot\sqrt{\frac{c_{f-g}}{c_{g}}}c_g$ which gives an allocation of $n=n_0$ and $N=n_0\frac{\sigma_{g}}{\sigma_{f-g}}\cdot\sqrt{\frac{c_{f-g}}{c_{g}}}$ for PEMC in accordance with Lemma \ref{ratio}, while comparing with $B/c_f$ samples for standard MC. The rest follows from Lemma \ref{pemcvariance} and the assumption $c_f = c_{f-g}$. 
\end{proof} 

\subsection{Proof of Lemma \ref{idealg}}
\begin{proof}{Proof}
    When $g = \mathbb{E}[f(\boldsymbol{Y}) \,|\,  \boldsymbol{X}]$ is the true regressor, i.e., $$g = \argmin_{h \text{ measurable}}\mathbb E[(f(\boldsymbol{Y})-h(\boldsymbol{X}))^2],$$ and $f$ is square-integrable, it follows that $\mathbb E[(f-g) h] =0$ for all square-integrable $h$. Plugging in $h = g$, we obtain $\mathrm{Cov}(f-g, g)=0$. Consequently we have $\rho:=\mathrm{corr}(f, g)=\frac{\sigma_g}{\sigma_f}$ and $\sigma_f^2 = \sigma_{f-g}^2+\sigma^2_g$, which further implies $\sigma_g = \rho^2\sigma_f^2$ and $\sigma_{f-g}^2 = (1-\rho^2)\sigma^2_f$. The rest follows from $c_{f-g} = c_f$.
\end{proof}



\subsection{Proof of Lemma \ref{learning_theory_summary}}
In this part, we go through the pipeline for a result in the form of Lemma \ref{learning_theory_summary} in Section \ref{LTE}. We begin by formally introducing the key concepts associated with the learning framework under consideration.



\begin{definition}
	Let $g_0$ denote the true regression function, defined by
	\begin{align*}
		g_0(\boldsymbol{\theta},\boldsymbol{X}(\boldsymbol{\theta}))
        :=& \mathbb{E}_{\text{risk neutral measure}(\boldsymbol{\theta})}\bigg[f_{\boldsymbol{\theta}_{\text{payoff}}}(\boldsymbol{Y}(\boldsymbol{\theta})) \,\bigg|\, (\boldsymbol{\theta}, \boldsymbol{X}(\boldsymbol{\theta}))\bigg]\\
		=& \argmin_{g \text{ measurable}} \mathbb{E}_{\boldsymbol{\theta}\sim\Theta, (\boldsymbol{X}(\boldsymbol{\theta}), \boldsymbol{Y}(\boldsymbol{\theta}))\sim\text{risk neutral measure}(\boldsymbol{\theta})}
		\biggl(f_{\boldsymbol{\theta}_{\text{payoff}}}(\boldsymbol{Y}(\boldsymbol{\theta})) - g(\boldsymbol{\theta}, \boldsymbol{X}(\boldsymbol{\theta}))\biggr)^2.
	\end{align*}
Note that equality exploits the well-known property of the squared loss minimizer: it is the conditional expectation of the target variable given the input features. The notable part is that, this formulation inherently incorporates the sampling over $\boldsymbol\theta \sim \boldsymbol\Theta$. This is because, in PEMC we generate training data by first drawing $\boldsymbol\theta$ from $\boldsymbol\Theta$ and then sampling $\boldsymbol{X}(\boldsymbol{\theta}), \boldsymbol{Y}(\boldsymbol{\theta})$ from the corresponding risk-neutral measure indexed by $\boldsymbol{\theta}$. However, since the result holds pointwise for each fixed $\boldsymbol\theta \in \boldsymbol\Theta$, it also holds in the aggregate setting where $\boldsymbol\theta$ is (uniformly) random. For simplicity, we do not delve into technical measurability considerations here.


Next, we introduce the hypothesis class and define the best-in-class predictor. The hypothesis class $\mathcal{G}$ plays a pivotal role in the learning framework, encapsulating the set of candidate functions from which the predictor $g$ is selected.

\begin{definition}

Let $\mathcal{G}$ be the hypothesis class induced by the NN model family. Define $g^*$ as the best-in-class function satisfying
	\begin{align*}
		g^*(\boldsymbol{\theta}, \boldsymbol{X}(\boldsymbol{\theta})):=& \argmin_{g \in \mathcal{G}} \mathbb{E}_{\boldsymbol{\theta}\sim\Theta, (\boldsymbol{X}(\boldsymbol{\theta}), \boldsymbol{Y}(\boldsymbol{\theta}))\sim\text{risk neutral measure}(\boldsymbol{\theta})}
		\biggl(f_{\boldsymbol{\theta}_{\text{payoff}}}(\boldsymbol{Y}(\boldsymbol{\theta})) - g(\boldsymbol{\theta}, \boldsymbol{X}(\boldsymbol{\theta}))\biggr)^2\\
		=& \argmin_{g \in \mathcal{G}} \mathbb{E}_{\boldsymbol{\theta}\sim\Theta, \boldsymbol{X}(\boldsymbol{\theta})\sim\text{risk neutral measure}(\boldsymbol{\theta})}
		\biggl((g_0 - g)(\boldsymbol{\theta}, \boldsymbol{X}(\boldsymbol{\theta}))\biggr)^2.
	\end{align*}
\end{definition}
where the second line follows again from the definition of $g_0$. Considering a model $g$ trained with $N_{\text{train}}$ samples and is held fixed during the evaluation of the expectation, as is standard when discussing generalization error, the approximation error is defined as
\begin{align*}
	\epsilon_{a}^{\mathcal{G}} := \mathbb{E}_{\boldsymbol{\theta}\sim\Theta, \boldsymbol{X}(\boldsymbol{\theta})\sim\text{risk neutral measure}(\boldsymbol{\theta})}
	\biggl((g_0 - g^*)(\boldsymbol{\theta}, \boldsymbol{X}(\boldsymbol{\theta}))\biggr)^2,
\end{align*}
and the statistical error from $g$ obtained from training on $N_{\text{train}}$ samples:
\begin{align*}
	\epsilon_{e}^{N_{\text{train}}} := \mathbb{E}_{ \boldsymbol{\theta}\sim\Theta, \boldsymbol{X}(\boldsymbol{\theta})\sim\text{risk neutral measure}(\boldsymbol{\theta})}
	\biggl((g^* - g)(\boldsymbol{\theta}, \boldsymbol{X}(\boldsymbol{\theta}))\biggr)^2.
\end{align*}
Finally, define the total error as
\begin{align*}
	\epsilon_{\text{total}} := \mathbb{E}_{\boldsymbol{\theta}\sim\Theta, \boldsymbol{X}(\boldsymbol{\theta})\sim\text{risk neutral measure}(\boldsymbol{\theta})}
	\biggl((g_0 - g)(\boldsymbol{\theta}, \boldsymbol{X}(\boldsymbol{\theta}))\biggr)^2.
\end{align*}
\end{definition}
It follows that
\begin{align}\label{bound}
	\epsilon_{\text{total}} \leq 2\epsilon_a^{\mathcal G} + 2\epsilon_e^{N_{\text{train}}}.
\end{align}
 The interaction between $\epsilon_{a}^{\mathcal{G}}$ and $\epsilon_{e}^{N_{\text{train}}}$ essentially captures the bias-variance tradeoff. By choosing more expressive model classes (e.g., richer neural network architectures) and increasing the training set size, we can jointly reduce $\epsilon_a^{\mathcal{G}}$ and $\epsilon_e^{N_{\text{train}}}$. Thus, under reasonable conditions, $\epsilon_{\text{total}}$ can be made arbitrarily small if both $\epsilon_a^{\mathcal{G}}$ and $\epsilon_e^{N_{\text{train}}}$. In the following sections, we analyze $\epsilon_a^{\mathcal{G}}$ and $\epsilon_e^{N_{\text{train}}}$ respectively.
\subsubsection{Approximation Error $\epsilon_a^{\mathcal{G}}$}\label{approximation_error}
Note that this best-in-class function $g^*$ depends on the distribution of $\boldsymbol{\theta}\sim\Theta$, meaning the notion of optimality is distribution-dependent on $\boldsymbol{\theta}$. This is also why we choose a distribution $\boldsymbol{\theta}\sim\boldsymbol{\Theta}$ that sufficiently covers the space. In this paper, $\mathcal{G}$ is induced by our choice of neural network architecture and training procedure. The complexity of $\mathcal{G}$ significantly impacts both approximation and statistical errors. Neural networks are renowned for their flexibility and expressiveness, serving as universal approximators. According to the Universal Approximation Theorem \citep{cybenko1989approximation,hornik1991approximation}, neural networks with a single hidden layer containing a sufficient number of neurons can approximate any continuous function on compact subsets of $\mathbb{R}^n$ to arbitrary accuracy. Modern extensions of this theorem provide more nuanced insights into how network depth and architecture influence approximation capabilities \citep{yarotsky2017error,lu2017expressive,shen2021neural, cybenko1989approximation,hornik1991approximation}. Typical universal universal approximation theorems deals with compact input space in $\mathbb R^n$ and point-wise convergence, in our context, we do not restrict $\boldsymbol{X}$ to live in a compact space and we only need $\mathscr L^2$ convergence, so the theorem from \cite{Pinkus1999} or \cite{LeshnoLinPinkusSchocken1993} is sufficient, which gives us
\begin{lemma}\label{uat}
    Suppose $g_0: \boldsymbol{\Theta}\times \mathbb R^{dim (\boldsymbol{X})}\to\mathbb R$ is in $\mathscr L^2(\mathbb P)$ where $\mathbb P$ is the probability measure that governs the joint distribution of $\boldsymbol{\theta}\sim\Theta, (\boldsymbol{X}(\boldsymbol{\theta}), \boldsymbol{Y}(\boldsymbol{\theta}))\sim\text{risk neutral measure}(\boldsymbol{\theta})$. Then, for any $\epsilon>0$, we can find a class of NN $\mathcal G$ such that 
    \begin{equation*}
        \epsilon_{a}^{\mathcal{G}} \leq \epsilon.
    \end{equation*}
\end{lemma}
\begin{proof}{Proof}
    See \cite{Pinkus1999} or \cite{LeshnoLinPinkusSchocken1993}. 
\end{proof}



\subsubsection{Statistical Error $\epsilon_{e}^{N_{\text{train}}} $}\label{statistical_error}

To quantify the capacity of $\mathcal{G}$, one could employ common complexity measures such as the Vapnik-Chervonenkis (VC) dimension \citep{vapnik1998statistical} or Rademacher complexity \citep{bartlett2002rademacher}. These measures provide bounds on the generalization error by capturing the richness of the hypothesis class. Modern studies have further refined our understanding of neural network complexity. For instance, norm-based capacity controls \citep{bartlett2017spectrally}, PAC-Bayesian bounds \citep{dziugaite2017computing}, and local Rademacher complexities \citep{bartlett2005local} offer more nuanced insights. In particular, most neural network architectures are known to have finite complexity measures, such as finite VC dimension or other capacity metrics, when considered as a hypothesis class with a fixed number of parameters \citep{AnthonyBartlett1999}.

Consequently, when empirical risk minimization (ERM) is performed over these networks with controlled complexity, standard statistical learning theory guarantees apply, yielding generalization bounds that typically decrease on the order of $O(1/\sqrt{N_{\text{train}}})$ where $N_{\text{train}}$ is the sample size \citep{bartlett2017spectrally, Neyshabur2018, Arora2018} and the constant in the rate depends on the complexity measure. Our PEMC prediction model can be considered as a ERM estimator. Thus, these results ensure that, given sufficiently large training sets and appropriate capacity constraints (e.g., weight regularization or architectural choices), neural networks can achieve low statistical error $\epsilon_{e}^{N_{\text{train}}}$.





Finally, there is an optimization error arising from the discrepancy between the empirical risk minimizer within $\mathcal{G}$ and the final trained model $g$. This error accounts for situations where the optimization algorithm does not perfectly identify the empirical risk minimizer. However, we do not consider this optimization error, effectively assuming the presence of an ideal “oracle” for optimization. Consequently, theoretical analyses typically treat our $g$ as readily available empirical minimizer.
\begin{lemma}\label{staterr}
    Suppose $g$ is the empirical risk minimizer of Algorithm \ref{sddd} and the neural network class $\mathcal G$ has a finite VC-dimension or Rademacher complexity. Then, for any $\epsilon>0$, there exists $N_{\text{train}}$ such that 
    \begin{equation*}
        \epsilon_{e}^{N_{\text{train}}} \leq \epsilon.
    \end{equation*}
\end{lemma}


\subsubsection{Proof of Lemma \ref{learning_theory_summary}}

Lemma \ref{uat} and Lemma \ref{staterr} allows us to control $\epsilon_{\text{total}}$ using \eqref{bound}, which allows us to prove Lemma \ref{learning_theory_summary} with the help of the following technical definition and lemma.
\begin{definition}
    Define $\epsilon_{\text{total}}(\boldsymbol{\theta}):=\mathbb E_{\boldsymbol{X}(\boldsymbol{\theta})\sim \text{risk neutral measure}(\boldsymbol{\theta})}\big(g(\boldsymbol{X}(\boldsymbol{\theta}))-g_0(\boldsymbol{X}(\boldsymbol{\theta}))\big)^2$.
\end{definition}
As a result, we have $\mathbb E_{\boldsymbol{\theta}\sim\boldsymbol{\Theta}}\epsilon_{\text{total}}(\boldsymbol{\theta}) = \epsilon_{\text{total}}$, which allows us to establish the following lemma. 
\begin{lemma}\label{diffvar}
	Let $G$ be a second moment bound for $g$, i.e.,
	\begin{align*}
		\mathbb{E}_{\boldsymbol{X}(\boldsymbol{\theta})\sim \text{risk neutral measure}(\boldsymbol{\theta})} g^2(\boldsymbol{X}(\boldsymbol{\theta})) \leq G.
	\end{align*}
	uniformly for all $\boldsymbol{\theta}\in\boldsymbol{\Theta}$. Then, for each $\boldsymbol{\theta}\in\boldsymbol{\Theta}$,
	\begin{align*}
		|\sigma_f^2 - \sigma_g^2 - \sigma_{f-g}^2| \leq 2\sqrt{\epsilon_{\text{total}}(\boldsymbol{\theta})}\sqrt{G}.
	\end{align*}
\end{lemma}

\begin{proof}{Proof}
    Fix any $\boldsymbol{\theta}\in\boldsymbol{\Theta}$. From the variance decomposition, we have
\begin{align*}
	\mathrm{Var}(f) = \mathrm{Var}(g) + \mathrm{Var}(f-g) + 2\,\mathrm{Cov}(f-g,g),
\end{align*}
which implies
\begin{align*}
	|\sigma_f^2 - \sigma_g^2 - \sigma_{f-g}^2| \leq 2|\mathrm{Cov}(f-g,g)|.
\end{align*}
Conditioning on $\boldsymbol{X}$ and utilizing the properties of $g_0$, we find that $\mathrm{Cov}(f-g,g) = \mathrm{Cov}(g_0 - g,g)$. Applying the Cauchy–Schwarz inequality yields the desired inequality.
\end{proof}
We can now prove Lemma \ref{learning_theory_summary}.
\begin{proof}{Proof of Lemma \ref{learning_theory_summary}}
    Besides the assumptions in Lemma \ref{uat}, Lemma \ref{staterr} and Lemma \ref{diffvar}, we further assume
    \begin{equation}\label{upandlowerboundsecond}
        g\leq \mathbb{E}_{\boldsymbol{X}(\boldsymbol{\theta})\sim \text{risk neutral measure}(\boldsymbol{\theta})} g^2(\boldsymbol{X}(\boldsymbol{\theta})), \mathbb{E}_{\boldsymbol{Y}(\boldsymbol{\theta})\sim \text{risk neutral measure}(\boldsymbol{\theta})} f^2(\boldsymbol{Y}(\boldsymbol{\theta})) \leq G,
    \end{equation}
    for some $0<g<G<\infty$, uniformly for all $\theta\in\Theta$. Then, based on Lemma \ref{uat}, \ref{staterr} and Markov inequality, we can find $\mathcal G$ and $N_{\text{train}}$ such that, with probability at least $1-\delta$, the randomly sampled $\boldsymbol{\theta}\sim\boldsymbol{\Theta}$ satisfies
\begin{equation*}
    \epsilon_{\text{total}}(\boldsymbol{\theta})\leq \epsilon,
\end{equation*}
which, together with Lemma \ref{diffvar} gives
\begin{equation*}
        |\sigma_f^2 - \sigma_g^2 - \sigma_{f-g}^2| \leq O(\epsilon), 
    \end{equation*}
with the constant in $O$ not dependent on $\boldsymbol{\theta}$.
Then, for at least $1-\delta$ fraction of $\boldsymbol{\theta}\in\boldsymbol{\Theta}$, as one shrinks $\epsilon\to0$, $\epsilon_{\text{total}}(\boldsymbol{\theta})\leq \epsilon$ and $|\sigma_f^2 - \sigma_g^2 - \sigma_{f-g}^2| \leq O(\epsilon)$ implies $\sigma_g^2\to\sigma_{g_0}^2$ and $\sigma_{f-g_0}^2\to\sigma_{f-g}^2$ uniformly for all such $\boldsymbol{\theta}$. Since $\sigma_f^2 = \sigma_{g_0}^2 + \sigma_{f-g_0}^2$, this further implies $\frac{\sigma_g}{\sigma_f}\to\frac{\sigma_{g_0}}{\sigma_f}$ and $\frac{\sigma_{f-g}}{\sigma_f}\to\frac{\sigma_{f-g_0}}{\sigma_f}$, given the boundedness of \eqref{upandlowerboundsecond}. Thus, $\frac{\mathrm{Var}(PEMC)}{\mathrm{Var}(MC)}$ in \eqref{ration_funda} $\to$ $r(\rho,c)$ in \eqref{ratio_number}, or equivalently, with probability at least $1-\delta$, the randomly sampled $\boldsymbol{\theta}\sim\boldsymbol{\Theta}$ satisfies
\begin{equation*}
    \frac{\mathrm{Var}(PEMC)}{\mathrm{Var}(MC)}=r(\rho,c) + O(\epsilon),
\end{equation*}
where the constant in $O$ does not depend on $\boldsymbol{\theta}$.
This concludes the proof. 
\end{proof}














\section{Numerical Results on Asian Option Pricing}\label{sec:empirical_evaluation_gbm}

We revisit the Asian option example and conduct experiments using the arithmetic Asian call option under the Geometric Brownian Motion (GBM) model. We choose the GBM model instead of the Heston model \eqref{heston} to facilitate a direct comparison between PEMC, standard Monte Carlo (MC), and the traditional Control Variate (CV) method on the extent of variance reduction. This is because the geometric Asian option, which serves as a well-established control variate, is analytically tractable within the GBM framework but lacks a closed-form solution under the Heston model \citep{dingec2015variance}.

This experiment aims to demonstrate the typical level of variance reduction that PEMC achieves. Our focus is strictly limited to variance reduction, because the GBM model actually allows for highly efficient and parallelized generation of both asset paths and corresponding payoffs, making the simulation of $\boldsymbol{Y}$ computationally straightforward. In other words, one could not fully leverage PEMC’s strengths in GBM model and this toy experiment only serves to provide insights into PEMC’s effectiveness in a controlled setting where a known CV exists. Practical applications and actual use-cases of PEMC will be provided in Section \ref{apps}.












\subsection{Experimental Setup}
We implement the PEMC procedure detailed in Section~\ref{sec:illustration}, utilizing a neural network (NN) as the predictive model. The asset price follows the Geometric Brownian Motion (GBM) model:
\begin{align}\label{gbm}
dS_t =& r S_t dt + \sigma S_t dW_t^S.
\end{align}
The payoff calculation $P_A(\{S_t\}_t) = (\frac{1}{n_D}\sum_{i=1}^{n_D} S_{t_i} - K, 0)^+$ with $n_D=252$, where simulations are carried out using daily time increments (i.e., $\Delta t=1$). The parameter space $\boldsymbol{\theta}:=(r,S_0,\sigma,K)\in\boldsymbol{\Theta}$ is: $r \in [0.01, 0.03]$, $S_0 \in [80, 120]$, $\sigma \in [0.05, 0.25]$, and $K \in [90, 110]$. For our feature $\boldsymbol{X}$, we experiment with the whole sum of Brownian increments $W_T^S:=\sum_{j=1}^{252}\Delta W^S_{j}$ with $\dim(\boldsymbol{X})=1$. We also tried a more granular representation where we partition 252 Brownian increments evenly into 14 parts, each summing 18 consecutive increments: $[\boldsymbol X]_i = \sum_{j=18(i-1)+1}^{18i}\Delta W^S_j$ for $i\in [14]$, yielding $\dim(\boldsymbol{X})=14$. The neural network is trained on a dataset comprising $N_{\text{train}} = 1.28 \times 10^6$ samples, generated by uniformly sampling $\boldsymbol{\theta}\sim\boldsymbol{\Theta}$.

The neural network architecture consists of three components: a $\boldsymbol{\theta}$ network branch, a $\boldsymbol{X}$ network branch, and a combined network. This architecture incorporates several modern deep learning practices, including Batch Normalization \citep{ioffe2015batch}, Rectified Linear Unit (ReLU) activations \citep{nair2010rectified}, and skip connections \citep{he2016deep} to enhance training stability and model performance. The $\boldsymbol{\theta}$ network branch processes the 4-dimensional input $\boldsymbol{\theta}$ using two fully connected layers with Batch Normalization and ReLU activation functions, outputting a 10-dimensional feature vector for subsequent processing. The $\boldsymbol{X}$ network branch uses two fully connected layers with width $\max(32, 2\dim(\boldsymbol{X}))$ neurons. Finally, the combined network integrates outputs from both branches through concatenation and employs skip connections featured in ResNet architectures to preserve information flow. The concatenated features pass through two additional fully connected layers with Batch Normalization and ReLU activation to produce the final prediction for PEMC. The network is implemented using PyTorch \citep{paszke2019pytorch} and trained using the Adam optimizer \citep{kingma2014adam} with a learning rate of $1 \times 10^{-3}$, incorporating dropout layers \citep{srivastava2014dropout} with a rate of 0.5 after each hidden layer to prevent overfitting. 

\subsection{Evaluation}
For comparison, we implement PEMC, MC and CV method with geometric Asian option $$P_G(\{S_t\}_t) = ((\prod_{i=1}^{n_D}S_{t_i})^{\frac{1}{{n_D}}} - K, 0)^+,$$ for the evaluation at $\boldsymbol{\theta}=(r,S_0,\sigma,K)=(0.02,100,0.2,100)$. The CV estimator is given by $$\text{CV} = \frac{1}{n}\sum_{i=1}^n \left( P_A(\{S_t^{(i)}\}_t) -  P_G(\{S_t^{(i)}\}_t)  \right)+P_G^{\text{exact}}(\boldsymbol{\theta}),$$ where $P_G^{\text{exact}}(\boldsymbol{\theta})$ is the closed-form price of geometric Asian option (with correction regarding $n_D$) \citep{glasserman2013monte}. We first evaluate the mean of $2\times 10^{9}$ MC samples as the ground truth value $A_0$. Then, we evaluate $n$ sample average of the MC, PEMC ($N=10n$) and the geometric CV estimator for $n=1000,4000,9000$ respectively, to record 3 different estimator for $A_0$. Then we repeat the experiments 300 times to get 300 estimators for each $n\in\{1000,4000,9000\}$ and each method in $\{\text{MC, PEMC, Geometric CV}\}$, to compare against $A_0$. The performance of the estimators is summarized in Table \ref{tab_asian_option_mse_comparison} and Figure \ref{fig2}.

\begin{table}[h]
