\section{Expression of moments in terms of \cref{eq:PairOfAmplitudes}}
\label{appen:pair_amplitude}
For $H_0(L,M)$, we can reorder the terms in the sum in \cref{eq:moments0}:
\begin{equation}
\begin{aligned}
    H_0(L,M) &= \sum_{\substack{\ell m \\ \ell' m'}}^{\infty} C_{\ell \, m;\ell' \, m'}^{L \, M}\sum_{\epsilon=\pm} [\ell]_m^{(\epsilon)}[\ell']_{m'}^{(\epsilon)*}  \\
    &+\sum_{\substack{\ell m \\ \ell' m'}}^{\infty} C_{\ell \, m;\ell' \, m'}^{L \, M}  \sum_{\epsilon=\pm} (-1)^{m-m'} [\ell]_{-m}^{(\epsilon)}[\ell']_{-m'}^{(\epsilon)*} .
\end{aligned}
\end{equation}
In the second term in on the right-hand side, we interchange $\ell$ and $\ell'$ as well as $m$ and $-m'$, so that this term becomes
\begin{equation}
    \sum_{\substack{\ell m \\ \ell' m'}}^{\infty} C_{\ell' \, -m';\ell \, -m}^{L \, M}  \sum_{\epsilon=\pm} (-1)^{-m+m'} [\ell']_{m'}^{(\epsilon)}[\ell]_{m}^{(\epsilon)*} .
\label{eq:second_term_moment0}
\end{equation}
Applying the symmetry property of the Clebsch-Gordan coefficients, 
\begin{equation}
    \langle j_1 m_1 j_2 m_2 | J M\rangle = (-1)^{j_2+m_2} \sqrt{\frac{2J+1}{2j_1 + 1}} \langle J (-M) j_2 m_2 | j_1 (-m_1) \rangle ,
    \label{eq:cg_relation}
\end{equation}
\cref{eq:second_term_moment0} becomes 

\begin{equation}
    \sum_{\substack{\ell m \\ \ell' m'}}^{\infty}  (-1)^{2L+M} C_{\ell \, m;\ell' \, m'}^{L \, M} \sum_{\epsilon=\pm} (-1)^{-m+m'} [\ell']_{m'}^{(\epsilon)}[\ell]_{m}^{(\epsilon)*} .
\end{equation}
Since the Clebsch-Gordan coefficients in $C_{\ell \, m;\ell' \, m'}^{L \, M}$ vanish unless $M+m' = m$, we get
\begin{equation}
    H_0(L,M) = \sum_{\substack{\ell m \\ \ell' m'}}^{\infty} C_{\ell \, m;\ell' \, m'}^{L \, M} \sum_{\epsilon=\pm}\bigg( [\ell]_m^{(\epsilon)}[\ell']_{m'}^{(\epsilon)*} + [\ell]_{m}^{(\epsilon)*} [\ell']_{m'}^{(\epsilon)}  \bigg) .
\label{eq:h0_appendix}
\end{equation}
The term in parentheses has the same form as the left-hand side of \cref{eq:PairOfAmplitudes}.

Interchanging $\ell$ and $\ell'$ as well as $m$ and $-m'$ in the expression for $H_1(L,M)$ in \cref{eq:moments1} only reorders the terms in the sums and consequently leaves the value of $H_1(L,M)$ unchanged. Hence, we can add the original expression and the one with interchanged indices and compensate by dividing by 2:
\begin{equation}
\begin{aligned}
    H_1(L,M) = \sum_{\substack{\ell m \\ 
    \ell' m'}}^{\infty} \sum_{\epsilon=\pm} \frac{\epsilon}{2} \bigg[
    &C_{\ell \, m;\ell' \, m'}^{L \, M}   \ \bigg( (-1)^m [\ell]_{-m}^{(\epsilon)}[\ell']_{m'}^{(\epsilon)*} + (-1)^{m'} [\ell]_{m}^{(\epsilon)}[\ell']_{-m'}^{(\epsilon)*} \bigg) +\\
    &C_{\ell' \, -m';\ell \, -m}^{L \, M}  \ \bigg( (-1)^{-m'} [\ell']_{m'}^{(\epsilon)}[\ell]_{-m}^{(\epsilon)*} + (-1)^{-m} [\ell']_{-m'}^{(\epsilon)}[\ell]_{m}^{(\epsilon)*} \bigg)\bigg] .
\end{aligned}
\end{equation}
Using \cref{eq:cg_relation} and $M+m' = m$, we obtain
\begin{equation}
\begin{aligned}
    H_1(L,M) = \sum_{\substack{\ell m \\ \ell' m'}}^{\infty} C_{\ell \, m;\ell' \, m'}^{L \, M} \sum_{\epsilon=\pm} \frac{\epsilon}{2} \ \bigg[ &(-1)^m \bigg( [\ell]_{-m}^{(\epsilon)}[\ell']_{m'}^{(\epsilon)*} + [\ell]_{-m}^{(\epsilon)*}[\ell']_{m'}^{(\epsilon)}\bigg)\\ 
    + &(-1)^{m'} \bigg( [\ell]_{m}^{(\epsilon)}[\ell']_{-m'}^{(\epsilon)*} + [\ell]_{m}^{(\epsilon)*}[\ell']_{-m'}^{(\epsilon)}\bigg ) \bigg] ,
\label{eq:h1_appendix}
\end{aligned}
\end{equation}
which is again a linear combination of terms in the form as the left-hand side of \cref{eq:PairOfAmplitudes}.

Since $H_2(L,M)$ has the same structure as $H_1(L,M)$, we can apply the same method and write $H_2(L,M)$ as
\begin{equation}
\begin{aligned}
    H_2(L,M) = i\sum_{\substack{\ell m \\ \ell' m'}}^{\infty} C_{\ell \, m;\ell' \, m'}^{L \, M} \sum_{\epsilon=\pm} \frac{\epsilon}{2} \ \bigg[ &(-1)^m \bigg( [\ell]_{-m}^{(\epsilon)}[\ell']_{m'}^{(\epsilon)*} + [\ell]_{-m}^{(\epsilon)*}[\ell']_{m'}^{(\epsilon)}\bigg) \\ - &(-1)^{m'} \bigg( [\ell]_{m}^{(\epsilon)}[\ell']_{-m'}^{(\epsilon)*} + [\ell]_{m}^{(\epsilon)*}[\ell']_{-m'}^{(\epsilon)}\bigg ) \bigg] .
\label{eq:h2_appendix}
\end{aligned}
\end{equation}


